const MatrixEditor: React.FC<{
    title: string;
    rows: string[];
    matrix: PriceMatrix;
    onChange: (updatedMatrix: PriceMatrix) => void;
}> = ({ title, rows, matrix, onChange }) => {

    // Helper to safely get value
    const getValue = (row: string, col: string, field: 'price' | 'mrp') => {
        return matrix[row]?.[col]?.[field] ?? 0;
    };

    const handleCellChange = (row: string, col: string, field: 'price' | 'mrp', value: string) => {
        const numValue = parseFloat(value) || 0;
        const newMatrix = { ...matrix };

        if (!newMatrix[row]) newMatrix[row] = {};
        if (!newMatrix[row][col]) newMatrix[row][col] = { price: 0, mrp: 0 };

        newMatrix[row][col] = {
            ...newMatrix[row][col],
            [field]: numValue
        };

        onChange(newMatrix);
    };

    return (
        <Card title={title} className="overflow-hidden">
            <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-slate-200 border-collapse">
                    <thead className="bg-slate-50">
