import { useReducer, useMemo, useCallback, useEffect } from 'react';
import { Service, ServiceStatus, TyreDetail, BatteryDetail, CustomService, CategorizedAddon, VehicleCategoryTag, DynamicAddon, PricingConfig } from '../types';
// FIX: Corrected import path for constants module.
import { SERVICE_PRICES, ADDON_CATEGORIES } from '../constants';

type FormAction =
  | { type: 'UPDATE_FIELD'; field: keyof Service; value: any }
  | { type: 'SET_FORM_DATA'; payload: Service }
  | { type: 'ADD_TYRE_DETAIL' }
  | { type: 'REMOVE_TYRE_DETAIL'; index: number }
  | { type: 'UPDATE_TYRE_DETAIL'; index: number; field: keyof TyreDetail; value: any }
  | { type: 'ADD_BATTERY_DETAIL' }
  | { type: 'REMOVE_BATTERY_DETAIL'; index: number }
  | { type: 'UPDATE_BATTERY_DETAIL'; index: number; field: keyof BatteryDetail; value: any }
  | { type: 'ADD_CUSTOM_SERVICE' }
  | { type: 'REMOVE_CUSTOM_SERVICE'; index: number }
  | { type: 'UPDATE_CUSTOM_SERVICE'; index: number; field: keyof CustomService; value: any }
  | { type: 'ADD_CATEGORIZED_ADDON' }
  | { type: 'REMOVE_CATEGORIZED_ADDON'; index: number }
  | { type: 'UPDATE_CATEGORIZED_ADDON'; index: number; field: keyof CategorizedAddon; value: any }
  | { type: 'UPDATE_DYNAMIC_ADDON_QTY'; name: string; quantity: number }
  | { type: 'UPDATE_CUSTOM_FIELD_DATA'; fieldId: string; value: string | number };

const createInitialState = (initialService?: Service | null): Service => {
  if (initialService) return JSON.parse(JSON.stringify(initialService));

  const submissionId = `SUB-${Date.now()}`;
  return {
    submissionId,
    appointmentId: submissionId,
    timestamp: new Date().toISOString(),
    customerFirstName: '',
    customerLastName: '',
    streetAddress: '',
    mobileNumber: '',
    carNumber: '',
    carBrandModel: '',
    vehicleCategoryTag: VehicleCategoryTag.Hatch,
    serviceSelection: [],

    isSubscription: false,
    carWashDetails: undefined,
    carCareDetails: undefined,

    beforeWashingPhoto: '',
    beforeVideoInventory: '',
    beforeVideoTopBody: '',
    beforeVideoUnderchassis: '',
    afterWashingPhoto: '',
    afterVideoInterior: '',
    afterVideoExterior: '',
    afterVideoUnderchassis: '',

    tyreReplacementQuantity: 0,
    tyreReplacementPrice: SERVICE_PRICES.tyreReplacement,
    tyreReplacementTotalAmount: 0,
    tyreDetails: [],

    batteryReplacementQuantity: 0,
    batteryReplacementTotalAmount: 0,
    batteryDetails: [],

    dynamicAddons: [],
    addonsTotal: 0,

    categorizedAddons: [],
    categorizedAddonsTotal: 0,

    customServices: [],
    customServicesTotal: 0,

    customFieldData: [],

    grandTotal: 0,
    acknowledgement: false,
    status: ServiceStatus.Draft,
    scheduledDate: undefined,
    scheduledTime: undefined,
    assignedTo: undefined,
  };
};

const formReducer = (state: Service, action: FormAction, pricingConfig?: PricingConfig): Service => {
  let nextState = state;

  switch (action.type) {
    case 'UPDATE_FIELD':
      nextState = { ...state, [action.field]: action.value };
      break;
    case 'SET_FORM_DATA':
      return action.payload; // Direct return, logic re-runs in effects
    case 'ADD_TYRE_DETAIL':
      nextState = { ...state, tyreDetails: [...state.tyreDetails, { tyreId: `T-${Date.now()}`, relatedServiceId: state.submissionId, dotCode: '', dotSerialNumberImage: '', tyreSize: '', brand: '', model: '' }] };
      break;
    case 'REMOVE_TYRE_DETAIL':
      nextState = { ...state, tyreDetails: state.tyreDetails.filter((_, i) => i !== action.index) };
      break;
    case 'UPDATE_TYRE_DETAIL':
      const newTyreDetails = state.tyreDetails.map((detail, i) => 
          i === action.index ? { ...detail, [action.field]: action.value } : detail
      );
      nextState = { ...state, tyreDetails: newTyreDetails };
      break;
    case 'ADD_BATTERY_DETAIL':
      nextState = { ...state, batteryDetails: [...state.batteryDetails, { batteryId: `B-${Date.now()}`, relatedServiceId: state.submissionId, serialNumber: '', brand: '', exchangeValue: 0, newBatteryAmount: 0 }] };
      break;
    case 'REMOVE_BATTERY_DETAIL':
      nextState = { ...state, batteryDetails: state.batteryDetails.filter((_, i) => i !== action.index) };
      break;
    case 'UPDATE_BATTERY_DETAIL':
      const newBatteryDetails = state.batteryDetails.map((detail, i) => 
          i === action.index ? { ...detail, [action.field]: action.value } : detail
      );
      nextState = { ...state, batteryDetails: newBatteryDetails };
      break;
    case 'ADD_CUSTOM_SERVICE':
      nextState = { ...state, customServices: [...state.customServices, { customServiceId: `CS-${Date.now()}`, relatedServiceId: state.submissionId, serviceDescription: '', amount: 0 }] };
      break;
    case 'REMOVE_CUSTOM_SERVICE':
      nextState = { ...state, customServices: state.customServices.filter((_, i) => i !== action.index) };
      break;
    case 'UPDATE_CUSTOM_SERVICE':
      const newCustomServices = state.customServices.map((service, i) =>
          i === action.index ? { ...service, [action.field]: action.value } : service
      );
      nextState = { ...state, customServices: newCustomServices };
      break;
    case 'ADD_CATEGORIZED_ADDON':
      nextState = { ...state, categorizedAddons: [...state.categorizedAddons, { id: `CA-${Date.now()}`, relatedServiceId: state.submissionId, category: ADDON_CATEGORIES[0], productName: '', quantity: 1, amount: 0 }] };
      break;
    case 'REMOVE_CATEGORIZED_ADDON':
      nextState = { ...state, categorizedAddons: state.categorizedAddons.filter((_, i) => i !== action.index) };
      break;
    case 'UPDATE_CATEGORIZED_ADDON':
      const newCategorizedAddons = state.categorizedAddons.map((addon, i) =>
          i === action.index ? { ...addon, [action.field]: action.value } : addon
      );
      nextState = { ...state, categorizedAddons: newCategorizedAddons };
      break;
    case 'UPDATE_DYNAMIC_ADDON_QTY':
      {
          const { name, quantity } = action;
          const category = state.vehicleCategoryTag;
          const currentAddons = state.dynamicAddons ? [...state.dynamicAddons] : [];

          let price = 0;
          let mrp = 0;

          if (pricingConfig && category) {
             const priceData = pricingConfig.addons[name]?.[category];
             price = priceData?.price || 0;
             mrp = priceData?.mrp || 0;
          }

          const existingIndex = currentAddons.findIndex(item => item.name === name);

          if (quantity <= 0) {
              nextState = { ...state, dynamicAddons: currentAddons.filter(item => item.name !== name) };
          } else {
              if (existingIndex > -1) {
                  currentAddons[existingIndex] = { ...currentAddons[existingIndex], quantity, price, mrp };
              } else {
                  currentAddons.push({ name, quantity, price, mrp });
              }
              nextState = { ...state, dynamicAddons: currentAddons };
          }
      }
      break;
     case 'UPDATE_CUSTOM_FIELD_DATA':
        {
            const { fieldId, value } = action;
            const existingIndex = (state.customFieldData || []).findIndex(item => item.fieldId === fieldId);
            let newCustomData = [...(state.customFieldData || [])];

            if (value === '' || value === undefined) {
                newCustomData = newCustomData.filter(item => item.fieldId !== fieldId);
            } else if (existingIndex > -1) {
                newCustomData[existingIndex] = { ...newCustomData[existingIndex], value };
            } else {
                newCustomData.push({ fieldId, value });
            }
            nextState = { ...state, customFieldData: newCustomData };
        }
        break;
    default:
      return state;
  }
  return nextState;
};

const LOCAL_STORAGE_KEY = 'service_form_in_progress';

export const useServiceForm = (initialService: Service | null | undefined, pricingConfig: PricingConfig) => {

  const initializer = (initialValue?: Service | null): Service => {
    try {
      const savedFormJson = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (savedFormJson) {
        const savedFormState: Service = JSON.parse(savedFormJson);
        if (!initialValue || initialValue.submissionId === savedFormState.submissionId) {
          console.log("Restoring in-progress form from local storage.");
          return savedFormState;
        }
      }
    } catch (e) {
      console.error("Could not load form state from localStorage. Starting fresh.", e);
      localStorage.removeItem(LOCAL_STORAGE_KEY);
    }
    return createInitialState(initialValue);
  };

  const [state, dispatch] = useReducer((state: Service, action: FormAction) => formReducer(state, action, pricingConfig), initialService, initializer);

  useEffect(() => {
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(state));
    } catch (e) {
        console.warn("Failed to save form draft to local storage", e);
    }
  }, [state]);

  const updateField = useCallback(<K extends keyof Service>(field: K, value: Service[K]) => {
    dispatch({ type: 'UPDATE_FIELD', field, value });
  }, []);

  // Recalculate Car Wash totals
  useEffect(() => {
    const washType = state.carWashDetails?.washType;
    const category = state.vehicleCategoryTag;

    if (state.isSubscription && state.serviceSelection.includes('Car Washing')) {
        updateField('carWashDetails', { ...state.carWashDetails!, price: 0 });
    } else if (washType && category && pricingConfig.wash[washType]?.[category]) {
        const { price, mrp } = pricingConfig.wash[washType][category];
        updateField('carWashDetails', { washType, price, mrp });
    }
  }, [state.carWashDetails?.washType, state.vehicleCategoryTag, state.isSubscription, state.serviceSelection, pricingConfig, updateField]);

  // Recalculate Car Care totals
  useEffect(() => {
    const careType = state.carCareDetails?.careType;
    const category = state.vehicleCategoryTag;

    if (careType && category && pricingConfig.carCare[careType]?.[category]) {
        const { price, mrp } = pricingConfig.carCare[careType][category];
        updateField('carCareDetails', { careType, price, mrp });
    }
  }, [state.carCareDetails?.careType, state.vehicleCategoryTag, pricingConfig, updateField]);

  // Recalculate dynamic addon prices if vehicle category changes
  useEffect(() => {
      const category = state.vehicleCategoryTag;
      if (!category || !state.dynamicAddons || state.dynamicAddons.length === 0) return;

      const updatedAddons = state.dynamicAddons.map(addon => {
          const priceData = pricingConfig.addons[addon.name]?.[category];
          return {
              ...addon,
              price: priceData?.price || 0,
              mrp: priceData?.mrp || 0,
          };
      });

      if (JSON.stringify(updatedAddons) !== JSON.stringify(state.dynamicAddons)) {
          updateField('dynamicAddons', updatedAddons);
      }
  }, [state.vehicleCategoryTag, state.dynamicAddons, pricingConfig, updateField]);


  useEffect(() => {
    const tyreTotal = state.tyreReplacementQuantity * (state.tyreReplacementPrice || 0);
    updateField('tyreReplacementTotalAmount', tyreTotal);
  }, [state.tyreReplacementQuantity, state.tyreReplacementPrice, updateField]);

  useEffect(() => {
    const batteryTotal = state.batteryDetails.reduce((total, battery) => {
      return total + ((battery.newBatteryAmount || 0) - (battery.exchangeValue || 0));
    }, 0);
    updateField('batteryReplacementTotalAmount', batteryTotal);
  }, [state.batteryDetails, updateField]);

  useEffect(() => {
    const dynamicAddonsTotal = (state.dynamicAddons || []).reduce((total, item) => {
        return total + (item.price * item.quantity);
    }, 0);

    const customAddonsTotal = state.categorizedAddons.reduce((sum, addon) => {
        return sum + ((addon.quantity || 0) * (addon.amount || 0));
    }, 0);

    updateField('categorizedAddonsTotal', customAddonsTotal);
    updateField('addonsTotal', dynamicAddonsTotal + customAddonsTotal);
  }, [state.dynamicAddons, state.categorizedAddons, updateField]);

  useEffect(() => {
    const customServicesTotal = state.customServices.reduce((sum, service) => sum + Number(service.amount || 0), 0);
    updateField('customServicesTotal', customServicesTotal);
  }, [state.customServices, updateField]);

  // Grand Total Calculation
  const grandTotal = useMemo(() => {
    let total = 0;
    if (state.serviceSelection.includes("Car Washing")) total += state.carWashDetails?.price || 0;
    if (state.serviceSelection.includes("Car Care")) total += state.carCareDetails?.price || 0;
    if (state.serviceSelection.includes("Tyre Replacement")) total += state.tyreReplacementTotalAmount;
    if (state.serviceSelection.includes("Battery Replacement")) total += state.batteryReplacementTotalAmount;
    total += state.addonsTotal;
    total += state.customServicesTotal;
    return total;
  }, [state.serviceSelection, state.carWashDetails, state.carCareDetails, state.tyreReplacementTotalAmount, state.batteryReplacementTotalAmount, state.addonsTotal, state.customServicesTotal]);

  useEffect(() => {
      updateField('grandTotal', grandTotal);
  }, [grandTotal, updateField]);

  // Sync child table rows with quantity
  useEffect(() => {
    if (!state.serviceSelection.includes("Tyre Replacement")) return;
    const diff = state.tyreReplacementQuantity - state.tyreDetails.length;
    if (diff > 0) {
      for (let i = 0; i < diff; i++) dispatch({ type: 'ADD_TYRE_DETAIL' });
    } else if (diff < 0) {
      for (let i = 0; i < -diff; i++) dispatch({ type: 'REMOVE_TYRE_DETAIL', index: state.tyreDetails.length - 1 - i });
    }
  }, [state.tyreReplacementQuantity, state.tyreDetails.length, state.serviceSelection]);

  useEffect(() => {
    if (!state.serviceSelection.includes("Battery Replacement")) return;
    const diff = state.batteryReplacementQuantity - state.batteryDetails.length;
    if (diff > 0) {
      for (let i = 0; i < diff; i++) dispatch({ type: 'ADD_BATTERY_DETAIL' });
    } else if (diff < 0) {
      for (let i = 0; i < -diff; i++) dispatch({ type: 'REMOVE_BATTERY_DETAIL', index: state.batteryDetails.length - 1 - i });
    }
  }, [state.batteryReplacementQuantity, state.batteryDetails.length, state.serviceSelection]);

  return { state, dispatch, updateField };
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
// FIX: Removed obsolete 'PredefinedAddon' from import.
import { Service, ServiceStatus, User, UserSubscription, ServiceTemplate, Permission, TyreData, PricingConfig } from '../types';
import { useServiceForm } from '../hooks/useServiceForm';
import CustomerDetailsStep from './CustomerDetailsStep';
import ServiceSelectionStep from './ServiceSelectionStep';
import { ServiceDetailsStep } from './ServiceDetailsStep';
import AddonsStep from './AddonsStep';
import CustomServicesStep from './CustomServicesStep';
import { SummaryStep } from './SummaryStep';
import Stepper from './Stepper';
import Card from './ui/Card';
import Button from './ui/Button';
import Input from './ui/Input';
import { APPOINTMENT_TIME_SLOTS, DEFAULT_PRICING_CONFIG } from '../constants';
import { validateStep, ValidationErrors } from '../services/validationService';
import { IconDeviceFloppy } from './ui/Icon';
import DependencyManager from './DependencyManager';
import CarCareStep from './CarCareStep';

interface ServiceFormProps {
  initialService?: Service | null;
  allSubmissions: Service[];
  onComplete: (service: Service) => void;
  onSaveDraft: (service: Service) => void;
  onAdminUpdate?: (service: Service) => void;
  onExit: () => void;
  googleDriveUploadUrl: string;
  currentUser: User;
  allUsers: Omit<User, 'password'>[];
  userSubscriptions: UserSubscription[];
  serviceTemplates: ServiceTemplate[];
  vehicleData: Record<string, string[]>;
  tyreData: TyreData;
  onUpdateVehicleData: (brand: string, model: string) => void;
  onUpdateTyreData: (type: keyof TyreData, value: string) => void;
  pricingConfig?: PricingConfig;
}

const ALL_STEPS = [
  { name: 'Customer Details', component: CustomerDetailsStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Service Selection', component: ServiceSelectionStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { 
    name: 'Car Care', 
    component: CarCareStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.includes("Car Care")
  },
  { 
    name: 'Service Details', 
    component: ServiceDetailsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.some(s => 
        ["Car Washing", "Tyre Replacement", "Battery Replacement"].includes(s)
      ) || state.serviceSelection.some(s => serviceTemplates.find(t => t.name === s && t.customFields.length > 0))
  },
  { 
    name: 'Add-ons', 
    component: AddonsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true
  },
  { name: 'Custom Services', component: CustomServicesStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Invoice Summary', component: SummaryStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
];

const ServiceForm: React.FC<ServiceFormProps> = ({ 
  initialService, 
  allSubmissions,
  onComplete, 
  onSaveDraft,
  onAdminUpdate,
  onExit, 
  googleDriveUploadUrl, 
  currentUser, 
  allUsers, 
  userSubscriptions,
  serviceTemplates,
  vehicleData,
  tyreData,
  onUpdateVehicleData,
  onUpdateTyreData,
  pricingConfig = DEFAULT_PRICING_CONFIG, // Use default if not provided
}) => {
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const { state, dispatch, updateField } = useServiceForm(initialService, pricingConfig);
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [prefillServiceId, setPrefillServiceId] = useState('');
  const [saveConfirmation, setSaveConfirmation] = useState('');

  const isAdminEditing = useMemo(() => 
    currentUser.permissions.includes(Permission.CAN_EDIT_ANY_ORDER) && !!initialService,
  [currentUser, initialService]);

  useEffect(() => {
    if (initialService) {
      dispatch({ type: 'SET_FORM_DATA', payload: JSON.parse(JSON.stringify(initialService)) });
    }
  }, [initialService, dispatch]);


  const sortedSubmissions = useMemo(() => {
    return [...allSubmissions].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [allSubmissions]);

  const handlePrefillChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedId = e.target.value;
    setPrefillServiceId(selectedId);

    if (!selectedId) return;

    const serviceToCopy = allSubmissions.find(s => s.submissionId === selectedId);
    if (!serviceToCopy) return;

    const newSubmissionId = `SUB-${Date.now()}`;
    const newServiceData: Service = {
      ...JSON.parse(JSON.stringify(serviceToCopy)),
      submissionId: newSubmissionId,
      appointmentId: newSubmissionId,
      timestamp: new Date().toISOString(),
      status: ServiceStatus.Draft,
      acknowledgement: false,
      beforeWashingPhoto: '', beforeVideoInventory: '', beforeVideoTopBody: '', beforeVideoUnderchassis: '',
      afterWashingPhoto: '', afterVideoInterior: '', afterVideoExterior: '', afterVideoUnderchassis: '',
      tyreDetails: [],
      batteryDetails: [],
      customFieldData: (serviceToCopy.customFieldData || []).filter(field => {
          const allCustomFields = serviceTemplates.flatMap(st => st.customFields);
          const fieldDef = allCustomFields.find(f => f.id === field.fieldId);
          return fieldDef?.type !== 'PHOTO';
      }),
      assignedTo: undefined,
      scheduledDate: undefined,
      scheduledTime: undefined,
      internalNotes: '',
      isFollowUp: true,
      dependsOn: [], // Dependencies should not be copied
    };

    dispatch({ type: 'SET_FORM_DATA', payload: newServiceData });
  };


  const visibleSteps = useMemo(() => {
    return ALL_STEPS.map((step, index) => ({...step, originalIndex: index}))
                     .filter(step => step.isVisible(state, serviceTemplates));
  }, [state, serviceTemplates]);

  const StepComponent = visibleSteps[currentStepIndex].component;

  const handleStepClick = (index: number) => {
    if (isAdminEditing || index < currentStepIndex) {
      setErrors({}); 
      setCurrentStepIndex(index);
    }
  };

  const nextStep = () => {
    const currentStepName = visibleSteps[currentStepIndex].name;
    const validationErrors = validateStep(currentStepName, state);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      setCurrentStepIndex(prev => Math.min(prev + 1, visibleSteps.length - 1));
    }
  };

  const prevStep = () => {
    setErrors({}); 
    setCurrentStepIndex(prev => Math.max(prev - 1, 0));
  };

  const handleSubmit = () => {
    if (state.acknowledgement) {
      localStorage.removeItem('service_form_in_progress');
      onComplete(state);
    }
  };

  const handleSaveDraftClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onSaveDraft(state);
  };

  const handleAdminSave = () => {
    if (!onAdminUpdate) return;
    onAdminUpdate(state);
    setSaveConfirmation('Changes saved successfully!');
    setTimeout(() => setSaveConfirmation(''), 2500);
  };

  const handleExitClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onExit();
  };

  const handleUpdateDependencies = useCallback((newDeps: string[]) => {
    updateField('dependsOn', newDeps);
  }, [updateField]);

  const isLastStep = currentStepIndex === visibleSteps.length - 1;

  const showDraftButton = (!initialService || initialService?.status === ServiceStatus.Draft);

  return (
    <Card className={!isAdminEditing ? "pb-24 sm:pb-6" : ""}>
      {!initialService && (
        <div className="p-4 mb-8 bg-slate-50 border border-slate-200 rounded-lg no-print">
          <label htmlFor="prefill-select" className="block text-sm font-medium text-slate-700 mb-1">
            Pre-fill from Existing Service (Optional)
          </label>
          <select
            id="prefill-select"
            value={prefillServiceId}
            onChange={handlePrefillChange}
            className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus-visible:border-brand-accent sm:text-sm"
          >
            <option value="">-- Select a past service to copy data from --</option>
            {sortedSubmissions.map(s => (
              <option key={s.submissionId} value={s.submissionId}>
                {new Date(s.timestamp).toLocaleDateString()} - #{s.appointmentId?.split('-').pop()} - {s.customerFirstName} ({s.carNumber})
              </option>
            ))}
          </select>
        </div>
      )}

      <div className="mb-8 pb-4 border-b border-slate-200 no-print">
        <Stepper 
          steps={visibleSteps} 
          currentStepIndex={currentStepIndex} 
          onStepClick={handleStepClick}
          isClickable={isAdminEditing}
        />
      </div>

      {isAdminEditing && (
        <div className="sticky top-[63px] bg-slate-100/80 backdrop-blur-md z-20 -mx-6 px-6 -mt-8 mb-8">
            <div className="flex justify-between items-center h-16 border-b">
                 <Button variant="ghost" onClick={handleExitClick}>Exit to Dashboard</Button>
                 <div className="flex items-center space-x-4">
                    {saveConfirmation && <p className="text-sm font-semibold text-green-600 animate-pulse">{saveConfirmation}</p>}
                    <Button onClick={handleAdminSave}>
                        <IconDeviceFloppy className="w-5 h-5 mr-2" />
                        Save Changes
                    </Button>
                 </div>
            </div>
        </div>
      )}

      {isAdminEditing && (
        <div className="p-4 mb-8 bg-blue-50 border border-blue-200 rounded-lg">
          <h3 className="text-lg font-semibold text-blue-800 mb-4">Admin Controls</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label htmlFor="assignedTo" className="block text-sm font-medium text-slate-700 mb-1">Assigned User</label>
              <select
                id="assignedTo"
                name="assignedTo"
                value={state.assignedTo || ''}
                onChange={(e) => updateField('assignedTo', e.target.value || undefined)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                <option value="">-- Unassigned --</option>
                {allUsers.map(u => <option key={u.username} value={u.username}>{u.username}</option>)}
              </select>
            </div>
            <Input 
                label="Scheduled Date" 
                id="scheduledDate"
                type="date"
                value={state.scheduledDate ? state.scheduledDate.split('T')[0] : ''}
                onChange={(e) => updateField('scheduledDate', e.target.value)}
            />
            <div>
              <label htmlFor="scheduledTime" className="block text-sm font-medium text-slate-700 mb-1">Scheduled Time</label>
              <select
                  id="scheduledTime"
                  name="scheduledTime"
                  value={state.scheduledTime || ''}
                  onChange={(e) => updateField('scheduledTime', e.target.value || undefined)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                  <option value="">-- No Time Set --</option>
                  {APPOINTMENT_TIME_SLOTS.map(time => (
                      <option key={time} value={time}>{time}</option>
                  ))}
              </select>
            </div>
             <div>
                <label htmlFor="status" className="block text-sm font-medium text-slate-700 mb-1">Status</label>
                <select
                    id="status"
                    name="status"
                    value={state.status}
                    onChange={(e) => updateField('status', e.target.value as ServiceStatus)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
                >
                    {Object.values(ServiceStatus).map(status => (
                        <option key={status} value={status}>{status}</option>
                    ))}
                </select>
            </div>
          </div>
           <div className="mt-6 pt-4 border-t">
              <DependencyManager 
                  service={state}
                  allSubmissions={allSubmissions}
                  onUpdateDependencies={handleUpdateDependencies}
              />
            </div>
        </div>
      )}

      {initialService && (currentUser.role === 'admin' || currentUser.role === 'manager' || currentUser.username === initialService.assignedTo) && (
        <div className="p-4 mb-8 bg-yellow-50 border border-yellow-200 rounded-lg">
            <h3 className="text-lg font-semibold text-yellow-800 mb-2">Internal Notes</h3>
            <p className="text-sm text-yellow-700 mb-4">These notes are only visible to administrators, managers, and the assigned service agent.</p>
            <textarea
                id="internalNotes"
                name="internalNotes"
                value={state.internalNotes || ''}
                onChange={(e) => updateField('internalNotes', e.target.value)}
                rows={3}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                placeholder="Add any internal remarks for this service (e.g., customer is particular about wheels, specific tool needed)..."
            />
        </div>
      )}

      <div className="min-h-[300px]">
        <h2 className="text-2xl font-bold text-slate-800 mb-6">{visibleSteps[currentStepIndex].name}</h2>
        {isLastStep ? (
          <SummaryStep state={state} updateField={updateField} serviceTemplates={serviceTemplates} />
        ) : (
          <StepComponent 
            state={state} 
            updateField={updateField} 
            dispatch={dispatch} 
            googleDriveUploadUrl={googleDriveUploadUrl}
            userSubscriptions={userSubscriptions}
            serviceTemplates={serviceTemplates}
            errors={errors}
            allSubmissions={allSubmissions}
            vehicleData={vehicleData}
            tyreData={tyreData}
            onUpdateVehicleData={onUpdateVehicleData}
            onUpdateTyreData={onUpdateTyreData}
            pricingConfig={pricingConfig} // Pass the pricing config down
          />
        )}
      </div>

      {!isAdminEditing && (
          <div className="fixed bottom-0 left-0 right-0 p-4 bg-white border-t border-slate-200 shadow-2xl z-30 flex flex-col-reverse gap-y-3 sm:static sm:bg-transparent sm:border-t-0 sm:shadow-none sm:flex-row sm:justify-between sm:items-center sm:p-0 sm:mt-8 sm:pt-6 no-print">
            <div className="flex items-center justify-between sm:justify-start space-x-2 w-full sm:w-auto">
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep} className="flex-1 sm:flex-none">Back</Button>
                )}
                <Button variant="ghost" onClick={handleExitClick} className="flex-1 sm:flex-none text-center">Exit</Button>
            </div>
            <div className="flex items-center space-x-2 w-full sm:w-auto">
              {showDraftButton && (
                <Button variant="ghost" onClick={handleSaveDraftClick} className="hidden sm:inline-flex">Save as Draft</Button>
              )}

              {!isLastStep && (
                <Button onClick={nextStep} className="w-full sm:w-auto justify-center">Next</Button>
              )}

              {isLastStep && (
                <Button onClick={handleSubmit} disabled={!state.acknowledgement} className="w-full sm:w-auto justify-center">
                    Complete Order
                </Button>
              )}
            </div>
          </div>
      )}

      {isAdminEditing && (
        <div className="mt-8 pt-6 border-t border-slate-200 flex justify-between items-center no-print">
            <div>
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep}>Back</Button>
                )}
            </div>

            {!isLastStep && (
                <Button onClick={nextStep}>Next</Button>
            )}
        </div>
      )}

    </Card>
  );
};

