// --- ROBUST PARSING HELPERS ---
export const robustParseFloat = (value: any): number => {
    if (typeof value === 'number') return value;
    if (typeof value !== 'string') return 0;
    const cleanedString = value.replace(/[^0-9.-]+/g, "");
    const number = parseFloat(cleanedString);
    return isNaN(number) ? 0 : number;
};

export const robustParseInt = (value: any): number => {
    const floatVal = robustParseFloat(value);
    return parseInt(String(floatVal), 10);
};

// --- OFFLINE QUEUE MANAGEMENT ---
const QUEUE_STORAGE_KEY = 'service_app_offline_queue';
let operationQueue: any[] = [];
let isProcessingQueue = false;
let callbacks = {
    onSyncStatusChange: (status: SyncStatus) => {},
    onSyncError: (error: string | null) => {},
};

// Load queue from storage on startup
const loadQueueFromStorage = () => {
    try {
        const savedQueue = localStorage.getItem(QUEUE_STORAGE_KEY);
        operationQueue = savedQueue ? JSON.parse(savedQueue) : [];
        if (operationQueue.length > 0) {
            callbacks.onSyncStatusChange('UNSAVED');
        }
    } catch (e) {
        console.error("Failed to load offline queue:", e);
        operationQueue = [];
    }
};

const saveQueueToStorage = () => {
    localStorage.setItem(QUEUE_STORAGE_KEY, JSON.stringify(operationQueue));
};

const addToQueue = (operation: any) => {
    operationQueue.push(operation);
    saveQueueToStorage();
    callbacks.onSyncStatusChange('UNSAVED');
    callbacks.onSyncError('You are offline. Changes have been saved locally and will sync when you reconnect.');
};

const processQueue = async (sheetsUrl: string) => {
    if (isProcessingQueue || !navigator.onLine || operationQueue.length === 0) {
        return;
    }
    isProcessingQueue = true;
    callbacks.onSyncStatusChange('SYNCING');
    callbacks.onSyncError(null);

    while (operationQueue.length > 0) {
        const operation = operationQueue[0];
        try {
            await executeOperation(operation, sheetsUrl);
            operationQueue.shift(); // Remove successful operation
            saveQueueToStorage();
        } catch (error) {
            console.error("Failed to process queued operation. Halting queue.", error);
            const errorMessage = error instanceof Error ? error.message : "An unknown sync error occurred.";
            callbacks.onSyncStatusChange('ERROR');
            callbacks.onSyncError(`Sync failed: ${errorMessage}`);
            isProcessingQueue = false;
            return; // Stop processing on failure
        }
    }

    callbacks.onSyncStatusChange('SYNCED');
    isProcessingQueue = false;
};

const PROXY_URL = '/.netlify/functions/google-sheets-proxy';

const executeOperation = (operation: any, sheetsUrl: string) => {
    // The payload for the Google Apps Script
    const gasPayload = {
        action: operation.type === 'delete' ? 'deleteRecord' : 'upsertRecord',
        ...operation.payload
    };

    // The payload for our Netlify proxy function, which includes the target URL
    const proxyPayload = {
        sheetsUrl: sheetsUrl,
        payload: gasPayload
    };

    // Instead of POSTing directly to Google, POST to our proxy.
    // The proxy will handle the redirect and return the final JSON response.
    return fetch(PROXY_URL, {
        method: 'POST',
        body: JSON.stringify(proxyPayload),
        headers: { 'Content-Type': 'application/json' }, // Our proxy expects JSON
    }).then(async response => {
        if (!response.ok) {
            const errorBody = await response.json().catch(() => ({ error: 'Proxy returned a non-JSON error response.', details: response.statusText }));
            const details = typeof errorBody === 'object' ? errorBody.details || errorBody.error : errorBody;
            throw new Error(`Request via proxy failed (${response.status}): ${details}`);
        }
        const result = await response.json();
        if (result.status !== 'success') {
            throw new Error(result.message || 'The cloud script returned an error via the proxy.');
        }
        return result;
    });
};


export const init = (appCallbacks: { onSyncStatusChange: (s: SyncStatus) => void, onSyncError: (e: string | null) => void }, sheetsUrl: string) => {
    callbacks = appCallbacks;
    loadQueueFromStorage();
    window.addEventListener('online', () => processQueue(sheetsUrl));
    // Initial attempt to process queue in case we start online with pending items
    if (navigator.onLine) {
        processQueue(sheetsUrl);
    }
};


// --- PRIMARY DATA ACTIONS ---

const getIdField = (sheetName: string): string => {
    switch (sheetName) {
        case 'Users': return 'username';
        case 'Submissions': return 'submissionId';
        case 'SubscriptionPlans': return 'id';
        case 'UserSubscriptions': return 'id';
        case 'ServiceTemplates': return 'id';
        case 'ServiceRequests': return 'id';
        case 'Notifications': return 'id';
        case 'LocationHistory': return 'historyId';
        case 'MiscSpends': return 'spendId';
        case 'Bookkeeping': return 'id';
        case 'ProfitLoss': return 'serviceId';
        case 'Settings': return 'googleSheetsUrl'; // Settings is a single-row "table"
        case 'VehicleData': return 'id'; // Assuming a single row with an 'id'
        case 'TyreData': return 'id'; // Assuming a single row with an 'id'
        case 'PricingConfig': return 'id'; // Assuming a single row with an 'id'
        default: throw new Error(`No ID field defined for sheet: ${sheetName}`);
    }
};

export const saveRecord = async (sheetName: string, record: any, sheetsUrl: string) => {
    // For single-row special sheets, add a static ID if it doesn't exist
    if ((sheetName === 'VehicleData' || sheetName === 'TyreData' || sheetName === 'PricingConfig') && !record.id) {
        record.id = 'singleton';
    }
    const idField = getIdField(sheetName);
    if (!record[idField]) {
        console.error(`Record for sheet "${sheetName}" is missing its ID field "${idField}".`, record);
        throw new Error(`Cannot save record: Missing ID field "${idField}".`);
    }

    const operation = {
        type: 'upsert',
        payload: {
            sheetName,
            idField,
            record,
        }
    };

    try {
        if (!navigator.onLine) throw new Error("Offline");
        await executeOperation(operation, sheetsUrl);
        // If successful, try to process any previously queued items
        await processQueue(sheetsUrl);
    } catch (error) {
        console.warn(`Save failed for ${sheetName}, adding to offline queue.`, error);
        addToQueue(operation);
        // Do not re-throw; allow the app to continue in offline mode
    }
};

export const deleteRecord = async (sheetName: string, recordId: string, sheetsUrl: string) => {
     const operation = {
        type: 'delete',
        payload: {
            sheetName,
            idField: getIdField(sheetName),
            recordId,
        }
    };
    try {
        if (!navigator.onLine) throw new Error("Offline");
        await executeOperation(operation, sheetsUrl);
        await processQueue(sheetsUrl);
    } catch (error) {
        console.warn(`Delete failed for ${sheetName}, adding to offline queue.`, error);
        addToQueue(operation);
    }
};

export const testCloudDataConnection = async (sheetsUrl: string): Promise<{ success: boolean; message: string; details?: string; }> => {
    if (!sheetsUrl) {
        return { success: false, message: "URL is empty. Please provide a valid Google Apps Script URL." };
    }

    try {
        const url = new URL(sheetsUrl);
        url.searchParams.set('action', 'loadAllData');

        const response = await fetch(url.toString(), { method: 'GET', mode: 'cors' });

        const text = await response.text();

        if (!response.ok) {
            if (text.includes('<title>Error</title>')) {
                return { success: false, message: "Connection failed. The server returned a Google error page. Check that your URL is correct (use the '/exec' link) and that the script's access is set to 'Anyone'." };
            }
            return { success: false, message: `Connection failed. Server returned status ${response.status}.`, details: text };
        }

        const data = JSON.parse(text);
        if (data.status === 'success') {
            return { success: true, message: "Connection successful! The app can communicate with your database." };
        } else {
            return { success: false, message: `The script returned an error: ${data.message || 'Unknown error'}` };
        }

    } catch (error) {
        let message = "An unknown error occurred.";
        let details = '';
        if (error instanceof Error) {
             if (error instanceof TypeError && error.message.includes('Invalid URL')) {
                message = "The provided URL is invalid. Please check the format.";
             } else if (error instanceof TypeError) { // Failed to fetch
                message = "A network error occurred. Check your internet connection and that the URL is correct.";
             } else if (error instanceof SyntaxError) {
                message = "The server returned an invalid response (not JSON). Please verify the URL and script permissions ('Anyone').";
             } else {
                message = error.message;
             }
             details = error.stack || '';
        }
        return { success: false, message, details };
    }
};


// --- INITIAL DATA LOADING ---
const getDefaultAppData = (settings: Settings): AppData => {
    const defaultNotificationPrefs: NotificationPreferences = {
        enabled: { assigned: true, reminder: true, queued: true, completed: true, manual: true, overdue: true },
        sound: 'default',
        vibration: true,
    };
    const defaultKpiTargets: RetentionKpiTargets = {
        monthlyFollowUps: 20,
        conversionRatePercentage: 50,
        monthlyRevenue: 15000,
    };
    return {
        submissions: [],
        users: [],
        settings: {...settings, retentionKpiTargets: defaultKpiTargets},
        subscriptionPlans: [],
        userSubscriptions: [],
        serviceTemplates: [],
        serviceRequests: [],
        notifications: [],
        locationHistory: [],
        miscSpends: [],
        bookkeeping: [],
        profitLoss: [],
        vehicleData: CAR_BRANDS,
        tyreData: { brands: TIRE_BRANDS, models: [], sizes: [] },
        predefinedAddons: [], // For backward compatibility
        pricingConfig: DEFAULT_PRICING_CONFIG,
    };
};

export const loadAppData = async (currentSettings: Settings): Promise<AppData> => {
    const sheetsUrl = currentSettings.googleSheetsUrl;
    if (!sheetsUrl) {
        console.log("Cloud URL not set. Using default initial data.");
        return getDefaultAppData(currentSettings);
    }

    console.log("Fetching relational data from cloud backend...");
    try {
        const url = new URL(sheetsUrl);
        url.searchParams.set('action', 'loadAllData');

        const response = await fetch(url.toString(), {
            method: 'GET',
            mode: 'cors',
        });

        const responseText = await response.text();
        if (!response.ok) {
             if (responseText.includes('<title>Error</title>')) {
                throw new Error(`The server returned a Google error page. This usually means the Cloud Data URL is incorrect (e.g., using a '/dev' link instead of the '/exec' link from your deployment) or that the script permissions are not set to 'Anyone'.`);
            }
            throw new Error(`Failed to fetch. Server responded with status: ${response.status}. Response: ${responseText}`);
        }

        const result = JSON.parse(responseText);
        if (result.status !== 'success') {
             throw new Error(result.message || 'Cloud script returned an error.');
        }

        console.log("Successfully loaded flat data from cloud. Re-hydrating...");

        const flatData = result.data;

        const tyreDetails: TyreDetail[] = (flatData.TyreDetails || []).map((d: any) => ({ ...d }));
        const batteryDetails: BatteryDetail[] = (flatData.BatteryDetails || []).map((d: any) => ({ 
            ...d, 
            exchangeValue: robustParseFloat(d.exchangeValue), 
            newBatteryAmount: robustParseFloat(d.newBatteryAmount)
        }));
        const customServices: CustomService[] = (flatData.CustomServices || []).map((d: any) => ({
             ...d, 
             amount: robustParseFloat(d.amount)
        }));
        const categorizedAddons: CategorizedAddon[] = (flatData.CategorizedAddons || []).map((d: any) => ({
            ...d,
            quantity: robustParseInt(d.quantity),
            amount: robustParseFloat(d.amount)
        }));
        const predefinedAddonQuantities = flatData.PredefinedAddonQuantities || [];
        const customFieldData = flatData.CustomFieldData || [];
        const serviceTemplateFields = flatData.ServiceTemplateFields || [];
        const locationHistory: LocationHistory[] = (flatData.LocationHistory || []).map((d: any) => ({
            ...d,
            latitude: robustParseFloat(d.latitude),
            longitude: robustParseFloat(d.longitude),
        }));
        const miscSpends: MiscSpend[] = (flatData.MiscSpends || []).map((s: any) => ({
            ...s,
            amount: robustParseFloat(s.amount),
        }));
        const bookkeeping: BookkeepingEntry[] = (flatData.Bookkeeping || []).map((b: any) => ({
            ...b,
            amount: robustParseFloat(b.amount),
        }));
        const profitLoss: ProfitLoss[] = (flatData.ProfitLoss || []).map((pl: any) => ({
            ...pl,
            materialCost: robustParseFloat(pl.materialCost),
            laborCost: robustParseFloat(pl.laborCost),
            otherExpenses: robustParseFloat(pl.otherExpenses),
            calculatedProfit: robustParseFloat(pl.calculatedProfit),
        }));


        const vehicleData = (flatData.VehicleData && flatData.VehicleData[0] && typeof flatData.VehicleData[0].data === 'string')
            ? JSON.parse(flatData.VehicleData[0].data)
            : CAR_BRANDS;

        const tyreData = (flatData.TyreData && flatData.TyreData[0] && typeof flatData.TyreData[0].data === 'string')
            ? JSON.parse(flatData.TyreData[0].data)
            : { brands: TIRE_BRANDS, models: [], sizes: [] };

        const pricingConfig: PricingConfig = (flatData.PricingConfig && flatData.PricingConfig[0] && typeof flatData.PricingConfig[0].data === 'string')
            ? JSON.parse(flatData.PricingConfig[0].data)
            : DEFAULT_PRICING_CONFIG;


        const subscriptionPlans: SubscriptionPlan[] = (flatData.SubscriptionPlans || []).map((p: any) => ({
            ...p,
            price: robustParseFloat(p.price),
            totalWashes: robustParseInt(p.totalWashes),
            features: p.features ? String(p.features).split(',').map(f => f.trim()) : [],
        }));

        const userSubscriptions: UserSubscription[] = (flatData.UserSubscriptions || []).map((s: any) => ({
            ...s,
            washesRemaining: robustParseInt(s.washesRemaining),
        }));

        const serviceRequests: ServiceRequest[] = (flatData.ServiceRequests || []).map((r: any) => ({...r}));

        const notifications: AppNotification[] = (flatData.Notifications || []).map((n: any) => ({
            ...n,
            isRead: String(n.isRead).toUpperCase() === 'TRUE',
        }));

        const serviceTemplates: ServiceTemplate[] = (flatData.ServiceTemplates || []).map((t: any) => ({
            ...t,
            isEnabled: String(t.isEnabled).toUpperCase() === 'TRUE',
            customFields: serviceTemplateFields
                .filter((f: any) => f.relatedTemplateId === t.id)
                .map(({ relatedTemplateId, ...rest }: any) => rest),
        }));

        const submissions: Service[] = (flatData.Submissions || []).map((sub: any): Service => {
            let status = sub.status;
            const validStatuses = Object.values(ServiceStatus);

            if (status === "Submitted") status = ServiceStatus.Completed;
            else if (status === "Order Created") status = ServiceStatus.Queued;
            if (!status || !validStatuses.includes(status as ServiceStatus)) status = ServiceStatus.Queued;

            let dynamicAddons = [];
            try {
                if (sub.dynamicAddons && typeof sub.dynamicAddons === 'string') dynamicAddons = JSON.parse(sub.dynamicAddons);
                else if (Array.isArray(sub.dynamicAddons)) dynamicAddons = sub.dynamicAddons;
            } catch(e) { console.warn(`Could not parse dynamicAddons for submission ${sub.submissionId}`); }

            let carWashDetails = undefined;
            try {
                if (sub.carWashDetails && typeof sub.carWashDetails === 'string') carWashDetails = JSON.parse(sub.carWashDetails);
                else if (typeof sub.carWashDetails === 'object' && sub.carWashDetails !== null) carWashDetails = sub.carWashDetails;
            } catch(e) { console.warn(`Could not parse carWashDetails for submission ${sub.submissionId}`); }

            let carCareDetails = undefined;
            try {
                if (sub.carCareDetails && typeof sub.carCareDetails === 'string') carCareDetails = JSON.parse(sub.carCareDetails);
                else if (typeof sub.carCareDetails === 'object' && sub.carCareDetails !== null) carCareDetails = sub.carCareDetails;
            } catch(e) { console.warn(`Could not parse carCareDetails for submission ${sub.submissionId}`); }

            return {
                ...sub,
                status: status,
                dynamicAddons,
                carWashDetails,
                carCareDetails,
                isSubscription: String(sub.isSubscription).toUpperCase() === 'TRUE',
                isFollowUp: String(sub.isFollowUp).toUpperCase() === 'TRUE',
                isAutoScheduled: String(sub.isAutoScheduled).toUpperCase() === 'TRUE',
                acknowledgement: String(sub.acknowledgement).toUpperCase() === 'TRUE',
                carwashQuantity: robustParseInt(sub.carwashQuantity),
                carWashPrice: robustParseFloat(sub.carWashPrice),
                carwashTotalAmount: robustParseFloat(sub.carwashTotalAmount),
                tyreReplacementQuantity: robustParseInt(sub.tyreReplacementQuantity),
                tyreReplacementPrice: robustParseFloat(sub.tyreReplacementPrice),
                tyreReplacementTotalAmount: robustParseFloat(sub.tyreReplacementTotalAmount),
                batteryReplacementQuantity: robustParseInt(sub.batteryReplacementQuantity),
                batteryReplacementTotalAmount: robustParseFloat(sub.batteryReplacementTotalAmount),
                addonsTotal: robustParseFloat(sub.addonsTotal),
                categorizedAddonsTotal: robustParseFloat(sub.categorizedAddonsTotal),
                customServicesTotal: robustParseFloat(sub.customServicesTotal),
                grandTotal: robustParseFloat(sub.grandTotal),
                appointmentId: sub.appointmentId || sub.submissionId,
                submittedBy: sub.submittedBy || undefined,
                scheduledDate: sub.scheduledDate || undefined,
                scheduledTime: sub.scheduledTime || undefined,
                assignedTo: sub.assignedTo || undefined,
                internalNotes: sub.internalNotes || '',
                tyreDetails: tyreDetails.filter((d: TyreDetail) => d.relatedServiceId === sub.submissionId),
                batteryDetails: batteryDetails.filter((d: BatteryDetail) => d.relatedServiceId === sub.submissionId),
                customServices: customServices.filter((d: CustomService) => d.relatedServiceId === sub.submissionId),
                categorizedAddons: categorizedAddons.filter((d: CategorizedAddon) => d.relatedServiceId === sub.submissionId),
                customFieldData: customFieldData
                    .filter((d: any) => d.relatedServiceId === sub.submissionId)
                    .map(({ relatedServiceId, ...rest }: any) => rest),
                serviceSelection: sub.serviceSelection ? String(sub.serviceSelection).split(',').map(s => s.trim()) : [],
                 dependsOn: sub.dependsOn ? String(sub.dependsOn).split(',').map(s => s.trim()) : [],
            };
        });

        const cloudSettingsPartial: Partial<Settings> = (flatData.Settings && flatData.Settings[0]) ? flatData.Settings[0] : {};
        let kpiTargets: RetentionKpiTargets | undefined;
        try {
            if (cloudSettingsPartial.retentionKpiTargets) {
                kpiTargets = typeof cloudSettingsPartial.retentionKpiTargets === 'string' 
                    ? JSON.parse(cloudSettingsPartial.retentionKpiTargets) 
                    : cloudSettingsPartial.retentionKpiTargets;
            }
        } catch(e) { console.warn("Could not parse KPI targets from cloud."); }

        const settings: Settings = {
            googleSheetsUrl: cloudSettingsPartial.googleSheetsUrl || currentSettings.googleSheetsUrl,
            googleDriveUploadUrl: cloudSettingsPartial.googleDriveUploadUrl || currentSettings.googleDriveUploadUrl,
            customLogoUrl: cloudSettingsPartial.customLogoUrl || currentSettings.customLogoUrl,
            retentionKpiTargets: kpiTargets || currentSettings.retentionKpiTargets
        };

        // Return an empty user array if the 'Users' sheet is empty from the cloud,
        // allowing the App to handle the initial admin creation more safely.
        const users: User[] = (flatData.Users && flatData.Users.length > 0) 
            ? (flatData.Users || []).map((u: any) => {
                let notificationPreferences: Partial<NotificationPreferences> = {};
                let pushSubscription = null;
                let attendanceHistory = [];
                let permissions = [];
                try { if (u.notificationPreferences) notificationPreferences = JSON.parse(u.notificationPreferences); } catch (e) { console.warn(`Could not parse notificationPreferences for user ${u.username}`) }
                try { if (u.pushSubscription) pushSubscription = JSON.parse(u.pushSubscription); } catch (e) { console.warn(`Could not parse pushSubscription for user ${u.username}`) }
                try { if (u.attendanceHistory) attendanceHistory = JSON.parse(u.attendanceHistory); } catch (e) { console.warn(`Could not parse attendanceHistory for user ${u.username}`) }
                try { if (u.permissions) permissions = JSON.parse(u.permissions); } catch (e) { console.warn(`Could not parse permissions for user ${u.username}`) }


                return { 
                    ...u,
                    notificationPreferences,
                    attendanceHistory,
                    permissions,
                    pushSubscription: pushSubscription || undefined,
                    latitude: u.latitude ? robustParseFloat(u.latitude) : undefined,
                    longitude: u.longitude ? robustParseFloat(u.longitude) : undefined,
                };
            })
            : getDefaultAppData(settings).users;
// FIX: Add missing 'predefinedAddons' property to align with the AppData type.
        return { submissions, users, settings, subscriptionPlans, userSubscriptions, serviceTemplates, serviceRequests, notifications, locationHistory, miscSpends, bookkeeping, profitLoss, vehicleData, tyreData, pricingConfig, predefinedAddons: [] };

    } catch (error) {
        console.error("Critical error loading data from cloud backend.", error);
        let detailedMessage = "An unknown error occurred during cloud data loading.";
        if (error instanceof Error) {
            if (error.message.includes('Failed to fetch')) {
                detailedMessage = "Network error. Please check your internet connection, ad-blockers, and ensure the Cloud Data App URL is correct and accessible.";
            } else if (error.name === 'SyntaxError') {
                 detailedMessage = "The server returned an invalid response (not JSON). This often means the Google Apps Script URL is incorrect or permissions are not set correctly.";
            } else {
                detailedMessage = error.message;
            }
        }
        throw new Error(detailedMessage);
    }
};

import { useReducer, useMemo, useCallback, useEffect } from 'react';
import { Service, ServiceStatus, TyreDetail, BatteryDetail, CustomService, CategorizedAddon, VehicleCategoryTag, DynamicAddon, PricingConfig } from '../types';
// FIX: Corrected import path for constants module.
import { SERVICE_PRICES, ADDON_CATEGORIES, WASH_PRICING_MATRIX, CAR_CARE_PRICING_MATRIX, DYNAMIC_ADDON_PRICING_MATRIX } from '../constants';

type FormAction =
  | { type: 'UPDATE_FIELD'; field: keyof Service; value: any }
  | { type: 'SET_FORM_DATA'; payload: Service }
  | { type: 'ADD_TYRE_DETAIL' }
  | { type: 'REMOVE_TYRE_DETAIL'; index: number }
  | { type: 'UPDATE_TYRE_DETAIL'; index: number; field: keyof TyreDetail; value: any }
  | { type: 'ADD_BATTERY_DETAIL' }
  | { type: 'REMOVE_BATTERY_DETAIL'; index: number }
  | { type: 'UPDATE_BATTERY_DETAIL'; index: number; field: keyof BatteryDetail; value: any }
  | { type: 'ADD_CUSTOM_SERVICE' }
  | { type: 'REMOVE_CUSTOM_SERVICE'; index: number }
  | { type: 'UPDATE_CUSTOM_SERVICE'; index: number; field: keyof CustomService; value: any }
  | { type: 'ADD_CATEGORIZED_ADDON' }
  | { type: 'REMOVE_CATEGORIZED_ADDON'; index: number }
  | { type: 'UPDATE_CATEGORIZED_ADDON'; index: number; field: keyof CategorizedAddon; value: any }
  | { type: 'UPDATE_DYNAMIC_ADDON_QTY'; name: string; quantity: number }
  | { type: 'UPDATE_CUSTOM_FIELD_DATA'; fieldId: string; value: string | number };

const createInitialState = (initialService?: Service | null): Service => {
  if (initialService) return JSON.parse(JSON.stringify(initialService));

  const submissionId = `SUB-${Date.now()}`;
  return {
    submissionId,
    appointmentId: submissionId,
    timestamp: new Date().toISOString(),
    customerFirstName: '',
    customerLastName: '',
    streetAddress: '',
    mobileNumber: '',
    carNumber: '',
    carBrandModel: '',
    vehicleCategoryTag: VehicleCategoryTag.Hatch,
    serviceSelection: [],

    isSubscription: false,
    carWashDetails: undefined,
    carCareDetails: undefined,

    beforeWashingPhoto: '',
    beforeVideoInventory: '',
    beforeVideoTopBody: '',
    beforeVideoUnderchassis: '',
    afterWashingPhoto: '',
    afterVideoInterior: '',
    afterVideoExterior: '',
    afterVideoUnderchassis: '',

    tyreReplacementQuantity: 0,
    tyreReplacementPrice: SERVICE_PRICES.tyreReplacement,
    tyreReplacementTotalAmount: 0,
    tyreDetails: [],

    batteryReplacementQuantity: 0,
    batteryReplacementTotalAmount: 0,
    batteryDetails: [],

    dynamicAddons: [],
    addonsTotal: 0,

    categorizedAddons: [],
    categorizedAddonsTotal: 0,

    customServices: [],
    customServicesTotal: 0,

    customFieldData: [],

    grandTotal: 0,
    acknowledgement: false,
    status: ServiceStatus.Draft,
    scheduledDate: undefined,
    scheduledTime: undefined,
    assignedTo: undefined,
  };
};

const formReducer = (state: Service, action: FormAction, pricingConfig?: PricingConfig): Service => {
  switch (action.type) {
    case 'UPDATE_FIELD':
      return { ...state, [action.field]: action.value };
    case 'SET_FORM_DATA':
      return action.payload;
    case 'ADD_TYRE_DETAIL':
      return { ...state, tyreDetails: [...state.tyreDetails, { tyreId: `T-${Date.now()}`, relatedServiceId: state.submissionId, dotCode: '', dotSerialNumberImage: '', tyreSize: '', brand: '', model: '' }] };
    case 'REMOVE_TYRE_DETAIL':
      return { ...state, tyreDetails: state.tyreDetails.filter((_, i) => i !== action.index) };
    case 'UPDATE_TYRE_DETAIL':
        {
            const newTyreDetails = state.tyreDetails.map((detail, i) => 
                i === action.index ? { ...detail, [action.field]: action.value } : detail
            );
            return { ...state, tyreDetails: newTyreDetails };
        }
    case 'ADD_BATTERY_DETAIL':
      return { ...state, batteryDetails: [...state.batteryDetails, { batteryId: `B-${Date.now()}`, relatedServiceId: state.submissionId, serialNumber: '', brand: '', exchangeValue: 0, newBatteryAmount: 0 }] };
    case 'REMOVE_BATTERY_DETAIL':
      return { ...state, batteryDetails: state.batteryDetails.filter((_, i) => i !== action.index) };
    case 'UPDATE_BATTERY_DETAIL':
        {
            const newBatteryDetails = state.batteryDetails.map((detail, i) => 
                i === action.index ? { ...detail, [action.field]: action.value } : detail
            );
            return { ...state, batteryDetails: newBatteryDetails };
        }
    case 'ADD_CUSTOM_SERVICE':
        return { ...state, customServices: [...state.customServices, { customServiceId: `CS-${Date.now()}`, relatedServiceId: state.submissionId, serviceDescription: '', amount: 0 }] };
    case 'REMOVE_CUSTOM_SERVICE':
        return { ...state, customServices: state.customServices.filter((_, i) => i !== action.index) };
    case 'UPDATE_CUSTOM_SERVICE':
        {
            const newCustomServices = state.customServices.map((service, i) =>
                i === action.index ? { ...service, [action.field]: action.value } : service
            );
            return { ...state, customServices: newCustomServices };
        }
    case 'ADD_CATEGORIZED_ADDON':
        return { ...state, categorizedAddons: [...state.categorizedAddons, { id: `CA-${Date.now()}`, relatedServiceId: state.submissionId, category: ADDON_CATEGORIES[0], productName: '', quantity: 1, amount: 0 }] };
    case 'REMOVE_CATEGORIZED_ADDON':
        return { ...state, categorizedAddons: state.categorizedAddons.filter((_, i) => i !== action.index) };
    case 'UPDATE_CATEGORIZED_ADDON':
        {
            const newCategorizedAddons = state.categorizedAddons.map((addon, i) =>
                i === action.index ? { ...addon, [action.field]: action.value } : addon
            );
            return { ...state, categorizedAddons: newCategorizedAddons };
        }
    case 'UPDATE_DYNAMIC_ADDON_QTY':
      {
          const { name, quantity } = action;
          const category = state.vehicleCategoryTag;
          const currentAddons = state.dynamicAddons ? [...state.dynamicAddons] : [];

          let price = 0;
          let mrp = 0;

          // Use provided pricingConfig or fallback to constants
          if (pricingConfig && category) {
             const priceData = pricingConfig.addons[name]?.[category];
             price = priceData?.price || 0;
             mrp = priceData?.mrp || 0;
          } else if (category) {
             const priceData = DYNAMIC_ADDON_PRICING_MATRIX[name as keyof typeof DYNAMIC_ADDON_PRICING_MATRIX]?.[category];
             price = priceData?.price || 0;
             mrp = priceData?.mrp || 0;
          }

          const existingIndex = currentAddons.findIndex(item => item.name === name);

          if (quantity <= 0) {
              // Remove if quantity is zero or less
              return { ...state, dynamicAddons: currentAddons.filter(item => item.name !== name) };
          } else {
              if (existingIndex > -1) {
                  // Update existing
                  currentAddons[existingIndex] = { ...currentAddons[existingIndex], quantity, price, mrp };
              } else {
                  // Add new
                  currentAddons.push({ name, quantity, price, mrp });
              }
              return { ...state, dynamicAddons: currentAddons };
          }
      }
     case 'UPDATE_CUSTOM_FIELD_DATA':
        {
            const { fieldId, value } = action;
            const existingIndex = (state.customFieldData || []).findIndex(item => item.fieldId === fieldId);
            let newCustomData = [...(state.customFieldData || [])];

            if (value === '' || value === undefined) {
                newCustomData = newCustomData.filter(item => item.fieldId !== fieldId);
            } else if (existingIndex > -1) {
                newCustomData[existingIndex] = { ...newCustomData[existingIndex], value };
            } else {
                newCustomData.push({ fieldId, value });
            }
            return { ...state, customFieldData: newCustomData };
        }
    default:
      return state;
  }
};

const LOCAL_STORAGE_KEY = 'service_form_in_progress';

export const useServiceForm = (initialService: Service | null | undefined, pricingConfig?: PricingConfig) => {

  const initializer = (initialValue?: Service | null): Service => {
    try {
      const savedFormJson = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (savedFormJson) {
        const savedFormState: Service = JSON.parse(savedFormJson);
        if (!initialValue || initialValue.submissionId === savedFormState.submissionId) {
          console.log("Restoring in-progress form from local storage.");
          return savedFormState;
        }
      }
    } catch (e) {
      console.error("Could not load form state from localStorage. Starting fresh.", e);
      localStorage.removeItem(LOCAL_STORAGE_KEY);
    }
    return createInitialState(initialValue);
  };

  const [state, dispatch] = useReducer((s: Service, a: FormAction) => formReducer(s, a, pricingConfig), initialService, initializer);

  useEffect(() => {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const updateField = useCallback(<K extends keyof Service>(field: K, value: Service[K]) => {
    dispatch({ type: 'UPDATE_FIELD', field, value });
  }, []);

  // Recalculate Car Wash totals
  useEffect(() => {
    const washType = state.carWashDetails?.washType;
    const category = state.vehicleCategoryTag;

    if (state.isSubscription && state.serviceSelection.includes('Car Washing')) {
        updateField('carWashDetails', { ...state.carWashDetails!, price: 0 });
    } else if (washType && category) {
        let price = 0;
        let mrp = 0;

        if (pricingConfig && pricingConfig.wash[washType]?.[category]) {
             price = pricingConfig.wash[washType][category].price;
             mrp = pricingConfig.wash[washType][category].mrp;
        } else if (WASH_PRICING_MATRIX[washType as keyof typeof WASH_PRICING_MATRIX]?.[category]) {
             price = WASH_PRICING_MATRIX[washType as keyof typeof WASH_PRICING_MATRIX][category].price;
             mrp = WASH_PRICING_MATRIX[washType as keyof typeof WASH_PRICING_MATRIX][category].mrp;
        }

        if (price !== undefined) {
            updateField('carWashDetails', { washType, price, mrp });
        }
    }
  }, [state.carWashDetails?.washType, state.vehicleCategoryTag, state.isSubscription, state.serviceSelection, pricingConfig, updateField]);

  // Recalculate Car Care totals
  useEffect(() => {
    const careType = state.carCareDetails?.careType;
    const category = state.vehicleCategoryTag;

    if (careType && category) {
        let price = 0;
        let mrp = 0;

        if (pricingConfig && pricingConfig.carCare[careType]?.[category]) {
             price = pricingConfig.carCare[careType][category].price;
             mrp = pricingConfig.carCare[careType][category].mrp;
        } else if (CAR_CARE_PRICING_MATRIX[careType as keyof typeof CAR_CARE_PRICING_MATRIX]?.[category]) {
             price = CAR_CARE_PRICING_MATRIX[careType as keyof typeof CAR_CARE_PRICING_MATRIX][category].price;
             mrp = CAR_CARE_PRICING_MATRIX[careType as keyof typeof CAR_CARE_PRICING_MATRIX][category].mrp;
        }

        if (price !== undefined) {
            updateField('carCareDetails', { careType, price, mrp });
        }
    }
  }, [state.carCareDetails?.careType, state.vehicleCategoryTag, pricingConfig, updateField]);

  // Recalculate dynamic addon prices if vehicle category changes
  useEffect(() => {
      const category = state.vehicleCategoryTag;
      if (!category || !state.dynamicAddons || state.dynamicAddons.length === 0) return;

      const updatedAddons = state.dynamicAddons.map(addon => {
          let price = 0;
          let mrp = 0;

          if (pricingConfig && pricingConfig.addons[addon.name]?.[category]) {
             price = pricingConfig.addons[addon.name][category].price;
             mrp = pricingConfig.addons[addon.name][category].mrp;
          } else {
             const priceData = DYNAMIC_ADDON_PRICING_MATRIX[addon.name as keyof typeof DYNAMIC_ADDON_PRICING_MATRIX]?.[category];
             price = priceData?.price || 0;
             mrp = priceData?.mrp || 0;
          }

          return {
              ...addon,
              price,
              mrp,
          };
      });

      if (JSON.stringify(updatedAddons) !== JSON.stringify(state.dynamicAddons)) {
          updateField('dynamicAddons', updatedAddons);
      }
  }, [state.vehicleCategoryTag, state.dynamicAddons, pricingConfig, updateField]);


  useEffect(() => {
    const tyreTotal = state.tyreReplacementQuantity * (state.tyreReplacementPrice || 0);
    updateField('tyreReplacementTotalAmount', tyreTotal);
  }, [state.tyreReplacementQuantity, state.tyreReplacementPrice, updateField]);

  useEffect(() => {
    const batteryTotal = state.batteryDetails.reduce((total, battery) => {
      return total + ((battery.newBatteryAmount || 0) - (battery.exchangeValue || 0));
    }, 0);
    updateField('batteryReplacementTotalAmount', batteryTotal);
  }, [state.batteryDetails, updateField]);

  useEffect(() => {
    const dynamicAddonsTotal = (state.dynamicAddons || []).reduce((total, item) => {
        return total + (item.price * item.quantity);
    }, 0);

    const customAddonsTotal = state.categorizedAddons.reduce((sum, addon) => {
        return sum + ((addon.quantity || 0) * (addon.amount || 0));
    }, 0);

    updateField('categorizedAddonsTotal', customAddonsTotal);
    updateField('addonsTotal', dynamicAddonsTotal + customAddonsTotal);
  }, [state.dynamicAddons, state.categorizedAddons, updateField]);

  useEffect(() => {
    const customServicesTotal = state.customServices.reduce((sum, service) => sum + Number(service.amount || 0), 0);
    updateField('customServicesTotal', customServicesTotal);
  }, [state.customServices, updateField]);

  // Grand Total Calculation
  const grandTotal = useMemo(() => {
    let total = 0;
    if (state.serviceSelection.includes("Car Washing")) total += state.carWashDetails?.price || 0;
    if (state.serviceSelection.includes("Car Care")) total += state.carCareDetails?.price || 0;
    if (state.serviceSelection.includes("Tyre Replacement")) total += state.tyreReplacementTotalAmount;
    if (state.serviceSelection.includes("Battery Replacement")) total += state.batteryReplacementTotalAmount;
    total += state.addonsTotal;
    total += state.customServicesTotal;
    return total;
  }, [state.serviceSelection, state.carWashDetails, state.carCareDetails, state.tyreReplacementTotalAmount, state.batteryReplacementTotalAmount, state.addonsTotal, state.customServicesTotal]);

  useEffect(() => {
      updateField('grandTotal', grandTotal);
  }, [grandTotal, updateField]);

  // Sync child table rows with quantity
  useEffect(() => {
    if (!state.serviceSelection.includes("Tyre Replacement")) return;
    const diff = state.tyreReplacementQuantity - state.tyreDetails.length;
    if (diff > 0) {
      for (let i = 0; i < diff; i++) dispatch({ type: 'ADD_TYRE_DETAIL' });
    } else if (diff < 0) {
      for (let i = 0; i < -diff; i++) dispatch({ type: 'REMOVE_TYRE_DETAIL', index: state.tyreDetails.length - 1 - i });
    }
  }, [state.tyreReplacementQuantity, state.tyreDetails.length, state.serviceSelection]);

  useEffect(() => {
    if (!state.serviceSelection.includes("Battery Replacement")) return;
    const diff = state.batteryReplacementQuantity - state.batteryDetails.length;
    if (diff > 0) {
      for (let i = 0; i < diff; i++) dispatch({ type: 'ADD_BATTERY_DETAIL' });
    } else if (diff < 0) {
      for (let i = 0; i < -diff; i++) dispatch({ type: 'REMOVE_BATTERY_DETAIL', index: state.batteryDetails.length - 1 - i });
    }
  }, [state.batteryReplacementQuantity, state.batteryDetails.length, state.serviceSelection]);

  return { state, dispatch, updateField };
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Service, ServiceStatus, User, UserSubscription, ServiceTemplate, Permission, TyreData, PricingConfig } from './types';
import { useServiceForm } from './hooks/useServiceForm';
import CustomerDetailsStep from './CustomerDetailsStep';
import ServiceSelectionStep from './ServiceSelectionStep';
import { ServiceDetailsStep } from './ServiceDetailsStep';
import AddonsStep from './AddonsStep';
import CustomServicesStep from './CustomServicesStep';
import { SummaryStep } from './SummaryStep';
import Stepper from './Stepper';
import Card from './ui/Card';
import Button from './ui/Button';
import Input from './ui/Input';
import { APPOINTMENT_TIME_SLOTS, DEFAULT_PRICING_CONFIG } from './constants';
import { validateStep, ValidationErrors } from './services/validationService';
import { IconDeviceFloppy } from './ui/Icon';
import DependencyManager from './DependencyManager';
import CarCareStep from './CarCareStep';

interface ServiceFormProps {
  initialService?: Service | null;
  allSubmissions: Service[];
  onComplete: (service: Service) => void;
  onSaveDraft: (service: Service) => void;
  onAdminUpdate?: (service: Service) => void;
  onExit: () => void;
  googleDriveUploadUrl: string;
  currentUser: User;
  allUsers: Omit<User, 'password'>[];
  userSubscriptions: UserSubscription[];
  serviceTemplates: ServiceTemplate[];
  vehicleData: Record<string, string[]>;
  tyreData: TyreData;
  onUpdateVehicleData: (brand: string, model: string) => void;
  onUpdateTyreData: (type: keyof TyreData, value: string) => void;
  pricingConfig?: PricingConfig;
}

const ALL_STEPS = [
  { name: 'Customer Details', component: CustomerDetailsStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Service Selection', component: ServiceSelectionStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { 
    name: 'Car Care', 
    component: CarCareStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.includes("Car Care")
  },
  { 
    name: 'Service Details', 
    component: ServiceDetailsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.some(s => 
        ["Car Washing", "Tyre Replacement", "Battery Replacement"].includes(s)
      ) || state.serviceSelection.some(s => serviceTemplates.find(t => t.name === s && t.customFields.length > 0))
  },
  { 
    name: 'Add-ons', 
    component: AddonsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true
  },
  { name: 'Custom Services', component: CustomServicesStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Invoice Summary', component: SummaryStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
];

const ServiceForm: React.FC<ServiceFormProps> = ({ 
  initialService, 
  allSubmissions,
  onComplete, 
  onSaveDraft,
  onAdminUpdate,
  onExit, 
  googleDriveUploadUrl, 
  currentUser, 
  allUsers, 
  userSubscriptions,
  serviceTemplates, 
  vehicleData, 
  tyreData, 
  onUpdateVehicleData, 
  onUpdateTyreData, 
  pricingConfig = DEFAULT_PRICING_CONFIG,
}) => {
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const { state, dispatch, updateField } = useServiceForm(initialService, pricingConfig);
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [prefillServiceId, setPrefillServiceId] = useState('');
  const [saveConfirmation, setSaveConfirmation] = useState('');

  const isAdminEditing = useMemo(() => 
    currentUser.permissions.includes(Permission.CAN_EDIT_ANY_ORDER) && !!initialService,
  [currentUser, initialService]);

  useEffect(() => {
    if (initialService) {
      dispatch({ type: 'SET_FORM_DATA', payload: JSON.parse(JSON.stringify(initialService)) });
    }
  }, [initialService, dispatch]);


  const sortedSubmissions = useMemo(() => {
    return [...allSubmissions].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [allSubmissions]);

  const handlePrefillChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedId = e.target.value;
    setPrefillServiceId(selectedId);

    if (!selectedId) return;

    const serviceToCopy = allSubmissions.find(s => s.submissionId === selectedId);
    if (!serviceToCopy) return;

    const newSubmissionId = `SUB-${Date.now()}`;
    const newServiceData: Service = {
      ...JSON.parse(JSON.stringify(serviceToCopy)),
      submissionId: newSubmissionId,
      appointmentId: newSubmissionId,
      timestamp: new Date().toISOString(),
      status: ServiceStatus.Draft,
      acknowledgement: false,
      beforeWashingPhoto: '', beforeVideoInventory: '', beforeVideoTopBody: '', beforeVideoUnderchassis: '',
      afterWashingPhoto: '', afterVideoInterior: '', afterVideoExterior: '', afterVideoUnderchassis: '',
      tyreDetails: [],
      batteryDetails: [],
      customFieldData: (serviceToCopy.customFieldData || []).filter(field => {
          const allCustomFields = serviceTemplates.flatMap(st => st.customFields);
          const fieldDef = allCustomFields.find(f => f.id === field.fieldId);
          return fieldDef?.type !== 'PHOTO';
      }),
      assignedTo: undefined,
      scheduledDate: undefined,
      scheduledTime: undefined,
      internalNotes: '',
      isFollowUp: true,
      dependsOn: [], // Dependencies should not be copied
    };

    dispatch({ type: 'SET_FORM_DATA', payload: newServiceData });
  };


  const visibleSteps = useMemo(() => {
    return ALL_STEPS.map((step, index) => ({...step, originalIndex: index}))
                     .filter(step => step.isVisible(state, serviceTemplates));
  }, [state, serviceTemplates]);

  const StepComponent = visibleSteps[currentStepIndex].component;

  const handleStepClick = (index: number) => {
    if (isAdminEditing || index < currentStepIndex) {
      setErrors({}); 
      setCurrentStepIndex(index);
    }
  };

  const nextStep = () => {
    const currentStepName = visibleSteps[currentStepIndex].name;
    const validationErrors = validateStep(currentStepName, state);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      setCurrentStepIndex(prev => Math.min(prev + 1, visibleSteps.length - 1));
    }
  };

  const prevStep = () => {
    setErrors({}); 
    setCurrentStepIndex(prev => Math.max(prev - 1, 0));
  };

  const handleSubmit = () => {
    if (state.acknowledgement) {
      localStorage.removeItem('service_form_in_progress');
      onComplete(state);
    }
  };

  const handleSaveDraftClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onSaveDraft(state);
  };

  const handleAdminSave = () => {
    if (!onAdminUpdate) return;
    onAdminUpdate(state);
    setSaveConfirmation('Changes saved successfully!');
    setTimeout(() => setSaveConfirmation(''), 2500);
  };

  const handleExitClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onExit();
  };

  const handleUpdateDependencies = useCallback((newDeps: string[]) => {
    updateField('dependsOn', newDeps);
  }, [updateField]);

  const isLastStep = currentStepIndex === visibleSteps.length - 1;

  const showDraftButton = (!initialService || initialService?.status === ServiceStatus.Draft);

  return (
    <Card>
      {!initialService && (
        <div className="p-4 mb-8 bg-slate-50 border border-slate-200 rounded-lg no-print">
          <label htmlFor="prefill-select" className="block text-sm font-medium text-slate-700 mb-1">
            Pre-fill from Existing Service (Optional)
          </label>
          <select
            id="prefill-select"
            value={prefillServiceId}
            onChange={handlePrefillChange}
            className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus-visible:border-brand-accent sm:text-sm"
          >
            <option value="">-- Select a past service to copy data from --</option>
            {sortedSubmissions.map(s => (
              <option key={s.submissionId} value={s.submissionId}>
                {new Date(s.timestamp).toLocaleDateString()} - #{s.appointmentId?.split('-').pop()} - {s.customerFirstName} ({s.carNumber})
              </option>
            ))}
          </select>
        </div>
      )}

      <div className="mb-8 pb-4 border-b border-slate-200 no-print">
        <Stepper 
          steps={visibleSteps} 
          currentStepIndex={currentStepIndex} 
          onStepClick={handleStepClick}
          isClickable={isAdminEditing}
        />
      </div>

      {isAdminEditing && (
        <div className="sticky top-[63px] bg-slate-100/80 backdrop-blur-md z-20 -mx-6 px-6 -mt-8 mb-8">
            <div className="flex justify-between items-center h-16 border-b">
                 <Button variant="ghost" onClick={handleExitClick}>Exit to Dashboard</Button>
                 <div className="flex items-center space-x-4">
                    {saveConfirmation && <p className="text-sm font-semibold text-green-600 animate-pulse">{saveConfirmation}</p>}
                    <Button onClick={handleAdminSave}>
                        <IconDeviceFloppy className="w-5 h-5 mr-2" />
                        Save Changes
                    </Button>
                 </div>
            </div>
        </div>
      )}

      {isAdminEditing && (
        <div className="p-4 mb-8 bg-blue-50 border border-blue-200 rounded-lg">
          <h3 className="text-lg font-semibold text-blue-800 mb-4">Admin Controls</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label htmlFor="assignedTo" className="block text-sm font-medium text-slate-700 mb-1">Assigned User</label>
              <select
                id="assignedTo"
                name="assignedTo"
                value={state.assignedTo || ''}
                onChange={(e) => updateField('assignedTo', e.target.value || undefined)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                <option value="">-- Unassigned --</option>
                {allUsers.map(u => <option key={u.username} value={u.username}>{u.username}</option>)}
              </select>
            </div>
            <Input 
                label="Scheduled Date" 
                id="scheduledDate"
                type="date"
                value={state.scheduledDate ? state.scheduledDate.split('T')[0] : ''}
                onChange={(e) => updateField('scheduledDate', e.target.value)}
            />
            <div>
              <label htmlFor="scheduledTime" className="block text-sm font-medium text-slate-700 mb-1">Scheduled Time</label>
              <select
                  id="scheduledTime"
                  name="scheduledTime"
                  value={state.scheduledTime || ''}
                  onChange={(e) => updateField('scheduledTime', e.target.value || undefined)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                  <option value="">-- No Time Set --</option>
                  {APPOINTMENT_TIME_SLOTS.map(time => (
                      <option key={time} value={time}>{time}</option>
                  ))}
              </select>
            </div>
             <div>
                <label htmlFor="status" className="block text-sm font-medium text-slate-700 mb-1">Status</label>
                <select
                    id="status"
                    name="status"
                    value={state.status}
                    onChange={(e) => updateField('status', e.target.value as ServiceStatus)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
                >
                    {Object.values(ServiceStatus).map(status => (
                        <option key={status} value={status}>{status}</option>
                    ))}
                </select>
            </div>
          </div>
           <div className="mt-6 pt-4 border-t">
              <DependencyManager 
                  service={state}
                  allSubmissions={allSubmissions}
                  onUpdateDependencies={handleUpdateDependencies}
              />
            </div>
        </div>
      )}

      {initialService && (currentUser.role === 'admin' || currentUser.role === 'manager' || currentUser.username === initialService.assignedTo) && (
        <div className="p-4 mb-8 bg-yellow-50 border border-yellow-200 rounded-lg">
            <h3 className="text-lg font-semibold text-yellow-800 mb-2">Internal Notes</h3>
            <p className="text-sm text-yellow-700 mb-4">These notes are only visible to administrators, managers, and the assigned service agent.</p>
            <textarea
                id="internalNotes"
                name="internalNotes"
                value={state.internalNotes || ''}
                onChange={(e) => updateField('internalNotes', e.target.value)}
                rows={3}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                placeholder="Add any internal remarks for this service (e.g., customer is particular about wheels, specific tool needed)..."
            />
        </div>
      )}

      <div className="min-h-[300px]">
        <h2 className="text-2xl font-bold text-slate-800 mb-6">{visibleSteps[currentStepIndex].name}</h2>
        {isLastStep ? (
          <SummaryStep state={state} updateField={updateField} serviceTemplates={serviceTemplates} />
        ) : (
          <StepComponent 
            state={state} 
            updateField={updateField} 
            dispatch={dispatch} 
            googleDriveUploadUrl={googleDriveUploadUrl}
            userSubscriptions={userSubscriptions}
            serviceTemplates={serviceTemplates}
            errors={errors}
            allSubmissions={allSubmissions}
            vehicleData={vehicleData}
            tyreData={tyreData}
            onUpdateVehicleData={onUpdateVehicleData}
            onUpdateTyreData={onUpdateTyreData}
            pricingConfig={pricingConfig}
          />
        )}
      </div>

      {!isAdminEditing && (
          <div className="mt-8 pt-6 border-t border-slate-200 flex flex-col-reverse gap-y-4 sm:flex-row sm:justify-between sm:items-center no-print">
            <div className="flex items-center space-x-2">
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep}>Back</Button>
                )}
                <Button variant="ghost" onClick={handleExitClick}>Exit to Dashboard</Button>
            </div>
            <div className="flex items-center space-x-2 w-full sm:w-auto">
              {showDraftButton && (
                <Button variant="ghost" onClick={handleSaveDraftClick}>Save as Draft</Button>
              )}

              {!isLastStep && (
                <Button onClick={nextStep} className="flex-1 sm:flex-auto justify-center">Next</Button>
              )}

              {isLastStep && (
                <Button onClick={handleSubmit} disabled={!state.acknowledgement} className="flex-1 sm:flex-auto justify-center">
                    Complete Order
                </Button>
              )}
            </div>
          </div>
      )}

      {isAdminEditing && (
        <div className="mt-8 pt-6 border-t border-slate-200 flex justify-between items-center no-print">
            <div>
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep}>Back</Button>
                )}
            </div>

            {!isLastStep && (
                <Button onClick={nextStep}>Next</Button>
            )}
        </div>
      )}

    </Card>
  );
};

export default ServiceForm;

import React, { useMemo } from 'react';
import { Service, ServiceTemplate } from '../types';
import Card from './ui/Card';
import Button from './ui/Button';
import { IconPrint } from './ui/Icon';
import Checkbox from './ui/Checkbox';

interface Props {
  state: Service;
  updateField: <K extends keyof Service>(field: K, value: Service[K]) => void;
  serviceTemplates: ServiceTemplate[];
}

interface PurchaseItem {
    description: string;
    qty: number;
    price: number;
}

export const SummaryStep: React.FC<Props> = ({ state, updateField, serviceTemplates }) => {
  const purchaseItems: PurchaseItem[] = useMemo(() => {
    const items: PurchaseItem[] = [];

    // Car Washing Service
    if (state.serviceSelection.includes("Car Washing") && state.carWashDetails) {
        items.push({
            description: `Car Washing: ${state.carWashDetails.washType} ${state.isSubscription ? '(Subscription)' : ''}`,
            qty: 1,
            price: state.carWashDetails.price,
        });
    }

    // Car Care Service
    if (state.serviceSelection.includes("Car Care") && state.carCareDetails) {
        items.push({
            description: `Car Care: ${state.carCareDetails.careType}`,
            qty: 1,
            price: state.carCareDetails.price,
        });
    }

    // Tyre Replacement Service (itemized)
    if (state.serviceSelection.includes("Tyre Replacement")) {
        if (state.tyreReplacementTotalAmount > 0) {
             items.push({
                description: `Tyre Replacement`,
                qty: state.tyreReplacementQuantity,
                price: state.tyreReplacementTotalAmount
            });
        }
    }

    // Battery Replacement Service (itemized)
    if (state.serviceSelection.includes("Battery Replacement")) {
        state.batteryDetails.forEach(battery => {
            const netAmount = (battery.newBatteryAmount || 0) - (battery.exchangeValue || 0);
            if (netAmount > 0) {
                items.push({
                    description: `Battery: ${battery.brand || 'Unspecified Brand'}`,
                    qty: 1,
                    price: netAmount,
                });
            }
        });
    }

    // Dynamic Add-ons
    (state.dynamicAddons || []).forEach(item => {
        if (item.quantity > 0) {
            items.push({
                description: item.name,
                qty: item.quantity,
                price: item.quantity * item.price,
            });
        }
    });


    // Categorized (Custom) Add-ons
    state.categorizedAddons.forEach(addon => {
        if (addon.amount > 0 && addon.quantity > 0) {
            items.push({
                description: `${addon.productName} (${addon.category})`,
                qty: addon.quantity,
                price: addon.quantity * addon.amount,
            });
        }
    });


    // Custom Services (itemized)
    state.customServices.forEach(custom => {
        if (custom.amount > 0) {
            items.push({
                description: custom.serviceDescription || 'Custom Service',
                qty: 1,
                price: custom.amount,
            });
        }
    });

    return items;
  }, [state]);

  const customFieldDetails = useMemo(() => {
        if (!state.customFieldData || state.customFieldData.length === 0) return null;

        const allCustomFields = serviceTemplates.flatMap(st => st.customFields);

        return state.customFieldData.map(data => {
            const fieldDef = allCustomFields.find(f => f.id === data.fieldId);
            if (!fieldDef || !data.value) return null;

            let displayValue: React.ReactNode = data.value;
            if (fieldDef.type === 'PHOTO' && typeof data.value === 'string') {
                displayValue = <a href={data.value} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:underline">View Photo</a>;
            }

            return {
                label: fieldDef.label,
                value: displayValue
            };
        }).filter(Boolean);
    }, [state.customFieldData, serviceTemplates]);


  const DetailItem: React.FC<{ label: string; value: string | React.ReactNode }> = ({ label, value }) => (
      <div>
          <dt className="text-sm font-medium text-slate-500">{label}</dt>
          <dd className="text-base font-semibold text-slate-800 break-words">{value}</dd>
      </div>
  );

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-8 printable-area">
      {/* Customer Details */}
      <Card title="Customer Details" className="print:shadow-none print:border">
          <dl className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-4">
              <DetailItem label="Name" value={`${state.customerFirstName} ${state.customerLastName}`} />
              <DetailItem label="Mobile Number" value={state.mobileNumber} />
              <DetailItem label="Car" value={`${state.carBrandModel} (${state.carNumber})`} />
               <DetailItem label="Vehicle Category" value={state.vehicleCategoryTag} />
              <DetailItem label="Address" value={state.streetAddress} />
          </dl>
      </Card>

      {/* Purchase Summary */}
      <Card title="Purchase Summary" className="print:shadow-none print:border relative">
          <div className="absolute top-4 right-4 no-print">
            <Button onClick={handlePrint} variant="ghost">
                <IconPrint className="w-5 h-5 mr-2" />
                Print Summary
            </Button>
          </div>
          <div className="overflow-x-auto">
            <div className="flow-root">
                <table className="min-w-full">
                    <thead className="bg-slate-50">
                        <tr>
                            <th scope="col" className="py-3.5 pl-4 pr-3 text-left text-sm font-semibold text-slate-900 sm:pl-6">Item / Service</th>
                            <th scope="col" className="px-3 py-3.5 text-center text-sm font-semibold text-slate-900">Quantity</th>
                            <th scope="col" className="px-3 py-3.5 text-right text-sm font-semibold text-slate-900">Price</th>
                        </tr>
                    </thead>
                    <tbody className="bg-white">
                        {purchaseItems.map((item, index) => (
                            <tr key={index} className="even:bg-slate-50 border-b border-slate-200 last:border-b-0">
                                <td className="w-full max-w-0 py-4 pl-4 pr-3 text-sm font-medium text-slate-900 sm:w-auto sm:max-w-none sm:pl-6">{item.description}</td>
                                <td className="px-3 py-4 text-sm text-center text-slate-500">{item.qty}</td>
                                <td className="px-3 py-4 text-sm text-right text-slate-500">₹{item.price.toFixed(2)}</td>
                            </tr>
                        ))}
                        {purchaseItems.length === 0 && (
                            <tr>
                                <td colSpan={3} className="text-center py-10 text-slate-500">No services or products selected.</td>
                            </tr>
                        )}
                    </tbody>
                    <tfoot>
                        <tr className="border-t-2 border-slate-300">
                            <th scope="row" colSpan={2} className="pl-4 pr-3 pt-4 text-right text-base font-bold text-slate-900 sm:pl-6">Grand Total</th>
