                        {rows.map(row => (
                            <tr key={row} className="hover:bg-slate-50">
                                <td className="px-3 py-4 text-sm font-medium text-slate-900 sticky left-0 bg-white hover:bg-slate-50 z-10 border-r border-slate-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]">
