import React, { useMemo } from 'react';
import { Service, ServiceTemplate } from '../types';
import Card from './ui/Card';
import Button from './ui/Button';
import { IconPrint } from './ui/Icon';
import Checkbox from './ui/Checkbox';

interface Props {
  state: Service;
  updateField: <K extends keyof Service>(field: K, value: Service[K]) => void;
  serviceTemplates: ServiceTemplate[];
}

interface PurchaseItem {
    description: string;
    qty: number;
    price: number;
}

export const SummaryStep: React.FC<Props> = ({ state, updateField, serviceTemplates }) => {
  const purchaseItems: PurchaseItem[] = useMemo(() => {
    const items: PurchaseItem[] = [];

    // Car Washing Service
    if (state.serviceSelection.includes("Car Washing") && state.carWashDetails) {
        items.push({
            description: `Car Washing: ${state.carWashDetails.washType} ${state.isSubscription ? '(Subscription)' : ''}`,
            qty: 1,
            price: state.carWashDetails.price,
        });
    }

    // Car Care Service
    if (state.serviceSelection.includes("Car Care") && state.carCareDetails) {
        items.push({
            description: `Car Care: ${state.carCareDetails.careType}`,
            qty: 1,
            price: state.carCareDetails.price,
        });
    }

    // Tyre Replacement Service (itemized)
    if (state.serviceSelection.includes("Tyre Replacement")) {
        if (state.tyreReplacementTotalAmount > 0) {
             items.push({
                description: `Tyre Replacement`,
                qty: state.tyreReplacementQuantity,
                price: state.tyreReplacementTotalAmount
            });
        }
    }

    // Battery Replacement Service (itemized)
    if (state.serviceSelection.includes("Battery Replacement")) {
        state.batteryDetails.forEach(battery => {
            const netAmount = (battery.newBatteryAmount || 0) - (battery.exchangeValue || 0);
            if (netAmount > 0) {
                items.push({
                    description: `Battery: ${battery.brand || 'Unspecified Brand'}`,
                    qty: 1,
                    price: netAmount,
                });
            }
        });
    }

    // Dynamic Add-ons
    (state.dynamicAddons || []).forEach(item => {
        if (item.quantity > 0) {
            items.push({
                description: item.name,
                qty: item.quantity,
                price: item.quantity * item.price,
            });
        }
    });


    // Categorized (Custom) Add-ons
    state.categorizedAddons.forEach(addon => {
        if (addon.amount > 0 && addon.quantity > 0) {
            items.push({
                description: `${addon.productName} (${addon.category})`,
                qty: addon.quantity,
                price: addon.quantity * addon.amount,
            });
        }
    });


    // Custom Services (itemized)
    state.customServices.forEach(custom => {
        if (custom.amount > 0) {
            items.push({
                description: custom.serviceDescription || 'Custom Service',
                qty: 1,
                price: custom.amount,
            });
        }
    });

    return items;
  }, [state]);

  const customFieldDetails = useMemo(() => {
        if (!state.customFieldData || state.customFieldData.length === 0) return null;

        const allCustomFields = serviceTemplates.flatMap(st => st.customFields);

        return state.customFieldData.map(data => {
            const fieldDef = allCustomFields.find(f => f.id === data.fieldId);
            if (!fieldDef || !data.value) return null;

            let displayValue: React.ReactNode = data.value;
            if (fieldDef.type === 'PHOTO' && typeof data.value === 'string') {
                displayValue = <a href={data.value} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:underline">View Photo</a>;
            }

            return {
                label: fieldDef.label,
                value: displayValue
            };
        }).filter(Boolean);
    }, [state.customFieldData, serviceTemplates]);


  const DetailItem: React.FC<{ label: string; value: string | React.ReactNode }> = ({ label, value }) => (
      <div>
          <dt className="text-sm font-medium text-slate-500">{label}</dt>
          <dd className="text-base font-semibold text-slate-800 break-words">{value}</dd>
      </div>
  );

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-8 printable-area">
      {/* Customer Details */}
      <Card title="Customer Details" className="print:shadow-none print:border">
          <dl className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-4">
              <DetailItem label="Name" value={`${state.customerFirstName} ${state.customerLastName}`} />
              <DetailItem label="Mobile Number" value={state.mobileNumber} />
              <DetailItem label="Car" value={`${state.carBrandModel} (${state.carNumber})`} />
               <DetailItem label="Vehicle Category" value={state.vehicleCategoryTag} />
              <DetailItem label="Address" value={state.streetAddress} />
          </dl>
      </Card>

      {/* Purchase Summary */}
      <Card title="Purchase Summary" className="print:shadow-none print:border relative">
          <div className="absolute top-4 right-4 no-print">
            <Button onClick={handlePrint} variant="ghost">
                <IconPrint className="w-5 h-5 mr-2" />
                Print Summary
            </Button>
          </div>
          <div className="overflow-x-auto">
            <div className="flow-root">
                <table className="min-w-full">
                    <thead className="bg-slate-50">
                        <tr>
                            <th scope="col" className="py-3.5 pl-4 pr-3 text-left text-sm font-semibold text-slate-900 sm:pl-6">Item / Service</th>
                            <th scope="col" className="px-3 py-3.5 text-center text-sm font-semibold text-slate-900">Quantity</th>
                            <th scope="col" className="px-3 py-3.5 text-right text-sm font-semibold text-slate-900">Price</th>
                        </tr>
                    </thead>
                    <tbody className="bg-white">
                        {purchaseItems.map((item, index) => (
                            <tr key={index} className="even:bg-slate-50 border-b border-slate-200 last:border-b-0">
                                <td className="w-full max-w-0 py-4 pl-4 pr-3 text-sm font-medium text-slate-900 sm:w-auto sm:max-w-none sm:pl-6">{item.description}</td>
                                <td className="px-3 py-4 text-sm text-center text-slate-500">{item.qty}</td>
                                <td className="px-3 py-4 text-sm text-right text-slate-500">₹{item.price.toFixed(2)}</td>
                            </tr>
                        ))}
                        {purchaseItems.length === 0 && (
                            <tr>
                                <td colSpan={3} className="text-center py-10 text-slate-500">No services or products selected.</td>
                            </tr>
                        )}
                    </tbody>
                    <tfoot>
                        <tr className="border-t-2 border-slate-300">
                            <th scope="row" colSpan={2} className="pl-4 pr-3 pt-4 text-right text-base font-bold text-slate-900 sm:pl-6">Grand Total</th>
                            <td className="pl-3 pr-4 pt-4 text-right text-base font-bold text-slate-900 sm:pr-6">₹{state.grandTotal.toFixed(2)}</td>
                        </tr>
                    </tfoot>
                </table>
            </div>
          </div>
          {customFieldDetails && customFieldDetails.length > 0 && (
            <div className="mt-6 pt-4 border-t border-slate-200">
                 <h4 className="text-md font-semibold text-slate-800">Service-Specific Details</h4>
                 <dl className="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-3">
                    {customFieldDetails.map(detail => detail && <DetailItem key={detail.label} label={detail.label} value={detail.value} />)}
                 </dl>
            </div>
          )}
      </Card>

      {/* Acknowledgement */}
      <div className="mt-6 no-print">
        <Checkbox
          id="acknowledgement"
          checked={state.acknowledgement}
          onChange={(checked) => updateField('acknowledgement', checked)}
          label="I acknowledge that all the information entered is correct and have verified the details with the customer before final submission."
        />
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Service, ServiceStatus, User, UserSubscription, ServiceTemplate, Permission, TyreData, PricingConfig } from '../types';
import { useServiceForm } from '../hooks/useServiceForm';
import CustomerDetailsStep from './CustomerDetailsStep';
import ServiceSelectionStep from './ServiceSelectionStep';
import { ServiceDetailsStep } from './ServiceDetailsStep';
import AddonsStep from './AddonsStep';
import CustomServicesStep from './CustomServicesStep';
import { SummaryStep } from './SummaryStep';
import Stepper from './Stepper';
import Card from './ui/Card';
import Button from './ui/Button';
import Input from './ui/Input';
import { APPOINTMENT_TIME_SLOTS, DEFAULT_PRICING_CONFIG } from '../constants';
import { validateStep, ValidationErrors } from '../services/validationService';
import { IconDeviceFloppy } from './ui/Icon';
import DependencyManager from './DependencyManager';
import CarCareStep from './CarCareStep';

interface ServiceFormProps {
  initialService?: Service | null;
  allSubmissions: Service[];
  onComplete: (service: Service) => void;
  onSaveDraft: (service: Service) => void;
  onAdminUpdate?: (service: Service) => void;
  onExit: () => void;
  googleDriveUploadUrl: string;
  currentUser: User;
  allUsers: Omit<User, 'password'>[];
  userSubscriptions: UserSubscription[];
  serviceTemplates: ServiceTemplate[];
  vehicleData: Record<string, string[]>;
  tyreData: TyreData;
  onUpdateVehicleData: (brand: string, model: string) => void;
  onUpdateTyreData: (type: keyof TyreData, value: string) => void;
  pricingConfig?: PricingConfig;
}

const ALL_STEPS = [
  { name: 'Customer Details', component: CustomerDetailsStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Service Selection', component: ServiceSelectionStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { 
    name: 'Car Care', 
    component: CarCareStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.includes("Car Care")
  },
  { 
    name: 'Service Details', 
    component: ServiceDetailsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.some(s => 
        ["Car Washing", "Tyre Replacement", "Battery Replacement"].includes(s)
      ) || state.serviceSelection.some(s => serviceTemplates.find(t => t.name === s && t.customFields.length > 0))
  },
  { 
    name: 'Add-ons', 
    component: AddonsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true
  },
  { name: 'Custom Services', component: CustomServicesStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Invoice Summary', component: SummaryStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
];

const ServiceForm: React.FC<ServiceFormProps> = ({ 
  initialService, 
  allSubmissions,
  onComplete, 
  onSaveDraft,
  onAdminUpdate,
  onExit, 
  googleDriveUploadUrl, 
  currentUser, 
  allUsers, 
  userSubscriptions,
  serviceTemplates,
  vehicleData,
  tyreData,
  onUpdateVehicleData,
  onUpdateTyreData,
  pricingConfig = DEFAULT_PRICING_CONFIG,
}) => {
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const { state, dispatch, updateField } = useServiceForm(initialService, pricingConfig);
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [prefillServiceId, setPrefillServiceId] = useState('');
  const [saveConfirmation, setSaveConfirmation] = useState('');

  const isAdminEditing = useMemo(() => 
    currentUser.permissions.includes(Permission.CAN_EDIT_ANY_ORDER) && !!initialService,
  [currentUser, initialService]);

  useEffect(() => {
    if (initialService) {
      dispatch({ type: 'SET_FORM_DATA', payload: JSON.parse(JSON.stringify(initialService)) });
    }
  }, [initialService, dispatch]);


  const sortedSubmissions = useMemo(() => {
    return [...allSubmissions].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [allSubmissions]);

  const handlePrefillChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedId = e.target.value;
    setPrefillServiceId(selectedId);

    if (!selectedId) return;

    const serviceToCopy = allSubmissions.find(s => s.submissionId === selectedId);
    if (!serviceToCopy) return;

    const newSubmissionId = `SUB-${Date.now()}`;
    const newServiceData: Service = {
      ...JSON.parse(JSON.stringify(serviceToCopy)),
      submissionId: newSubmissionId,
      appointmentId: newSubmissionId,
      timestamp: new Date().toISOString(),
      status: ServiceStatus.Draft,
      acknowledgement: false,
      beforeWashingPhoto: '', beforeVideoInventory: '', beforeVideoTopBody: '', beforeVideoUnderchassis: '',
      afterWashingPhoto: '', afterVideoInterior: '', afterVideoExterior: '', afterVideoUnderchassis: '',
      tyreDetails: [],
      batteryDetails: [],
      customFieldData: (serviceToCopy.customFieldData || []).filter(field => {
          const allCustomFields = serviceTemplates.flatMap(st => st.customFields);
          const fieldDef = allCustomFields.find(f => f.id === field.fieldId);
          return fieldDef?.type !== 'PHOTO';
      }),
      assignedTo: undefined,
      scheduledDate: undefined,
      scheduledTime: undefined,
      internalNotes: '',
      isFollowUp: true,
      dependsOn: [], // Dependencies should not be copied
    };

    dispatch({ type: 'SET_FORM_DATA', payload: newServiceData });
  };


  const visibleSteps = useMemo(() => {
    return ALL_STEPS.map((step, index) => ({...step, originalIndex: index}))
                     .filter(step => step.isVisible(state, serviceTemplates));
  }, [state, serviceTemplates]);

  const StepComponent = visibleSteps[currentStepIndex].component;

  const handleStepClick = (index: number) => {
    if (isAdminEditing || index < currentStepIndex) {
      setErrors({}); 
      setCurrentStepIndex(index);
    }
  };

  const nextStep = () => {
    const currentStepName = visibleSteps[currentStepIndex].name;
    const validationErrors = validateStep(currentStepName, state);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      setCurrentStepIndex(prev => Math.min(prev + 1, visibleSteps.length - 1));
    }
  };

  const prevStep = () => {
    setErrors({}); 
    setCurrentStepIndex(prev => Math.max(prev - 1, 0));
  };

  const handleSubmit = () => {
    if (state.acknowledgement) {
      localStorage.removeItem('service_form_in_progress');
      onComplete(state);
    }
  };

  const handleSaveDraftClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onSaveDraft(state);
  };

  const handleAdminSave = () => {
    if (!onAdminUpdate) return;
    onAdminUpdate(state);
    setSaveConfirmation('Changes saved successfully!');
    setTimeout(() => setSaveConfirmation(''), 2500);
  };

  const handleExitClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onExit();
  };

  const handleUpdateDependencies = useCallback((newDeps: string[]) => {
    updateField('dependsOn', newDeps);
  }, [updateField]);

  const isLastStep = currentStepIndex === visibleSteps.length - 1;

  const showDraftButton = (!initialService || initialService?.status === ServiceStatus.Draft);

  return (
    <Card>
      {!initialService && (
        <div className="p-4 mb-8 bg-slate-50 border border-slate-200 rounded-lg no-print">
          <label htmlFor="prefill-select" className="block text-sm font-medium text-slate-700 mb-1">
            Pre-fill from Existing Service (Optional)
          </label>
          <select
            id="prefill-select"
            value={prefillServiceId}
            onChange={handlePrefillChange}
            className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus-visible:border-brand-accent sm:text-sm"
          >
            <option value="">-- Select a past service to copy data from --</option>
            {sortedSubmissions.map(s => (
              <option key={s.submissionId} value={s.submissionId}>
                {new Date(s.timestamp).toLocaleDateString()} - #{s.appointmentId?.split('-').pop()} - {s.customerFirstName} ({s.carNumber})
              </option>
            ))}
          </select>
        </div>
      )}

      <div className="mb-8 pb-4 border-b border-slate-200 no-print">
        <Stepper 
          steps={visibleSteps} 
          currentStepIndex={currentStepIndex} 
          onStepClick={handleStepClick}
          isClickable={isAdminEditing}
        />
      </div>

      {isAdminEditing && (
        <div className="sticky top-[63px] bg-slate-100/80 backdrop-blur-md z-20 -mx-6 px-6 -mt-8 mb-8">
            <div className="flex justify-between items-center h-16 border-b">
                 <Button variant="ghost" onClick={handleExitClick}>Exit to Dashboard</Button>
                 <div className="flex items-center space-x-4">
                    {saveConfirmation && <p className="text-sm font-semibold text-green-600 animate-pulse">{saveConfirmation}</p>}
                    <Button onClick={handleAdminSave}>
                        <IconDeviceFloppy className="w-5 h-5 mr-2" />
                        Save Changes
                    </Button>
                 </div>
            </div>
        </div>
      )}

      {isAdminEditing && (
        <div className="p-4 mb-8 bg-blue-50 border border-blue-200 rounded-lg">
          <h3 className="text-lg font-semibold text-blue-800 mb-4">Admin Controls</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label htmlFor="assignedTo" className="block text-sm font-medium text-slate-700 mb-1">Assigned User</label>
              <select
                id="assignedTo"
                name="assignedTo"
                value={state.assignedTo || ''}
                onChange={(e) => updateField('assignedTo', e.target.value || undefined)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                <option value="">-- Unassigned --</option>
                {allUsers.map(u => <option key={u.username} value={u.username}>{u.username}</option>)}
              </select>
            </div>
            <Input 
                label="Scheduled Date" 
                id="scheduledDate"
                type="date"
                value={state.scheduledDate ? state.scheduledDate.split('T')[0] : ''}
                onChange={(e) => updateField('scheduledDate', e.target.value)}
            />
            <div>
              <label htmlFor="scheduledTime" className="block text-sm font-medium text-slate-700 mb-1">Scheduled Time</label>
              <select
                  id="scheduledTime"
                  name="scheduledTime"
                  value={state.scheduledTime || ''}
                  onChange={(e) => updateField('scheduledTime', e.target.value || undefined)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                  <option value="">-- No Time Set --</option>
                  {APPOINTMENT_TIME_SLOTS.map(time => (
                      <option key={time} value={time}>{time}</option>
                  ))}
              </select>
            </div>
             <div>
                <label htmlFor="status" className="block text-sm font-medium text-slate-700 mb-1">Status</label>
                <select
                    id="status"
                    name="status"
                    value={state.status}
                    onChange={(e) => updateField('status', e.target.value as ServiceStatus)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
                >
                    {Object.values(ServiceStatus).map(status => (
                        <option key={status} value={status}>{status}</option>
                    ))}
                </select>
            </div>
          </div>
           <div className="mt-6 pt-4 border-t">
              <DependencyManager 
                  service={state}
                  allSubmissions={allSubmissions}
                  onUpdateDependencies={handleUpdateDependencies}
              />
            </div>
        </div>
      )}

      {initialService && (currentUser.role === 'admin' || currentUser.role === 'manager' || currentUser.username === initialService.assignedTo) && (
        <div className="p-4 mb-8 bg-yellow-50 border border-yellow-200 rounded-lg">
            <h3 className="text-lg font-semibold text-yellow-800 mb-2">Internal Notes</h3>
            <p className="text-sm text-yellow-700 mb-4">These notes are only visible to administrators, managers, and the assigned service agent.</p>
            <textarea
                id="internalNotes"
                name="internalNotes"
                value={state.internalNotes || ''}
                onChange={(e) => updateField('internalNotes', e.target.value)}
                rows={3}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                placeholder="Add any internal remarks for this service (e.g., customer is particular about wheels, specific tool needed)..."
            />
        </div>
      )}

      <div className="min-h-[300px]">
        <h2 className="text-2xl font-bold text-slate-800 mb-6">{visibleSteps[currentStepIndex].name}</h2>
        {isLastStep ? (
          <SummaryStep state={state} updateField={updateField} serviceTemplates={serviceTemplates} />
        ) : (
          <StepComponent 
            state={state} 
            updateField={updateField} 
            dispatch={dispatch} 
            googleDriveUploadUrl={googleDriveUploadUrl}
            userSubscriptions={userSubscriptions}
            serviceTemplates={serviceTemplates}
            errors={errors}
            allSubmissions={allSubmissions}
            vehicleData={vehicleData}
            tyreData={tyreData}
            onUpdateVehicleData={onUpdateVehicleData}
            onUpdateTyreData={onUpdateTyreData}
            pricingConfig={pricingConfig}
          />
        )}
      </div>

      {!isAdminEditing && (
          <div className="mt-8 pt-6 border-t border-slate-200 flex flex-col-reverse gap-y-4 sm:flex-row sm:justify-between sm:items-center no-print">
            <div className="flex items-center space-x-2">
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep}>Back</Button>
                )}
                <Button variant="ghost" onClick={handleExitClick}>Exit to Dashboard</Button>
            </div>
            <div className="flex items-center space-x-2 w-full sm:w-auto">
              {showDraftButton && (
                <Button variant="ghost" onClick={handleSaveDraftClick}>Save as Draft</Button>
              )}

              {!isLastStep && (
                <Button onClick={nextStep} className="flex-1 sm:flex-auto justify-center">Next</Button>
              )}

              {isLastStep && (
                <Button onClick={handleSubmit} disabled={!state.acknowledgement} className="flex-1 sm:flex-auto justify-center">
                    Complete Order
                </Button>
              )}
            </div>
          </div>
      )}

      {isAdminEditing && (
        <div className="mt-8 pt-6 border-t border-slate-200 flex justify-between items-center no-print">
            <div>
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep}>Back</Button>
                )}
            </div>

            {!isLastStep && (
                <Button onClick={nextStep}>Next</Button>
            )}
        </div>
      )}

    </Card>
  );
};

export default ServiceForm;

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { Customer, UserSubscription, ServiceTemplate, Service, VehicleCategoryTag, User } from '../../types';
import Button from '../ui/Button';
import Input from '../ui/Input';
import { APPOINTMENT_TIME_SLOTS, VEHICLE_CATEGORY_TAGS } from '../../constants';
import { IconTrophy, IconLoader, IconDeviceFloppy, IconTrash, IconCrosshair, IconMapPin, IconCheck } from '../ui/Icon';
import { findCustomerByMobile } from '../../services/customerService';
import VehicleSelector from '../VehicleSelector';
import { getCategoryForVehicle } from '../../services/vehicleService';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onCreateOrder: (details: { 
    customer: Pick<Customer, 'firstName' | 'lastName' | 'mobileNumber' | 'carNumber' | 'carBrandModel' | 'streetAddress' | 'customerEmail' | 'latitude' | 'longitude'>, 
    scheduledDate?: string, 
    scheduledTime?: string, 
    serviceSelection: string[], 
    vehicleCategoryTag?: VehicleCategoryTag,
    assignedTo?: string 
  }) => void;
  userSubscriptions: UserSubscription[];
  serviceTemplates: ServiceTemplate[];
  allSubmissions: Service[];
  vehicleData: Record<string, string[]>;
  users: Omit<User, 'password'>[];
}

// Stable no-op function to prevent re-renders in VehicleSelector
const noOp = () => {};

const DRAFT_KEY = 'create_order_modal_draft';

const CreateOrderModal: React.FC<Props> = ({ isOpen, onClose, onCreateOrder, userSubscriptions, serviceTemplates, allSubmissions, vehicleData, users }) => {
  const [customer, setCustomer] = useState<Pick<Customer, 'firstName' | 'lastName' | 'mobileNumber' | 'carNumber' | 'carBrandModel' | 'streetAddress' | 'customerEmail' | 'latitude' | 'longitude'>>(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).customer : { firstName: '', lastName: '', mobileNumber: '', carNumber: '', carBrandModel: '', streetAddress: '', customerEmail: '', latitude: undefined, longitude: undefined };
  });

  const [scheduledDate, setScheduledDate] = useState(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).scheduledDate : '';
  });

  const [scheduledTime, setScheduledTime] = useState(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).scheduledTime : '';
  });

  const [serviceSelection, setServiceSelection] = useState<string[]>(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).serviceSelection : [];
  });

  const [vehicleCategoryTag, setVehicleCategoryTag] = useState<VehicleCategoryTag | undefined>(() => {
     const saved = localStorage.getItem(DRAFT_KEY);
     return saved ? JSON.parse(saved).vehicleCategoryTag : undefined;
  });

  const [assignedTo, setAssignedTo] = useState<string>(() => {
      const saved = localStorage.getItem(DRAFT_KEY);
      return saved ? JSON.parse(saved).assignedTo || '' : '';
  });

  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [isSearching, setIsSearching] = useState(false);
  const [searchMessage, setSearchMessage] = useState('');
  const searchTimeoutRef = useRef<number | null>(null);
  const [foundProfiles, setFoundProfiles] = useState<Awaited<ReturnType<typeof findCustomerByMobile>> | null>(null);
  const [isGettingLocation, setIsGettingLocation] = useState(false);


  useEffect(() => {
    const draftData = {
        customer,
        scheduledDate,
        scheduledTime,
        serviceSelection,
        vehicleCategoryTag,
        assignedTo
    };
    localStorage.setItem(DRAFT_KEY, JSON.stringify(draftData));
  }, [customer, scheduledDate, scheduledTime, serviceSelection, vehicleCategoryTag, assignedTo]);

  useEffect(() => {
    if (customer.carBrandModel) {
        const detectedCategory = getCategoryForVehicle(customer.carBrandModel);
        if (vehicleCategoryTag !== detectedCategory && !vehicleCategoryTag) {
            setVehicleCategoryTag(detectedCategory);
        }
    }
  }, [customer.carBrandModel]);

  useEffect(() => {
    if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);

    const mobileNumber = customer.mobileNumber;
    if (mobileNumber.trim().length < 10) {
      setSearchMessage('');
      setIsSearching(false);
      if (mobileNumber.trim().length === 0) setFoundProfiles(null);
      return;
    }

    setIsSearching(true);
    setSearchMessage('');

    searchTimeoutRef.current = window.setTimeout(async () => {
      const profiles = await findCustomerByMobile(mobileNumber, allSubmissions, userSubscriptions);
      setIsSearching(false);
      if (profiles && profiles.length > 0) {
        if (profiles.length === 1) {
            setCustomer(prev => ({ ...prev, ...profiles[0].customer }));
            setFoundProfiles(null);
            if (profiles[0].isSubscriber) {
                setSearchMessage(`Subscriber found! Washes Left: ${profiles[0].washesRemaining}.`);
            } else {
                setSearchMessage('Existing customer found. Details pre-filled.');
            }
        } else {
            setFoundProfiles(profiles);
            const firstProfile = profiles[0].customer;
            setCustomer(prev => ({
                ...prev,
                firstName: firstProfile.firstName,
                lastName: firstProfile.lastName,
                streetAddress: firstProfile.streetAddress,
                customerEmail: firstProfile.customerEmail,
                carNumber: '',
                carBrandModel: '',
            }));
            setSearchMessage(`${profiles.length} vehicles found. Please select one.`);
        }
      } else {
        setSearchMessage('New customer.');
        setFoundProfiles(null);
      }
    }, 500); 

    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, [customer.mobileNumber, allSubmissions, userSubscriptions]);

  const handleVehicleChange = useCallback((value: string) => {
    setCustomer(prev => ({...prev, carBrandModel: value}));
    if (errors.carBrandModel) {
        setErrors(p => {
            const newErrors = { ...p };
            delete newErrors.carBrandModel;
            return newErrors;
        });
    }
  }, [errors.carBrandModel]);

  const handleGetLocation = () => {
    if (!navigator.geolocation) {
        alert("Geolocation is not supported by this browser.");
        return;
    }
    setIsGettingLocation(true);
    navigator.geolocation.getCurrentPosition(
        (position) => {
            setCustomer(prev => ({
                ...prev,
                latitude: position.coords.latitude,
                longitude: position.coords.longitude
            }));
            setIsGettingLocation(false);
        },
        (error) => {
            console.error("Error getting location", error);
            alert("Unable to retrieve location. Please ensure location services are enabled.");
            setIsGettingLocation(false);
        },
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  if (!isOpen) return null;

  const handleCarSelection = (profile: any) => {
    setCustomer(prev => ({ ...prev, ...profile.customer }));
    setFoundProfiles(null); 
  };

  const handleCustomerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    if (name === 'mobileNumber') {
      const sanitized = value.replace(/[^0-9+]/g, '').replace(/(?!^)\+/g, '');
      if (sanitized.length <= 15) {
          setCustomer(prev => ({ ...prev, mobileNumber: sanitized }));
      }
    } else {
      setCustomer(prev => ({ ...prev, [name]: value }));
    }

    if (errors[name]) {
        setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleToggleService = (selection: string) => {
    const newSelections = serviceSelection.includes(selection)
      ? serviceSelection.filter(s => s !== selection)
      : [...serviceSelection, selection];
    setServiceSelection(newSelections);
  };

  const clearForm = () => {
      if(window.confirm("Are you sure you want to clear all fields? This cannot be undone.")) {
          setCustomer({ firstName: '', lastName: '', mobileNumber: '', carNumber: '', carBrandModel: '', streetAddress: '', customerEmail: '', latitude: undefined, longitude: undefined});
          setScheduledDate('');
          setScheduledTime('');
          setServiceSelection([]);
          setVehicleCategoryTag(undefined);
          setAssignedTo('');
          setErrors({});
          setSearchMessage('');
          localStorage.removeItem(DRAFT_KEY);
      }
  }

  const handleSubmit = () => {
    const newErrors: { [key: string]: string } = {};

    if (!customer.firstName.trim()) newErrors.firstName = 'First Name is required.';
    if (!customer.mobileNumber.trim()) newErrors.mobileNumber = 'Mobile Number is required.';
    if (!customer.carNumber.trim()) newErrors.carNumber = 'Car Number is required.';
    if (!customer.carBrandModel.trim()) newErrors.carBrandModel = 'Car Brand & Model are required.';

    if (scheduledDate) {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const selected = new Date(scheduledDate);
        const userTimezoneOffset = selected.getTimezoneOffset() * 60000;
        const localSelectedDate = new Date(selected.getTime() + userTimezoneOffset);

        if (localSelectedDate < today) {
            newErrors.scheduledDate = 'Scheduled date cannot be in the past.';
        }
    }

    setErrors(newErrors);

    if (Object.keys(newErrors).length > 0) {
      return;
    }

    onCreateOrder({ customer, scheduledDate, scheduledTime, serviceSelection, vehicleCategoryTag, assignedTo });
    localStorage.removeItem(DRAFT_KEY);
    setCustomer({ firstName: '', lastName: '', mobileNumber: '', carNumber: '', carBrandModel: '', streetAddress: '', customerEmail: '', latitude: undefined, longitude: undefined});
    setScheduledDate('');
    setScheduledTime('');
    setServiceSelection([]);
    setAssignedTo('');
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-60 flex items-start sm:items-center justify-center z-50 p-4 pt-8 sm:pt-4 modal-backdrop" onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-lg bg-white rounded-xl shadow-md flex flex-col max-h-[90vh] modal-content">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex-shrink-0 flex justify-between items-center">
          <h3 className="text-lg font-semibold text-slate-800">Create New Service Order</h3>
          <button onClick={clearForm} className="text-xs text-red-600 hover:text-red-800 flex items-center">
              <IconTrash className="w-3 h-3 mr-1"/> Clear Form
          </button>
        </div>

        <div className="overflow-y-auto p-6">
            <div className="mb-4 bg-blue-50 border-l-4 border-blue-400 p-3 rounded text-xs text-blue-800 flex items-start">
                 <IconDeviceFloppy className="w-4 h-4 mr-2 mt-0.5 flex-shrink-0"/>
                 <p><strong>Smart Draft:</strong> Your data is saved automatically as you type. If you refresh or close this window, your progress will be restored.</p>
            </div>

          <div className="space-y-6">
            <div>
              <h3 className="text-md font-semibold text-slate-700 mb-2">Customer & Vehicle Details</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <Input 
                    label="Mobile Number" name="mobileNumber" type="tel" value={customer.mobileNumber} onChange={handleCustomerChange} 
                    required error={errors.mobileNumber} maxLength={15} prefix="+91" 
                    suffix={isSearching ? <IconLoader className="w-5 h-5 text-slate-400 animate-spin" /> : undefined}
                  />
                  {searchMessage && !isSearching && !foundProfiles && <p className={`mt-1 text-xs font-semibold ${searchMessage.includes('Subscriber') ? 'text-green-600' : searchMessage.includes('found') ? 'text-blue-600' : 'text-slate-500'}`}>{searchMessage}</p>}
                </div>
                <Input label="First Name" name="firstName" value={customer.firstName} onChange={handleCustomerChange} required error={errors.firstName} />
                <Input label="Last Name" name="lastName" value={customer.lastName} onChange={handleCustomerChange} />
                <Input label="Email (Optional)" name="customerEmail" type="email" value={customer.customerEmail || ''} onChange={handleCustomerChange} />
                 {foundProfiles ? (
                    <div className="sm:col-span-2 space-y-2">
                        <p className="text-sm font-semibold text-blue-700">{searchMessage}</p>
                        {foundProfiles.map((profile, index) => (
                            <button
                                key={index}
                                type="button"
                                onClick={() => handleCarSelection(profile)}
                                className="w-full text-left p-3 rounded-md border-2 bg-white hover:border-brand-accent focus:border-brand-accent focus:outline-none transition-colors"
                            >
                                <p className="font-semibold text-slate-800">{profile.customer.carBrandModel}</p>
                                <p className="text-slate-600">{profile.customer.carNumber}</p>
                            </button>
                        ))}
                    </div>
                ) : (
                    <>
                      <Input label="Car Number" name="carNumber" value={customer.carNumber} onChange={handleCustomerChange} required error={errors.carNumber} />
                        <div className="sm:col-span-2">
                            <VehicleSelector
                                value={customer.carBrandModel}
                                onChange={handleVehicleChange}
                                error={errors.carBrandModel}
                                vehicleData={vehicleData}
                                onUpdateVehicleData={noOp}
                            />
                        </div>
                    </>
                )}
                 <div>
                    <label htmlFor="vehicleCategoryTag" className="block text-sm font-medium text-slate-700 mb-1">
                        Vehicle Category
                    </label>
                    <select
                        id="vehicleCategoryTag"
                        value={vehicleCategoryTag || ''}
                        onChange={(e) => setVehicleCategoryTag(e.target.value as VehicleCategoryTag)}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm"
                    >
                        <option value="">-- Select Category --</option>
                        {VEHICLE_CATEGORY_TAGS.map(tag => (
                            <option key={tag} value={tag}>{tag}</option>
                        ))}
                    </select>
                </div>
                <Input label="Street Address" name="streetAddress" className="sm:col-span-2" value={customer.streetAddress} onChange={handleCustomerChange} />

                {/* Location Pinning UI */}
                <div className="sm:col-span-2 bg-slate-50 p-3 rounded-lg border border-slate-200">
                    <div className="flex items-center justify-between">
                         <div className="flex items-center space-x-2">
                             <div className={`p-1.5 rounded-full ${customer.latitude ? 'bg-green-100 text-green-600' : 'bg-slate-200 text-slate-400'}`}>
                                 <IconMapPin className="w-5 h-5" />
                             </div>
                             <div>
                                 <p className="text-sm font-medium text-slate-800">
                                    {customer.latitude ? 'Location Pinned' : 'Location Not Set'}
                                 </p>
                                 <p className="text-xs text-slate-500">
                                     {customer.latitude && customer.longitude 
                                        ? `${customer.latitude.toFixed(6)}, ${customer.longitude.toFixed(6)}` 
                                        : 'Capture customer exact location'}
                                 </p>
                             </div>
                         </div>
                         <div className="flex space-x-2">
                             {customer.latitude && (
                                 <a 
                                    href={`https://www.google.com/maps/search/?api=1&query=${customer.latitude},${customer.longitude}`} 
                                    target="_blank" 
                                    rel="noreferrer"
                                    className="px-3 py-1.5 text-xs font-medium text-blue-600 hover:text-blue-800 hover:underline"
                                 >
                                     Verify
                                 </a>
                             )}
                             <Button type="button" variant={customer.latitude ? "secondary" : "primary"} size="sm" onClick={handleGetLocation} disabled={isGettingLocation}>
                                {isGettingLocation ? <IconLoader className="w-4 h-4 animate-spin"/> : customer.latitude ? <IconCrosshair className="w-4 h-4 mr-1"/> : <IconMapPin className="w-4 h-4 mr-1"/>}
                                {customer.latitude ? 'Update Pin' : 'Pin Location'}
                             </Button>
                         </div>
                    </div>
                </div>

              </div>
              {searchMessage.includes('Subscriber') && !foundProfiles && (
                <div className="mt-4 p-3 bg-green-50 border border-green-200 rounded-lg flex items-center justify-center space-x-3">
                    <IconTrophy className="w-6 h-6 text-green-600 flex-shrink-0"/>
                    <p className="text-sm font-semibold text-green-800 text-center">{searchMessage}</p>
                </div>
              )}
            </div>

            <div className="pt-4 border-t">
              <h3 className="text-md font-semibold text-slate-700 mb-2">Assignment & Scheduling</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="sm:col-span-2">
                    <label htmlFor="assignedTo" className="block text-sm font-medium text-slate-700 mb-1">Assign To (Optional)</label>
                    <select
                        id="assignedTo"
                        name="assignedTo"
                        value={assignedTo}
                        onChange={(e) => setAssignedTo(e.target.value)}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm"
                    >
                        <option value="">-- Unassigned (Queue) --</option>
                        {users.filter(u => u.role !== 'admin' && u.role !== 'manager').map(u => (
                            <option key={u.username} value={u.username}>{u.username} ({u.role})</option>
                        ))}
                    </select>
                </div>
                <Input 
                    label="Scheduled Date" 
                    type="date" 
                    value={scheduledDate} 
                    onChange={(e) => {
                        setScheduledDate(e.target.value);
                        if (errors.scheduledDate) setErrors(p => ({...p, scheduledDate: ''}));
                    }}
                    error={errors.scheduledDate}
                />
                <div>
                    <label htmlFor="scheduledTime" className="block text-sm font-medium text-slate-700 mb-1">Scheduled Time</label>
                    <select
                        id="scheduledTime"
                        name="scheduledTime"
                        value={scheduledTime}
                        onChange={(e) => setScheduledTime(e.target.value)}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm"
                    >
                        <option value="">-- No Time Set --</option>
                        {APPOINTMENT_TIME_SLOTS.map(time => (
                            <option key={time} value={time}>{time}</option>
                        ))}
                    </select>
                </div>
              </div>
            </div>

            <div className="pt-4 border-t">
              <h3 className="text-md font-semibold text-slate-700 mb-2">Select Services</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {serviceTemplates.filter(t => t.isEnabled).map(template => {
                  const isSelected = serviceSelection.includes(template.name);
                  return (
                    <button
                      key={template.id}
                      type="button"
                      onClick={() => handleToggleService(template.name)}
                      className={`p-3 text-left rounded-lg border-2 transition-all duration-200 ${
                        isSelected 
                        ? 'bg-brand-accent/10 border-brand-accent' 
                        : 'bg-white border-slate-300 hover:border-brand-accent/70'
                      }`}
                    >
                      <div className="flex items-center justify-between">
                        <span className={`font-semibold text-sm ${isSelected ? 'text-brand-blue' : 'text-slate-700'}`}>{template.name}</span>
                        <div className={`w-5 h-5 rounded-full flex items-center justify-center border-2 ${isSelected ? 'bg-brand-accent border-brand-accent' : 'border-slate-300'}`}>
                          {isSelected && (
                            <svg className="w-3 h-3 text-brand-blue" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" />
                            </svg>
                          )}
                        </div>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>

        <div className="p-6 flex justify-end space-x-2 border-t border-slate-200 flex-shrink-0">
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button onClick={handleSubmit}>Create Order</Button>
        </div>
      </div>
    </div>
  );
};

export default CreateOrderModal;

import React, { useMemo, useState, useEffect } from 'react';
import { Service, ServiceStatus, User } from '../../types';
import Button from '../ui/Button';
import { IconBellRinging, IconClipboardList, IconClock, IconUser, IconEngine, IconPhone, IconLink, IconCheck, IconShare, IconReceipt, IconMapPin } from '../ui/Icon';
import { getUncompletedDependencies } from '../../services/dependencyService';

interface AppointmentCardProps {
  service: Service;
  currentUser: User;
  allSubmissions: Service[];
  onAssign?: () => void;
  onStart?: () => void;
  onUpdate?: () => void;
  onClaim?: () => void;
  onDelete?: () => void;
  onNotify?: () => void;
  onShareOrder?: (service: Service) => void;
  isOverdue?: boolean;
  isToday?: boolean;
}

export const AppointmentCard: React.FC<AppointmentCardProps> = ({ service, currentUser, allSubmissions, onAssign, onStart, onUpdate, onClaim, onDelete, onNotify, onShareOrder, isOverdue, isToday }) => {

  const [showCompletionAnimation, setShowCompletionAnimation] = useState(false);

  useEffect(() => {
    if (service.status === ServiceStatus.Completed) {
      setShowCompletionAnimation(true);
      const timer = setTimeout(() => setShowCompletionAnimation(false), 1500); // Animation duration
      return () => clearTimeout(timer);
    }
  }, [service.status]);

  const uncompletedDependencies = useMemo(() => getUncompletedDependencies(service, allSubmissions), [service, allSubmissions]);
  const canStart = onStart && uncompletedDependencies.length === 0;

  const statusConfig = {
    [ServiceStatus.Completed]: { bg: 'bg-green-100', text: 'text-green-800', border: 'border-green-400' },
    [ServiceStatus.InProgress]: { bg: 'bg-purple-100', text: 'text-purple-800', border: 'border-purple-400' },
    [ServiceStatus.Assigned]: { bg: 'bg-blue-100', text: 'text-blue-800', border: 'border-blue-400' },
    [ServiceStatus.Queued]: { bg: 'bg-slate-100', text: 'text-slate-800', border: 'border-slate-400' },
    [ServiceStatus.Draft]: { bg: 'bg-yellow-100', text: 'text-yellow-800', border: 'border-yellow-400' },
  };

  const isCompleted = service.status === ServiceStatus.Completed;
  const currentStatusConfig = statusConfig[service.status] || statusConfig.Draft;
  const isAdminOrManager = currentUser.role === 'admin' || currentUser.role === 'manager';
  const isDraggable = isAdminOrManager && service.status === ServiceStatus.Queued;
  const canNotify = isAdminOrManager && onNotify && service.status !== ServiceStatus.Completed && service.status !== ServiceStatus.Draft;
  const canViewNotes = service.internalNotes && (isAdminOrManager || currentUser.username === service.assignedTo);

  const cardBorderColor = isOverdue ? 'border-red-400' : isToday ? 'border-brand-accent' : currentStatusConfig.border;

  const canShare = onShareOrder && navigator.share && service.status !== ServiceStatus.Draft;
  const canCall = service.mobileNumber && service.status !== ServiceStatus.Draft;
  const hasActions = onAssign || onStart || onUpdate || onClaim || onDelete;

  // Check if location is pinned
  const hasLocation = !!(service.customerLatitude && service.customerLongitude);

  const serviceSummary = useMemo(() => {
    const services = service.serviceSelection.map(s => {
        if (s === 'Car Washing' && service.carWashDetails?.washType) {
            return service.carWashDetails.washType;
        }
         if (s === 'Car Care' && service.carCareDetails?.careType) {
            return service.carCareDetails.careType;
        }
        return s;
    });
    return services.join(', ') || 'N/A';
  }, [service.serviceSelection, service.carWashDetails, service.carCareDetails]);

  const renderAdminButtons = () => {
    return (
      <>
           {onDelete && <Button variant="danger" size="sm" onClick={onDelete}>Delete</Button>}
           {onUpdate && <Button variant="secondary" size="sm" onClick={onUpdate}>Edit</Button>}
           {service.status === ServiceStatus.Queued && onAssign && <Button onClick={onAssign} size="sm">Assign</Button>}
      </>
    );
  }

  const renderUserButtons = () => {
    const isAssignedToCurrentUser = service.assignedTo === currentUser.username;

    switch (service.status) {
      case ServiceStatus.Queued:
        return onClaim && <Button onClick={onClaim} size="sm">Claim Order</Button>;

      case ServiceStatus.Assigned:
        if (isAssignedToCurrentUser) {
          return (
            onStart && (
                <Button 
                  onClick={onStart} 
                  size="sm" 
                  disabled={!canStart}
                  title={!canStart ? `Blocked by prerequisite task(s): ${uncompletedDependencies.map(s => `#${s.appointmentId?.split('-').pop()}`).join(', ')}` : 'Start Order'}
                >
                  Start Order
                </Button>
            )
          );
        }
        return null;

      case ServiceStatus.InProgress:
        if (isAssignedToCurrentUser) {
           return onUpdate && <Button onClick={onUpdate} size="sm">Update Details</Button>;
        }
        return onUpdate && <Button onClick={onUpdate} size="sm">Update Details</Button>;

      case ServiceStatus.Completed:
           return <Button variant="ghost" disabled size="sm">Completed</Button>;
      default:
        return onUpdate && <Button variant="secondary" size="sm" onClick={onUpdate}>Edit</Button>;
    }
  }


  return (
    <div 
      className={`relative ${isCompleted ? 'bg-slate-100/50' : 'bg-white hover:shadow-md'} rounded-lg shadow-sm border-l-4 ${cardBorderColor} flex flex-col ${isDraggable ? 'cursor-grab' : ''} transition-all duration-300`}
      style={{ transition: 'background-color 500ms ease-in-out' }}
      draggable={isDraggable}
      onDragStart={isDraggable ? (e) => e.dataTransfer.setData('text/plain', service.submissionId) : undefined}
    >
      <div className="p-4 flex-grow">
         {canNotify && (
            <div className="absolute top-3 right-3 z-10">
                <Button 
                    size="sm" 
                    onClick={onNotify} 
                    className="p-2 h-9 w-9 rounded-full bg-slate-100 text-slate-500 hover:bg-brand-accent/20 hover:text-brand-accent transition-colors"
                    title="Send notification for this order"
                >
                    <IconBellRinging className="w-5 h-5" />
                </Button>
            </div>
        )}
        <div className="flex items-start justify-between">
            <div className="flex items-center space-x-3 flex-wrap gap-y-1">
              <h3 className="text-lg font-bold text-slate-800">{service.customerFirstName} {service.customerLastName}</h3>
              {service.appointmentId && <span className="text-sm font-mono text-brand-blue bg-blue-100 px-2 py-0.5 rounded-md">#{service.appointmentId.split('-').pop()}</span>}
              {isOverdue && <span className="text-xs font-semibold text-red-800 bg-red-100 px-2 py-0.5 rounded-full">Overdue</span>}
              {isToday && !isOverdue && <span className="text-xs font-semibold text-amber-800 bg-amber-100 px-2 py-0.5 rounded-full">Today</span>}
              {service.isAutoScheduled && (
                  <span title="This was automatically scheduled" className="text-xs font-semibold text-purple-800 bg-purple-100 px-2 py-0.5 rounded-full">Auto</span>
              )}
            </div>
             <span className={`px-3 py-1 text-xs font-semibold rounded-full flex-shrink-0 ml-2 flex items-center gap-1 ${currentStatusConfig.bg} ${currentStatusConfig.text}`}>
                {showCompletionAnimation && <IconCheck className="w-4 h-4 animate-check" />}
                <span>{service.status}</span>
            </span>
        </div>

        <div className="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-2 text-sm text-slate-600">
            <div className="flex items-center">
                <IconEngine className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0" />
                <span>{service.carBrandModel} ({service.carNumber})</span>
            </div>
            <div className="flex items-center">
                <IconUser className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0" />
                <span>Assigned to: <strong className="font-semibold">{service.assignedTo || 'Unassigned'}</strong></span>
            </div>
            {service.streetAddress && (
                <div className="flex items-start sm:col-span-2">
                    <IconMapPin className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0 mt-0.5" />
                    <span>{service.streetAddress}</span>
                </div>
            )}

            {hasLocation && (
                <div className="flex items-start sm:col-span-2 text-green-700">
                     <IconMapPin className="w-4 h-4 mr-2 flex-shrink-0 mt-0.5" />
                     <span className="font-medium text-xs bg-green-50 px-2 py-0.5 rounded-md border border-green-200">Exact Location Pinned</span>
                </div>
            )}

            <div className="flex items-start sm:col-span-2">
                <IconClipboardList className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0 mt-0.5" />
                <span>Services: <strong className="font-semibold">{serviceSummary}</strong></span>
            </div>
            <div className="flex items-center">
                <IconClock className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0" />
                <span>Scheduled: <strong className="font-semibold">{service.scheduledDate ? new Date(service.scheduledDate).toLocaleDateString() : 'N/A'} at {service.scheduledTime || 'N/A'}</strong></span>
            </div>
             <div className="flex items-center">
                <IconReceipt className="w-4 h-4 mr-2 text-slate-400 flex-shrink-0" />
                <span>Value: <strong className="font-bold text-slate-800">₹{service.grandTotal.toFixed(2)}</strong></span>
            </div>
        </div>

        {canViewNotes && (
            <div className="mt-3 p-2.5 bg-yellow-50 border-l-4 border-yellow-300 rounded-r-md flex items-start space-x-3">
                <IconClipboardList className="w-5 h-5 text-yellow-600 flex-shrink-0 mt-0.5" />
                <div>
                    <p className="text-xs font-bold text-yellow-800 uppercase tracking-wide">Internal Note</p>
                    <p className="text-sm text-yellow-900 whitespace-pre-wrap">{service.internalNotes}</p>
                </div>
            </div>
        )}
        {uncompletedDependencies.length > 0 && (
            <div className="mt-3 p-2.5 bg-amber-50 border-l-4 border-amber-300 rounded-r-md flex items-start space-x-3">
                <IconLink className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" />
                <div>
                    <p className="text-xs font-bold text-amber-800 uppercase tracking-wide">Blocked by Prerequisite</p>
                    <p className="text-sm text-amber-900">
                        Cannot be started until task(s) {uncompletedDependencies.map(dep => ` #${dep.appointmentId?.split('-').pop()}`).join(', ')} are complete.
                    </p>
                </div>
            </div>
        )}
      </div>

      {(hasActions || canShare || canCall || hasLocation) && (
         <div className="px-4 py-3 bg-slate-50/70 border-t border-slate-200">
            <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="flex items-center space-x-2">
                    {hasLocation && (
                         <a href={`https://www.google.com/maps/search/?api=1&query=${service.customerLatitude},${service.customerLongitude}`} target="_blank" rel="noopener noreferrer" aria-label="Navigate to customer">
                            <Button variant="secondary" size="sm" title="Navigate" className="px-2">
                                <IconMapPin className="w-4 h-4 mr-1.5" />
                                Map
                            </Button>
                         </a>
                    )}
                    {canShare && (
                        <Button variant="secondary" size="sm" onClick={() => onShareOrder!(service)} title="Share Order Details" className="px-2">
                            <IconShare className="w-4 h-4 mr-1.5" />
                            Share
                        </Button>
                    )}
                    {canCall && (
                       <a href={`tel:${service.mobileNumber}`} aria-label={`Call ${service.customerFirstName}`}>
                         <Button variant="secondary" size="sm" title="Call Customer" className="px-2">
                           <IconPhone className="w-4 h-4 mr-1.5" />
                           Call
                         </Button>
                       </a>
                    )}
                </div>
                <div className="flex items-center justify-end space-x-2">
                    {isAdminOrManager ? renderAdminButtons() : renderUserButtons()}
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default AppointmentCard;

import React, { useEffect, useRef, useMemo, useState } from 'react';
import { User, Service, ServiceStatus, LocationHistory } from '../../types';
import Card from '../ui/Card';
import Button from '../ui/Button';
import { IconRefresh } from '../ui/Icon';
import Input from '../ui/Input';

// Declare Leaflet 'L' to TypeScript to avoid errors, as it's loaded from a CDN
declare const L: any;

const truckIconSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" style="width: 20px; height: 20px; color: white;"><path d="M3.375 4.5C2.339 4.5 1.5 5.34 1.5 6.375V13.5h1.5v-1.125c0-1.036.84-1.875 1.875-1.875h13.5c1.035 0 1.875.84 1.875 1.875v1.125h1.5V6.375c0-1.036-.84-1.875-1.875-1.875h-13.5Z" /><path fill-rule="evenodd" d="M3 19.5a1.5 1.5 0 1 1 3 0 1.5 1.5 0 0 1-3 0Zm12 0a1.5 1.5 0 1 1 3 0 1.5 1.5 0 0 1-3 0ZM1.5 15a.75.75 0 0 0-.75.75v3c0 .414.336.75.75.75h1.5a.75.75 0 0 0 .75-.75v-3a.75.75 0 0 0-.75-.75h-1.5Zm12 0a.75.75 0 0 0-.75.75v3c0 .414.336.75.75.75h1.5a.75.75 0 0 0 .75-.75v-3a.75.75 0 0 0-.75-.75h-1.5Z" clip-rule="evenodd" /></svg>`;
const houseIconSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" style="width: 20px; height: 20px; color: white;"><path d="M11.47 3.84a.75.75 0 011.06 0l8.69 8.69a.75.75 0 101.06-1.06l-8.689-8.69a2.25 2.25 0 00-3.182 0l-8.69 8.69a.75.75 0 001.061 1.06l8.69-8.69z" /><path d="M12 5.432l8.159 8.159c.03.03.06.058.091.086v6.198c0 1.035-.84 1.875-1.875 1.875H15a.75.75 0 01-.75-.75v-4.5a.75.75 0 00-.75-.75h-3a.75.75 0 00-.75.75V21a.75.75 0 01-.75.75H5.625a1.875 1.875 0 01-1.875-1.875v-6.198a2.29 2.29 0 00.091-.086L12 5.43z" /></svg>`;

interface Props {
  users: Omit<User, 'password' | 'notificationPreferences' | 'pushSubscription'>[];
  currentUser: User;
  submissions: Service[];
  onRefresh: () => void;
  isRefreshing: boolean;
  locationHistory: LocationHistory[];
}

type AgentStatus = 'IDLE' | 'IN_PROGRESS' | 'BUSY' | 'OFFLINE';

const timeSince = (date: Date): string => {
    const seconds = Math.floor((new Date().getTime() - date.getTime()) / 1000);
    let interval = seconds / 31536000;
    if (interval > 1) return `${Math.floor(interval)}y ago`;
    interval = seconds / 2592000;
    if (interval > 1) return `${Math.floor(interval)}mo ago`;
    interval = seconds / 86400;
    if (interval > 1) return `${Math.floor(interval)}d ago`;
    interval = seconds / 3600;
    if (interval > 1) return `${Math.floor(interval)}h ago`;
    interval = seconds / 60;
    if (interval > 1) return `${Math.floor(interval)}m ago`;
    return `${Math.floor(seconds)}s ago`;
}

const parseServiceDateTime = (service: Service): Date | null => {
    if (!service.scheduledDate || !service.scheduledTime) return null;
    try {
        const timePart = service.scheduledTime.split(' - ')[0]; // e.g., "09:00"
        const dateOnly = service.scheduledDate.split('T')[0];
        const dateTimeString = `${dateOnly}T${timePart}:00`;
        const date = new Date(dateTimeString);
        return isNaN(date.getTime()) ? null : date;
    } catch (e) {
        console.error("Error parsing date/time for service:", service.submissionId, e);
        return null;
    }
};

const statusOptions: { id: AgentStatus, label: string, color: string, border: string }[] = [
    { id: 'IDLE', label: 'Idle', color: 'bg-blue-100', border: 'border-blue-400' },
    { id: 'IN_PROGRESS', label: 'In Progress', color: 'bg-purple-100', border: 'border-purple-400' },
    { id: 'BUSY', label: 'Busy', color: 'bg-orange-100', border: 'border-orange-400' },
    { id: 'OFFLINE', label: 'Offline', color: 'bg-slate-100', border: 'border-slate-400' },
];


const LiveMapPage: React.FC<Props> = ({ users, submissions, onRefresh, isRefreshing, locationHistory }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markersRef = useRef<{ [key: string]: any }>({});
  const jobMarkersRef = useRef<{ [key: string]: any }>({});
  const tripPolylineLayerRef = useRef<any>(null);

  const [selectedAgent, setSelectedAgent] = useState<string>('');
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [statusFilters, setStatusFilters] = useState<AgentStatus[]>(['IDLE', 'IN_PROGRESS', 'BUSY', 'OFFLINE']);


  const agentData = useMemo(() => {
    const now = new Date();
    const fifteenMinutesFromNow = new Date(now.getTime() + 15 * 60 * 1000);

    const calculatedData = users
      .filter(u => u.role !== 'admin' && u.role !== 'manager' && u.attendanceStatus === 'CHECKED_IN')
      .map(user => {
        let status: AgentStatus = 'IDLE';
        let relevantService: Service | undefined;

        if (user.lastLocationUpdate) {
            const lastUpdate = new Date(user.lastLocationUpdate);
            const minutesSinceUpdate = (now.getTime() - lastUpdate.getTime()) / 60000;
            if (minutesSinceUpdate > 5) {
              status = 'OFFLINE';
            }
        } else {
            status = 'OFFLINE';
        }

        if (status !== 'OFFLINE') {
            const activeService = submissions.find(s => s.assignedTo === user.username && s.status === ServiceStatus.InProgress);
            if (activeService) {
                status = 'IN_PROGRESS';
                relevantService = activeService;
            } else {
                const upcomingService = submissions.find(s => {
                    if (s.assignedTo !== user.username || s.status !== ServiceStatus.Assigned) return false;
                    const scheduledDateTime = parseServiceDateTime(s);
                    return scheduledDateTime && scheduledDateTime > now && scheduledDateTime <= fifteenMinutesFromNow;
                });
                if (upcomingService) {
                    status = 'BUSY';
                    relevantService = upcomingService;
                }
            }
        }
        return { user, activeService: relevantService, status };
      });

      const sortedData = calculatedData.sort((a, b) => {
          const statusOrder = { IN_PROGRESS: 1, BUSY: 2, IDLE: 3, OFFLINE: 4 };
          if (statusOrder[a.status] !== statusOrder[b.status]) {
              return statusOrder[a.status] - statusOrder[b.status];
          }
          return a.user.username.localeCompare(b.user.username);
      });

      // Apply filters
      if (statusFilters.length === 4) return sortedData; // All are selected, no need to filter
      return sortedData.filter(agent => statusFilters.includes(agent.status));

  }, [users, submissions, statusFilters]);

  const panToUser = (user: User) => {
      const marker = markersRef.current[user.username];
      const map = mapInstanceRef.current;
      if (marker && map && user.latitude && user.longitude) {
          map.flyTo([user.latitude, user.longitude], 16);
          marker.openPopup();
      }
  };

  const handleClearHistory = () => {
    if (tripPolylineLayerRef.current) {
        mapInstanceRef.current.removeLayer(tripPolylineLayerRef.current);
        tripPolylineLayerRef.current = null;
    }
  };

  const handleStatusFilterChange = (statusId: AgentStatus) => {
    setStatusFilters(prev =>
        prev.includes(statusId)
            ? prev.filter(s => s !== statusId)
            : [...prev, statusId]
    );
  };

  const handleShowHistory = () => {
      handleClearHistory();
      if (!selectedAgent || !selectedDate || !mapInstanceRef.current) return;

      const historyPoints = locationHistory
          .filter(h => h.userId === selectedAgent && h.timestamp.startsWith(selectedDate))
          .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());

      if (historyPoints.length < 2) {
          alert('Not enough location data to draw a trip for this day.');
          return;
      }

      const segments: { serviceId?: string; points: [number, number][] }[] = [];
      if (historyPoints.length > 0) {
          let currentSegment = {
              serviceId: historyPoints[0].relatedServiceId,
              points: [[historyPoints[0].latitude, historyPoints[0].longitude] as [number, number]]
          };

          for (let i = 1; i < historyPoints.length; i++) {
              const point = historyPoints[i];
              if (point.relatedServiceId === currentSegment.serviceId) {
                  currentSegment.points.push([point.latitude, point.longitude]);
              } else {
                  segments.push(currentSegment);
                  currentSegment = {
                      serviceId: point.relatedServiceId,
                      points: [[point.latitude, point.longitude]]
                  };
              }
          }
          segments.push(currentSegment);
      }

      const polylineLayers: any[] = [];
      const allLatLngs: [number, number][] = [];

      segments.forEach(segment => {
          if (segment.points.length < 2) return;

          allLatLngs.push(...segment.points);

          const color = segment.serviceId ? '#a855f7' : '#3b82f6'; // purple for service, blue for idle
          const polyline = L.polyline(segment.points, { color, weight: 5, opacity: 0.8 });
          polylineLayers.push(polyline);

          // Add markers for start and end of each segment
          const startMarker = L.circleMarker(segment.points[0], { radius: 6, color: 'white', weight: 2, fillColor: '#22c55e', fillOpacity: 1 }).bindPopup(`Start of ${segment.serviceId ? 'Service' : 'Idle'} Trip`);
          const endMarker = L.circleMarker(segment.points[segment.points.length - 1], { radius: 6, color: 'white', weight: 2, fillColor: '#ef4444', fillOpacity: 1 }).bindPopup(`End of segment`);
          polylineLayers.push(startMarker, endMarker);
      });

      if (polylineLayers.length > 0) {
          tripPolylineLayerRef.current = L.layerGroup(polylineLayers).addTo(mapInstanceRef.current);
          mapInstanceRef.current.fitBounds(L.latLngBounds(allLatLngs), { padding: [50, 50] });
      }
  };

  useEffect(() => {
    if (mapContainerRef.current && !mapInstanceRef.current) {
      try {
        const map = L.map(mapContainerRef.current).setView([20.5937, 78.9629], 5);
        mapInstanceRef.current = map;

        const streetLayer = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
          attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
          maxZoom: 19,
        });

        const satelliteImageryLayer = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
            attribution: 'Tiles &copy; Esri',
            maxZoom: 19,
        });

        const satelliteLabelsLayer = L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager_only_labels/{z}/{x}/{y}{r}.png', {
            attribution: '&copy; CARTO',
            subdomains: 'abcd',
            maxZoom: 20,
            pane: 'shadowPane'
        });

        const hybridSatelliteLayer = L.layerGroup([satelliteImageryLayer, satelliteLabelsLayer]);

        const baseMaps = {
            "Street": streetLayer,
            "Satellite": hybridSatelliteLayer
        };

        hybridSatelliteLayer.addTo(map);
        L.control.layers(baseMaps).addTo(map);

      } catch (error) {
        console.error("Leaflet is not loaded.", error);
      }
    }
  }, []);

  // Update Agent Markers
  useEffect(() => {
    if (mapInstanceRef.current && agentData) {
        const map = mapInstanceRef.current;
        const currentMarkers = markersRef.current;

        const trackedUsernames = new Set(agentData.map(d => d.user.username));

        Object.keys(currentMarkers).forEach(username => {
            if (!trackedUsernames.has(username)) {
                map.removeLayer(currentMarkers[username]);
                delete currentMarkers[username];
            }
        });

        agentData.forEach(agent => {
            const { user, activeService, status } = agent;
            if (typeof user.latitude !== 'number' || typeof user.longitude !== 'number') {
                if (currentMarkers[user.username]) {
                    map.removeLayer(currentMarkers[user.username]);
                    delete currentMarkers[user.username];
                }
                return;
            }

            const pos: [number, number] = [user.latitude, user.longitude];

            const getIconClassName = (s: AgentStatus) => {
              const statusMap = {
                IDLE: 'agent-status-idle',
                IN_PROGRESS: 'agent-status-in_progress',
                BUSY: 'agent-status-busy',
                OFFLINE: 'agent-status-offline'
              }
              return `agent-marker-icon ${statusMap[s] || 'agent-status-offline'}`;
            }

            const customIcon = L.divIcon({
                html: `<div class="${getIconClassName(status)}">${truckIconSvg}</div>`,
                className: 'leaflet-div-icon',
                iconSize: [36, 36],
                iconAnchor: [18, 18],
                popupAnchor: [0, -24]
            });

            const lastUpdateText = user.lastLocationUpdate ? `${timeSince(new Date(user.lastLocationUpdate))}` : 'N/A';
            let popupContent = `
                <div style="font-family: sans-serif; line-height: 1.5; min-width: 180px;">
                    <h3 style="font-weight: bold; font-size: 1rem; margin: 0 0 4px 0; color: #1e293b;">${user.username}</h3>
                    <dl style="margin: 0; font-size: 0.875rem;">
                        <div style="display: flex;">
                            <dt style="font-weight: 600; color: #475569; min-width: 55px;">Status:</dt>
                            <dd style="margin: 0; color: #1e293b;">${status.replace('_', ' ')}</dd>
                        </div>
            `;
            if (activeService) {
                popupContent += `
                        <div style="display: flex;">
                            <dt style="font-weight: 600; color: #475569; min-width: 55px;">Task:</dt>
                            <dd style="margin: 0; color: #1e293b; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${status === 'BUSY' ? 'Upcoming: ' : ''}Serving ${activeService.customerFirstName}</dd>
                        </div>
                `;
            }
            popupContent += `
                    </dl>
                    <p style="font-size: 0.75rem; color: #94a3b8; margin: 8px 0 0 0; padding-top: 4px; border-top: 1px solid #e2e8f0;">
                        Updated: ${lastUpdateText}
                    </p>
                </div>
            `;

            if (currentMarkers[user.username]) {
                currentMarkers[user.username].setLatLng(pos).setIcon(customIcon).setPopupContent(popupContent);
            } else {
                const marker = L.marker(pos, { icon: customIcon }).addTo(map);
                marker.bindPopup(popupContent);
                currentMarkers[user.username] = marker;
            }
        });
    }
  }, [agentData]);

  // Update Job (Service) Markers
  useEffect(() => {
    if (mapInstanceRef.current && submissions) {
        const map = mapInstanceRef.current;
        const currentJobMarkers = jobMarkersRef.current;

        // Filter active services with valid location data
        const activeServicesWithLocation = submissions.filter(s => 
            (s.status === ServiceStatus.Assigned || s.status === ServiceStatus.InProgress) && 
            s.customerLatitude && s.customerLongitude
        );

        const trackedServiceIds = new Set(activeServicesWithLocation.map(s => s.submissionId));

        // Remove old markers
        Object.keys(currentJobMarkers).forEach(sid => {
            if (!trackedServiceIds.has(sid)) {
                map.removeLayer(currentJobMarkers[sid]);
                delete currentJobMarkers[sid];
            }
        });

        // Add/Update markers
        activeServicesWithLocation.forEach(service => {
            if (!service.customerLatitude || !service.customerLongitude) return;

            const pos: [number, number] = [service.customerLatitude, service.customerLongitude];

            // Different color based on status
            const colorClass = service.status === ServiceStatus.InProgress ? 'bg-purple-500' : 'bg-blue-500';

            const customIcon = L.divIcon({
                html: `<div style="width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 2px 5px rgba(0,0,0,0.3); border: 2px solid white;" class="${colorClass}">${houseIconSvg}</div>`,
                className: 'leaflet-div-icon',
                iconSize: [28, 28],
                iconAnchor: [14, 14],
                popupAnchor: [0, -20]
            });

            const popupContent = `
                <div style="font-family: sans-serif; line-height: 1.5;">
                    <h4 style="font-weight: bold; margin: 0 0 4px 0;">${service.customerFirstName}</h4>
                    <p style="margin: 0; font-size: 0.85rem; color: #475569;">${service.carBrandModel}</p>
                    <p style="margin: 0; font-size: 0.85rem; color: #475569;">${service.status}</p>
                    <p style="margin: 4px 0 0 0; font-size: 0.75rem; color: #64748b;">Assigned: ${service.assignedTo || 'Unassigned'}</p>
                </div>
            `;

            if (currentJobMarkers[service.submissionId]) {
                currentJobMarkers[service.submissionId].setLatLng(pos).setIcon(customIcon).setPopupContent(popupContent);
            } else {
                const marker = L.marker(pos, { icon: customIcon }).addTo(map);
                marker.bindPopup(popupContent);
                currentJobMarkers[service.submissionId] = marker;
            }
        });
    }
  }, [submissions]);

  const statusConfig = {
      IN_PROGRESS: { text: 'text-purple-700', bg: 'bg-purple-100', border: 'border-purple-400' },
      BUSY: { text: 'text-orange-700', bg: 'bg-orange-100', border: 'border-orange-400' },
      IDLE: { text: 'text-blue-700', bg: 'bg-blue-100', border: 'border-blue-400' },
      OFFLINE: { text: 'text-slate-600', bg: 'bg-slate-100', border: 'border-slate-400' },
  }

  return (
    <Card>
      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start mb-4 gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-800 tracking-tight">Live Agent Map</h1>
          <p className="text-slate-500 mt-1">Real-time location of checked-in agents and active job sites.</p>
        </div>
        <Button onClick={onRefresh} disabled={isRefreshing}>
            <IconRefresh className={`w-5 h-5 mr-2 ${isRefreshing ? 'animate-spin' : ''}`} />
            Refresh Now
        </Button>
      </div>
       <div className="flex flex-col md:flex-row gap-6">
        <div className="md:w-1/3 lg:w-1/4 flex-shrink-0">
          <Card title="Trip History" className="mb-4">
            <div className="space-y-4">
              <div>
                <label htmlFor="agent-select" className="block text-sm font-medium text-slate-700 mb-1">Select Agent</label>
                <select id="agent-select" value={selectedAgent} onChange={(e) => setSelectedAgent(e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm">
                  <option value="">-- All Agents --</option>
                  {agentData.map(({ user }) => <option key={user.username} value={user.username}>{user.username}</option>)}
                </select>
              </div>
              <Input label="Select Date" type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} />
              <div className="flex space-x-2">
                <Button onClick={handleShowHistory} disabled={!selectedAgent} className="flex-1">Show History</Button>
                <Button onClick={handleClearHistory} variant="secondary">Clear</Button>
              </div>
            </div>
          </Card>

          <Card title="Agent Filters & List">
            <div className="mb-4">
              <div className="grid grid-cols-2 gap-2">
                {statusOptions.map(opt => (
                  <button key={opt.id} onClick={() => handleStatusFilterChange(opt.id)} className={`px-2 py-1 text-sm rounded-md border-2 transition-all ${statusFilters.includes(opt.id) ? `${opt.color} ${opt.border} font-semibold` : 'bg-white hover:bg-slate-200 border-slate-200'}`}>
                    {opt.label}
                  </button>
                ))}
              </div>
            </div>
            <ul className="space-y-2 max-h-[45vh] overflow-y-auto pr-2">
              {agentData.map(({ user, status, activeService }) => {
                  const config = statusConfig[status];
                  return (
                      <li key={user.username}>
                          <button 
                              onClick={() => panToUser(user)}
                              className={`w-full text-left p-3 rounded-lg border-l-4 transition-all duration-200 hover:shadow-md hover:border-brand-accent ${config.bg} ${config.border}`}
                              disabled={!user.latitude}
                          >
                              <div className="flex justify-between items-center">
                                  <p className={`font-bold ${config.text}`}>{user.username}</p>
                                  <span className={`text-xs font-semibold px-2 py-0.5 rounded-full ${config.bg} ${config.text}`}>{status.replace('_', ' ')}</span>
                              </div>
                              <p className="text-xs text-slate-500 mt-1 truncate">
                                  {activeService ? `${status === 'BUSY' ? 'Upcoming: ' : ''}Servicing ${activeService.customerFirstName}` : 'Awaiting task'}
                              </p>
                              <p className="text-xs text-slate-400 mt-1">
                                  {user.lastLocationUpdate ? `Updated ${timeSince(new Date(user.lastLocationUpdate))}` : 'No location data'}
                              </p>
                          </button>
                      </li>
                  );
              })}
              {agentData.length === 0 && <p className="text-sm text-slate-500 p-4 text-center">No agents match the current filters.</p>}
            </ul>
          </Card>
        </div>
        <div className="flex-1 min-h-[400px]">
          <div ref={mapContainerRef} style={{ height: '75vh', width: '100%', borderRadius: '8px', border: '1px solid #e2e8f0', zIndex: 0 }}>
          </div>
        </div>
      </div>
    </Card>
  );
};

export default LiveMapPage;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Service, ServiceStatus, User, UserSubscription, ServiceTemplate, Permission, TyreData, PricingConfig } from './types';
import { useServiceForm } from './hooks/useServiceForm';
import CustomerDetailsStep from './CustomerDetailsStep';
import ServiceSelectionStep from './ServiceSelectionStep';
import { ServiceDetailsStep } from './ServiceDetailsStep';
import AddonsStep from './AddonsStep';
import CustomServicesStep from './CustomServicesStep';
import { SummaryStep } from './SummaryStep';
import Stepper from './Stepper';
import Card from './ui/Card';
import Button from './ui/Button';
import Input from './ui/Input';
import { APPOINTMENT_TIME_SLOTS, DEFAULT_PRICING_CONFIG } from './constants';
import { validateStep, ValidationErrors } from './services/validationService';
import { IconDeviceFloppy } from './ui/Icon';
import DependencyManager from './DependencyManager';
import CarCareStep from './CarCareStep';

interface ServiceFormProps {
  initialService?: Service | null;
  allSubmissions: Service[];
  onComplete: (service: Service) => void;
  onSaveDraft: (service: Service) => void;
  onAdminUpdate?: (service: Service) => void;
  onExit: () => void;
  googleDriveUploadUrl: string;
  currentUser: User;
  allUsers: Omit<User, 'password'>[];
  userSubscriptions: UserSubscription[];
  serviceTemplates: ServiceTemplate[];
  vehicleData: Record<string, string[]>;
  tyreData: TyreData;
  onUpdateVehicleData: (brand: string, model: string) => void;
  onUpdateTyreData: (type: keyof TyreData, value: string) => void;
  pricingConfig?: PricingConfig;
}

const ALL_STEPS = [
  { name: 'Customer Details', component: CustomerDetailsStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Service Selection', component: ServiceSelectionStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { 
    name: 'Car Care', 
    component: CarCareStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.includes("Car Care")
  },
  { 
    name: 'Service Details', 
    component: ServiceDetailsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.some(s => 
        ["Car Washing", "Tyre Replacement", "Battery Replacement"].includes(s)
      ) || state.serviceSelection.some(s => serviceTemplates.find(t => t.name === s && t.customFields.length > 0))
  },
  { 
    name: 'Add-ons', 
    component: AddonsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true
  },
  { name: 'Custom Services', component: CustomServicesStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Invoice Summary', component: SummaryStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
];

const ServiceForm: React.FC<ServiceFormProps> = ({ 
  initialService, 
  allSubmissions,
  onComplete, 
  onSaveDraft,
  onAdminUpdate,
  onExit, 
  googleDriveUploadUrl, 
  currentUser, 
  allUsers, 
  userSubscriptions,
  serviceTemplates, 
  vehicleData, 
  tyreData, 
  onUpdateVehicleData, 
  onUpdateTyreData, 
  pricingConfig = DEFAULT_PRICING_CONFIG,
}) => {
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const { state, dispatch, updateField } = useServiceForm(initialService, pricingConfig);
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [prefillServiceId, setPrefillServiceId] = useState('');
  const [saveConfirmation, setSaveConfirmation] = useState('');

  const isAdminEditing = useMemo(() => 
    currentUser.permissions.includes(Permission.CAN_EDIT_ANY_ORDER) && !!initialService,
  [currentUser, initialService]);

  useEffect(() => {
    if (initialService) {
      dispatch({ type: 'SET_FORM_DATA', payload: JSON.parse(JSON.stringify(initialService)) });
    }
  }, [initialService, dispatch]);


  const sortedSubmissions = useMemo(() => {
    return [...allSubmissions].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [allSubmissions]);

  const handlePrefillChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedId = e.target.value;
    setPrefillServiceId(selectedId);

    if (!selectedId) return;

    const serviceToCopy = allSubmissions.find(s => s.submissionId === selectedId);
    if (!serviceToCopy) return;

    const newSubmissionId = `SUB-${Date.now()}`;
    const newServiceData: Service = {
      ...JSON.parse(JSON.stringify(serviceToCopy)),
      submissionId: newSubmissionId,
      appointmentId: newSubmissionId,
      timestamp: new Date().toISOString(),
      status: ServiceStatus.Draft,
      acknowledgement: false,
      beforeWashingPhoto: '', beforeVideoInventory: '', beforeVideoTopBody: '', beforeVideoUnderchassis: '',
      afterWashingPhoto: '', afterVideoInterior: '', afterVideoExterior: '', afterVideoUnderchassis: '',
      tyreDetails: [],
      batteryDetails: [],
      customFieldData: (serviceToCopy.customFieldData || []).filter(field => {
          const allCustomFields = serviceTemplates.flatMap(st => st.customFields);
          const fieldDef = allCustomFields.find(f => f.id === field.fieldId);
          return fieldDef?.type !== 'PHOTO';
      }),
      assignedTo: undefined,
      scheduledDate: undefined,
      scheduledTime: undefined,
      internalNotes: '',
      isFollowUp: true,
      dependsOn: [], // Dependencies should not be copied
    };

    dispatch({ type: 'SET_FORM_DATA', payload: newServiceData });
  };


  const visibleSteps = useMemo(() => {
    return ALL_STEPS.map((step, index) => ({...step, originalIndex: index}))
                     .filter(step => step.isVisible(state, serviceTemplates));
  }, [state, serviceTemplates]);

  const StepComponent = visibleSteps[currentStepIndex].component;

  const handleStepClick = (index: number) => {
    if (isAdminEditing || index < currentStepIndex) {
      setErrors({}); 
      setCurrentStepIndex(index);
    }
  };

  const nextStep = () => {
    const currentStepName = visibleSteps[currentStepIndex].name;
    const validationErrors = validateStep(currentStepName, state);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      setCurrentStepIndex(prev => Math.min(prev + 1, visibleSteps.length - 1));
    }
  };

  const prevStep = () => {
    setErrors({}); 
    setCurrentStepIndex(prev => Math.max(prev - 1, 0));
  };

  const handleSubmit = () => {
    if (state.acknowledgement) {
      localStorage.removeItem('service_form_in_progress');
      onComplete(state);
    }
  };

  const handleSaveDraftClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onSaveDraft(state);
  };

  const handleAdminSave = () => {
    if (!onAdminUpdate) return;
    onAdminUpdate(state);
    setSaveConfirmation('Changes saved successfully!');
    setTimeout(() => setSaveConfirmation(''), 2500);
  };

  const handleExitClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onExit();
  };

  const handleUpdateDependencies = useCallback((newDeps: string[]) => {
    updateField('dependsOn', newDeps);
  }, [updateField]);

  const isLastStep = currentStepIndex === visibleSteps.length - 1;

  const showDraftButton = (!initialService || initialService?.status === ServiceStatus.Draft);

  return (
    <Card>
      {!initialService && (
        <div className="p-4 mb-8 bg-slate-50 border border-slate-200 rounded-lg no-print">
          <label htmlFor="prefill-select" className="block text-sm font-medium text-slate-700 mb-1">
            Pre-fill from Existing Service (Optional)
          </label>
          <select
            id="prefill-select"
            value={prefillServiceId}
            onChange={handlePrefillChange}
            className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus-visible:border-brand-accent sm:text-sm"
          >
            <option value="">-- Select a past service to copy data from --</option>
            {sortedSubmissions.map(s => (
              <option key={s.submissionId} value={s.submissionId}>
                {new Date(s.timestamp).toLocaleDateString()} - #{s.appointmentId?.split('-').pop()} - {s.customerFirstName} ({s.carNumber})
              </option>
            ))}
          </select>
        </div>
      )}

      <div className="mb-8 pb-4 border-b border-slate-200 no-print">
        <Stepper 
          steps={visibleSteps} 
          currentStepIndex={currentStepIndex} 
          onStepClick={handleStepClick}
          isClickable={isAdminEditing}
        />
      </div>

      {isAdminEditing && (
        <div className="sticky top-[63px] bg-slate-100/80 backdrop-blur-md z-20 -mx-6 px-6 -mt-8 mb-8">
            <div className="flex justify-between items-center h-16 border-b">
                 <Button variant="ghost" onClick={handleExitClick}>Exit to Dashboard</Button>
                 <div className="flex items-center space-x-4">
                    {saveConfirmation && <p className="text-sm font-semibold text-green-600 animate-pulse">{saveConfirmation}</p>}
                    <Button onClick={handleAdminSave}>
                        <IconDeviceFloppy className="w-5 h-5 mr-2" />
                        Save Changes
                    </Button>
                 </div>
            </div>
        </div>
      )}

      {isAdminEditing && (
        <div className="p-4 mb-8 bg-blue-50 border border-blue-200 rounded-lg">
          <h3 className="text-lg font-semibold text-blue-800 mb-4">Admin Controls</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label htmlFor="assignedTo" className="block text-sm font-medium text-slate-700 mb-1">Assigned User</label>
              <select
                id="assignedTo"
                name="assignedTo"
                value={state.assignedTo || ''}
                onChange={(e) => updateField('assignedTo', e.target.value || undefined)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                <option value="">-- Unassigned --</option>
                {allUsers.map(u => <option key={u.username} value={u.username}>{u.username}</option>)}
              </select>
            </div>
            <Input 
                label="Scheduled Date" 
                id="scheduledDate"
                type="date"
                value={state.scheduledDate ? state.scheduledDate.split('T')[0] : ''}
                onChange={(e) => updateField('scheduledDate', e.target.value)}
            />
            <div>
              <label htmlFor="scheduledTime" className="block text-sm font-medium text-slate-700 mb-1">Scheduled Time</label>
              <select
                  id="scheduledTime"
                  name="scheduledTime"
                  value={state.scheduledTime || ''}
                  onChange={(e) => updateField('scheduledTime', e.target.value || undefined)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                  <option value="">-- No Time Set --</option>
                  {APPOINTMENT_TIME_SLOTS.map(time => (
                      <option key={time} value={time}>{time}</option>
                  ))}
              </select>
            </div>
             <div>
                <label htmlFor="status" className="block text-sm font-medium text-slate-700 mb-1">Status</label>
                <select
                    id="status"
                    name="status"
                    value={state.status}
                    onChange={(e) => updateField('status', e.target.value as ServiceStatus)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
                >
                    {Object.values(ServiceStatus).map(status => (
                        <option key={status} value={status}>{status}</option>
                    ))}
                </select>
            </div>
          </div>
           <div className="mt-6 pt-4 border-t">
              <DependencyManager 
                  service={state}
                  allSubmissions={allSubmissions}
                  onUpdateDependencies={handleUpdateDependencies}
              />
            </div>
        </div>
      )}

      {initialService && (currentUser.role === 'admin' || currentUser.role === 'manager' || currentUser.username === initialService.assignedTo) && (
        <div className="p-4 mb-8 bg-yellow-50 border border-yellow-200 rounded-lg">
            <h3 className="text-lg font-semibold text-yellow-800 mb-2">Internal Notes</h3>
            <p className="text-sm text-yellow-700 mb-4">These notes are only visible to administrators, managers, and the assigned service agent.</p>
            <textarea
                id="internalNotes"
                name="internalNotes"
                value={state.internalNotes || ''}
                onChange={(e) => updateField('internalNotes', e.target.value)}
                rows={3}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                placeholder="Add any internal remarks for this service (e.g., customer is particular about wheels, specific tool needed)..."
            />
        </div>
      )}

      <div className="min-h-[300px]">
        <h2 className="text-2xl font-bold text-slate-800 mb-6">{visibleSteps[currentStepIndex].name}</h2>
        {isLastStep ? (
          <SummaryStep state={state} updateField={updateField} serviceTemplates={serviceTemplates} />
        ) : (
          <StepComponent 
            state={state} 
            updateField={updateField} 
            dispatch={dispatch} 
            googleDriveUploadUrl={googleDriveUploadUrl}
            userSubscriptions={userSubscriptions}
            serviceTemplates={serviceTemplates}
            errors={errors}
            allSubmissions={allSubmissions}
            vehicleData={vehicleData}
            tyreData={tyreData}
            onUpdateVehicleData={onUpdateVehicleData}
            onUpdateTyreData={onUpdateTyreData}
            pricingConfig={pricingConfig}
          />
        )}
      </div>

      {!isAdminEditing && (
          <div className="mt-8 pt-6 border-t border-slate-200 flex flex-col-reverse gap-y-4 sm:flex-row sm:justify-between sm:items-center no-print">
            <div className="flex items-center space-x-2">
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep}>Back</Button>
                )}
                <Button variant="ghost" onClick={handleExitClick}>Exit to Dashboard</Button>
            </div>
            <div className="flex items-center space-x-2 w-full sm:w-auto">
              {showDraftButton && (
                <Button variant="ghost" onClick={handleSaveDraftClick}>Save as Draft</Button>
              )}

              {!isLastStep && (
                <Button onClick={nextStep} className="flex-1 sm:flex-auto justify-center">Next</Button>
              )}

              {isLastStep && (
                <Button onClick={handleSubmit} disabled={!state.acknowledgement} className="flex-1 sm:flex-auto justify-center">
                    Complete Order
                </Button>
              )}
            </div>
          </div>
      )}

      {isAdminEditing && (
        <div className="mt-8 pt-6 border-t border-slate-200 flex justify-between items-center no-print">
            <div>
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep}>Back</Button>
                )}
            </div>

            {!isLastStep && (
                <Button onClick={nextStep}>Next</Button>
            )}
        </div>
      )}

    </Card>
  );
};

export default ServiceForm;

import React, { useEffect, useRef, useState } from 'react';
import Button from './Button';
import { IconMapPin, IconCrosshair } from './Icon';

// Declare Leaflet global
declare const L: any;

interface LocationPickerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (lat: number, lng: number) => void;
  initialLat?: number;
  initialLng?: number;
}

const LocationPickerModal: React.FC<LocationPickerModalProps> = ({
  isOpen,
  onClose,
  onConfirm,
  initialLat,
  initialLng,
}) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markerRef = useRef<any>(null);
  const [currentPos, setCurrentPos] = useState<{ lat: number; lng: number } | null>(
    initialLat && initialLng ? { lat: initialLat, lng: initialLng } : null
  );

  useEffect(() => {
    // If the modal is closing, cleanup map
    if (!isOpen) {
        if (mapInstanceRef.current) {
            mapInstanceRef.current.remove();
            mapInstanceRef.current = null;
        }
        return;
    }

    // Initialize Map only if isOpen is true and map isn't already initialized
    if (isOpen && mapContainerRef.current && !mapInstanceRef.current) {
      // Default to center of India if no location, or user's location later
      const defaultCenter = [20.5937, 78.9629];
      const zoomLevel = initialLat ? 16 : 5;
      const center = initialLat && initialLng ? [initialLat, initialLng] : defaultCenter;

      const map = L.map(mapContainerRef.current).setView(center, zoomLevel);
      mapInstanceRef.current = map;

      // Add Tile Layer
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; OpenStreetMap contributors',
        maxZoom: 19,
      }).addTo(map);

      // Custom Icon
      const customIcon = L.divIcon({
        html: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" style="color: #dc2626; width: 40px; height: 40px; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.3));"><path fill-rule="evenodd" d="M11.54 22.351l.07.04.028.016a.76.76 0 00.723 0l.028-.015.071-.041a16.975 16.975 0 001.144-.742 19.58 19.58 0 002.683-2.282c1.944-1.99 3.963-4.98 3.963-8.827a8.25 8.25 0 00-16.5 0c0 3.846 2.02 6.837 3.963 8.827a19.58 19.58 0 002.682 2.282 16.975 16.975 0 001.145.742zM12 13.5a3 3 0 100-6 3 3 0 000 6z" clip-rule="evenodd" /></svg>`,
        className: 'bg-transparent border-none',
        iconSize: [40, 40],
        iconAnchor: [20, 40],
      });

      // Add Marker
      const marker = L.marker(center, { icon: customIcon, draggable: true }).addTo(map);
      markerRef.current = marker;

      // Event: Marker Drag
      marker.on('dragend', function (event: any) {
        const m = event.target;
        const position = m.getLatLng();
        setCurrentPos({ lat: position.lat, lng: position.lng });
        map.panTo(position);
      });

      // Event: Map Click
      map.on('click', function (e: any) {
        marker.setLatLng(e.latlng);
        setCurrentPos({ lat: e.latlng.lat, lng: e.latlng.lng });
        map.panTo(e.latlng);
      });

      // If no initial location passed, try to auto-locate
      if (!initialLat && !initialLng) {
        map.locate({ setView: true, maxZoom: 16 });
        map.on('locationfound', (e: any) => {
             marker.setLatLng(e.latlng);
             setCurrentPos({ lat: e.latlng.lat, lng: e.latlng.lng });
        });
      }
    }
  }, [isOpen, initialLat, initialLng]);

  const handleLocateMe = () => {
      const map = mapInstanceRef.current;
      if (!map) return;
      map.locate({ setView: true, maxZoom: 16 });
  };

  const handleConfirm = () => {
    if (currentPos) {
      onConfirm(currentPos.lat, currentPos.lng);
      onClose();
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-[60] p-4 modal-backdrop" onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-2xl bg-white rounded-xl shadow-xl flex flex-col h-[80vh] md:h-[600px] modal-content">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center rounded-t-xl">
          <h3 className="text-lg font-semibold text-slate-800">Pin Exact Location</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
            <span className="text-2xl leading-none">&times;</span>
          </button>
        </div>

        <div className="flex-1 relative bg-slate-100">
            <div ref={mapContainerRef} className="w-full h-full z-0" />

            <button 
                onClick={handleLocateMe}
                className="absolute top-4 right-4 z-[400] bg-white p-2 rounded-md shadow-md border border-slate-300 text-slate-600 hover:bg-slate-50 hover:text-brand-blue"
                title="Use Current Location"
            >
                <IconCrosshair className="w-6 h-6" />
            </button>
            <div className="absolute bottom-4 left-4 right-4 z-[400] bg-white/90 backdrop-blur px-3 py-2 rounded-md shadow text-xs text-center sm:text-left text-slate-600 pointer-events-none">
                Drag the marker or click on the map to set the exact customer location.
            </div>
        </div>

        <div className="p-4 bg-white border-t border-slate-200 rounded-b-xl flex justify-between items-center gap-4">
             <div className="text-sm text-slate-600 hidden sm:block">
                {currentPos ? (
                    <span className="font-mono bg-slate-100 px-2 py-1 rounded">
                        {currentPos.lat.toFixed(6)}, {currentPos.lng.toFixed(6)}
                    </span>
                ) : (
                    <span>Location not set</span>
                )}
             </div>
             <div className="flex space-x-3 w-full sm:w-auto justify-end">
                 <Button variant="ghost" onClick={onClose}>Cancel</Button>
                 <Button onClick={handleConfirm} disabled={!currentPos}>
                    <IconMapPin className="w-4 h-4 mr-2" />
                    Confirm Pin
                 </Button>
             </div>
        </div>
      </div>
    </div>
  );
};

export default LocationPickerModal;

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { Customer, UserSubscription, ServiceTemplate, Service, VehicleCategoryTag, User } from '../../types';
import Button from '../ui/Button';
import Input from '../ui/Input';
import { APPOINTMENT_TIME_SLOTS, VEHICLE_CATEGORY_TAGS } from '../../constants';
import { IconTrophy, IconLoader, IconDeviceFloppy, IconTrash, IconCrosshair, IconMapPin, IconCheck } from '../ui/Icon';
import { findCustomerByMobile } from '../../services/customerService';
import VehicleSelector from '../VehicleSelector';
import { getCategoryForVehicle } from '../../services/vehicleService';
import LocationPickerModal from '../ui/LocationPickerModal';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onCreateOrder: (details: { 
    customer: Pick<Customer, 'firstName' | 'lastName' | 'mobileNumber' | 'carNumber' | 'carBrandModel' | 'streetAddress' | 'customerEmail' | 'latitude' | 'longitude'>, 
    scheduledDate?: string, 
    scheduledTime?: string, 
    serviceSelection: string[], 
    vehicleCategoryTag?: VehicleCategoryTag,
    assignedTo?: string 
  }) => void;
  userSubscriptions: UserSubscription[];
  serviceTemplates: ServiceTemplate[];
  allSubmissions: Service[];
  vehicleData: Record<string, string[]>;
  users: Omit<User, 'password'>[];
}

// Stable no-op function to prevent re-renders in VehicleSelector
const noOp = () => {};

const DRAFT_KEY = 'create_order_modal_draft';

const CreateOrderModal: React.FC<Props> = ({ isOpen, onClose, onCreateOrder, userSubscriptions, serviceTemplates, allSubmissions, vehicleData, users }) => {
  const [customer, setCustomer] = useState<Pick<Customer, 'firstName' | 'lastName' | 'mobileNumber' | 'carNumber' | 'carBrandModel' | 'streetAddress' | 'customerEmail' | 'latitude' | 'longitude'>>(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).customer : { firstName: '', lastName: '', mobileNumber: '', carNumber: '', carBrandModel: '', streetAddress: '', customerEmail: '', latitude: undefined, longitude: undefined };
  });

  const [scheduledDate, setScheduledDate] = useState(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).scheduledDate : '';
  });

  const [scheduledTime, setScheduledTime] = useState(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).scheduledTime : '';
  });

  const [serviceSelection, setServiceSelection] = useState<string[]>(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).serviceSelection : [];
  });

  const [vehicleCategoryTag, setVehicleCategoryTag] = useState<VehicleCategoryTag | undefined>(() => {
     const saved = localStorage.getItem(DRAFT_KEY);
     return saved ? JSON.parse(saved).vehicleCategoryTag : undefined;
  });

  const [assignedTo, setAssignedTo] = useState<string>(() => {
      const saved = localStorage.getItem(DRAFT_KEY);
      return saved ? JSON.parse(saved).assignedTo || '' : '';
  });

  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [isSearching, setIsSearching] = useState(false);
  const [searchMessage, setSearchMessage] = useState('');
  const searchTimeoutRef = useRef<number | null>(null);
  const [foundProfiles, setFoundProfiles] = useState<Awaited<ReturnType<typeof findCustomerByMobile>> | null>(null);
  const [isLocationPickerOpen, setIsLocationPickerOpen] = useState(false);


  useEffect(() => {
    const draftData = {
        customer,
        scheduledDate,
        scheduledTime,
        serviceSelection,
        vehicleCategoryTag,
        assignedTo
    };
    localStorage.setItem(DRAFT_KEY, JSON.stringify(draftData));
  }, [customer, scheduledDate, scheduledTime, serviceSelection, vehicleCategoryTag, assignedTo]);

  useEffect(() => {
    if (customer.carBrandModel) {
        const detectedCategory = getCategoryForVehicle(customer.carBrandModel);
        if (vehicleCategoryTag !== detectedCategory && !vehicleCategoryTag) {
            setVehicleCategoryTag(detectedCategory);
        }
    }
  }, [customer.carBrandModel]);

  useEffect(() => {
    if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);

    const mobileNumber = customer.mobileNumber;
    if (mobileNumber.trim().length < 10) {
      setSearchMessage('');
      setIsSearching(false);
      if (mobileNumber.trim().length === 0) setFoundProfiles(null);
      return;
    }

    setIsSearching(true);
    setSearchMessage('');

    searchTimeoutRef.current = window.setTimeout(async () => {
      const profiles = await findCustomerByMobile(mobileNumber, allSubmissions, userSubscriptions);
      setIsSearching(false);
      if (profiles && profiles.length > 0) {
        if (profiles.length === 1) {
            setCustomer(prev => ({ ...prev, ...profiles[0].customer }));
            setFoundProfiles(null);
            if (profiles[0].isSubscriber) {
                setSearchMessage(`Subscriber found! Washes Left: ${profiles[0].washesRemaining}.`);
            } else {
                setSearchMessage('Existing customer found. Details pre-filled.');
            }
        } else {
            setFoundProfiles(profiles);
            const firstProfile = profiles[0].customer;
            setCustomer(prev => ({
                ...prev,
                firstName: firstProfile.firstName,
                lastName: firstProfile.lastName,
                streetAddress: firstProfile.streetAddress,
                customerEmail: firstProfile.customerEmail,
                carNumber: '',
                carBrandModel: '',
            }));
            setSearchMessage(`${profiles.length} vehicles found. Please select one.`);
        }
      } else {
        setSearchMessage('New customer.');
        setFoundProfiles(null);
      }
    }, 500); 

    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, [customer.mobileNumber, allSubmissions, userSubscriptions]);

  const handleVehicleChange = useCallback((value: string) => {
    setCustomer(prev => ({...prev, carBrandModel: value}));
    if (errors.carBrandModel) {
        setErrors(p => {
            const newErrors = { ...p };
            delete newErrors.carBrandModel;
            return newErrors;
        });
    }
  }, [errors.carBrandModel]);

  const handleOpenLocationPicker = () => {
      setIsLocationPickerOpen(true);
  };

  const handleLocationConfirm = (lat: number, lng: number) => {
      setCustomer(prev => ({
          ...prev,
          latitude: lat,
          longitude: lng
      }));
  };

  if (!isOpen) return null;

  const handleCarSelection = (profile: any) => {
    setCustomer(prev => ({ ...prev, ...profile.customer }));
    setFoundProfiles(null); 
  };

  const handleCustomerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    if (name === 'mobileNumber') {
      const sanitized = value.replace(/[^0-9+]/g, '').replace(/(?!^)\+/g, '');
      if (sanitized.length <= 15) {
          setCustomer(prev => ({ ...prev, mobileNumber: sanitized }));
      }
    } else {
      setCustomer(prev => ({ ...prev, [name]: value }));
    }

    if (errors[name]) {
        setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleToggleService = (selection: string) => {
    const newSelections = serviceSelection.includes(selection)
      ? serviceSelection.filter(s => s !== selection)
      : [...serviceSelection, selection];
    setServiceSelection(newSelections);
  };

  const clearForm = () => {
      if(window.confirm("Are you sure you want to clear all fields? This cannot be undone.")) {
          setCustomer({ firstName: '', lastName: '', mobileNumber: '', carNumber: '', carBrandModel: '', streetAddress: '', customerEmail: '', latitude: undefined, longitude: undefined});
          setScheduledDate('');
          setScheduledTime('');
          setServiceSelection([]);
          setVehicleCategoryTag(undefined);
          setAssignedTo('');
          setErrors({});
          setSearchMessage('');
          localStorage.removeItem(DRAFT_KEY);
      }
  }

  const handleSubmit = () => {
    const newErrors: { [key: string]: string } = {};

    if (!customer.firstName.trim()) newErrors.firstName = 'First Name is required.';
    if (!customer.mobileNumber.trim()) newErrors.mobileNumber = 'Mobile Number is required.';
    if (!customer.carNumber.trim()) newErrors.carNumber = 'Car Number is required.';
    if (!customer.carBrandModel.trim()) newErrors.carBrandModel = 'Car Brand & Model are required.';

    if (scheduledDate) {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const selected = new Date(scheduledDate);
        const userTimezoneOffset = selected.getTimezoneOffset() * 60000;
        const localSelectedDate = new Date(selected.getTime() + userTimezoneOffset);

        if (localSelectedDate < today) {
            newErrors.scheduledDate = 'Scheduled date cannot be in the past.';
        }
    }

    setErrors(newErrors);

    if (Object.keys(newErrors).length > 0) {
      return;
    }

    onCreateOrder({ customer, scheduledDate, scheduledTime, serviceSelection, vehicleCategoryTag, assignedTo });
    localStorage.removeItem(DRAFT_KEY);
    setCustomer({ firstName: '', lastName: '', mobileNumber: '', carNumber: '', carBrandModel: '', streetAddress: '', customerEmail: '', latitude: undefined, longitude: undefined});
    setScheduledDate('');
    setScheduledTime('');
    setServiceSelection([]);
    setAssignedTo('');
    onClose();
  };

  return (
    <>
    <div className="fixed inset-0 bg-black bg-opacity-60 flex items-start sm:items-center justify-center z-50 p-4 pt-8 sm:pt-4 modal-backdrop" onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-lg bg-white rounded-xl shadow-md flex flex-col max-h-[90vh] modal-content">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex-shrink-0 flex justify-between items-center">
          <h3 className="text-lg font-semibold text-slate-800">Create New Service Order</h3>
          <button onClick={clearForm} className="text-xs text-red-600 hover:text-red-800 flex items-center">
              <IconTrash className="w-3 h-3 mr-1"/> Clear Form
          </button>
        </div>

        <div className="overflow-y-auto p-6">
            <div className="mb-4 bg-blue-50 border-l-4 border-blue-400 p-3 rounded text-xs text-blue-800 flex items-start">
                 <IconDeviceFloppy className="w-4 h-4 mr-2 mt-0.5 flex-shrink-0"/>
                 <p><strong>Smart Draft:</strong> Your data is saved automatically as you type. If you refresh or close this window, your progress will be restored.</p>
            </div>

          <div className="space-y-6">
            <div>
              <h3 className="text-md font-semibold text-slate-700 mb-2">Customer & Vehicle Details</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <Input 
                    label="Mobile Number" name="mobileNumber" type="tel" value={customer.mobileNumber} onChange={handleCustomerChange} 
                    required error={errors.mobileNumber} maxLength={15} prefix="+91" 
                    suffix={isSearching ? <IconLoader className="w-5 h-5 text-slate-400 animate-spin" /> : undefined}
                  />
                  {searchMessage && !isSearching && !foundProfiles && <p className={`mt-1 text-xs font-semibold ${searchMessage.includes('Subscriber') ? 'text-green-600' : searchMessage.includes('found') ? 'text-blue-600' : 'text-slate-500'}`}>{searchMessage}</p>}
                </div>
                <Input label="First Name" name="firstName" value={customer.firstName} onChange={handleCustomerChange} required error={errors.firstName} />
                <Input label="Last Name" name="lastName" value={customer.lastName} onChange={handleCustomerChange} />
                <Input label="Email (Optional)" name="customerEmail" type="email" value={customer.customerEmail || ''} onChange={handleCustomerChange} />
                 {foundProfiles ? (
                    <div className="sm:col-span-2 space-y-2">
                        <p className="text-sm font-semibold text-blue-700">{searchMessage}</p>
                        {foundProfiles.map((profile, index) => (
                            <button
                                key={index}
                                type="button"
                                onClick={() => handleCarSelection(profile)}
                                className="w-full text-left p-3 rounded-md border-2 bg-white hover:border-brand-accent focus:border-brand-accent focus:outline-none transition-colors"
                            >
                                <p className="font-semibold text-slate-800">{profile.customer.carBrandModel}</p>
                                <p className="text-slate-600">{profile.customer.carNumber}</p>
                            </button>
                        ))}
                    </div>
                ) : (
                    <>
                      <Input label="Car Number" name="carNumber" value={customer.carNumber} onChange={handleCustomerChange} required error={errors.carNumber} />
                        <div className="sm:col-span-2">
                            <VehicleSelector
                                value={customer.carBrandModel}
                                onChange={handleVehicleChange}
                                error={errors.carBrandModel}
                                vehicleData={vehicleData}
                                onUpdateVehicleData={noOp}
                            />
                        </div>
                    </>
                )}
                 <div>
                    <label htmlFor="vehicleCategoryTag" className="block text-sm font-medium text-slate-700 mb-1">
                        Vehicle Category
                    </label>
                    <select
                        id="vehicleCategoryTag"
                        value={vehicleCategoryTag || ''}
                        onChange={(e) => setVehicleCategoryTag(e.target.value as VehicleCategoryTag)}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm"
                    >
                        <option value="">-- Select Category --</option>
                        {VEHICLE_CATEGORY_TAGS.map(tag => (
                            <option key={tag} value={tag}>{tag}</option>
                        ))}
                    </select>
                </div>
                <Input label="Street Address" name="streetAddress" className="sm:col-span-2" value={customer.streetAddress} onChange={handleCustomerChange} />

                {/* Location Pinning UI */}
                <div className="sm:col-span-2 bg-slate-50 p-3 rounded-lg border border-slate-200">
                    <div className="flex items-center justify-between">
                         <div className="flex items-center space-x-2">
                             <div className={`p-1.5 rounded-full ${customer.latitude ? 'bg-green-100 text-green-600' : 'bg-slate-200 text-slate-400'}`}>
                                 <IconMapPin className="w-5 h-5" />
                             </div>
                             <div>
                                 <p className="text-sm font-medium text-slate-800">
                                    {customer.latitude ? 'Location Pinned' : 'Location Not Set'}
                                 </p>
                                 <p className="text-xs text-slate-500">
                                     {customer.latitude && customer.longitude 
                                        ? `${customer.latitude.toFixed(6)}, ${customer.longitude.toFixed(6)}` 
                                        : 'Capture customer exact location'}
                                 </p>
                             </div>
                         </div>
                         <div className="flex space-x-2">
                             {customer.latitude && (
                                 <a 
                                    href={`https://www.google.com/maps/search/?api=1&query=${customer.latitude},${customer.longitude}`} 
                                    target="_blank" 
                                    rel="noreferrer"
                                    className="px-3 py-1.5 text-xs font-medium text-blue-600 hover:text-blue-800 hover:underline"
                                 >
                                     Verify
                                 </a>
                             )}
                             <Button type="button" variant={customer.latitude ? "secondary" : "primary"} size="sm" onClick={handleOpenLocationPicker}>
                                {customer.latitude ? <IconCrosshair className="w-4 h-4 mr-1"/> : <IconMapPin className="w-4 h-4 mr-1"/>}
                                {customer.latitude ? 'Update Pin' : 'Pin Location'}
                             </Button>
                         </div>
                    </div>
                </div>

              </div>
              {searchMessage.includes('Subscriber') && !foundProfiles && (
                <div className="mt-4 p-3 bg-green-50 border border-green-200 rounded-lg flex items-center justify-center space-x-3">
                    <IconTrophy className="w-6 h-6 text-green-600 flex-shrink-0"/>
                    <p className="text-sm font-semibold text-green-800 text-center">{searchMessage}</p>
                </div>
              )}
            </div>

            <div className="pt-4 border-t">
              <h3 className="text-md font-semibold text-slate-700 mb-2">Assignment & Scheduling</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="sm:col-span-2">
                    <label htmlFor="assignedTo" className="block text-sm font-medium text-slate-700 mb-1">Assign To (Optional)</label>
                    <select
                        id="assignedTo"
                        name="assignedTo"
                        value={assignedTo}
                        onChange={(e) => setAssignedTo(e.target.value)}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm"
                    >
                        <option value="">-- Unassigned (Queue) --</option>
                        {users.filter(u => u.role !== 'admin' && u.role !== 'manager').map(u => (
                            <option key={u.username} value={u.username}>{u.username} ({u.role})</option>
                        ))}
                    </select>
                </div>
                <Input 
                    label="Scheduled Date" 
                    type="date" 
                    value={scheduledDate} 
                    onChange={(e) => {
                        setScheduledDate(e.target.value);
                        if (errors.scheduledDate) setErrors(p => ({...p, scheduledDate: ''}));
                    }}
                    error={errors.scheduledDate}
                />
                <div>
                    <label htmlFor="scheduledTime" className="block text-sm font-medium text-slate-700 mb-1">Scheduled Time</label>
                    <select
                        id="scheduledTime"
                        name="scheduledTime"
                        value={scheduledTime}
                        onChange={(e) => setScheduledTime(e.target.value)}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm"
                    >
                        <option value="">-- No Time Set --</option>
                        {APPOINTMENT_TIME_SLOTS.map(time => (
                            <option key={time} value={time}>{time}</option>
                        ))}
                    </select>
                </div>
              </div>
            </div>

            <div className="pt-4 border-t">
              <h3 className="text-md font-semibold text-slate-700 mb-2">Select Services</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {serviceTemplates.filter(t => t.isEnabled).map(template => {
                  const isSelected = serviceSelection.includes(template.name);
                  return (
                    <button
                      key={template.id}
                      type="button"
                      onClick={() => handleToggleService(template.name)}
                      className={`p-3 text-left rounded-lg border-2 transition-all duration-200 ${
                        isSelected 
                        ? 'bg-brand-accent/10 border-brand-accent' 
                        : 'bg-white border-slate-300 hover:border-brand-accent/70'
                      }`}
                    >
                      <div className="flex items-center justify-between">
                        <span className={`font-semibold text-sm ${isSelected ? 'text-brand-blue' : 'text-slate-700'}`}>{template.name}</span>
                        <div className={`w-5 h-5 rounded-full flex items-center justify-center border-2 ${isSelected ? 'bg-brand-accent border-brand-accent' : 'border-slate-300'}`}>
                          {isSelected && (
                            <svg className="w-3 h-3 text-brand-blue" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" />
                            </svg>
                          )}
                        </div>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>

        <div className="p-6 flex justify-end space-x-2 border-t border-slate-200 flex-shrink-0">
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button onClick={handleSubmit}>Create Order</Button>
        </div>
      </div>
    </div>

    <LocationPickerModal 
        isOpen={isLocationPickerOpen}
        onClose={() => setIsLocationPickerOpen(false)}
        onConfirm={handleLocationConfirm}
        initialLat={customer.latitude}
        initialLng={customer.longitude}
    />
    </>
  );
};

export default CreateOrderModal;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Service, ServiceStatus, User, UserSubscription, ServiceTemplate, Permission, TyreData, PricingConfig } from './types';
import { useServiceForm } from './hooks/useServiceForm';
import CustomerDetailsStep from './CustomerDetailsStep';
import ServiceSelectionStep from './ServiceSelectionStep';
import { ServiceDetailsStep } from './ServiceDetailsStep';
import AddonsStep from './AddonsStep';
import CustomServicesStep from './CustomServicesStep';
import { SummaryStep } from './SummaryStep';
import Stepper from './Stepper';
import Card from './ui/Card';
import Button from './ui/Button';
import Input from './ui/Input';
import { APPOINTMENT_TIME_SLOTS, DEFAULT_PRICING_CONFIG } from './constants';
import { validateStep, ValidationErrors } from './services/validationService';
import { IconDeviceFloppy } from './ui/Icon';
import DependencyManager from './DependencyManager';
import CarCareStep from './CarCareStep';

interface ServiceFormProps {
  initialService?: Service | null;
  allSubmissions: Service[];
  onComplete: (service: Service) => void;
  onSaveDraft: (service: Service) => void;
  onAdminUpdate?: (service: Service) => void;
  onExit: () => void;
  googleDriveUploadUrl: string;
  currentUser: User;
  allUsers: Omit<User, 'password'>[];
  userSubscriptions: UserSubscription[];
  serviceTemplates: ServiceTemplate[];
  vehicleData: Record<string, string[]>;
  tyreData: TyreData;
  onUpdateVehicleData: (brand: string, model: string) => void;
  onUpdateTyreData: (type: keyof TyreData, value: string) => void;
  pricingConfig?: PricingConfig;
}

const ALL_STEPS = [
  { name: 'Customer Details', component: CustomerDetailsStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Service Selection', component: ServiceSelectionStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { 
    name: 'Car Care', 
    component: CarCareStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.includes("Car Care")
  },
  { 
    name: 'Service Details', 
    component: ServiceDetailsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.some(s => 
        ["Car Washing", "Tyre Replacement", "Battery Replacement"].includes(s)
      ) || state.serviceSelection.some(s => serviceTemplates.find(t => t.name === s && t.customFields.length > 0))
  },
  { 
    name: 'Add-ons', 
    component: AddonsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true
  },
  { name: 'Custom Services', component: CustomServicesStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Invoice Summary', component: SummaryStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
];

const ServiceForm: React.FC<ServiceFormProps> = ({ 
  initialService, 
  allSubmissions,
  onComplete, 
  onSaveDraft,
  onAdminUpdate,
  onExit, 
  googleDriveUploadUrl, 
  currentUser, 
  allUsers, 
  userSubscriptions,
  serviceTemplates, 
  vehicleData, 
  tyreData, 
  onUpdateVehicleData, 
  onUpdateTyreData, 
  pricingConfig = DEFAULT_PRICING_CONFIG,
}) => {
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const { state, dispatch, updateField } = useServiceForm(initialService, pricingConfig);
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [prefillServiceId, setPrefillServiceId] = useState('');
  const [saveConfirmation, setSaveConfirmation] = useState('');

  const isAdminEditing = useMemo(() => 
    currentUser.permissions.includes(Permission.CAN_EDIT_ANY_ORDER) && !!initialService,
  [currentUser, initialService]);

  useEffect(() => {
    if (initialService) {
      dispatch({ type: 'SET_FORM_DATA', payload: JSON.parse(JSON.stringify(initialService)) });
    }
  }, [initialService, dispatch]);


  const sortedSubmissions = useMemo(() => {
    return [...allSubmissions].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [allSubmissions]);

  const handlePrefillChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedId = e.target.value;
    setPrefillServiceId(selectedId);

    if (!selectedId) return;

    const serviceToCopy = allSubmissions.find(s => s.submissionId === selectedId);
    if (!serviceToCopy) return;

    const newSubmissionId = `SUB-${Date.now()}`;
    const newServiceData: Service = {
      ...JSON.parse(JSON.stringify(serviceToCopy)),
      submissionId: newSubmissionId,
      appointmentId: newSubmissionId,
      timestamp: new Date().toISOString(),
      status: ServiceStatus.Draft,
      acknowledgement: false,
      beforeWashingPhoto: '', beforeVideoInventory: '', beforeVideoTopBody: '', beforeVideoUnderchassis: '',
      afterWashingPhoto: '', afterVideoInterior: '', afterVideoExterior: '', afterVideoUnderchassis: '',
      tyreDetails: [],
      batteryDetails: [],
      customFieldData: (serviceToCopy.customFieldData || []).filter(field => {
          const allCustomFields = serviceTemplates.flatMap(st => st.customFields);
          const fieldDef = allCustomFields.find(f => f.id === field.fieldId);
          return fieldDef?.type !== 'PHOTO';
      }),
      assignedTo: undefined,
      scheduledDate: undefined,
      scheduledTime: undefined,
      internalNotes: '',
      isFollowUp: true,
      dependsOn: [], // Dependencies should not be copied
    };

    dispatch({ type: 'SET_FORM_DATA', payload: newServiceData });
  };


  const visibleSteps = useMemo(() => {
    return ALL_STEPS.map((step, index) => ({...step, originalIndex: index}))
                     .filter(step => step.isVisible(state, serviceTemplates));
  }, [state, serviceTemplates]);

  const StepComponent = visibleSteps[currentStepIndex].component;

  const handleStepClick = (index: number) => {
    if (isAdminEditing || index < currentStepIndex) {
      setErrors({}); 
      setCurrentStepIndex(index);
    }
  };

  const nextStep = () => {
    const currentStepName = visibleSteps[currentStepIndex].name;
    const validationErrors = validateStep(currentStepName, state);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      setCurrentStepIndex(prev => Math.min(prev + 1, visibleSteps.length - 1));
    }
  };

  const prevStep = () => {
    setErrors({}); 
    setCurrentStepIndex(prev => Math.max(prev - 1, 0));
  };

  const handleSubmit = () => {
    if (state.acknowledgement) {
      localStorage.removeItem('service_form_in_progress');
      onComplete(state);
    }
  };

  const handleSaveDraftClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onSaveDraft(state);
  };

  const handleAdminSave = () => {
    if (!onAdminUpdate) return;
    onAdminUpdate(state);
    setSaveConfirmation('Changes saved successfully!');
    setTimeout(() => setSaveConfirmation(''), 2500);
  };

  const handleExitClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onExit();
  };

  const handleUpdateDependencies = useCallback((newDeps: string[]) => {
    updateField('dependsOn', newDeps);
  }, [updateField]);

  const isLastStep = currentStepIndex === visibleSteps.length - 1;

  const showDraftButton = (!initialService || initialService?.status === ServiceStatus.Draft);

  return (
    <Card>
      {!initialService && (
        <div className="p-4 mb-8 bg-slate-50 border border-slate-200 rounded-lg no-print">
          <label htmlFor="prefill-select" className="block text-sm font-medium text-slate-700 mb-1">
            Pre-fill from Existing Service (Optional)
          </label>
          <select
            id="prefill-select"
            value={prefillServiceId}
            onChange={handlePrefillChange}
            className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus-visible:border-brand-accent sm:text-sm"
          >
            <option value="">-- Select a past service to copy data from --</option>
            {sortedSubmissions.map(s => (
              <option key={s.submissionId} value={s.submissionId}>
                {new Date(s.timestamp).toLocaleDateString()} - #{s.appointmentId?.split('-').pop()} - {s.customerFirstName} ({s.carNumber})
              </option>
            ))}
          </select>
        </div>
      )}

      <div className="mb-8 pb-4 border-b border-slate-200 no-print">
        <Stepper 
          steps={visibleSteps} 
          currentStepIndex={currentStepIndex} 
          onStepClick={handleStepClick}
          isClickable={isAdminEditing}
        />
      </div>

      {isAdminEditing && (
        <div className="sticky top-[63px] bg-slate-100/80 backdrop-blur-md z-20 -mx-6 px-6 -mt-8 mb-8">
            <div className="flex justify-between items-center h-16 border-b">
                 <Button variant="ghost" onClick={handleExitClick}>Exit to Dashboard</Button>
                 <div className="flex items-center space-x-4">
                    {saveConfirmation && <p className="text-sm font-semibold text-green-600 animate-pulse">{saveConfirmation}</p>}
                    <Button onClick={handleAdminSave}>
                        <IconDeviceFloppy className="w-5 h-5 mr-2" />
                        Save Changes
                    </Button>
                 </div>
            </div>
        </div>
      )}

      {isAdminEditing && (
        <div className="p-4 mb-8 bg-blue-50 border border-blue-200 rounded-lg">
          <h3 className="text-lg font-semibold text-blue-800 mb-4">Admin Controls</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label htmlFor="assignedTo" className="block text-sm font-medium text-slate-700 mb-1">Assigned User</label>
              <select
                id="assignedTo"
                name="assignedTo"
                value={state.assignedTo || ''}
                onChange={(e) => updateField('assignedTo', e.target.value || undefined)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                <option value="">-- Unassigned --</option>
                {allUsers.map(u => <option key={u.username} value={u.username}>{u.username}</option>)}
              </select>
            </div>
            <Input 
                label="Scheduled Date" 
                id="scheduledDate"
                type="date"
                value={state.scheduledDate ? state.scheduledDate.split('T')[0] : ''}
                onChange={(e) => updateField('scheduledDate', e.target.value)}
            />
            <div>
              <label htmlFor="scheduledTime" className="block text-sm font-medium text-slate-700 mb-1">Scheduled Time</label>
              <select
                  id="scheduledTime"
                  name="scheduledTime"
                  value={state.scheduledTime || ''}
                  onChange={(e) => updateField('scheduledTime', e.target.value || undefined)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                  <option value="">-- No Time Set --</option>
                  {APPOINTMENT_TIME_SLOTS.map(time => (
                      <option key={time} value={time}>{time}</option>
                  ))}
              </select>
            </div>
             <div>
                <label htmlFor="status" className="block text-sm font-medium text-slate-700 mb-1">Status</label>
                <select
                    id="status"
                    name="status"
                    value={state.status}
                    onChange={(e) => updateField('status', e.target.value as ServiceStatus)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
                >
                    {Object.values(ServiceStatus).map(status => (
                        <option key={status} value={status}>{status}</option>
                    ))}
                </select>
            </div>
          </div>
           <div className="mt-6 pt-4 border-t">
              <DependencyManager 
                  service={state}
                  allSubmissions={allSubmissions}
                  onUpdateDependencies={handleUpdateDependencies}
              />
            </div>
        </div>
      )}

      {initialService && (currentUser.role === 'admin' || currentUser.role === 'manager' || currentUser.username === initialService.assignedTo) && (
        <div className="p-4 mb-8 bg-yellow-50 border border-yellow-200 rounded-lg">
            <h3 className="text-lg font-semibold text-yellow-800 mb-2">Internal Notes</h3>
            <p className="text-sm text-yellow-700 mb-4">These notes are only visible to administrators, managers, and the assigned service agent.</p>
            <textarea
                id="internalNotes"
                name="internalNotes"
                value={state.internalNotes || ''}
                onChange={(e) => updateField('internalNotes', e.target.value)}
                rows={3}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                placeholder="Add any internal remarks for this service (e.g., customer is particular about wheels, specific tool needed)..."
            />
        </div>
      )}

      <div className="min-h-[300px]">
        <h2 className="text-2xl font-bold text-slate-800 mb-6">{visibleSteps[currentStepIndex].name}</h2>
        {isLastStep ? (
          <SummaryStep state={state} updateField={updateField} serviceTemplates={serviceTemplates} />
        ) : (
          <StepComponent 
            state={state} 
            updateField={updateField} 
            dispatch={dispatch} 
            googleDriveUploadUrl={googleDriveUploadUrl}
            userSubscriptions={userSubscriptions}
            serviceTemplates={serviceTemplates}
            errors={errors}
            allSubmissions={allSubmissions}
            vehicleData={vehicleData}
            tyreData={tyreData}
            onUpdateVehicleData={onUpdateVehicleData}
            onUpdateTyreData={onUpdateTyreData}
            pricingConfig={pricingConfig}
          />
        )}
      </div>

      {!isAdminEditing && (
          <div className="mt-8 pt-6 border-t border-slate-200 flex flex-col-reverse gap-y-4 sm:flex-row sm:justify-between sm:items-center no-print">
            <div className="flex items-center space-x-2">
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep}>Back</Button>
                )}
                <Button variant="ghost" onClick={handleExitClick}>Exit to Dashboard</Button>
            </div>
            <div className="flex items-center space-x-2 w-full sm:w-auto">
              {showDraftButton && (
                <Button variant="ghost" onClick={handleSaveDraftClick}>Save as Draft</Button>
              )}

              {!isLastStep && (
                <Button onClick={nextStep} className="flex-1 sm:flex-auto justify-center">Next</Button>
              )}

              {isLastStep && (
                <Button onClick={handleSubmit} disabled={!state.acknowledgement} className="flex-1 sm:flex-auto justify-center">
                    Complete Order
                </Button>
              )}
            </div>
          </div>
      )}

      {isAdminEditing && (
        <div className="mt-8 pt-6 border-t border-slate-200 flex justify-between items-center no-print">
            <div>
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep}>Back</Button>
                )}
            </div>

            {!isLastStep && (
                <Button onClick={nextStep}>Next</Button>
            )}
        </div>
      )}

    </Card>
  );
};

