import React, { useEffect, useRef, useState } from 'react';
import Button from './Button';
import { IconMapPin, IconCrosshair } from './Icon';

// Declare Leaflet global
declare const L: any;

interface LocationPickerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (lat: number, lng: number) => void;
  initialLat?: number;
  initialLng?: number;
}

const LocationPickerModal: React.FC<LocationPickerModalProps> = ({
  isOpen,
  onClose,
  onConfirm,
  initialLat,
  initialLng,
}) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<any>(null);
  const markerRef = useRef<any>(null);
  const [currentPos, setCurrentPos] = useState<{ lat: number; lng: number } | null>(
    initialLat && initialLng ? { lat: initialLat, lng: initialLng } : null
  );

  useEffect(() => {
    // If the modal is closing, cleanup map
    if (!isOpen) {
        if (mapInstanceRef.current) {
            mapInstanceRef.current.remove();
            mapInstanceRef.current = null;
        }
        return;
    }

    // Initialize Map only if isOpen is true and map isn't already initialized
    if (isOpen && mapContainerRef.current && !mapInstanceRef.current) {
      // Default to Krishnanagar, West Bengal (741101)
      const defaultCenter = [23.4013, 88.5021];
      // Use level 13 for city view if no initial lat provided
      const zoomLevel = initialLat ? 16 : 13;
      const center = initialLat && initialLng ? [initialLat, initialLng] : defaultCenter;

      const map = L.map(mapContainerRef.current).setView(center, zoomLevel);
      mapInstanceRef.current = map;

      // Add Tile Layer
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; OpenStreetMap contributors',
        maxZoom: 19,
      }).addTo(map);

      // Custom Icon
      const customIcon = L.divIcon({
        html: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" style="color: #dc2626; width: 40px; height: 40px; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.3));"><path fill-rule="evenodd" d="M11.54 22.351l.07.04.028.016a.76.76 0 00.723 0l.028-.015.071-.041a16.975 16.975 0 001.144-.742 19.58 19.58 0 002.683-2.282c1.944-1.99 3.963-4.98 3.963-8.827a8.25 8.25 0 00-16.5 0c0 3.846 2.02 6.837 3.963 8.827a19.58 19.58 0 002.682 2.282 16.975 16.975 0 001.145.742zM12 13.5a3 3 0 100-6 3 3 0 000 6z" clip-rule="evenodd" /></svg>`,
        className: 'bg-transparent border-none',
        iconSize: [40, 40],
        iconAnchor: [20, 40],
      });

      // Add Marker
      const marker = L.marker(center, { icon: customIcon, draggable: true }).addTo(map);
      markerRef.current = marker;

      // Event: Marker Drag
      marker.on('dragend', function (event: any) {
        const m = event.target;
        const position = m.getLatLng();
        setCurrentPos({ lat: position.lat, lng: position.lng });
        map.panTo(position);
      });

      // Event: Map Click
      map.on('click', function (e: any) {
        marker.setLatLng(e.latlng);
        setCurrentPos({ lat: e.latlng.lat, lng: e.latlng.lng });
        map.panTo(e.latlng);
      });

      // If no initial location passed, try to auto-locate
      if (!initialLat && !initialLng) {
        map.locate({ setView: true, maxZoom: 16 });
        map.on('locationfound', (e: any) => {
             marker.setLatLng(e.latlng);
             setCurrentPos({ lat: e.latlng.lat, lng: e.latlng.lng });
        });
      }
    }
  }, [isOpen, initialLat, initialLng]);

  const handleLocateMe = () => {
      const map = mapInstanceRef.current;
      if (!map) return;
      map.locate({ setView: true, maxZoom: 16 });
  };

  const handleConfirm = () => {
    if (currentPos) {
      onConfirm(currentPos.lat, currentPos.lng);
      onClose();
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-[60] p-4 modal-backdrop" onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-2xl bg-white rounded-xl shadow-xl flex flex-col h-[80vh] md:h-[600px] modal-content">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center rounded-t-xl">
          <h3 className="text-lg font-semibold text-slate-800">Pin Exact Location</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
            <span className="text-2xl leading-none">&times;</span>
          </button>
        </div>

        <div className="flex-1 relative bg-slate-100">
            <div ref={mapContainerRef} className="w-full h-full z-0" />

            <button 
                onClick={handleLocateMe}
                className="absolute top-4 right-4 z-[400] bg-white p-2 rounded-md shadow-md border border-slate-300 text-slate-600 hover:bg-slate-50 hover:text-brand-blue"
                title="Use Current Location"
            >
                <IconCrosshair className="w-6 h-6" />
            </button>
            <div className="absolute bottom-4 left-4 right-4 z-[400] bg-white/90 backdrop-blur px-3 py-2 rounded-md shadow text-xs text-center sm:text-left text-slate-600 pointer-events-none">
                Drag the marker or click on the map to set the exact customer location.
            </div>
        </div>

        <div className="p-4 bg-white border-t border-slate-200 rounded-b-xl flex justify-between items-center gap-4">
             <div className="text-sm text-slate-600 hidden sm:block">
                {currentPos ? (
                    <span className="font-mono bg-slate-100 px-2 py-1 rounded">
                        {currentPos.lat.toFixed(6)}, {currentPos.lng.toFixed(6)}
                    </span>
                ) : (
                    <span>Location not set</span>
                )}
             </div>
             <div className="flex space-x-3 w-full sm:w-auto justify-end">
                 <Button variant="ghost" onClick={onClose}>Cancel</Button>
                 <Button onClick={handleConfirm} disabled={!currentPos}>
                    <IconMapPin className="w-4 h-4 mr-2" />
                    Confirm Pin
                 </Button>
             </div>
        </div>
      </div>
    </div>
  );
};

export default LocationPickerModal;

