const cleanSelectionArray = (arr: any[] | undefined): string[] => {
    if (!arr || !Array.isArray(arr)) return [];

    const cleaned: string[] = [];
    const addCleanedItem = (item: any) => {
        if (typeof item === 'string') {
            const trimmed = item.trim();
            // Check for stringified arrays like '["Item"]'
            if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
                try {
                    const parsed = JSON.parse(trimmed);
                    if (Array.isArray(parsed)) {
                         parsed.forEach(p => addCleanedItem(p));
                         return;
                    } else if (parsed) {
                         addCleanedItem(parsed);
                         return;
                    }
                } catch(e) {
                    // Fallback if not valid JSON but has brackets
                }
            }
            // Aggressively strip brackets and quotes for single items like '[Car Washing'
            const stripped = trimmed.replace(/[\[\]"']/g, '').trim();
            if (stripped) cleaned.push(stripped);
        } else if (item) {
            cleaned.push(String(item));
        }
    };

    arr.forEach(item => addCleanedItem(item));
    return [...new Set(cleaned)];
};

