        return n;
    }));
    // FIX: Changed 'n' to 'notifToSave' to fix variable not defined error.
    if(notifToSave) cloudDataService.saveRecord('Notifications', notifToSave, settings.googleSheetsUrl);
  };

  const handleMarkAllAsRead = () => {
    if (!currentUser) return;
    const notificationsToUpdate: AppNotification[] = [];
    setNotifications(prev => prev.map(n => {
        if((n.userId === currentUser.username || currentUser.role === 'admin' || currentUser.role === 'manager') && !n.isRead) {
            const updated = { ...n, isRead: true };
            notificationsToUpdate.push(updated);
            return updated;
        }
        return n;
    }));
    notificationsToUpdate.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
  };

  const handleManualNotifyAll = useCallback(() => {
    if (!currentUser || currentUser.role !== 'admin') return;

    const newNotifications: AppNotification[] = [];
    users.forEach(user => {
        const message = `Admin Broadcast from ${currentUser.username}: Please check the dashboard for updates.`;
        const notif: AppNotification = {
            id: `notif_manual_${Date.now()}_${user.username}`,
            userId: user.username, serviceId: 'manual_broadcast', message,
            timestamp: new Date().toISOString(), isRead: false, type: 'manual-admin'
        };
        newNotifications.push(notif);
        const prefs = user.notificationPreferences || defaultNotificationPrefs;
        if(prefs.enabled.manual) {
            playNotificationAlert(prefs);
            if(user.pushSubscription) sendPushNotification(user.pushSubscription, "Admin Broadcast", message, prefs);
        }
    });

    setNotifications(prev => [...prev, ...newNotifications]);
    newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
    setIsNotificationHistoryOpen(true);
}, [currentUser, users, settings.googleSheetsUrl]);

const handleNotifyForOrder = useCallback((serviceId: string) => {
    const service = submissions.find(s => s.submissionId === serviceId);
    if (!service || service.status === ServiceStatus.Completed || service.status === ServiceStatus.Draft) return;

    let newNotifications: AppNotification[] = [];
    let usersToNotify: User[] = [];

    if (service.status === ServiceStatus.Queued) {
        usersToNotify = users.filter(u => u.role === 'admin' || u.role === 'manager');
        usersToNotify.forEach(admin => {
            newNotifications.push({
                id: `notif_manual_order_${Date.now()}_${admin.username}`, userId: admin.username, serviceId: service.submissionId,
                message: `Admin Reminder: The queued order for ${service.customerFirstName} needs attention.`,
                timestamp: new Date().toISOString(), isRead: false, type: 'manual-order'
            });
        });
    } else if ((service.status === ServiceStatus.Assigned || service.status === ServiceStatus.InProgress) && service.assignedTo) {
        const assignedUser = users.find(u => u.username === service.assignedTo);
        if (assignedUser) {
            usersToNotify.push(assignedUser);
            newNotifications.push({
                id: `notif_manual_order_${Date.now()}_${service.assignedTo}`, userId: service.assignedTo, serviceId: service.submissionId,
                message: `Reminder: Please check on your assigned order for ${service.customerFirstName}.`,
                timestamp: new Date().toISOString(), isRead: false, type: 'manual-order'
            });
        }
    }

    if (newNotifications.length > 0) {
        setNotifications(prev => [...prev, ...newNotifications]);
        newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
        usersToNotify.forEach(user => {
            const prefs = user.notificationPreferences || defaultNotificationPrefs;
            if(prefs.enabled.manual) {
                playNotificationAlert(prefs);
                const message = newNotifications.find(n => n.userId === user.username)?.message || "Order Reminder";
                if(user.pushSubscription) sendPushNotification(user.pushSubscription, "Order Reminder", message, prefs);
            }
        });
    }
}, [submissions, users, settings.googleSheetsUrl]);

const handleUpdateNotificationPreferences = (username: string, prefs: NotificationPreferences) => {
    let userToSave: User | undefined;
    setUsers(prev => prev.map(u => {
        if(u.username === username) {
            userToSave = { ...u, notificationPreferences: prefs };
            return userToSave;
        }
        return u;
    }));
    if(currentUser?.username === username) {
        setCurrentUser(prev => prev ? ({...prev, notificationPreferences: prefs}) : null);
    }
    if(userToSave) cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
  };

const handleUpdatePushSubscription = (username: string, subscription: PushSubscriptionJSON | null) => {
    let userToSave: User | undefined;
    setUsers(prev => prev.map(u => {
        if(u.username === username) {
            userToSave = { ...u, pushSubscription: subscription || undefined };
            return userToSave;
        }
        return u;
    }));
    if(currentUser?.username === username) {
        setCurrentUser(prev => prev ? ({ ...prev, pushSubscription: subscription || undefined }) : null);
    }
    if(userToSave) cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
};

const handleSaveNewSpend = (spendData: Omit<MiscSpend, 'spendId' | 'userId' | 'timestamp' | 'status'>) => {
    if (!currentUser) return;
    const newSpend: MiscSpend = {
        ...spendData,
        spendId: `spend_${Date.now()}`,
        userId: currentUser.username,
        timestamp: new Date().toISOString(),
        status: MiscSpendStatus.Pending,
    };
    setMiscSpends(prev => [...prev, newSpend]);
    cloudDataService.saveRecord('MiscSpends', newSpend, settings.googleSheetsUrl);
    triggerHapticFeedback('success');
};

const handleUpdateSpendStatus = (spendId: string, status: MiscSpendStatus) => {
    const originalSpend = miscSpends.find(s => s.spendId === spendId);
    if (!originalSpend) {
        console.error(`Could not find MiscSpend with id ${spendId} to update.`);
        return;
    }

    const updatedSpend = { ...originalSpend, status };

    setMiscSpends(prevSpends => prevSpends.map(s => s.spendId === spendId ? updatedSpend : s));

    cloudDataService.saveRecord('MiscSpends', updatedSpend, settings.googleSheetsUrl);

    const wasPaid = originalSpend.status === MiscSpendStatus.Paid;
    const isNowPaid = status === MiscSpendStatus.Paid;

    if (!wasPaid && isNowPaid) {
        // Add expense entry to bookkeeping
        const newExpenseEntry: BookkeepingEntry = {
            id: `bk_exp_${spendId}`,
            timestamp: new Date().toISOString(),
            type: BookkeepingEntryType.Expense,
            description: `${updatedSpend.spendType} by ${updatedSpend.userId}`,
            amount: updatedSpend.amount,
            relatedId: spendId,
            recordedBy: currentUser?.username || 'system',
        };
        setBookkeeping(prev => [...prev.filter(b => b.id !== newExpenseEntry.id), newExpenseEntry]);
        cloudDataService.saveRecord('Bookkeeping', newExpenseEntry, settings.googleSheetsUrl);
    } else if (wasPaid && !isNowPaid) {
        // Remove expense entry from bookkeeping
        setBookkeeping(prev => prev.filter(b => b.relatedId !== spendId));
        cloudDataService.deleteRecord('Bookkeeping', `bk_exp_${spendId}`, settings.googleSheetsUrl);
    }

    triggerHapticFeedback('success');
};

const handleUpdateAttendanceStatus = (username: string, status: AttendanceStatus) => {
    const newRecord = { timestamp: new Date().toISOString(), status };
    let userToSave: User | undefined;

    const updatedUsers = users.map(u => {
        if (u.username === username) {
            userToSave = {
                ...u,
                attendanceStatus: status,
                attendanceHistory: [...(u.attendanceHistory || []), newRecord]
            };
            return userToSave;
        }
        return u;
    });
    setUsers(updatedUsers);

    if (currentUser?.username === username) {
        const updatedCurrentUser = updatedUsers.find(u => u.username === username)!;
        setCurrentUser(updatedCurrentUser);
        localStorage.setItem('service_app_current_user', JSON.stringify(updatedCurrentUser));
    }
    if(userToSave) {
        cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
        triggerHapticFeedback('success');
    }
};

