               /> : <DashboardPage {...dashboardProps} />;
       case 'CUSTOMER_HISTORY':
        return hasPermission(Permission.CAN_VIEW_CUSTOMER_HISTORY) ? <CustomerHistoryPage
                 submissions={submissions.filter(s => !s.isDeleted)}
