                          aria-label="Refresh data from cloud"
                          title={!settings.googleSheetsUrl ? "Cloud sync is offline. Check settings." : "Refresh data from cloud"}
                      >
                          <IconRefresh className={`w-6 h-6 ${isManualRefreshing ? 'animate-spin' : ''}`} />
                      </button>
                      <SyncStatusIndicator status={syncStatus} errorMessage={syncError} />
                  </div>
                   {isNotificationHistoryOpen && (
                        <NotificationHistory
                            notifications={currentUserNotifications}
                            onMarkAsRead={handleMarkNotificationAsRead}
                            onMarkAllAsRead={handleMarkAllAsRead}
                            onClose={() => setIsNotificationHistoryOpen(false)}
                        />
                    )}
              </div>
          </header>

          <main className="p-4 sm:p-6 lg:p-8 w-full">
            {syncStatus === 'ERROR' && syncError && (
                <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 relative mb-6 rounded-r-md" role="alert">
                    <strong className="font-bold">Sync Error:</strong>
                    <span className="block sm:inline ml-2">{syncError}</span>
