import React, { useState, useMemo } from 'react';
import { User, AttendanceRecord, AttendanceStatus } from '../../types';
import Card from '../ui/Card';
import Button from '../ui/Button';
import Input from '../ui/Input';
import { IconFingerprint, IconUserCheck, IconUserOff, IconClock, IconChevronDown } from '../ui/Icon';

interface AttendancePageProps {
  users: Omit<User, 'password'>[];
}

interface ProcessedAttendance {
  username: string;
  firstIn: string | null;
  lastOut: string | null;
  totalDurationMs: number;
  status: 'Present' | 'Absent' | 'Active Now';
  logs: AttendanceRecord[];
}

const formatDuration = (ms: number): string => {
  if (ms === 0) return '0h 0m';
  const hours = Math.floor(ms / (1000 * 60 * 60));
  const minutes = Math.floor((ms % (1000 * 60 * 60)) / (1000 * 60));
  return `${hours}h ${minutes}m`;
};

const formatTime = (isoString: string): string => {
  return new Date(isoString).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', hour12: true });
};

const AttendancePage: React.FC<AttendancePageProps> = ({ users }) => {
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [expandedUser, setExpandedUser] = useState<string | null>(null);

  const processedData: ProcessedAttendance[] = useMemo(() => {
    const selectedDateObj = new Date(selectedDate);
    const dateStr = selectedDateObj.toDateString();

    return users
      .filter(u => u.role !== 'admin') // Exclude generic admin accounts from attendance
      .map(user => {
        const history = user.attendanceHistory || [];

        // Filter logs for the selected date
        const dailyLogs = history.filter(log => {
          const logDate = new Date(log.timestamp);
          return logDate.toDateString() === dateStr;
        }).sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());

        let firstIn = null;
        let lastOut = null;
        let totalDurationMs = 0;
        let currentState: AttendanceStatus | null = null;
        let lastInTime: number | null = null;

        // Calculate duration based on pairs of IN/OUT
        dailyLogs.forEach((log) => {
            if (log.status === 'CHECKED_IN') {
                if (!firstIn) firstIn = log.timestamp;
                if (!lastInTime) lastInTime = new Date(log.timestamp).getTime();
                currentState = 'CHECKED_IN';
            } else if (log.status === 'CHECKED_OUT') {
                lastOut = log.timestamp;
                if (lastInTime) {
                    totalDurationMs += (new Date(log.timestamp).getTime() - lastInTime);
                    lastInTime = null;
                }
                currentState = 'CHECKED_OUT';
            }
        });

        // Handle case where user is still active (active session adds to duration if viewing today)
        const isToday = new Date().toDateString() === dateStr;
        if (currentState === 'CHECKED_IN' && lastInTime && isToday) {
             totalDurationMs += (new Date().getTime() - lastInTime);
        }

        let status: 'Present' | 'Absent' | 'Active Now' = 'Absent';
        if (currentState === 'CHECKED_IN' && isToday) status = 'Active Now';
        else if (dailyLogs.length > 0) status = 'Present';

        return {
          username: user.username,
          firstIn,
          lastOut,
          totalDurationMs,
          status,
          logs: dailyLogs
        };
      }).sort((a, b) => {
          // Sort by active, then present, then absent
          const rank = (s: string) => s === 'Active Now' ? 0 : s === 'Present' ? 1 : 2;
          return rank(a.status) - rank(b.status);
      });
  }, [users, selectedDate]);

  const stats = useMemo(() => {
      const active = processedData.filter(d => d.status === 'Active Now').length;
      const present = processedData.filter(d => d.status === 'Present').length;
      const absent = processedData.filter(d => d.status === 'Absent').length;
      return { active, present, absent, total: processedData.length };
  }, [processedData]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 tracking-tight flex items-center gap-3">
                Attendance Management
            </h1>
             <p className="text-slate-500 mt-1">Track daily agent check-ins, work hours, and activity logs.</p>
        </div>
        <div className="bg-white p-2 rounded-lg shadow-sm border border-slate-200">
            <Input 
                label="" 
                type="date" 
                id="attendance-date" 
                value={selectedDate} 
                onChange={(e) => setSelectedDate(e.target.value)} 
                className="!mt-0"
            />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
           <div className="bg-green-100 p-4 rounded-xl border border-green-200 flex items-center justify-between">
                <div>
                    <p className="text-sm font-semibold text-green-800 uppercase tracking-wider">Active Now</p>
                    <p className="text-3xl font-bold text-green-900">{stats.active}</p>
                </div>
                <div className="p-3 bg-white/50 rounded-full">
                    <IconUserCheck className="w-6 h-6 text-green-700" />
                </div>
           </div>
           <div className="bg-blue-100 p-4 rounded-xl border border-blue-200 flex items-center justify-between">
                <div>
                    <p className="text-sm font-semibold text-blue-800 uppercase tracking-wider">Checked Out</p>
                    <p className="text-3xl font-bold text-blue-900">{stats.present}</p>
                </div>
                 <div className="p-3 bg-white/50 rounded-full">
                    <IconClock className="w-6 h-6 text-blue-700" />
                </div>
           </div>
           <div className="bg-slate-100 p-4 rounded-xl border border-slate-200 flex items-center justify-between">
                <div>
                    <p className="text-sm font-semibold text-slate-600 uppercase tracking-wider">Absent</p>
                    <p className="text-3xl font-bold text-slate-800">{stats.absent}</p>
                </div>
                 <div className="p-3 bg-white/50 rounded-full">
                    <IconUserOff className="w-6 h-6 text-slate-500" />
                </div>
           </div>
      </div>

      <Card title={`Attendance Report for ${new Date(selectedDate).toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'})}`}>
        <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-slate-200">
                <thead className="bg-slate-50">
                    <tr>
                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Agent</th>
                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Status</th>
                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">First In</th>
                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Last Out</th>
                        <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Total Duration</th>
                        <th className="px-6 py-3 text-right text-xs font-bold text-slate-500 uppercase tracking-wider">Details</th>
                    </tr>
                </thead>
                <tbody className="bg-white divide-y divide-slate-200">
                    {processedData.map((data) => (
                        <React.Fragment key={data.username}>
                            <tr className="hover:bg-slate-50 transition-colors">
                                <td className="px-6 py-4 whitespace-nowrap">
                                    <div className="font-semibold text-slate-800">{data.username}</div>
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap">
                                    <span className={`px-2 py-1 text-xs font-semibold rounded-full ${
                                        data.status === 'Active Now' ? 'bg-green-100 text-green-800' :
                                        data.status === 'Present' ? 'bg-blue-100 text-blue-800' :
                                        'bg-slate-100 text-slate-500'
                                    }`}>
                                        {data.status}
                                    </span>
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                                    {data.firstIn ? formatTime(data.firstIn) : '-'}
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                                    {data.lastOut ? formatTime(data.lastOut) : '-'}
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm font-mono text-slate-700">
                                    {formatDuration(data.totalDurationMs)}
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-right">
                                    <button 
                                        onClick={() => setExpandedUser(expandedUser === data.username ? null : data.username)}
                                        className="text-brand-blue hover:bg-brand-blue/10 p-2 rounded-full transition-colors"
                                        disabled={data.logs.length === 0}
                                    >
                                        <IconChevronDown className={`w-5 h-5 transition-transform duration-300 ${expandedUser === data.username ? 'rotate-180' : ''} ${data.logs.length === 0 ? 'opacity-30' : ''}`} />
                                    </button>
                                </td>
                            </tr>
                            {expandedUser === data.username && data.logs.length > 0 && (
                                <tr className="bg-slate-50">
                                    <td colSpan={6} className="px-6 py-4">
                                        <div className="text-sm">
                                            <p className="font-semibold text-slate-600 mb-2">Activity Log:</p>
                                            <ul className="space-y-2">
                                                {data.logs.map((log, idx) => (
                                                    <li key={idx} className="flex items-center space-x-3 text-slate-700">
                                                        <div className={`w-2 h-2 rounded-full ${log.status === 'CHECKED_IN' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                                                        <span className="font-mono text-xs text-slate-500">{formatTime(log.timestamp)}</span>
                                                        <span className="font-medium">{log.status === 'CHECKED_IN' ? 'Checked In' : 'Checked Out'}</span>
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </React.Fragment>
                    ))}
                    {processedData.length === 0 && (
                         <tr>
                            <td colSpan={6} className="px-6 py-10 text-center text-slate-500">No users found.</td>
                        </tr>
                    )}
                </tbody>
            </table>
        </div>
      </Card>
    </div>
  );
};

export default AttendancePage;

