const handleNotifyForOrder = useCallback((serviceId: string) => {
    const service = submissions.find(s => s.submissionId === serviceId);
    if (!service || service.status === ServiceStatus.Completed || service.status === ServiceStatus.Draft) return;

    let newNotifications: AppNotification[] = [];
    let usersToNotify: User[] = [];

    if (service.status === ServiceStatus.Queued) {
        usersToNotify = users.filter(u => u.role === 'admin' || u.role === 'manager');
        usersToNotify.forEach(admin => {
            newNotifications.push({
                id: `notif_manual_order_${Date.now()}_${admin.username}`, userId: admin.username, serviceId: service.submissionId,
                message: `Admin Reminder: The queued order for ${service.customerFirstName} needs attention.`,
                timestamp: new Date().toISOString(), isRead: false, type: 'manual-order'
            });
        });
    } else if ((service.status === ServiceStatus.Assigned || service.status === ServiceStatus.InProgress) && service.assignedTo) {
        const assignedUser = users.find(u => u.username === service.assignedTo);
        if (assignedUser) {
            usersToNotify.push(assignedUser);
            newNotifications.push({
                id: `notif_manual_order_${Date.now()}_${service.assignedTo}`, userId: service.assignedTo, serviceId: service.submissionId,
                message: `Reminder: Please check on your assigned order for ${service.customerFirstName}.`,
                timestamp: new Date().toISOString(), isRead: false, type: 'manual-order'
            });
        }
    }

    if (newNotifications.length > 0) {
        setNotifications(prev => [...prev, ...newNotifications]);
        newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
        usersToNotify.forEach(user => {
            const prefs = user.notificationPreferences || defaultNotificationPrefs;
            if(prefs.enabled.manual) {
                playNotificationAlert(prefs);
                const message = newNotifications.find(n => n.userId === user.username)?.message || "Order Reminder";
                if(user.pushSubscription) sendPushNotification(user.pushSubscription, "Order Reminder", message, prefs);
            }
        });
    }
}, [submissions, users, settings.googleSheetsUrl]);

