        return hasPermission(Permission.CAN_VIEW_APPOINTMENTS_OVERVIEW) ? <AppointmentsOverviewPage
                    currentUser={currentUser}
                    submissions={submissions.filter(s => !s.isDeleted)}
                    onUpdateOrder={handleEditService}
                    onStartOrder={handleStartOrder}
                    onShareOrder={handleShareOrder}
                /> : <DashboardPage {...dashboardProps} />;
      case 'NOTIFICATION_PREFERENCES':
        return <NotificationPreferencesPage
                 currentUser={currentUser}
                 onSave={handleUpdateNotificationPreferences}
                 onUpdatePushSubscription={handleUpdatePushSubscription}
               />;
      case 'USER_MANAGEMENT':
        return hasPermission(Permission.CAN_MANAGE_USERS) ? <UserManagementPage
                 users={users.map(({password, ...rest}) => rest)}
                 onUpdateUsers={handleUpdateUsers}
                 fullUserList={users}
                 currentUser={currentUser}
               /> : <DashboardPage {...dashboardProps} />;
      case 'SERVICE_TEMPLATE_MANAGEMENT':
        return hasPermission(Permission.CAN_MANAGE_SERVICES) ? <ServiceTemplateManagementPage
                  templates={serviceTemplates}
                  onUpdateTemplates={handleUpdateServiceTemplates}
                  onEditTemplate={handleEditTemplate}
                /> : <DashboardPage {...dashboardProps} />;
       case 'SERVICE_TEMPLATE_EDITOR':
        return hasPermission(Permission.CAN_MANAGE_SERVICES) ? <ServiceTemplateEditorPage
                  template={editingTemplate!}
                  onSave={handleSaveServiceTemplate}
                  onExit={() => { setView('SERVICE_TEMPLATE_MANAGEMENT'); setEditingTemplate(null); }}
               /> : <DashboardPage {...dashboardProps} />;
      case 'PLAN_MANAGEMENT':
          return hasPermission(Permission.CAN_MANAGE_PLANS) ? <SubscriptionPlanManagementPage
                    plans={subscriptionPlans}
                    onUpdatePlans={handleUpdateSubscriptionPlans}
                /> : <DashboardPage {...dashboardProps} />;
      case 'USER_SUBSCRIPTION_MANAGEMENT':
          return hasPermission(Permission.CAN_MANAGE_SUBSCRIPTIONS) ? <UserSubscriptionManagementPage
                    userSubscriptions={userSubscriptions}
                    subscriptionPlans={subscriptionPlans}
                    onUpdateUserSubscriptions={handleUpdateUserSubscriptions}
                    onAutoSchedule={handleAutoSchedule}
                 /> : <DashboardPage {...dashboardProps} />;
      case 'SERVICE_REQUEST':
        return hasPermission(Permission.CAN_VIEW_SERVICE_REQUESTS) ? <ServiceRequestPage
                 serviceRequests={serviceRequests}
               /> : <DashboardPage {...dashboardProps} />;
       case 'LIVE_MAP':
        return hasPermission(Permission.CAN_VIEW_LIVE_MAP) ? <LiveMapPage
                 users={users.map(({password, ...rest}) => rest)}
                 currentUser={currentUser}
                 submissions={submissions.filter(s => !s.isDeleted)}
                 onRefresh={handleManualRefresh}
                 isRefreshing={isManualRefreshing}
                 locationHistory={locationHistory}
               /> : <DashboardPage {...dashboardProps} />;
      case 'ANALYTICS':
        return hasPermission(Permission.CAN_VIEW_ANALYTICS) ? <AnalyticsPage
                 submissions={submissions.filter(s => !s.isDeleted)}
                 users={users.map(({password, ...rest}) => rest)}
                 serviceTemplates={serviceTemplates}
               /> : <DashboardPage {...dashboardProps} />;
       case 'CUSTOMER_HISTORY':
        return hasPermission(Permission.CAN_VIEW_CUSTOMER_HISTORY) ? <CustomerHistoryPage
                 submissions={submissions.filter(s => !s.isDeleted)}
                 currentUser={currentUser}
                 onShareOrder={handleShareOrder}
               /> : <DashboardPage {...dashboardProps} />;
      case 'RETENTION':
        return hasPermission(Permission.CAN_VIEW_RETENTION_DASHBOARD) ? <RetentionDashboard
                 submissions={submissions.filter(s => !s.isDeleted)}
                 onCreateFollowUp={handleCreateFollowUp}
                 settings={settings}
                 onUpdateKpiTargets={handleUpdateKpiTargets}
               /> : <DashboardPage {...dashboardProps} />;
      case 'BOOKKEEPING':
        return hasPermission(Permission.CAN_LOG_EXPENSES) ? <BookkeepingPage
            currentUser={currentUser}
            miscSpends={miscSpends}
            users={users.map(({password, ...rest}) => rest)}
            googleDriveUploadUrl={settings.googleDriveUploadUrl}
            onSaveNewSpend={handleSaveNewSpend}
            onUpdateSpendStatus={handleUpdateSpendStatus}
            bookkeeping={bookkeeping}
        /> : <DashboardPage {...dashboardProps} />;
      case 'PROFIT_LOSS':
        return hasPermission(Permission.CAN_VIEW_PROFIT_LOSS) ? <ProfitLossPage
            submissions={submissions.filter(s => !s.isDeleted)}
            profitLossData={profitLossData}
            onSave={handleUpdateProfitLoss}
        /> : <DashboardPage {...dashboardProps} />;
       case 'TRASH':
        return hasPermission(Permission.CAN_VIEW_TRASH) ? <TrashPage
            deletedSubmissions={submissions.filter(s => s.isDeleted)}
            onRestore={handleRestoreFromTrash}
            onPermanentDelete={handleDeleteRequest}
        /> : <DashboardPage {...dashboardProps} />;
        case 'PRICING_MANAGEMENT':
            return hasPermission(Permission.CAN_MANAGE_PRICING) ? <PricingManagementPage
                pricingConfig={pricingConfig}
                onUpdatePricing={handleUpdatePricingConfig}
            /> : <DashboardPage {...dashboardProps} />;
        case 'ATTENDANCE_MANAGEMENT':
            return hasPermission(Permission.CAN_MANAGE_USERS) ? <AttendancePage
                users={users.map(({password, ...rest}) => rest)}
            /> : <DashboardPage {...dashboardProps} />;
      case 'DASHBOARD':
        return hasPermission(Permission.CAN_VIEW_DASHBOARD) ? <DashboardPage {...dashboardProps} /> : <div>Access Denied</div>;
      default:
        return <div>Unknown view</div>;
    }
  };

  const dashboardProps = {
    submissions: submissions.filter(s => !s.isDeleted),
    users: users.map(({password, ...rest}) => rest),
    currentUser,
    onCreateOrder: handleCreateOrder,
    onAssignOrder: handleAssignOrder,
    onStartOrder: handleStartOrder,
    onUpdateOrder: handleEditService,
    onSelfAssignOrder: handleSelfAssignOrder,
    onDeleteOrder: handleDeleteRequest,
    onScheduleDroppedOrder: handleScheduleDroppedOrder,
    onNotifyForOrder: handleNotifyForOrder,
    onUpdateAttendanceStatus: handleUpdateAttendanceStatus,
    userSubscriptions,
    serviceTemplates,
    setIsChatbotOpen,
    settings,
    locationHistory,
    vehicleData,
    tyreData,
    onShareOrder: handleShareOrder,
  };

  return (
    <div className="min-h-screen bg-slate-100 flex">
      {isSettingsOpen && currentUser.permissions.includes(Permission.CAN_EDIT_SETTINGS) && (
        <SettingsModal 
          initialSettings={settings}
          onClose={() => setIsSettingsOpen(false)} 
          onSave={handleSaveSettings}
        />
      )}

      {summarizingService && (
          <SummaryModal 
            service={summarizingService}
            onClose={() => setSummarizingService(null)}
          />
      )}

      {sharingService && (
        <ShareOrderModal 
          service={sharingService}
          onClose={() => setSharingService(null)}
        />
      )}

      {isChatbotOpen && (
        <ChatbotModal
            isOpen={isChatbotOpen}
            onClose={() => setIsChatbotOpen(false)}
            onSubmit={handleSaveDraftFromChatbot}
            serviceTemplates={serviceTemplates}
        />
       )}

      {deletingService && (
        <DeleteConfirmationModal
            isOpen={!!deletingService}
            onClose={() => setDeletingService(null)}
            onConfirm={handleConfirmDelete}
            service={deletingService}
            isPermanent={deletingService.isDeleted}
        />
      )}

      <Sidebar
          currentUser={currentUser}
          currentView={view}
          onNavigate={handleNavigate}
          onNewService={() => handleEditService(null)}
          onOpenSettings={() => setIsSettingsOpen(true)}
          onLogout={handleLogout}
          logoUrl={settings.customLogoUrl}
          logoHasError={logoHasError}
          onLogoError={() => setLogoHasError(true)}
          isMinimized={isSidebarMinimized}
          isOpenOnMobile={isMobileMenuOpen}
          onToggleDesktop={() => setIsSidebarMinimized(!isSidebarMinimized)}
          onCloseMobile={() => setIsMobileMenuOpen(false)}
      />

       {isMobileMenuOpen && <div className="fixed inset-0 bg-black/60 z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)}></div>}

      <div className={`flex-1 transition-all duration-300 ${isSidebarMinimized ? 'md:pl-20' : 'md:pl-64'}`}>
          <header className="sticky top-0 bg-slate-100/80 backdrop-blur-md z-30 border-b border-slate-200 no-print">
              <div className="relative flex items-center justify-between min-h-16 px-4 md:px-6 py-2 gap-2">
                  <button className="md:hidden text-slate-600" onClick={() => setIsMobileMenuOpen(true)} aria-label="Open menu">
                      <IconMenu2 className="w-6 h-6" />
                  </button>
                  <div className="flex items-center gap-2 flex-wrap justify-end">
                      <RealTimeClock />
                      <div className="h-6 w-px bg-slate-300 hidden sm:block"></div>
                      <NotificationBell 
                          unreadCount={unreadCount}
                          onClick={() => setIsNotificationHistoryOpen(prev => !prev)}
                      />
                      {currentUser.role === 'admin' && (
                          <button
                              onClick={handleManualNotifyAll}
                              className="p-2 text-slate-500 hover:text-slate-800 hover:bg-slate-200 rounded-full transition-colors"
                              aria-label="Send broadcast notification to all users"
                              title="Send a notification to all users"
                          >
                              <IconBellRinging className="w-6 h-6" />
                          </button>
                      )}
                      <button
                          onClick={handleManualRefresh}
                          disabled={isManualRefreshing || !settings.googleSheetsUrl}
                          className="p-2 text-slate-500 hover:text-slate-800 hover:bg-slate-200 rounded-full transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                          aria-label="Refresh data from cloud"
                          title={!settings.googleSheetsUrl ? "Cloud sync is offline. Check settings." : "Refresh data from cloud"}
                      >
                          <IconRefresh className={`w-6 h-6 ${isManualRefreshing ? 'animate-spin' : ''}`} />
                      </button>
                      <SyncStatusIndicator status={syncStatus} errorMessage={syncError} />
                  </div>
                   {isNotificationHistoryOpen && (
                        <NotificationHistory
                            notifications={currentUserNotifications}
                            onMarkAsRead={handleMarkNotificationAsRead}
                            onMarkAllAsRead={handleMarkAllAsRead}
                            onClose={() => setIsNotificationHistoryOpen(false)}
                        />
                    )}
              </div>
          </header>

          <main className="p-4 sm:p-6 lg:p-8 w-full">
            {syncStatus === 'ERROR' && syncError && (
                <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 relative mb-6 rounded-r-md" role="alert">
                    <strong className="font-bold">Sync Error:</strong>
                    <span className="block sm:inline ml-2">{syncError}</span>
                    <button 
                      onClick={() => setSyncError(null)} 
                      className="absolute top-0 bottom-0 right-0 px-4 py-3"
                      aria-label="Dismiss error message"
                    >
                      <IconX className="h-6 w-6 text-red-500" />
                    </button>
                </div>
            )}

            {renderView()}
          </main>
      </div>
    </div>
  );
};

import React from 'react';
import { User, Permission } from '../../types';
import Button from './Button';
import { IconLayoutDashboard, IconClock, IconUser, IconSettings, IconLogout, IconPlus, IconChevronLeft, IconChevronRight, IconCreditCard, IconTrophy, IconSparkles, IconWorld, IconClipboardList, IconBellCog, IconMapPin, IconChartBar, IconSearch, IconRetention, IconReceipt, IconCalendar, IconUsers, IconFileAnalytics, IconTrash, IconFingerprint } from './Icon';

interface SidebarProps {
  currentUser: User;
  currentView: string;
  isMinimized: boolean;
  isOpenOnMobile: boolean;
  onNavigate: (view: 'DASHBOARD' | 'LIST' | 'USER_MANAGEMENT' | 'PLAN_MANAGEMENT' | 'USER_SUBSCRIPTION_MANAGEMENT' | 'SERVICE_TEMPLATE_MANAGEMENT' | 'SERVICE_REQUEST' | 'NOTIFICATION_PREFERENCES' | 'LIVE_MAP' | 'ANALYTICS' | 'CUSTOMER_HISTORY' | 'RETENTION' | 'BOOKKEEPING' | 'APPOINTMENTS_OVERVIEW' | 'PROFIT_LOSS' | 'TRASH' | 'PRICING_MANAGEMENT' | 'ATTENDANCE_MANAGEMENT') => void;
  onNewService: () => void;
  onOpenSettings: () => void;
  onLogout: () => void;
  onToggleDesktop: () => void;
  onCloseMobile: () => void;
  logoUrl?: string;
  logoHasError: boolean;
  onLogoError: () => void;
}

interface NavLinkProps {
  icon: React.ReactElement;
  label: string;
  isActive: boolean;
  isMinimized: boolean;
  onClick: () => void;
}

const NavLink: React.FC<NavLinkProps> = ({ icon, label, isActive, isMinimized, onClick }) => {

  // FIX: Cast icon to React.ReactElement<any> to resolve a type inference issue with React.cloneElement.
  // This allows adding a className to the SVG icon component, which is a known pattern for this issue.
  const styledIcon = React.cloneElement(icon as React.ReactElement<any>, {
    className: `w-5 h-5 transition-transform duration-200 group-hover:scale-105`
  });

  return (
    <li className="relative">
      <button
        onClick={onClick}
        title={isMinimized ? label : undefined}
        className={`group w-full flex items-center px-4 py-3 text-sm font-medium rounded-lg transition-colors duration-150 ${
          isActive
            ? 'text-white'
            : 'text-slate-300 hover:text-white'
        } ${isMinimized ? 'justify-center' : ''}`}
      >
        {isActive && !isMinimized && (
          <div className="absolute left-0 top-1/2 -translate-y-1/2 h-5 w-1 bg-brand-accent rounded-r-full"></div>
        )}
        <div className={`
          flex items-center justify-center h-9 w-9 rounded-lg transition-all duration-200 
          ${isActive 
            ? 'bg-brand-accent text-brand-blue shadow-lg'
            : 'bg-white/5 group-hover:bg-white/10 shadow-md'
          }`
        }>
          {styledIcon}
        </div>
        <span className={`ml-3 whitespace-nowrap ${isMinimized ? 'md:hidden' : ''}`}>{label}</span>
      </button>
    </li>
  );
};

export const Sidebar: React.FC<SidebarProps> = ({
  currentUser,
  currentView,
  isMinimized,
  isOpenOnMobile,
  onNavigate,
  onNewService,
  onOpenSettings,
  onLogout,
  onToggleDesktop,
  onCloseMobile,
  logoUrl,
  logoHasError,
  onLogoError,
}) => {
  const sidebarClasses = `
    fixed inset-y-0 left-0 z-50 bg-gradient-to-b from-brand-blue to-slate-900 flex flex-col no-print
    transition-transform transform md:transition-all md:transform-none duration-300 ease-in-out
    w-64
    pb-12
    ${isOpenOnMobile ? 'translate-x-0' : '-translate-x-full'}
    ${isMinimized ? 'md:w-20' : 'md:w-64'}
  `;

  const hasPermission = (p: Permission) => currentUser.permissions.includes(p);

  return (
    <aside className={sidebarClasses}>
      {/* Header */}
      <div className={`flex items-center justify-center h-20 border-b border-white/5 px-4 flex-shrink-0 ${isMinimized ? 'md:px-2' : 'md:px-4'}`}>
        <div className="flex items-center space-x-3 overflow-hidden">
          <div className="bg-white rounded-full p-1 h-12 w-12 flex items-center justify-center flex-shrink-0">
            {logoUrl && !logoHasError ? (
              <img
                src={logoUrl}
                alt="Custom Logo"
                className="h-10 w-10 rounded-full object-cover"
                onError={onLogoError}
              />
            ) : (
              <img
                src="https://pub-d1d6c35dc7024f819f155246a42ea32b.r2.dev/Website%20Assets/logo/bigengine%203.png"
                alt="A Big Engine Logo"
                className="h-10 w-10 object-contain"
              />
            )}
          </div>
          <div className={`whitespace-nowrap ${isMinimized ? 'md:hidden' : ''}`}>
            <h1 className="text-xl font-bold tracking-tight uppercase">
                <span className="text-white">A Big </span>
                <span className="text-brand-accent">Engine</span>
            </h1>
          </div>
        </div>
      </div>

      {/* Main Actions */}
      <div className="p-4 flex-shrink-0">
        {hasPermission(Permission.CAN_CREATE_ORDERS) && (
            <Button onClick={onNewService} className="w-full">
                <IconPlus className="w-5 h-5" />
                <span className={`ml-2 ${isMinimized ? 'md:hidden' : ''}`}>New Service</span>
            </Button>
        )}
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-4 py-2 space-y-1.5 overflow-y-auto sidebar-scrollbar">
        <ul>
          {hasPermission(Permission.CAN_VIEW_DASHBOARD) && (
            <NavLink
                icon={<IconLayoutDashboard />}
                label="Dashboard"
                isActive={currentView === 'DASHBOARD'}
                onClick={() => onNavigate('DASHBOARD')}
                isMinimized={isMinimized}
            />
          )}
          {(currentUser.role === 'agent' || currentUser.role === 'technician') && hasPermission(Permission.CAN_VIEW_APPOINTMENTS_OVERVIEW) && (
             <NavLink
                icon={<IconCalendar />}
                label="My Appointments"
                isActive={currentView === 'APPOINTMENTS_OVERVIEW'}
                onClick={() => onNavigate('APPOINTMENTS_OVERVIEW')}
                isMinimized={isMinimized}
            />
          )}
          {hasPermission(Permission.CAN_VIEW_SERVICE_HISTORY) && (
            <NavLink
                icon={<IconClock />}
                label="Service History"
                isActive={currentView === 'LIST'}
                onClick={() => onNavigate('LIST')}
                isMinimized={isMinimized}
            />
          )}
           <NavLink
            icon={<IconBellCog />}
            label="Notification Prefs"
            isActive={currentView === 'NOTIFICATION_PREFERENCES'}
            onClick={() => onNavigate('NOTIFICATION_PREFERENCES')}
            isMinimized={isMinimized}
          />
           {hasPermission(Permission.CAN_LOG_EXPENSES) && (
             <NavLink
                icon={<IconReceipt />}
                label="Bookkeeping"
                isActive={currentView === 'BOOKKEEPING'}
                onClick={() => onNavigate('BOOKKEEPING')}
                isMinimized={isMinimized}
            />
           )}

            <>
              {(hasPermission(Permission.CAN_MANAGE_USERS) || hasPermission(Permission.CAN_VIEW_LIVE_MAP)) && (
                <div className={`my-4 border-t border-white/5 ${isMinimized ? 'mx-2' : 'mx-4'}`}></div>
              )}
               {hasPermission(Permission.CAN_VIEW_CUSTOMER_HISTORY) && <NavLink
                icon={<IconSearch />}
                label="Customer History"
                isActive={currentView === 'CUSTOMER_HISTORY'}
                onClick={() => onNavigate('CUSTOMER_HISTORY')}
                isMinimized={isMinimized}
              />}
              {hasPermission(Permission.CAN_VIEW_RETENTION_DASHBOARD) && <NavLink
                icon={<IconRetention />}
                label="Retention"
                isActive={currentView === 'RETENTION'}
                onClick={() => onNavigate('RETENTION')}
                isMinimized={isMinimized}
              />}
              {hasPermission(Permission.CAN_VIEW_ANALYTICS) && <NavLink
                icon={<IconChartBar />}
                label="Analytics"
                isActive={currentView === 'ANALYTICS'}
                onClick={() => onNavigate('ANALYTICS')}
                isMinimized={isMinimized}
              />}
               {hasPermission(Permission.CAN_VIEW_PROFIT_LOSS) && <NavLink
                icon={<IconFileAnalytics />}
                label="Profit & Loss"
                isActive={currentView === 'PROFIT_LOSS'}
                onClick={() => onNavigate('PROFIT_LOSS')}
                isMinimized={isMinimized}
              />}
              {hasPermission(Permission.CAN_VIEW_LIVE_MAP) && <NavLink
                icon={<IconMapPin />}
                label="Live Map"
                isActive={currentView === 'LIVE_MAP'}
                onClick={() => onNavigate('LIVE_MAP')}
                isMinimized={isMinimized}
              />}
              {hasPermission(Permission.CAN_MANAGE_USERS) && (
                <>
                <NavLink
                    icon={<IconUsers />}
                    label="Manage Users"
                    isActive={currentView === 'USER_MANAGEMENT'}
                    onClick={() => onNavigate('USER_MANAGEMENT')}
                    isMinimized={isMinimized}
                />
                 <NavLink
                    icon={<IconFingerprint />}
                    label="Attendance"
                    isActive={currentView === 'ATTENDANCE_MANAGEMENT'}
                    onClick={() => onNavigate('ATTENDANCE_MANAGEMENT')}
                    isMinimized={isMinimized}
                />
                </>
              )}
               {hasPermission(Permission.CAN_MANAGE_PLANS) && <NavLink
                icon={<IconCreditCard />}
                label="Manage Plans"
                isActive={currentView === 'PLAN_MANAGEMENT'}
                onClick={() => onNavigate('PLAN_MANAGEMENT')}
                isMinimized={isMinimized}
              />}
               {hasPermission(Permission.CAN_MANAGE_SUBSCRIPTIONS) && <NavLink
                icon={<IconTrophy />}
                label="User Subscriptions"
                isActive={currentView === 'USER_SUBSCRIPTION_MANAGEMENT'}
                onClick={() => onNavigate('USER_SUBSCRIPTION_MANAGEMENT')}
                isMinimized={isMinimized}
              />}
               {hasPermission(Permission.CAN_MANAGE_SERVICES) && <NavLink
                icon={<IconWorld />}
                label="Manage Services"
                isActive={currentView === 'SERVICE_TEMPLATE_MANAGEMENT'}
                onClick={() => onNavigate('SERVICE_TEMPLATE_MANAGEMENT')}
                isMinimized={isMinimized}
              />}
               {hasPermission(Permission.CAN_MANAGE_PRICING) && <NavLink
                icon={<IconCreditCard />}
                label="Pricing Config"
                isActive={currentView === 'PRICING_MANAGEMENT'}
                onClick={() => onNavigate('PRICING_MANAGEMENT')}
                isMinimized={isMinimized}
              />}
              {hasPermission(Permission.CAN_VIEW_SERVICE_REQUESTS) && <NavLink
                icon={<IconClipboardList />}
                label="Service Request"
                isActive={currentView === 'SERVICE_REQUEST'}
                onClick={() => onNavigate('SERVICE_REQUEST')}
                isMinimized={isMinimized}
              />}
              {hasPermission(Permission.CAN_VIEW_TRASH) && <NavLink
                icon={<IconTrash />}
                label="Trash"
                isActive={currentView === 'TRASH'}
                onClick={() => onNavigate('TRASH')}
                isMinimized={isMinimized}
              />}
            </>
        </ul>
      </nav>

      {/* Footer */}
      <div className="flex-shrink-0 mt-auto border-t border-white/5">
        <div className="p-4 space-y-1.5">
          {hasPermission(Permission.CAN_EDIT_SETTINGS) && (
              <NavLink
                icon={<IconSettings />}
                label="Settings"
                isActive={false} // Settings opens a modal, not a view
                onClick={onOpenSettings}
                isMinimized={isMinimized}
              />
          )}
          <NavLink
            icon={<IconLogout />}
            label="Logout"
            isActive={false}
            onClick={onLogout}
            isMinimized={isMinimized}
          />
        </div>
        <div className="hidden md:flex items-center justify-center p-2 border-t border-white/5">
            <button
                onClick={onToggleDesktop}
                className="p-2 text-slate-300 hover:text-white hover:bg-white/10 rounded-md"
                title={isMinimized ? 'Expand Sidebar' : 'Collapse Sidebar'}
            >
                {isMinimized ? <IconChevronRight className="w-5 h-5" /> : <IconChevronLeft className="w-5 h-5" />}
            </button>
        </div>
      </div>
    </aside>
  );
};

