import React, { useState, useMemo } from 'react';
import { User, AttendanceRecord, AttendanceStatus } from '../../types';
import Card from '../ui/Card';
import Button from '../ui/Button';
import Input from '../ui/Input';
import { IconFingerprint, IconUserCheck, IconUserOff, IconClock, IconChevronDown, IconCalendarEvent, IconList, IconChevronLeft, IconChevronRight } from '../ui/Icon';

interface AttendancePageProps {
  users: Omit<User, 'password'>[];
}

interface ProcessedAttendance {
  username: string;
  firstIn: string | null;
  lastOut: string | null;
  totalDurationMs: number;
  status: 'Present' | 'Absent' | 'Active Now';
  logs: AttendanceRecord[];
}

const formatDuration = (ms: number): string => {
  if (ms === 0) return '-';
  const hours = Math.floor(ms / (1000 * 60 * 60));
  const minutes = Math.floor((ms % (1000 * 60 * 60)) / (1000 * 60));
  return `${hours}h ${minutes}m`;
};

const formatTime = (isoString: string): string => {
  return new Date(isoString).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', hour12: true });
};

const getDaysInMonth = (year: number, month: number) => {
    return new Date(year, month + 1, 0).getDate();
};

const getStatusForDay = (user: Omit<User, 'password'>, date: Date): 'P' | 'A' | 'Active' | 'Abs' => {
    const dateStr = date.toDateString();
    const logs = user.attendanceHistory || [];

    // Check if user is currently active
    const lastLog = logs[logs.length - 1];
    const isCurrentlyActive = lastLog && lastLog.status === 'CHECKED_IN';
    const isToday = new Date().toDateString() === dateStr;

    if (isToday && isCurrentlyActive) return 'Active';

    // Check history for this day
    const hasRecord = logs.some(log => new Date(log.timestamp).toDateString() === dateStr);

    if (hasRecord) return 'P';

    // Future dates shouldn't be Absent
    if (date > new Date()) return 'Abs'; // Or return null/empty for future

    return 'Abs';
};


const AttendancePage: React.FC<AttendancePageProps> = ({ users }) => {
  const [viewMode, setViewMode] = useState<'day' | 'month'>('day');

  // Day View State
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [expandedUser, setExpandedUser] = useState<string | null>(null);

  // Month View State
  const [currentMonth, setCurrentMonth] = useState(new Date().getMonth());
  const [currentYear, setCurrentYear] = useState(new Date().getFullYear());

  const handlePrevMonth = () => {
      if (currentMonth === 0) {
          setCurrentMonth(11);
          setCurrentYear(currentYear - 1);
      } else {
          setCurrentMonth(currentMonth - 1);
      }
  };

  const handleNextMonth = () => {
      if (currentMonth === 11) {
          setCurrentMonth(0);
          setCurrentYear(currentYear + 1);
      } else {
          setCurrentMonth(currentMonth + 1);
      }
  };

  // --- Data Processing for Day View ---
  const processedDayData: ProcessedAttendance[] = useMemo(() => {
    const selectedDateObj = new Date(selectedDate);
    const dateStr = selectedDateObj.toDateString();

    return users
      .filter(u => u.role !== 'admin')
      .map(user => {
        const history = user.attendanceHistory || [];
        const dailyLogs = history.filter(log => {
          const logDate = new Date(log.timestamp);
          return logDate.toDateString() === dateStr;
        }).sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());

        let firstIn = null;
        let lastOut = null;
        let totalDurationMs = 0;
        let currentState: AttendanceStatus | null = null;
        let lastInTime: number | null = null;

        dailyLogs.forEach((log) => {
            if (log.status === 'CHECKED_IN') {
                if (!firstIn) firstIn = log.timestamp;
                if (!lastInTime) lastInTime = new Date(log.timestamp).getTime();
                currentState = 'CHECKED_IN';
            } else if (log.status === 'CHECKED_OUT') {
                lastOut = log.timestamp;
                if (lastInTime) {
                    totalDurationMs += (new Date(log.timestamp).getTime() - lastInTime);
                    lastInTime = null;
                }
                currentState = 'CHECKED_OUT';
            }
        });

        const isToday = new Date().toDateString() === dateStr;
        if (currentState === 'CHECKED_IN' && lastInTime && isToday) {
             totalDurationMs += (new Date().getTime() - lastInTime);
        }

        let status: 'Present' | 'Absent' | 'Active Now' = 'Absent';
        if (currentState === 'CHECKED_IN' && isToday) status = 'Active Now';
        else if (dailyLogs.length > 0) status = 'Present';

        return {
          username: user.username,
          firstIn,
          lastOut,
          totalDurationMs,
          status,
          logs: dailyLogs
        };
      }).sort((a, b) => {
          const rank = (s: string) => s === 'Active Now' ? 0 : s === 'Present' ? 1 : 2;
          return rank(a.status) - rank(b.status);
      });
  }, [users, selectedDate]);


  // --- Data Processing for Month View ---
  const daysInCurrentMonth = useMemo(() => getDaysInMonth(currentYear, currentMonth), [currentMonth, currentYear]);
  const monthDates = useMemo(() => Array.from({ length: daysInCurrentMonth }, (_, i) => new Date(currentYear, currentMonth, i + 1)), [daysInCurrentMonth, currentMonth, currentYear]);

  const monthGridData = useMemo(() => {
    return users.filter(u => u.role !== 'admin').map(user => {
        const row = monthDates.map(date => ({
            date,
            status: getStatusForDay(user, date)
        }));

        const totalPresent = row.filter(d => d.status === 'P' || d.status === 'Active').length;

        return {
            user,
            row,
            totalPresent
        };
    });
  }, [users, monthDates]);


  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 tracking-tight flex items-center gap-3">
                Attendance Management
            </h1>
             <p className="text-slate-500 mt-1">Track agent check-ins, calculate hours, and view monthly reports.</p>
        </div>

        <div className="flex bg-slate-200 p-1 rounded-lg">
            <button
                onClick={() => setViewMode('day')}
                className={`px-4 py-2 text-sm font-medium rounded-md transition-all flex items-center gap-2 ${viewMode === 'day' ? 'bg-white text-brand-blue shadow-sm' : 'text-slate-600 hover:text-slate-800'}`}
            >
                <IconList className="w-4 h-4" /> Day View
            </button>
            <button
                onClick={() => setViewMode('month')}
                className={`px-4 py-2 text-sm font-medium rounded-md transition-all flex items-center gap-2 ${viewMode === 'month' ? 'bg-white text-brand-blue shadow-sm' : 'text-slate-600 hover:text-slate-800'}`}
            >
                <IconCalendarEvent className="w-4 h-4" /> Month View
            </button>
        </div>
      </div>

      {viewMode === 'day' && (
        <>
            <div className="flex justify-end">
                <div className="bg-white p-2 rounded-lg shadow-sm border border-slate-200 w-full md:w-auto">
                    <Input 
                        label="" 
                        type="date" 
                        value={selectedDate} 
                        onChange={(e) => setSelectedDate(e.target.value)} 
                        className="!mt-0"
                    />
                </div>
            </div>

            <Card title={`Attendance Report: ${new Date(selectedDate).toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'})}`}>
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-slate-200">
                        <thead className="bg-slate-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Agent</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Status</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Shift Timeline</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">First In</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Last Out</th>
                                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Duration</th>
                                <th className="px-6 py-3 text-right text-xs font-bold text-slate-500 uppercase tracking-wider">Log</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-slate-200">
                            {processedDayData.map((data) => (
                                <React.Fragment key={data.username}>
                                    <tr className="hover:bg-slate-50 transition-colors">
                                        <td className="px-6 py-4 whitespace-nowrap">
                                            <div className="font-semibold text-slate-800">{data.username}</div>
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap">
                                            <span className={`px-2 py-1 text-xs font-semibold rounded-full ${
                                                data.status === 'Active Now' ? 'bg-green-100 text-green-800' :
                                                data.status === 'Present' ? 'bg-blue-100 text-blue-800' :
                                                'bg-slate-100 text-slate-500'
                                            }`}>
                                                {data.status}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap align-middle">
                                            {/* Visual Timeline Bar */}
                                            {data.logs.length > 0 ? (
                                                <div className="h-2 w-32 bg-slate-200 rounded-full overflow-hidden flex">
                                                    {data.status !== 'Absent' && (
                                                        <div className={`h-full ${data.status === 'Active Now' ? 'bg-green-400 animate-pulse' : 'bg-blue-400'}`} style={{ width: '100%' }}></div>
                                                    )}
                                                </div>
                                            ) : <div className="h-2 w-32 bg-slate-100 rounded-full"></div>}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                                            {data.firstIn ? formatTime(data.firstIn) : '-'}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                                            {data.lastOut ? formatTime(data.lastOut) : (data.status === 'Active Now' ? <span className="text-green-600 text-xs font-bold">ON DUTY</span> : '-')}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm font-mono text-slate-700">
                                            {formatDuration(data.totalDurationMs)}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-right">
                                            <button 
                                                onClick={() => setExpandedUser(expandedUser === data.username ? null : data.username)}
                                                className="text-brand-blue hover:bg-brand-blue/10 p-2 rounded-full transition-colors"
                                                disabled={data.logs.length === 0}
                                            >
                                                <IconChevronDown className={`w-5 h-5 transition-transform duration-300 ${expandedUser === data.username ? 'rotate-180' : ''} ${data.logs.length === 0 ? 'opacity-30' : ''}`} />
                                            </button>
                                        </td>
                                    </tr>
                                    {expandedUser === data.username && data.logs.length > 0 && (
                                        <tr className="bg-slate-50">
                                            <td colSpan={7} className="px-6 py-4">
                                                <div className="text-sm border-l-2 border-slate-300 pl-4 ml-4">
                                                    <p className="font-semibold text-slate-600 mb-2">Detailed Logs:</p>
                                                    <ul className="space-y-2">
                                                        {data.logs.map((log, idx) => (
                                                            <li key={idx} className="flex items-center space-x-3 text-slate-700">
                                                                <div className={`w-2 h-2 rounded-full ${log.status === 'CHECKED_IN' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                                                                <span className="font-mono text-xs text-slate-500 w-16">{formatTime(log.timestamp)}</span>
                                                                <span className="font-medium">{log.status === 'CHECKED_IN' ? 'Checked In' : 'Checked Out'}</span>
                                                            </li>
                                                        ))}
                                                    </ul>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </React.Fragment>
                            ))}
                             {processedDayData.length === 0 && (
                                <tr>
                                    <td colSpan={7} className="px-6 py-10 text-center text-slate-500">No users found.</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </Card>
        </>
      )}

      {viewMode === 'month' && (
          <Card>
              <div className="flex flex-col md:flex-row justify-between items-center mb-6">
                   <div className="flex items-center space-x-4 mb-4 md:mb-0">
                        <Button variant="ghost" onClick={handlePrevMonth}><IconChevronLeft className="w-5 h-5"/></Button>
                        <h2 className="text-xl font-bold text-slate-700 w-48 text-center">
                            {new Date(currentYear, currentMonth).toLocaleDateString('default', { month: 'long', year: 'numeric' })}
                        </h2>
                        <Button variant="ghost" onClick={handleNextMonth}><IconChevronRight className="w-5 h-5"/></Button>
                   </div>
                   <div className="flex gap-4 text-xs font-semibold">
                       <div className="flex items-center gap-1"><span className="w-3 h-3 rounded-sm bg-green-500"></span> Present</div>
                       <div className="flex items-center gap-1"><span className="w-3 h-3 rounded-sm bg-blue-400"></span> Active</div>
                       <div className="flex items-center gap-1"><span className="w-3 h-3 rounded-sm bg-red-100"></span> Absent</div>
                   </div>
              </div>

              <div className="overflow-x-auto border rounded-lg border-slate-200">
                  <table className="w-full border-collapse text-sm">
                      <thead>
                          <tr className="bg-slate-100 text-slate-600">
                              <th className="p-3 text-left font-bold border-b border-r border-slate-200 sticky left-0 bg-slate-100 z-10 w-40">Agent</th>
                              {monthDates.map(date => (
                                  <th key={date.getDate()} className="p-2 border-b border-r border-slate-200 text-center min-w-[36px]">
                                      <div className="text-xs">{date.toLocaleDateString('default', { weekday: 'narrow' })}</div>
                                      <div>{date.getDate()}</div>
                                  </th>
                              ))}
                              <th className="p-3 text-center font-bold border-b border-slate-200 bg-slate-100">Total</th>
                          </tr>
                      </thead>
                      <tbody>
                          {monthGridData.map(({ user, row, totalPresent }) => (
                              <tr key={user.username} className="hover:bg-slate-50 group">
                                  <td className="p-3 border-b border-r border-slate-200 font-medium text-slate-800 sticky left-0 bg-white group-hover:bg-slate-50 z-10 truncate max-w-[160px]">
                                      {user.username}
                                  </td>
                                  {row.map((dayData, idx) => (
                                      <td key={idx} className="p-1 border-b border-r border-slate-200 text-center h-10">
                                          {dayData.status === 'P' && <div className="w-6 h-6 mx-auto bg-green-500 text-white rounded-md flex items-center justify-center text-xs font-bold" title="Present">P</div>}
                                          {dayData.status === 'Active' && <div className="w-6 h-6 mx-auto bg-blue-400 text-white rounded-md flex items-center justify-center text-xs font-bold animate-pulse" title="Active Now">A</div>}
                                          {dayData.status === 'Abs' && <div className="w-6 h-6 mx-auto bg-red-50 text-red-300 rounded-md flex items-center justify-center text-[10px]" title="Absent">•</div>}
                                      </td>
                                  ))}
                                  <td className="p-3 border-b border-slate-200 text-center font-bold text-slate-700 bg-slate-50">
                                      {totalPresent}
                                  </td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
          </Card>
      )}
    </div>
  );
};

export default AttendancePage;

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { Customer, UserSubscription, ServiceTemplate, Service, VehicleCategoryTag, User } from '../../types';
import Button from '../ui/Button';
import Input from '../ui/Input';
import { APPOINTMENT_TIME_SLOTS, VEHICLE_CATEGORY_TAGS } from '../../constants';
import { IconTrophy, IconLoader, IconDeviceFloppy, IconTrash, IconCrosshair, IconMapPin, IconCheck } from '../ui/Icon';
import { findCustomerByMobile } from '../../services/customerService';
import VehicleSelector from '../VehicleSelector';
import { getCategoryForVehicle } from '../../services/vehicleService';
import LocationPickerModal from '../ui/LocationPickerModal';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onCreateOrder: (details: { 
    customer: Pick<Customer, 'firstName' | 'lastName' | 'mobileNumber' | 'carNumber' | 'carBrandModel' | 'streetAddress' | 'customerEmail' | 'latitude' | 'longitude'>, 
    scheduledDate?: string, 
    scheduledTime?: string, 
    serviceSelection: string[], 
    vehicleCategoryTag?: VehicleCategoryTag,
    assignedTo?: string 
  }) => void;
  userSubscriptions: UserSubscription[];
  serviceTemplates: ServiceTemplate[];
  allSubmissions: Service[];
  vehicleData: Record<string, string[]>;
  users: Omit<User, 'password'>[];
}

// Stable no-op function to prevent re-renders in VehicleSelector
const noOp = () => {};

const DRAFT_KEY = 'create_order_modal_draft';

const CreateOrderModal: React.FC<Props> = ({ isOpen, onClose, onCreateOrder, userSubscriptions, serviceTemplates, allSubmissions, vehicleData, users }) => {
  const [customer, setCustomer] = useState<Pick<Customer, 'firstName' | 'lastName' | 'mobileNumber' | 'carNumber' | 'carBrandModel' | 'streetAddress' | 'customerEmail' | 'latitude' | 'longitude'>>(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).customer : { firstName: '', lastName: '', mobileNumber: '', carNumber: '', carBrandModel: '', streetAddress: '', customerEmail: '', latitude: undefined, longitude: undefined };
  });

  const [scheduledDate, setScheduledDate] = useState(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).scheduledDate : '';
  });

  const [scheduledTime, setScheduledTime] = useState(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).scheduledTime : '';
  });

  const [serviceSelection, setServiceSelection] = useState<string[]>(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    return saved ? JSON.parse(saved).serviceSelection : [];
  });

  const [vehicleCategoryTag, setVehicleCategoryTag] = useState<VehicleCategoryTag | undefined>(() => {
     const saved = localStorage.getItem(DRAFT_KEY);
     return saved ? JSON.parse(saved).vehicleCategoryTag : undefined;
  });

  const [assignedTo, setAssignedTo] = useState<string>(() => {
      const saved = localStorage.getItem(DRAFT_KEY);
      return saved ? JSON.parse(saved).assignedTo || '' : '';
  });

  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [isSearching, setIsSearching] = useState(false);
  const [searchMessage, setSearchMessage] = useState('');
  const searchTimeoutRef = useRef<number | null>(null);
  const [foundProfiles, setFoundProfiles] = useState<Awaited<ReturnType<typeof findCustomerByMobile>> | null>(null);
  const [isLocationPickerOpen, setIsLocationPickerOpen] = useState(false);


  useEffect(() => {
    const draftData = {
        customer,
        scheduledDate,
        scheduledTime,
        serviceSelection,
        vehicleCategoryTag,
        assignedTo
    };
    localStorage.setItem(DRAFT_KEY, JSON.stringify(draftData));
  }, [customer, scheduledDate, scheduledTime, serviceSelection, vehicleCategoryTag, assignedTo]);

  useEffect(() => {
    if (customer.carBrandModel) {
        const detectedCategory = getCategoryForVehicle(customer.carBrandModel);
        if (vehicleCategoryTag !== detectedCategory && !vehicleCategoryTag) {
            setVehicleCategoryTag(detectedCategory);
        }
    }
  }, [customer.carBrandModel]);

  useEffect(() => {
    if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);

    const mobileNumber = customer.mobileNumber;
    if (mobileNumber.trim().length < 10) {
      setSearchMessage('');
      setIsSearching(false);
      if (mobileNumber.trim().length === 0) setFoundProfiles(null);
      return;
    }

    setIsSearching(true);
    setSearchMessage('');

    searchTimeoutRef.current = window.setTimeout(async () => {
      const profiles = await findCustomerByMobile(mobileNumber, allSubmissions, userSubscriptions);
      setIsSearching(false);
      if (profiles && profiles.length > 0) {
        if (profiles.length === 1) {
            setCustomer(prev => ({ ...prev, ...profiles[0].customer }));
            setFoundProfiles(null);
            if (profiles[0].isSubscriber) {
                setSearchMessage(`Subscriber found! Washes Left: ${profiles[0].washesRemaining}.`);
            } else {
                setSearchMessage('Existing customer found. Details pre-filled.');
            }
        } else {
            setFoundProfiles(profiles);
            const firstProfile = profiles[0].customer;
            setCustomer(prev => ({
                ...prev,
                firstName: firstProfile.firstName,
                lastName: firstProfile.lastName,
                streetAddress: firstProfile.streetAddress,
                customerEmail: firstProfile.customerEmail,
                carNumber: '',
                carBrandModel: '',
            }));
            setSearchMessage(`${profiles.length} vehicles found. Please select one.`);
        }
      } else {
        setSearchMessage('New customer.');
        setFoundProfiles(null);
      }
    }, 500); 

    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, [customer.mobileNumber, allSubmissions, userSubscriptions]);

  const handleVehicleChange = useCallback((value: string) => {
    setCustomer(prev => ({...prev, carBrandModel: value}));
    if (errors.carBrandModel) {
        setErrors(p => {
            const newErrors = { ...p };
            delete newErrors.carBrandModel;
            return newErrors;
        });
    }
  }, [errors.carBrandModel]);

  const handleOpenLocationPicker = () => {
      setIsLocationPickerOpen(true);
  };

  const handleLocationConfirm = (lat: number, lng: number) => {
      setCustomer(prev => ({
          ...prev,
          latitude: lat,
          longitude: lng
      }));
  };

  if (!isOpen) return null;

  const handleCarSelection = (profile: any) => {
    setCustomer(prev => ({ ...prev, ...profile.customer }));
    setFoundProfiles(null); 
  };

  const handleCustomerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    if (name === 'mobileNumber') {
      const sanitized = value.replace(/[^0-9+]/g, '').replace(/(?!^)\+/g, '');
      if (sanitized.length <= 15) {
          setCustomer(prev => ({ ...prev, mobileNumber: sanitized }));
      }
    } else {
      setCustomer(prev => ({ ...prev, [name]: value }));
    }

    if (errors[name]) {
        setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleToggleService = (selection: string) => {
    const newSelections = serviceSelection.includes(selection)
      ? serviceSelection.filter(s => s !== selection)
      : [...serviceSelection, selection];
    setServiceSelection(newSelections);
  };

  const clearForm = () => {
      if(window.confirm("Are you sure you want to clear all fields? This cannot be undone.")) {
          setCustomer({ firstName: '', lastName: '', mobileNumber: '', carNumber: '', carBrandModel: '', streetAddress: '', customerEmail: '', latitude: undefined, longitude: undefined});
          setScheduledDate('');
          setScheduledTime('');
          setServiceSelection([]);
          setVehicleCategoryTag(undefined);
          setAssignedTo('');
          setErrors({});
          setSearchMessage('');
          localStorage.removeItem(DRAFT_KEY);
      }
  }

  const handleSubmit = () => {
    const newErrors: { [key: string]: string } = {};

    if (!customer.firstName.trim()) newErrors.firstName = 'First Name is required.';
    if (!customer.mobileNumber.trim()) newErrors.mobileNumber = 'Mobile Number is required.';
    if (!customer.carNumber.trim()) newErrors.carNumber = 'Car Number is required.';
    if (!customer.carBrandModel.trim()) newErrors.carBrandModel = 'Car Brand & Model are required.';

    if (scheduledDate) {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const selected = new Date(scheduledDate);
        const userTimezoneOffset = selected.getTimezoneOffset() * 60000;
        const localSelectedDate = new Date(selected.getTime() + userTimezoneOffset);

        if (localSelectedDate < today) {
            newErrors.scheduledDate = 'Scheduled date cannot be in the past.';
        }
    }

    setErrors(newErrors);

    if (Object.keys(newErrors).length > 0) {
      return;
    }

    onCreateOrder({ customer, scheduledDate, scheduledTime, serviceSelection, vehicleCategoryTag, assignedTo });
    localStorage.removeItem(DRAFT_KEY);
    setCustomer({ firstName: '', lastName: '', mobileNumber: '', carNumber: '', carBrandModel: '', streetAddress: '', customerEmail: '', latitude: undefined, longitude: undefined});
    setScheduledDate('');
    setScheduledTime('');
    setServiceSelection([]);
    setAssignedTo('');
    onClose();
  };

  return (
    <>
    <div className="fixed inset-0 bg-black bg-opacity-60 flex items-start sm:items-center justify-center z-50 p-4 pt-8 sm:pt-4 modal-backdrop" onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-lg bg-white rounded-xl shadow-md flex flex-col max-h-[90vh] modal-content">
        <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex-shrink-0 flex justify-between items-center">
          <h3 className="text-lg font-semibold text-slate-800">Create New Service Order</h3>
          <button onClick={clearForm} className="text-xs text-red-600 hover:text-red-800 flex items-center">
              <IconTrash className="w-3 h-3 mr-1"/> Clear Form
          </button>
        </div>

        <div className="overflow-y-auto p-6">
            <div className="mb-4 bg-blue-50 border-l-4 border-blue-400 p-3 rounded text-xs text-blue-800 flex items-start">
                 <IconDeviceFloppy className="w-4 h-4 mr-2 mt-0.5 flex-shrink-0"/>
                 <p><strong>Smart Draft:</strong> Your data is saved automatically as you type. If you refresh or close this window, your progress will be restored.</p>
            </div>

          <div className="space-y-6">
            <div>
              <h3 className="text-md font-semibold text-slate-700 mb-2">Customer & Vehicle Details</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <Input 
                    label="Mobile Number" name="mobileNumber" type="tel" value={customer.mobileNumber} onChange={handleCustomerChange} 
                    required error={errors.mobileNumber} maxLength={15} prefix="+91" 
                    suffix={isSearching ? <IconLoader className="w-5 h-5 text-slate-400 animate-spin" /> : undefined}
                  />
                  {searchMessage && !isSearching && !foundProfiles && <p className={`mt-1 text-xs font-semibold ${searchMessage.includes('Subscriber') ? 'text-green-600' : searchMessage.includes('found') ? 'text-blue-600' : 'text-slate-500'}`}>{searchMessage}</p>}
                </div>
                <Input label="First Name" name="firstName" value={customer.firstName} onChange={handleCustomerChange} required error={errors.firstName} />
                <Input label="Last Name" name="lastName" value={customer.lastName} onChange={handleCustomerChange} />
                <Input label="Email (Optional)" name="customerEmail" type="email" value={customer.customerEmail || ''} onChange={handleCustomerChange} />
                 {foundProfiles ? (
                    <div className="sm:col-span-2 space-y-2">
                        <p className="text-sm font-semibold text-blue-700">{searchMessage}</p>
                        {foundProfiles.map((profile, index) => (
                            <button
                                key={index}
                                type="button"
                                onClick={() => handleCarSelection(profile)}
                                className="w-full text-left p-3 rounded-md border-2 bg-white hover:border-brand-accent focus:border-brand-accent focus:outline-none transition-colors"
                            >
                                <p className="font-semibold text-slate-800">{profile.customer.carBrandModel}</p>
                                <p className="text-slate-600">{profile.customer.carNumber}</p>
                            </button>
                        ))}
                    </div>
                ) : (
                    <>
                      <Input label="Car Number" name="carNumber" value={customer.carNumber} onChange={handleCustomerChange} required error={errors.carNumber} />
                        <div className="sm:col-span-2">
                            <VehicleSelector
                                value={customer.carBrandModel}
                                onChange={handleVehicleChange}
                                error={errors.carBrandModel}
                                vehicleData={vehicleData}
                                onUpdateVehicleData={noOp}
                            />
                        </div>
                    </>
                )}
                 <div>
                    <label htmlFor="vehicleCategoryTag" className="block text-sm font-medium text-slate-700 mb-1">
                        Vehicle Category
                    </label>
                    <select
                        id="vehicleCategoryTag"
                        value={vehicleCategoryTag || ''}
                        onChange={(e) => setVehicleCategoryTag(e.target.value as VehicleCategoryTag)}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm"
                    >
                        <option value="">-- Select Category --</option>
                        {VEHICLE_CATEGORY_TAGS.map(tag => (
                            <option key={tag} value={tag}>{tag}</option>
                        ))}
                    </select>
                </div>
