interface AttendanceControlProps {
    currentUser: User;
    onUpdateAttendanceStatus: (username: string, status: AttendanceStatus) => void;
}

const ShiftTimer: React.FC<{ startTime: string }> = ({ startTime }) => {
    const [duration, setDuration] = useState('00:00:00');

    useEffect(() => {
        const start = new Date(startTime).getTime();
        const timer = setInterval(() => {
            const now = new Date().getTime();
            const diff = now - start;

            const hours = Math.floor(diff / (1000 * 60 * 60));
            const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((diff % (1000 * 60)) / 1000);

            setDuration(
                `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
            );
        }, 1000);

        return () => clearInterval(timer);
    }, [startTime]);

    return <span className="font-mono text-2xl font-bold tracking-widest">{duration}</span>;
};

const AttendanceControl: React.FC<AttendanceControlProps> = ({ currentUser, onUpdateAttendanceStatus }) => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);

    const isCheckedIn = currentUser.attendanceStatus === 'CHECKED_IN';
    const nextStatus: AttendanceStatus = isCheckedIn ? 'CHECKED_OUT' : 'CHECKED_IN';

    // Get the timestamp of the last check-in from history if available
    const currentSessionStart = isCheckedIn && currentUser.attendanceHistory && currentUser.attendanceHistory.length > 0
        ? currentUser.attendanceHistory[currentUser.attendanceHistory.length - 1].timestamp
        : new Date().toISOString();

    const handleToggle = () => {
        setIsModalOpen(true);
    };

    const handleConfirm = () => {
        setIsLoading(true);
        // Simulate a brief delay for UX (getting location lock feel)
        setTimeout(() => {
            onUpdateAttendanceStatus(currentUser.username, nextStatus);
            setIsLoading(false);
            setIsModalOpen(false);
        }, 800);
    };

    const ConfirmationModal = () => (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4 modal-backdrop" onClick={() => setIsModalOpen(false)}>
            <div onClick={(e) => e.stopPropagation()} className="w-full max-w-md modal-content">
                <Card title={nextStatus === 'CHECKED_IN' ? 'Start Your Shift' : 'End Your Shift'}>
                    <div className="text-slate-600 space-y-4">
                        {nextStatus === 'CHECKED_IN' ? (
                            <div className="flex flex-col items-center text-center space-y-4 py-4">
                                <div className="p-4 bg-green-100 rounded-full">
                                    <IconMapPin className="w-8 h-8 text-green-600" />
                                </div>
                                <div>
                                    <h4 className="font-bold text-lg text-slate-800">Enable Live Tracking?</h4>
                                    <p className="text-sm text-slate-500 mt-2">
                                        Checking in enables <strong>Smart GPS Tracking</strong>. 
                                        Your location will be streamed to the admin dashboard in real-time while you are on duty.
                                    </p>
                                </div>
                            </div>
                        ) : (
                            <div className="flex flex-col items-center text-center space-y-4 py-4">
                                 <div className="p-4 bg-red-100 rounded-full">
                                    <IconUserOff className="w-8 h-8 text-red-600" />
                                </div>
                                <p>Are you sure you want to check out? This will stop location tracking and end your shift timer.</p>
                            </div>
                        )}
                    </div>
                    <div className="mt-6 flex justify-end space-x-2 border-t pt-4">
                        <Button variant="ghost" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                        <Button onClick={handleConfirm} variant={nextStatus === 'CHECKED_IN' ? 'primary' : 'danger'} disabled={isLoading}>
                            {isLoading ? <IconLoader className="w-5 h-5 animate-spin"/> : (nextStatus === 'CHECKED_IN' ? 'Confirm Check-In' : 'Confirm Check-Out')}
                        </Button>
                    </div>
                </Card>
            </div>
        </div>
    );

    return (
        <div className={`rounded-xl shadow-sm border transition-all duration-500 overflow-hidden relative ${isCheckedIn ? 'bg-gradient-to-br from-white to-green-50 border-green-200' : 'bg-white border-slate-200'}`}>
            {/* Active Indicator Pulse */}
            {isCheckedIn && (
                <div className="absolute top-3 right-3 flex items-center space-x-2">
                    <span className="relative flex h-3 w-3">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
                    </span>
                    <span className="text-xs font-bold text-green-700 uppercase tracking-wider">Live Tracking</span>
                </div>
            )}

            <div className="p-6">
                <div className="flex flex-col sm:flex-row items-center justify-between gap-6">
                    <div className="flex items-center space-x-4 w-full sm:w-auto">
                        <div className={`p-4 rounded-full shadow-inner ${isCheckedIn ? 'bg-green-100' : 'bg-slate-100'}`}>
                            {isCheckedIn ? <IconUserCheck className="w-8 h-8 text-green-600" /> : <IconUserOff className="w-8 h-8 text-slate-400" />}
                        </div>
                        <div>
                            <p className="text-sm font-medium text-slate-500 uppercase tracking-wider mb-1">Current Status</p>
                            <h3 className={`text-xl font-bold ${isCheckedIn ? 'text-green-700' : 'text-slate-700'}`}>
                                {isCheckedIn ? "On Duty" : "Off Duty"}
                            </h3>
                            {isCheckedIn && (
                                <p className="text-xs text-green-600 mt-1 flex items-center">
                                    <IconMapPin className="w-3 h-3 mr-1" /> GPS Active
                                </p>
                            )}
                        </div>
                    </div>

                    {/* Timer Section */}
                    {isCheckedIn ? (
                        <div className="flex flex-col items-center bg-white/60 p-3 rounded-lg border border-green-100 w-full sm:w-auto min-w-[160px]">
                            <p className="text-xs text-slate-500 flex items-center mb-1">
                                <IconClock className="w-3 h-3 mr-1" /> Shift Duration
                            </p>
                            <div className="text-green-800">
                                <ShiftTimer startTime={currentSessionStart} />
                            </div>
                        </div>
                    ) : (
                         <div className="hidden sm:block text-slate-400 text-sm italic">
                            Ready to start your day?
                         </div>
                    )}

                    <div className="w-full sm:w-auto">
                        <Button
                            onClick={handleToggle}
                            variant={isCheckedIn ? 'danger' : 'primary'}
                            className={`w-full sm:w-auto py-3 px-6 shadow-md transition-transform active:scale-95 ${isCheckedIn ? 'bg-red-500 hover:bg-red-600 border-red-600' : 'bg-brand-blue hover:bg-brand-blue/90'}`}
                        >
                            {isCheckedIn ? 'End Shift' : 'Start Shift'}
                        </Button>
                    </div>
                </div>
            </div>

            {/* Bottom Bar for Offline Status */}
            {!isCheckedIn && (
                <div className="bg-slate-50 px-6 py-2 border-t border-slate-100 text-xs text-slate-500 flex items-center justify-center sm:justify-start">
                    <IconUserOff className="w-3 h-3 mr-2" />
                    <span>Location tracking is currently disabled. Check in to enable.</span>
                </div>
            )}

            {isModalOpen && <ConfirmationModal />}
        </div>
    );
};

