import React, { useState, useEffect } from 'react';
import { User, AttendanceStatus } from '../../types';
import Button from '../ui/Button';
import { IconUserCheck, IconUserOff, IconClock, IconMapPin, IconLoader } from '../ui/Icon';
import Card from '../ui/Card';

interface AttendanceControlProps {
    currentUser: User;
    onUpdateAttendanceStatus: (username: string, status: AttendanceStatus) => void;
}

const ShiftTimer: React.FC<{ startTime: string }> = ({ startTime }) => {
    const [duration, setDuration] = useState('00:00:00');

    useEffect(() => {
        const start = new Date(startTime).getTime();
        const timer = setInterval(() => {
            const now = new Date().getTime();
            const diff = now - start;

            const hours = Math.floor(diff / (1000 * 60 * 60));
            const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((diff % (1000 * 60)) / 1000);

            setDuration(
                `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
            );
        }, 1000);

        return () => clearInterval(timer);
    }, [startTime]);

    return <span className="font-mono text-2xl font-bold tracking-widest">{duration}</span>;
};

const AttendanceControl: React.FC<AttendanceControlProps> = ({ currentUser, onUpdateAttendanceStatus }) => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);

    const isCheckedIn = currentUser.attendanceStatus === 'CHECKED_IN';
    const nextStatus: AttendanceStatus = isCheckedIn ? 'CHECKED_OUT' : 'CHECKED_IN';

    // Get the timestamp of the last check-in from history if available
    const currentSessionStart = isCheckedIn && currentUser.attendanceHistory && currentUser.attendanceHistory.length > 0
        ? currentUser.attendanceHistory[currentUser.attendanceHistory.length - 1].timestamp
        : new Date().toISOString();

    const handleToggle = () => {
        setIsModalOpen(true);
    };

    const handleConfirm = () => {
        setIsLoading(true);
        // Simulate a brief delay for UX (getting location lock feel)
        setTimeout(() => {
            onUpdateAttendanceStatus(currentUser.username, nextStatus);
            setIsLoading(false);
            setIsModalOpen(false);
        }, 800);
    };

    const ConfirmationModal = () => (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4 modal-backdrop" onClick={() => setIsModalOpen(false)}>
            <div onClick={(e) => e.stopPropagation()} className="w-full max-w-md modal-content">
                <Card title={nextStatus === 'CHECKED_IN' ? 'Start Your Shift' : 'End Your Shift'}>
                    <div className="text-slate-600 space-y-4">
                        {nextStatus === 'CHECKED_IN' ? (
