  const handleAutoSchedule = (subscription: UserSubscription) => {
    const plan = subscriptionPlans.find(p => p.id === subscription.planId);
    if (!plan || plan.totalWashes <= 0) { return; }

    const today = new Date();
    if (today.getDate() > 7) {
        alert("Auto-scheduling for this month has been skipped because it is past the first week. You can schedule washes manually.");
        return;
    }

    const year = today.getFullYear();
    const month = today.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const washesToSchedule = plan.totalWashes;
    const interval = Math.floor(daysInMonth / washesToSchedule);
    const newServices: Service[] = [];

    for (let i = 0; i < washesToSchedule; i++) {
      const scheduledDay = Math.round((i * interval) + (interval / 2));
      const scheduledDate = new Date(year, month, scheduledDay);
      if (scheduledDate < new Date(today.getFullYear(), today.getMonth(), today.getDate())) { continue; }

      const submissionId = `SUB-${Date.now()}-${i}`;
      const newService: Service = {
        ...createDefaultServiceState(),
        submissionId, appointmentId: submissionId, timestamp: new Date().toISOString(), status: ServiceStatus.Queued,
        customerFirstName: subscription.customerFirstName, customerLastName: subscription.customerLastName, mobileNumber: subscription.mobileNumber,
        customerEmail: subscription.customerEmail,
        carNumber: subscription.carNumber, carBrandModel: subscription.carBrandModel, streetAddress: subscription.streetAddress,
        serviceSelection: ['Car Washing'], isSubscription: true, isAutoScheduled: true,
        scheduledDate: scheduledDate.toISOString().split('T')[0], scheduledTime: "09:00 - 10:00",
        acknowledgement: true,
      };
      newServices.push(newService);
    }

    if (newServices.length > 0) {
      setSubmissions(prev => [...prev, ...newServices]);
      newServices.forEach(s => cloudDataService.saveRecord('Submissions', s, settings.googleSheetsUrl));
      alert(`${newServices.length} washes have been automatically scheduled for this month.`);
    }
  };

