    }
    if(userToSave) {
        cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
        triggerHapticFeedback('success');
    }
};

  const handleShareOrder = (service: Service) => {
    setSharingService(service);
  };

  if (publicService) {
    return <PublicServiceSummary serviceData={publicService.data} logoUrl={settings.customLogoUrl} />;
  }

  if (appIsLoading) {
    return <LoadingScreen />;
  }

  if (!currentUser) {
    return <LoginPage onLoginAttempt={handleLoginAttempt} error={loginError} />;
  }

  if (printingService) {
    return <PrintPreview service={printingService} onClose={() => setPrintingService(null)} serviceTemplates={serviceTemplates} />;
  }

  const currentUserNotifications = notifications
    .filter(n => n.userId === currentUser.username || currentUser.role === 'admin' || currentUser.role === 'manager')
    .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

  const unreadCount = currentUserNotifications.filter(n => !n.isRead).length;

  const renderView = () => {
    const hasPermission = (p: Permission) => currentUser.permissions.includes(p);

    switch(view) {
      case 'FORM':
        return hasPermission(Permission.CAN_CREATE_ORDERS) ? <ServiceForm 
                 initialService={editingService} 
                 allSubmissions={submissions}
                 onComplete={handleCompleteOrder}
                 onSaveDraft={handleSaveDraft}
                 onAdminUpdate={handleAdminUpdate}
                 onExit={() => { setView('DASHBOARD'); setEditingService(null); }}
                 googleDriveUploadUrl={settings.googleDriveUploadUrl}
                 currentUser={currentUser}
                 allUsers={users.map(({password, ...rest}) => rest)}
                 userSubscriptions={userSubscriptions}
                 serviceTemplates={serviceTemplates}
                 vehicleData={vehicleData}
                 tyreData={tyreData}
                 onUpdateVehicleData={handleUpdateVehicleData}
                 onUpdateTyreData={handleUpdateTyreData}
               /> : <DashboardPage {...dashboardProps} />;
      case 'LIST':
        return hasPermission(Permission.CAN_VIEW_SERVICE_HISTORY) ? <SubmissionList 
                 submissions={submissions}
                 users={users.map(({password, ...rest}) => rest)}
                 onEdit={handleEditService}
                 onPrint={setPrintingService}
                 onSummarize={setSummarizingService}
                 currentUser={currentUser}
                 serviceTemplates={serviceTemplates}
               /> : <DashboardPage {...dashboardProps} />;
      case 'APPOINTMENTS_OVERVIEW':
        return hasPermission(Permission.CAN_VIEW_APPOINTMENTS_OVERVIEW) ? <AppointmentsOverviewPage
                    currentUser={currentUser}
                    submissions={submissions}
                    onUpdateOrder={handleEditService}
                    onStartOrder={handleStartOrder}
                    onShareOrder={handleShareOrder}
                /> : <DashboardPage {...dashboardProps} />;
      case 'NOTIFICATION_PREFERENCES':
        return <NotificationPreferencesPage
                 currentUser={currentUser}
                 onSave={handleUpdateNotificationPreferences}
                 onUpdatePushSubscription={handleUpdatePushSubscription}
               />;
      case 'USER_MANAGEMENT':
        return hasPermission(Permission.CAN_MANAGE_USERS) ? <UserManagementPage
                 users={users.map(({password, ...rest}) => rest)}
                 onUpdateUsers={handleUpdateUsers}
                 fullUserList={users}
                 currentUser={currentUser}
               /> : <DashboardPage {...dashboardProps} />;
      case 'SERVICE_TEMPLATE_MANAGEMENT':
        return hasPermission(Permission.CAN_MANAGE_SERVICES) ? <ServiceTemplateManagementPage
                  templates={serviceTemplates}
                  onUpdateTemplates={handleUpdateServiceTemplates}
                  onEditTemplate={handleEditTemplate}
                /> : <DashboardPage {...dashboardProps} />;
       case 'SERVICE_TEMPLATE_EDITOR':
        return hasPermission(Permission.CAN_MANAGE_SERVICES) ? <ServiceTemplateEditorPage
                  template={editingTemplate!}
                  onSave={handleSaveServiceTemplate}
                  onExit={() => { setView('SERVICE_TEMPLATE_MANAGEMENT'); setEditingTemplate(null); }}
               /> : <DashboardPage {...dashboardProps} />;
      case 'PLAN_MANAGEMENT':
          return hasPermission(Permission.CAN_MANAGE_PLANS) ? <SubscriptionPlanManagementPage
                    plans={subscriptionPlans}
                    onUpdatePlans={handleUpdateSubscriptionPlans}
                /> : <DashboardPage {...dashboardProps} />;
      case 'USER_SUBSCRIPTION_MANAGEMENT':
          return hasPermission(Permission.CAN_MANAGE_SUBSCRIPTIONS) ? <UserSubscriptionManagementPage
                    userSubscriptions={userSubscriptions}
                    subscriptionPlans={subscriptionPlans}
                    onUpdateUserSubscriptions={handleUpdateUserSubscriptions}
                    onAutoSchedule={handleAutoSchedule}
                 /> : <DashboardPage {...dashboardProps} />;
      case 'SERVICE_REQUEST':
        return hasPermission(Permission.CAN_VIEW_SERVICE_REQUESTS) ? <ServiceRequestPage
                 serviceRequests={serviceRequests}
               /> : <DashboardPage {...dashboardProps} />;
       case 'LIVE_MAP':
        return hasPermission(Permission.CAN_VIEW_LIVE_MAP) ? <LiveMapPage
                 users={users.map(({password, ...rest}) => rest)}
                 currentUser={currentUser}
                 submissions={submissions}
                 onRefresh={handleManualRefresh}
                 isRefreshing={isManualRefreshing}
                 locationHistory={locationHistory}
               /> : <DashboardPage {...dashboardProps} />;
      case 'ANALYTICS':
        return hasPermission(Permission.CAN_VIEW_ANALYTICS) ? <AnalyticsPage
                 submissions={submissions}
                 users={users.map(({password, ...rest}) => rest)}
                 serviceTemplates={serviceTemplates}
               /> : <DashboardPage {...dashboardProps} />;
       case 'CUSTOMER_HISTORY':
        return hasPermission(Permission.CAN_VIEW_CUSTOMER_HISTORY) ? <CustomerHistoryPage
                 submissions={submissions}
                 currentUser={currentUser}
                 onShareOrder={handleShareOrder}
               /> : <DashboardPage {...dashboardProps} />;
      case 'RETENTION':
        return hasPermission(Permission.CAN_VIEW_RETENTION_DASHBOARD) ? <RetentionDashboard
                 submissions={submissions}
                 onCreateFollowUp={handleCreateFollowUp}
                 settings={settings}
                 onUpdateKpiTargets={handleUpdateKpiTargets}
               /> : <DashboardPage {...dashboardProps} />;
      case 'BOOKKEEPING':
        return hasPermission(Permission.CAN_LOG_EXPENSES) ? <BookkeepingPage
            currentUser={currentUser}
            miscSpends={miscSpends}
            users={users.map(({password, ...rest}) => rest)}
            googleDriveUploadUrl={settings.googleDriveUploadUrl}
            onSaveNewSpend={handleSaveNewSpend}
            onUpdateSpendStatus={handleUpdateSpendStatus}
            bookkeeping={bookkeeping}
        /> : <DashboardPage {...dashboardProps} />;
      case 'PROFIT_LOSS':
        return hasPermission(Permission.CAN_VIEW_PROFIT_LOSS) ? <ProfitLossPage
            submissions={submissions}
            profitLossData={profitLossData}
            onSave={handleUpdateProfitLoss}
        /> : <DashboardPage {...dashboardProps} />;
      case 'DASHBOARD':
        return hasPermission(Permission.CAN_VIEW_DASHBOARD) ? <DashboardPage {...dashboardProps} /> : <div>Access Denied</div>;
      default:
        return <div>Unknown view</div>;
    }
  };

  const dashboardProps = {
    submissions,
    users: users.map(({password, ...rest}) => rest),
    currentUser,
    onCreateOrder: handleCreateOrder,
    onAssignOrder: handleAssignOrder,
    onStartOrder: handleStartOrder,
    onUpdateOrder: handleEditService,
    onSelfAssignOrder: handleSelfAssignOrder,
    onDeleteOrder: handleDeleteRequest,
    onScheduleDroppedOrder: handleScheduleDroppedOrder,
    onNotifyForOrder: handleNotifyForOrder,
    onUpdateAttendanceStatus: handleUpdateAttendanceStatus,
    userSubscriptions,
    serviceTemplates,
    setIsChatbotOpen,
    settings,
    locationHistory,
    vehicleData,
    tyreData,
    onShareOrder: handleShareOrder,
  };

  return (
    <div className="min-h-screen bg-slate-100 flex">
      {isSettingsOpen && currentUser.permissions.includes(Permission.CAN_EDIT_SETTINGS) && (
        <SettingsModal 
          initialSettings={settings}
          onClose={() => setIsSettingsOpen(false)} 
          onSave={handleSaveSettings}
        />
      )}

      {summarizingService && (
          <SummaryModal 
            service={summarizingService}
            onClose={() => setSummarizingService(null)}
          />
      )}

      {sharingService && (
        <ShareOrderModal 
          service={sharingService}
          onClose={() => setSharingService(null)}
        />
      )}

      {isChatbotOpen && (
        <ChatbotModal
            isOpen={isChatbotOpen}
            onClose={() => setIsChatbotOpen(false)}
            onSubmit={handleSaveDraftFromChatbot}
            serviceTemplates={serviceTemplates}
        />
       )}

      {deletingService && (
        <DeleteConfirmationModal
            isOpen={!!deletingService}
            onClose={() => setDeletingService(null)}
            onConfirm={handleConfirmDelete}
            service={deletingService}
        />
      )}

      <Sidebar
          currentUser={currentUser}
          currentView={view}
          onNavigate={handleNavigate}
          onNewService={() => handleEditService(null)}
          onOpenSettings={() => setIsSettingsOpen(true)}
          onLogout={handleLogout}
          logoUrl={settings.customLogoUrl}
          logoHasError={logoHasError}
          onLogoError={() => setLogoHasError(true)}
          isMinimized={isSidebarMinimized}
          isOpenOnMobile={isMobileMenuOpen}
          onToggleDesktop={() => setIsSidebarMinimized(!isSidebarMinimized)}
          onCloseMobile={() => setIsMobileMenuOpen(false)}
      />

       {isMobileMenuOpen && <div className="fixed inset-0 bg-black/60 z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)}></div>}

      <div className={`flex-1 transition-all duration-300 ${isSidebarMinimized ? 'md:pl-20' : 'md:pl-64'}`}>
          <header className="sticky top-0 bg-slate-100/80 backdrop-blur-md z-30 border-b border-slate-200 no-print">
              <div className="relative flex items-center justify-between min-h-16 px-4 md:px-6 py-2 gap-2">
                  <button className="md:hidden text-slate-600" onClick={() => setIsMobileMenuOpen(true)} aria-label="Open menu">
                      <IconMenu2 className="w-6 h-6" />
                  </button>
                  <div className="flex items-center gap-2 flex-wrap justify-end">
                      <RealTimeClock />
                      <div className="h-6 w-px bg-slate-300 hidden sm:block"></div>
                      <NotificationBell 
                          unreadCount={unreadCount}
                          onClick={() => setIsNotificationHistoryOpen(prev => !prev)}
                      />
                      {currentUser.role === 'admin' && (
                          <button
                              onClick={handleManualNotifyAll}
                              className="p-2 text-slate-500 hover:text-slate-800 hover:bg-slate-200 rounded-full transition-colors"
                              aria-label="Send broadcast notification to all users"
                              title="Send a notification to all users"
                          >
                              <IconBellRinging className="w-6 h-6" />
                          </button>
                      )}
                      <button
                          onClick={handleManualRefresh}
                          disabled={isManualRefreshing || !settings.googleSheetsUrl}
                          className="p-2 text-slate-500 hover:text-slate-800 hover:bg-slate-200 rounded-full transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                          aria-label="Refresh data from cloud"
                          title={!settings.googleSheetsUrl ? "Cloud sync is offline. Check settings." : "Refresh data from cloud"}
                      >
                          <IconRefresh className={`w-6 h-6 ${isManualRefreshing ? 'animate-spin' : ''}`} />
                      </button>
                      <SyncStatusIndicator status={syncStatus} errorMessage={syncError} />
                  </div>
                   {isNotificationHistoryOpen && (
                        <NotificationHistory
                            notifications={currentUserNotifications}
                            onMarkAsRead={handleMarkNotificationAsRead}
                            onMarkAllAsRead={handleMarkAllAsRead}
                            onClose={() => setIsNotificationHistoryOpen(false)}
                        />
                    )}
              </div>
          </header>

          <main className="p-4 sm:p-6 lg:p-8 w-full">
            {syncStatus === 'ERROR' && syncError && (
                <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 relative mb-6 rounded-r-md" role="alert">
                    <strong className="font-bold">Sync Error:</strong>
                    <span className="block sm:inline ml-2">{syncError}</span>
                    <button 
                      onClick={() => setSyncError(null)} 
                      className="absolute top-0 bottom-0 right-0 px-4 py-3"
                      aria-label="Dismiss error message"
                    >
                      <IconX className="h-6 w-6 text-red-500" />
                    </button>
                </div>
            )}

            {renderView()}
          </main>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
// FIX: Removed obsolete 'PredefinedAddon' from import.
import { Service, ServiceStatus, User, UserSubscription, ServiceTemplate, Permission, TyreData, PricingConfig } from '../types';
import { useServiceForm } from '../hooks/useServiceForm';
import CustomerDetailsStep from './CustomerDetailsStep';
import ServiceSelectionStep from './ServiceSelectionStep';
import { ServiceDetailsStep } from './ServiceDetailsStep';
import AddonsStep from './AddonsStep';
import CustomServicesStep from './CustomServicesStep';
import { SummaryStep } from './SummaryStep';
import Stepper from './Stepper';
import Card from './ui/Card';
import Button from './ui/Button';
import Input from './ui/Input';
import { APPOINTMENT_TIME_SLOTS, DEFAULT_PRICING_CONFIG } from '../constants';
import { validateStep, ValidationErrors } from '../services/validationService';
import { IconDeviceFloppy } from './ui/Icon';
import DependencyManager from './DependencyManager';
import CarCareStep from './CarCareStep';

interface ServiceFormProps {
  initialService?: Service | null;
  allSubmissions: Service[];
  onComplete: (service: Service) => void;
  onSaveDraft: (service: Service) => void;
  onAdminUpdate?: (service: Service) => void;
  onExit: () => void;
  googleDriveUploadUrl: string;
  currentUser: User;
  allUsers: Omit<User, 'password'>[];
  userSubscriptions: UserSubscription[];
  serviceTemplates: ServiceTemplate[];
  vehicleData: Record<string, string[]>;
  tyreData: TyreData;
  onUpdateVehicleData: (brand: string, model: string) => void;
  onUpdateTyreData: (type: keyof TyreData, value: string) => void;
  pricingConfig?: PricingConfig;
}

const ALL_STEPS = [
  { name: 'Customer Details', component: CustomerDetailsStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Service Selection', component: ServiceSelectionStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { 
    name: 'Car Care', 
    component: CarCareStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.includes("Car Care")
  },
  { 
    name: 'Service Details', 
    component: ServiceDetailsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => 
      state.serviceSelection.some(s => 
        ["Car Washing", "Tyre Replacement", "Battery Replacement"].includes(s)
      ) || state.serviceSelection.some(s => (serviceTemplates || []).find(t => t.name === s && t.customFields.length > 0))
  },
  { 
    name: 'Add-ons', 
    component: AddonsStep, 
    isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true
  },
  { name: 'Custom Services', component: CustomServicesStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
  { name: 'Invoice Summary', component: SummaryStep, isVisible: (state: Service, serviceTemplates: ServiceTemplate[]) => true },
];

const ServiceForm: React.FC<ServiceFormProps> = ({ 
  initialService, 
  allSubmissions,
  onComplete, 
  onSaveDraft,
  onAdminUpdate,
  onExit, 
  googleDriveUploadUrl, 
  currentUser, 
  allUsers, 
  userSubscriptions,
  serviceTemplates,
  vehicleData,
  tyreData,
  onUpdateVehicleData,
  onUpdateTyreData,
  pricingConfig = DEFAULT_PRICING_CONFIG, // Use default if not provided
}) => {
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const { state, dispatch, updateField } = useServiceForm(initialService, pricingConfig);
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [prefillServiceId, setPrefillServiceId] = useState('');
  const [saveConfirmation, setSaveConfirmation] = useState('');

  const isAdminEditing = useMemo(() => 
    currentUser.permissions.includes(Permission.CAN_EDIT_ANY_ORDER) && !!initialService,
  [currentUser, initialService]);

  useEffect(() => {
    if (initialService) {
      dispatch({ type: 'SET_FORM_DATA', payload: JSON.parse(JSON.stringify(initialService)) });
    }
  }, [initialService, dispatch]);


  const sortedSubmissions = useMemo(() => {
    return [...allSubmissions].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [allSubmissions]);

  const handlePrefillChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedId = e.target.value;
    setPrefillServiceId(selectedId);

    if (!selectedId) return;

    const serviceToCopy = allSubmissions.find(s => s.submissionId === selectedId);
    if (!serviceToCopy) return;

    const newSubmissionId = `SUB-${Date.now()}`;
    const newServiceData: Service = {
      ...JSON.parse(JSON.stringify(serviceToCopy)),
      submissionId: newSubmissionId,
      appointmentId: newSubmissionId,
      timestamp: new Date().toISOString(),
      status: ServiceStatus.Draft,
      acknowledgement: false,
      beforeWashingPhoto: '', beforeVideoInventory: '', beforeVideoTopBody: '', beforeVideoUnderchassis: '',
      afterWashingPhoto: '', afterVideoInterior: '', afterVideoExterior: '', afterVideoUnderchassis: '',
      tyreDetails: [],
      batteryDetails: [],
      customFieldData: (serviceToCopy.customFieldData || []).filter(field => {
          const allCustomFields = serviceTemplates.flatMap(st => st.customFields);
          const fieldDef = allCustomFields.find(f => f.id === field.fieldId);
          return fieldDef?.type !== 'PHOTO';
      }),
      assignedTo: undefined,
      scheduledDate: undefined,
      scheduledTime: undefined,
      internalNotes: '',
      isFollowUp: true,
      dependsOn: [], // Dependencies should not be copied
    };

    dispatch({ type: 'SET_FORM_DATA', payload: newServiceData });
  };


  const visibleSteps = useMemo(() => {
    return ALL_STEPS.map((step, index) => ({...step, originalIndex: index}))
                     .filter(step => step.isVisible(state, serviceTemplates));
  }, [state, serviceTemplates]);

  const StepComponent = visibleSteps[currentStepIndex].component;

  const handleStepClick = (index: number) => {
    if (isAdminEditing || index < currentStepIndex) {
      setErrors({}); 
      setCurrentStepIndex(index);
    }
  };

  const nextStep = () => {
    const currentStepName = visibleSteps[currentStepIndex].name;
    const validationErrors = validateStep(currentStepName, state);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      setCurrentStepIndex(prev => Math.min(prev + 1, visibleSteps.length - 1));
    }
  };

  const prevStep = () => {
    setErrors({}); 
    setCurrentStepIndex(prev => Math.max(prev - 1, 0));
  };

  const handleSubmit = () => {
    if (state.acknowledgement) {
      localStorage.removeItem('service_form_in_progress');
      onComplete(state);
    }
  };

  const handleSaveDraftClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onSaveDraft(state);
  };

  const handleAdminSave = () => {
    if (!onAdminUpdate) return;
    onAdminUpdate(state);
    setSaveConfirmation('Changes saved successfully!');
    setTimeout(() => setSaveConfirmation(''), 2500);
  };

  const handleExitClick = () => {
    localStorage.removeItem('service_form_in_progress');
    onExit();
  };

  const handleUpdateDependencies = useCallback((newDeps: string[]) => {
    updateField('dependsOn', newDeps);
  }, [updateField]);

  const isLastStep = currentStepIndex === visibleSteps.length - 1;

  const showDraftButton = (!initialService || initialService?.status === ServiceStatus.Draft);

  return (
    <Card className={!isAdminEditing ? "pb-24 sm:pb-6" : ""}>
      {!initialService && (
        <div className="p-4 mb-8 bg-slate-50 border border-slate-200 rounded-lg no-print">
          <label htmlFor="prefill-select" className="block text-sm font-medium text-slate-700 mb-1">
            Pre-fill from Existing Service (Optional)
          </label>
          <select
            id="prefill-select"
            value={prefillServiceId}
            onChange={handlePrefillChange}
            className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus-visible:border-brand-accent sm:text-sm"
          >
            <option value="">-- Select a past service to copy data from --</option>
            {sortedSubmissions.map(s => (
              <option key={s.submissionId} value={s.submissionId}>
                {new Date(s.timestamp).toLocaleDateString()} - #{s.appointmentId?.split('-').pop()} - {s.customerFirstName} ({s.carNumber})
              </option>
            ))}
          </select>
        </div>
      )}

      <div className="mb-8 pb-4 border-b border-slate-200 no-print">
        <Stepper 
          steps={visibleSteps} 
          currentStepIndex={currentStepIndex} 
          onStepClick={handleStepClick}
          isClickable={isAdminEditing}
        />
      </div>

      {isAdminEditing && (
        <div className="sticky top-[63px] bg-slate-100/80 backdrop-blur-md z-20 -mx-6 px-6 -mt-8 mb-8">
            <div className="flex justify-between items-center h-16 border-b">
                 <Button variant="ghost" onClick={handleExitClick}>Exit to Dashboard</Button>
                 <div className="flex items-center space-x-4">
                    {saveConfirmation && <p className="text-sm font-semibold text-green-600 animate-pulse">{saveConfirmation}</p>}
                    <Button onClick={handleAdminSave}>
                        <IconDeviceFloppy className="w-5 h-5 mr-2" />
                        Save Changes
                    </Button>
                 </div>
            </div>
        </div>
      )}

      {isAdminEditing && (
        <div className="p-4 mb-8 bg-blue-50 border border-blue-200 rounded-lg">
          <h3 className="text-lg font-semibold text-blue-800 mb-4">Admin Controls</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label htmlFor="assignedTo" className="block text-sm font-medium text-slate-700 mb-1">Assigned User</label>
              <select
                id="assignedTo"
                name="assignedTo"
                value={state.assignedTo || ''}
                onChange={(e) => updateField('assignedTo', e.target.value || undefined)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                <option value="">-- Unassigned --</option>
                {allUsers.map(u => <option key={u.username} value={u.username}>{u.username}</option>)}
              </select>
            </div>
            <Input 
                label="Scheduled Date" 
                id="scheduledDate" 
                type="date" 
                value={state.scheduledDate ? state.scheduledDate.split('T')[0] : ''} 
                onChange={(e) => updateField('scheduledDate', e.target.value)}
            />
            <div>
              <label htmlFor="scheduledTime" className="block text-sm font-medium text-slate-700 mb-1">Scheduled Time</label>
              <select
                  id="scheduledTime"
                  name="scheduledTime"
                  value={state.scheduledTime || ''}
                  onChange={(e) => updateField('scheduledTime', e.target.value || undefined)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
              >
                  <option value="">-- No Time Set --</option>
                  {APPOINTMENT_TIME_SLOTS.map(time => (
                      <option key={time} value={time}>{time}</option>
                  ))}
              </select>
            </div>
             <div>
                <label htmlFor="status" className="block text-sm font-medium text-slate-700 mb-1">Status</label>
                <select
                    id="status"
                    name="status"
                    value={state.status}
                    onChange={(e) => updateField('status', e.target.value as ServiceStatus)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent focus:border-brand-accent sm:text-sm"
                >
                    {Object.values(ServiceStatus).map(status => (
                        <option key={status} value={status}>{status}</option>
                    ))}
                </select>
            </div>
          </div>
           <div className="mt-6 pt-4 border-t">
              <DependencyManager 
                  service={state}
                  allSubmissions={allSubmissions}
                  onUpdateDependencies={handleUpdateDependencies}
              />
            </div>
        </div>
      )}

      {initialService && (currentUser.role === 'admin' || currentUser.role === 'manager' || currentUser.username === initialService.assignedTo) && (
        <div className="p-4 mb-8 bg-yellow-50 border border-yellow-200 rounded-lg">
            <h3 className="text-lg font-semibold text-yellow-800 mb-2">Internal Notes</h3>
            <p className="text-sm text-yellow-700 mb-4">These notes are only visible to administrators, managers, and the assigned service agent.</p>
            <textarea
                id="internalNotes"
                name="internalNotes"
                value={state.internalNotes || ''}
                onChange={(e) => updateField('internalNotes', e.target.value)}
                rows={3}
                className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                placeholder="Add any internal remarks for this service (e.g., customer is particular about wheels, specific tool needed)..."
            />
        </div>
      )}

      <div className="min-h-[300px]">
        <h2 className="text-2xl font-bold text-slate-800 mb-6">{visibleSteps[currentStepIndex].name}</h2>
        {isLastStep ? (
          <SummaryStep state={state} updateField={updateField} serviceTemplates={serviceTemplates} />
        ) : (
          <StepComponent 
            state={state} 
            updateField={updateField} 
            dispatch={dispatch} 
            googleDriveUploadUrl={googleDriveUploadUrl}
            userSubscriptions={userSubscriptions}
            serviceTemplates={serviceTemplates}
            errors={errors}
            allSubmissions={allSubmissions}
            vehicleData={vehicleData}
            tyreData={tyreData}
            onUpdateVehicleData={onUpdateVehicleData}
            onUpdateTyreData={onUpdateTyreData}
            pricingConfig={pricingConfig}
          />
        )}
      </div>

      {!isAdminEditing && (
          <div className="fixed bottom-0 left-0 right-0 p-4 bg-white border-t border-slate-200 shadow-2xl z-30 flex flex-col-reverse gap-y-3 sm:static sm:bg-transparent sm:border-t-0 sm:shadow-none sm:flex-row sm:justify-between sm:items-center sm:p-0 sm:mt-8 sm:pt-6 no-print">
            <div className="flex items-center justify-between sm:justify-start space-x-2 w-full sm:w-auto">
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep} className="flex-1 sm:flex-none">Back</Button>
                )}
                <Button variant="ghost" onClick={handleExitClick} className="flex-1 sm:flex-none text-center">Exit</Button>
            </div>
            <div className="flex items-center space-x-2 w-full sm:w-auto">
              {showDraftButton && (
                <Button variant="ghost" onClick={handleSaveDraftClick} className="hidden sm:inline-flex">Save as Draft</Button>
              )}

              {!isLastStep && (
                <Button onClick={nextStep} className="w-full sm:w-auto justify-center">Next</Button>
              )}

              {isLastStep && (
                <Button onClick={handleSubmit} disabled={!state.acknowledgement} className="w-full sm:w-auto justify-center">
                    Complete Order
                </Button>
              )}
            </div>
          </div>
      )}

      {isAdminEditing && (
        <div className="mt-8 pt-6 border-t border-slate-200 flex justify-between items-center no-print">
            <div>
                {currentStepIndex > 0 && (
                    <Button variant="secondary" onClick={prevStep}>Back</Button>
                )}
            </div>

            {!isLastStep && (
                <Button onClick={nextStep}>Next</Button>
            )}
        </div>
      )}

    </Card>
  );
};

export default ServiceForm;

import React, { useMemo, useEffect, useRef, useState } from 'react';
import { Service, ServiceStatus, User, ServiceTemplate, ProfitLoss } from '../../types';
import Card from '../ui/Card';
import Button from '../ui/Button';
import { IconChartBar, IconClipboardList, IconReceipt, IconUsers, IconFileAnalytics, IconTable, IconCreditCard } from '../ui/Icon';
import Input from '../ui/Input';
import ExportReportModal, { ReportType, DataScope, FileFormat, PDFReportType } from './ExportReportModal';
import DataTableReport from './DataTableReport';

// Declare Chart.js, jspdf, and xlsx from CDN
declare const Chart: any;
declare const jspdf: any;
declare const XLSX: any;

interface AnalyticsPageProps {
  submissions: Service[];
  users: Omit<User, 'password'>[];
  serviceTemplates: ServiceTemplate[];
  profitLossData: ProfitLoss[];
}

// A new, styled StatCard component specific for this page
const StatCard: React.FC<{ title: string; value: string; icon: React.ReactNode; iconBg: string; subtext?: string }> = ({ title, value, icon, iconBg, subtext }) => (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center space-x-4">
        <div className={`p-3 rounded-full ${iconBg}`}>
            {icon}
        </div>
        <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">{title}</p>
            <p className="text-2xl font-bold text-slate-800">{value}</p>
            {subtext && <p className="text-xs text-slate-400 mt-1">{subtext}</p>}
        </div>
    </div>
);

const ChartComponent: React.FC<{ type: 'bar' | 'line' | 'doughnut' | 'pie', data: any, options: any, title: string }> = ({ type, data, options, title }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const chartInstanceRef = useRef<any>(null);

    useEffect(() => {
        if (!canvasRef.current || typeof Chart === 'undefined') return;
        const ctx = canvasRef.current.getContext('2d');
        if (!ctx) return;

        if (chartInstanceRef.current) {
            chartInstanceRef.current.destroy();
        }

        chartInstanceRef.current = new Chart(ctx, { type, data, options });

        return () => {
            if (chartInstanceRef.current) {
                chartInstanceRef.current.destroy();
            }
        };
    }, [type, data, options]);

    return (
      <Card title={title}>
        <canvas ref={canvasRef}></canvas>
      </Card>
    );
};

export const AnalyticsPage: React.FC<AnalyticsPageProps> = ({ submissions, users, serviceTemplates, profitLossData }) => {
    const today = new Date().toISOString().split('T')[0];
    const thirtyDaysAgo = new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0];

    const [filters, setFilters] = useState({
        startDate: thirtyDaysAgo,
        endDate: today,
        user: '',
        serviceType: ''
    });
    const [view, setView] = useState<'dashboard' | 'table'>('dashboard');
    const [isExportModalOpen, setIsExportModalOpen] = useState(false);
    const [isExporting, setIsExporting] = useState(false);

    const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFilters(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const filteredSubmissions = useMemo(() => {
        const completed = submissions.filter(s => s.status === ServiceStatus.Completed);

        const startDate = filters.startDate ? new Date(filters.startDate) : null;
        if(startDate) startDate.setHours(0,0,0,0);

        const endDate = filters.endDate ? new Date(filters.endDate) : null;
        if(endDate) endDate.setHours(23,59,59,999);

        return completed.filter(s => {
            const serviceDate = new Date(s.timestamp);
            const matchesDate = (!startDate || serviceDate >= startDate) && (!endDate || serviceDate <= endDate);
            const matchesUser = !filters.user || s.assignedTo === filters.user;
            const matchesService = !filters.serviceType || s.serviceSelection.includes(filters.serviceType);
            return matchesDate && matchesUser && matchesService;
        });
    }, [submissions, filters]);

    const kpiData = useMemo(() => {
        let totalRevenue = 0;
        let totalCost = 0;

        filteredSubmissions.forEach(s => {
            totalRevenue += s.grandTotal;
            // SAFEGUARD: Ensure profitLossData is an array
            const pl = (profitLossData || []).find(p => p.serviceId === s.submissionId);
            if (pl) {
                totalCost += (pl.materialCost || 0) + (pl.laborCost || 0) + (pl.otherExpenses || 0);
            }
        });

        const netProfit = totalRevenue - totalCost;
        const profitMargin = totalRevenue > 0 ? (netProfit / totalRevenue) * 100 : 0;
        const completedServices = filteredSubmissions.length;
        const avgRevenue = completedServices > 0 ? totalRevenue / completedServices : 0;

        const customerFirstServiceMap = new Map<string, string>();
        submissions.forEach(s => {
            if(s.status === ServiceStatus.Completed) {
                const existing = customerFirstServiceMap.get(s.mobileNumber);
                if (!existing || s.timestamp < existing) {
                    customerFirstServiceMap.set(s.mobileNumber, s.timestamp);
                }
            }
        });

        const newCustomers = new Set<string>();
        filteredSubmissions.forEach(s => {
            if(customerFirstServiceMap.get(s.mobileNumber) === s.timestamp) {
                newCustomers.add(s.mobileNumber);
            }
        });

        return {
            totalRevenue,
            totalCost,
            netProfit,
            profitMargin,
            completedServices,
            avgRevenue,
            newCustomers: newCustomers.size,
        };
    }, [filteredSubmissions, submissions, profitLossData]);

    const financialOverviewData = useMemo(() => {
         return {
            labels: ['Revenue', 'Costs', 'Net Profit'],
            datasets: [{
                label: 'Amount (₹)',
                data: [kpiData.totalRevenue, kpiData.totalCost, kpiData.netProfit],
                backgroundColor: ['#3b82f6', '#ef4444', '#10b981'],
            }]
        };
    }, [kpiData]);

    const revenueTrendData = useMemo(() => {
        const dataByDate: { [key: string]: number } = {};
        filteredSubmissions.forEach(s => {
            const date = s.timestamp.split('T')[0];
            dataByDate[date] = (dataByDate[date] || 0) + s.grandTotal;
        });

        const sortedDates = Object.keys(dataByDate).sort();
        return {
            labels: sortedDates.map(d => new Date(d).toLocaleDateString('en-IN', { month: 'short', day: 'numeric'})),
            datasets: [{
                label: 'Daily Revenue',
                data: sortedDates.map(d => dataByDate[d]),
                borderColor: '#0D2A4F',
                backgroundColor: 'rgba(13, 42, 79, 0.1)',
                fill: true,
                tension: 0.3
            }]
        };
    }, [filteredSubmissions]);

    const servicePopularityData = useMemo(() => {
        const counts = new Map<string, number>();
        filteredSubmissions.forEach(s => {
            s.serviceSelection.forEach(serviceName => {
                let key = serviceName;
                if (serviceName === 'Car Washing' && s.carWashDetails?.washType) {
                    key = `Wash: ${s.carWashDetails.washType}`;
                } else if (serviceName === 'Car Care' && s.carCareDetails?.careType) {
                    key = `Care: ${s.carCareDetails.careType}`;
                }
                counts.set(key, (counts.get(key) || 0) + 1);
            });
        });
        const sorted = [...counts.entries()].sort((a,b) => b[1] - a[1]);
        return {
            labels: sorted.map(s => s[0]),
            datasets: [{
                label: 'Number of Times Performed',
                data: sorted.map(s => s[1]),
                backgroundColor: '#f8bf2a'
            }]
        };
    }, [filteredSubmissions]);

    const serviceRevenueData = useMemo(() => {
        const revenue = {
            'Car Washing': 0,
            'Car Care': 0,
            'Tyre Replacement': 0,
            'Battery Replacement': 0,
            'Add-ons': 0,
            'Custom Services': 0
        };

        filteredSubmissions.forEach(s => {
            if (s.carWashDetails) revenue['Car Washing'] += (s.carWashDetails.price || 0);
            if (s.carCareDetails) revenue['Car Care'] += (s.carCareDetails.price || 0);
            revenue['Tyre Replacement'] += (s.tyreReplacementTotalAmount || 0);
            revenue['Battery Replacement'] += (s.batteryReplacementTotalAmount || 0);
            revenue['Add-ons'] += (s.addonsTotal || 0);
            revenue['Custom Services'] += (s.customServicesTotal || 0);
        });

        return {
            labels: Object.keys(revenue),
            datasets: [{
                label: 'Revenue',
                data: Object.values(revenue),
                backgroundColor: ['#3b82f6', '#8b5cf6', '#f97316', '#ef4444', '#10b981', '#64748b']
            }]
        };
    }, [filteredSubmissions]);

    const agentPerformanceData = useMemo(() => {
        const performance = new Map<string, { revenue: number, count: number }>();
        filteredSubmissions.forEach(s => {
            const agent = s.assignedTo || 'Unassigned';
            const current = performance.get(agent) || { revenue: 0, count: 0 };
            current.revenue += s.grandTotal;
            current.count++;
            performance.set(agent, current);
        });
        const sorted = [...performance.entries()].sort((a,b) => b[1].revenue - a[1].revenue);
        return {
            labels: sorted.map(p => p[0]),
            datasets: [{
                label: 'Total Revenue',
                data: sorted.map(p => p[1].revenue),
                backgroundColor: '#0D2A4F'
            }]
        };
    }, [filteredSubmissions]);

    const handleExport = async (fileFormat: FileFormat, reportType: ReportType, dataScope: DataScope, pdfReportType: PDFReportType) => {
        setIsExporting(true);
        await new Promise(res => setTimeout(res, 50)); // UI update delay

        const dataToExport = dataScope === 'full' 
            ? submissions.filter(s => s.status === ServiceStatus.Completed) 
            : filteredSubmissions;

        if (!dataToExport || dataToExport.length === 0) {
            alert("No data available to export based on your current selection.");
            setIsExporting(false);
            setIsExportModalOpen(false);
            return;
        }

        const fileName = `report_${new Date().toISOString().split('T')[0]}`;

        if (fileFormat === 'csv') { // 'csv' option in modal actually generates XLSX for multi-sheet support
            try {
                if (typeof XLSX === 'undefined') throw new Error("Excel export library (SheetJS) is not available. Please check your internet connection.");

                const wb = XLSX.utils.book_new();

                const flattenService = (s: Service) => {
                    // SAFEGUARD: Ensure profitLossData is an array
                    const pl = (profitLossData || []).find(p => p.serviceId === s.submissionId);
                    const totalCost = pl ? (pl.materialCost + pl.laborCost + pl.otherExpenses) : 0;
                    const netProfit = s.grandTotal - totalCost;

                    const selectionArray = Array.isArray(s.serviceSelection) ? s.serviceSelection : [];
                    const serviceList = selectionArray.map(sel => {
                        if (sel === 'Car Washing') return `Car Washing (${s.carWashDetails?.washType || 'N/A'})`;
                        if (sel === 'Car Care') return `Car Care (${s.carCareDetails?.careType || 'N/A'})`;
                        return sel;
                    }).join(', ');

                    return {
                        'Order ID': s.appointmentId?.split('-').pop() || '',
                        'Date': new Date(s.timestamp).toLocaleString('en-IN'),
                        'Customer Name': `${s.customerFirstName} ${s.customerLastName}`,
                        'Mobile': s.mobileNumber || '',
                        'Car Brand & Model': s.carBrandModel || '',
                        'Car Number': s.carNumber || '',
                        'Services': serviceList,
                        'Assigned Agent': s.assignedTo || 'Unassigned',
                        'Status': s.status,
                        'Car Wash Type': s.carWashDetails?.washType || '-',
                        'Car Wash Price': s.carWashDetails ? (s.carWashDetails.price || 0) : 0,
                        'Car Care Type': s.carCareDetails?.careType || '-',
                        'Car Care Price': s.carCareDetails ? (s.carCareDetails.price || 0) : 0,
                        'Tyre Qty': s.tyreReplacementQuantity || 0,
                        'Tyre Total': s.tyreReplacementTotalAmount || 0,
                        'Battery Qty': s.batteryReplacementQuantity || 0,
                        'Battery Total': s.batteryReplacementTotalAmount || 0,
                        'Addons': [
                            ...(s.dynamicAddons || []).map(a => `${a.name} (x${a.quantity})`),
                            ...(s.categorizedAddons || []).map(a => `${a.productName} (x${a.quantity})`)
                        ].join('; ') || '-',
                        'Custom Services Total': s.customServicesTotal || 0,
                        'Grand Total': s.grandTotal || 0,
                        'Total Cost': totalCost || 0,
                        'Net Profit': netProfit || 0
                    };
                };

                if (reportType === 'summary') {
                    const wsData = dataToExport.map(flattenService);
                    const ws = XLSX.utils.json_to_sheet(wsData);
                    XLSX.utils.book_append_sheet(wb, ws, "Summary Report");
                } else if (reportType === 'agent') {
                    const dataByAgent: Record<string, Service[]> = {};
                    dataToExport.forEach(s => {
                        const agent = s.assignedTo || 'Unassigned';
                        if (!dataByAgent[agent]) dataByAgent[agent] = [];
                        dataByAgent[agent].push(s);
                    });
                    for (const agent in dataByAgent) {
                        const wsData = dataByAgent[agent].map(flattenService);
                        const ws = XLSX.utils.json_to_sheet(wsData);
                        // Sheet names are limited to 31 chars
                        const sheetName = agent.replace(/[\\/*?[\]:]/g, "").substring(0, 31) || "Agent";
                        XLSX.utils.book_append_sheet(wb, ws, sheetName);
                    }
                } else if (reportType === 'service') {
                     const dataByService: Record<string, Service[]> = {};
                     dataToExport.forEach(s => {
                        const selectionArray = Array.isArray(s.serviceSelection) ? s.serviceSelection : [];
                        selectionArray.forEach(serviceName => {
                            if (!dataByService[serviceName]) dataByService[serviceName] = [];
                            dataByService[serviceName].push(s);
                        });
                     });
                     for (const serviceName in dataByService) {
                        const wsData = dataByService[serviceName].map(flattenService);
                        const ws = XLSX.utils.json_to_sheet(wsData);
                        const sheetName = serviceName.replace(/[\\/*?[\]:]/g, "").substring(0, 31) || "Service";
                        XLSX.utils.book_append_sheet(wb, ws, sheetName);
                     }
                }

                XLSX.writeFile(wb, `${fileName}_${reportType}.xlsx`);

            } catch (error) {
                console.error("Export failed:", error);
                alert(`Could not generate export file. ${error instanceof Error ? error.message : 'Unknown error'}`);
            }
        } else if (fileFormat === 'pdf') {
            try {
                if (typeof jspdf === 'undefined' || typeof (jspdf as any).jsPDF === 'undefined') {
                     throw new Error("PDF export library (jsPDF) is not available.");
                }
                const doc = new (jspdf as any).jsPDF();

                const addHeaderFooter = (title: string) => {
                    const pageCount = doc.internal.getNumberOfPages();
                    for (let i = 1; i <= pageCount; i++) {
                        doc.setPage(i);
                        doc.setFontSize(16);
                        doc.setTextColor(40);
                        doc.text('A Big Engine - Analytics Report', 15, 15);
                        doc.setFontSize(12);
                        doc.setTextColor(100);
                        doc.text(title, 15, 22);
                        doc.setFontSize(10);
                        doc.text(`Page ${i} of ${pageCount}`, doc.internal.pageSize.width - 25, doc.internal.pageSize.height - 10);
                        doc.text(`Generated on: ${new Date().toLocaleDateString()}`, 15, doc.internal.pageSize.height - 10);
                    }
                };

                if (pdfReportType === 'performance') {
                    const head = [['Agent', 'Revenue (INR)', 'Services Completed']];
                    const body = agentPerformanceData.labels.map((agent) => [
                        agent,
                        `₹${(agentPerformanceData.datasets[0].data[agentPerformanceData.labels.indexOf(agent)] || 0).toLocaleString('en-IN')}`,
                        filteredSubmissions.filter(s => (s.assignedTo || 'Unassigned') === agent).length
                    ]);
                    (doc as any).autoTable({ head, body, startY: 30 });
                    addHeaderFooter('Agent Performance Report');
                } else if (pdfReportType === 'services') {
                     const head = [['Service Type', 'Times Performed']];
                     const body = servicePopularityData.labels.map((service, index) => [
                        service,
                        servicePopularityData.datasets[0].data[index]
                     ]);
                     (doc as any).autoTable({ head, body, startY: 30 });
                     addHeaderFooter('Service Popularity Report');
                } else if (pdfReportType === 'revenue') {
                     const head = [['Date', 'Revenue (INR)']];
                     const body = revenueTrendData.labels.map((date, index) => [
                        date,
                        `₹${(revenueTrendData.datasets[0].data[index] || 0).toLocaleString('en-IN')}`
                     ]);
                     (doc as any).autoTable({ head, body, startY: 30 });
                     addHeaderFooter('Daily Revenue Report');
                }

                doc.save(`${fileName}_${pdfReportType}.pdf`);

            } catch (error) {
                console.error("PDF Export failed:", error);
                alert(`Could not generate PDF file. ${error instanceof Error ? error.message : 'Unknown error'}`);
            }
        }

        setIsExporting(false);
        setIsExportModalOpen(false);
    };


    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4">
                 <h1 className="text-3xl font-bold text-slate-800 tracking-tight">Analytics & Reports</h1>
                 <div className="flex items-center gap-2">
                    <div className="flex rounded-md shadow-sm">
                        <button onClick={() => setView('dashboard')} className={`px-4 py-2 text-sm font-medium rounded-l-md transition-colors flex items-center gap-2 ${view === 'dashboard' ? 'bg-brand-blue text-white z-10' : 'bg-white text-slate-700 hover:bg-slate-50 border'}`}>
                            <IconChartBar className="w-5 h-5" />
                            Dashboard
                        </button>
                        <button onClick={() => setView('table')} className={`-ml-px px-4 py-2 text-sm font-medium rounded-r-md transition-colors flex items-center gap-2 ${view === 'table' ? 'bg-brand-blue text-white z-10' : 'bg-white text-slate-700 hover:bg-slate-50 border'}`}>
                            <IconTable className="w-5 h-5" />
                            Data Table
                        </button>
                    </div>
                    <Button onClick={() => setIsExportModalOpen(true)}>
                        <IconFileAnalytics className="w-5 h-5 mr-2"/>
                        Export Report
                    </Button>
                </div>
            </div>

            <Card title="Filters">
                 <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                    <Input label="From Date" name="startDate" type="date" value={filters.startDate} onChange={handleFilterChange} />
                    <Input label="To Date" name="endDate" type="date" value={filters.endDate} onChange={handleFilterChange} />
                    <div>
                        <label htmlFor="user" className="block text-sm font-medium text-slate-700 mb-1">Agent</label>
                        <select id="user" name="user" value={filters.user} onChange={handleFilterChange} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm">
                            <option value="">All Agents</option>
                            {users.map(u => <option key={u.username} value={u.username}>{u.username}</option>)}
                        </select>
                    </div>
                     <div>
                        <label htmlFor="serviceType" className="block text-sm font-medium text-slate-700 mb-1">Service Type</label>
                        <select id="serviceType" name="serviceType" value={filters.serviceType} onChange={handleFilterChange} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm">
                            <option value="">All Services</option>
                            {serviceTemplates.map(t => <option key={t.id} value={t.name}>{t.name}</option>)}
                        </select>
                    </div>
                </div>
            </Card>

            {view === 'dashboard' ? (
                <>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                        <StatCard title="Total Revenue" value={`₹${kpiData.totalRevenue.toLocaleString('en-IN')}`} icon={<IconReceipt className="w-6 h-6 text-green-600"/>} iconBg="bg-green-100" />
                        <StatCard title="Total Cost" value={`₹${kpiData.totalCost.toLocaleString('en-IN')}`} icon={<IconCreditCard className="w-6 h-6 text-red-600"/>} iconBg="bg-red-100" />
                        <StatCard title="Net Profit" value={`₹${kpiData.netProfit.toLocaleString('en-IN')}`} icon={<IconChartBar className="w-6 h-6 text-blue-600"/>} iconBg="bg-blue-100" subtext={`Margin: ${kpiData.profitMargin.toFixed(1)}%`} />
                        <StatCard title="Completed Services" value={kpiData.completedServices.toString()} icon={<IconClipboardList className="w-6 h-6 text-blue-600"/>} iconBg="bg-blue-100" />
                        <StatCard title="Avg. Revenue" value={`₹${kpiData.avgRevenue.toLocaleString('en-IN', { maximumFractionDigits: 0 })}`} icon={<IconChartBar className="w-6 h-6 text-purple-600"/>} iconBg="bg-purple-100" />
                        <StatCard title="New Customers" value={kpiData.newCustomers.toString()} icon={<IconUsers className="w-6 h-6 text-amber-600"/>} iconBg="bg-amber-100" />
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        <ChartComponent type="bar" data={financialOverviewData} options={{ responsive: true, plugins: { legend: { display: false }}}} title="Financial Overview (Rev/Cost/Profit)" />
                        <ChartComponent type="line" data={revenueTrendData} options={{ responsive: true, plugins: { legend: { display: false }}}} title="Revenue Trend" />
                    </div>
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                         <ChartComponent type="doughnut" data={serviceRevenueData} options={{ responsive: true, plugins: { legend: { position: 'right' }}}} title="Revenue by Category" />
                         <ChartComponent type="bar" data={agentPerformanceData} options={{ responsive: true, plugins: { legend: { display: false }}}} title="Agent Performance (by Revenue)" />
                         <ChartComponent type="bar" data={servicePopularityData} options={{ responsive: true, plugins: { legend: { display: false }}}} title="Service Popularity (Detailed)" />
                    </div>
                </>
            ) : (
                <DataTableReport submissions={filteredSubmissions} profitLossData={profitLossData} />
            )}

            <ExportReportModal 
                isOpen={isExportModalOpen}
                onClose={() => setIsExportModalOpen(false)}
                onExport={handleExport}
                isExporting={isExporting}
            />
        </div>
    );
};

import React from 'react';
import { Service, ProfitLoss } from '../../types';
import Card from '../ui/Card';

interface DataTableReportProps {
  submissions: Service[];
  profitLossData?: ProfitLoss[];
}

const DataTableReport: React.FC<DataTableReportProps> = ({ submissions, profitLossData = [] }) => {
  if (submissions.length === 0) {
    return (
      <Card>
        <p className="text-center text-slate-500 py-8">No data available for the selected filters.</p>
      </Card>
    );
  }

  // Flatten data for table view
  const flattenedData = submissions.map(s => {
    const addonsSummary = [
      ...(s.dynamicAddons || []).map(a => `${a.name} (x${a.quantity})`),
      ...(s.categorizedAddons || []).map(a => `${a.productName} (x${a.quantity})`),
    ].join('; ');

    const serviceList = s.serviceSelection.map(sel => {
        if (sel === 'Car Washing') return `Car Washing (${s.carWashDetails?.washType || 'N/A'})`;
        if (sel === 'Car Care') return `Car Care (${s.carCareDetails?.careType || 'N/A'})`;
        return sel;
    }).join(', ');

    // Profit Calculation
    // SAFEGUARD: Ensure profitLossData is an array
    const pl = (profitLossData || []).find(p => p.serviceId === s.submissionId);
    const totalCost = pl ? (pl.materialCost + pl.laborCost + pl.otherExpenses) : 0;
    const netProfit = s.grandTotal - totalCost;

    return {
      'Order ID': s.appointmentId?.split('-').pop() || '',
      'Date': new Date(s.timestamp).toLocaleString('en-IN'),
      'Customer Name': `${s.customerFirstName} ${s.customerLastName}`,
      'Mobile': s.mobileNumber,
      'Car Brand & Model': s.carBrandModel,
      'Car Number': s.carNumber,
      'Services': serviceList,
      'Assigned Agent': s.assignedTo || 'N/A',
      'Status': s.status,
      'Car Wash Type': s.carWashDetails?.washType || '-',
      'Car Wash Price': s.carWashDetails ? `₹${s.carWashDetails.price.toFixed(2)}` : '-',
      'Car Care Type': s.carCareDetails?.careType || '-',
      'Car Care Price': s.carCareDetails ? `₹${s.carCareDetails.price.toFixed(2)}` : '-',
      'Tyre Qty': s.tyreReplacementQuantity || 0,
      'Tyre Total': `₹${s.tyreReplacementTotalAmount.toFixed(2)}`,
      'Battery Qty': s.batteryReplacementQuantity || 0,
      'Battery Total': `₹${s.batteryReplacementTotalAmount.toFixed(2)}`,
      'Addons': addonsSummary || '-',
      'Custom Services Total': `₹${s.customServicesTotal.toFixed(2)}`,
      'Grand Total': `₹${s.grandTotal.toFixed(2)}`,
      'Total Cost': `₹${totalCost.toFixed(2)}`,
      'Net Profit': `₹${netProfit.toFixed(2)}`
    };
  });

  const headers = Object.keys(flattenedData[0]);

  return (
    <Card>
      <div className="overflow-x-auto relative border border-slate-200 rounded-lg" style={{ maxHeight: '70vh' }}>
        <table className="min-w-full text-sm text-left text-slate-500">
          <thead className="text-xs text-slate-700 uppercase bg-slate-100 sticky top-0 z-10">
            <tr>
              {headers.map(header => (
                <th key={header} scope="col" className="px-6 py-3 whitespace-nowrap">
                  {header}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="bg-white">
            {flattenedData.map((row, rowIndex) => (
              <tr key={rowIndex} className="border-b hover:bg-slate-50">
                {headers.map(header => {
                  const val = row[header as keyof typeof row];
                  let className = "px-6 py-4 whitespace-nowrap";
                  if (header === 'Net Profit') {
                      const num = parseFloat(String(val).replace('₹', ''));
                      className += num >= 0 ? " text-green-600 font-bold" : " text-red-600 font-bold";
                  }
                  return (
                    <td key={header} className={className}>
                        {val}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Card>
  );
};

