                     const message = `Reminder: Service for ${service.customerFirstName} is due in 30 minutes.`;
                     const notif: AppNotification = {
                        id: `notif_rem30_${service.submissionId}`, userId: service.assignedTo!, serviceId: service.submissionId, message,
                        timestamp: new Date().toISOString(), isRead: false, type: 'reminder-30min'
                    };
                    newNotifications.push(notif);
                    if(prefs.enabled.reminder) {
                        playNotificationAlert(prefs);
                        if (targetUser.pushSubscription) sendPushNotification(targetUser.pushSubscription, "Upcoming Service", message, prefs);
                    }
                }
            } else {
                // --- OVERDUE REMINDER LOGIC ---
                const minutesSince = (now.getTime() - scheduledDateTime.getTime()) / 60000;

                if (minutesSince > 60) { // Over 1 hour late
                    const lastOverdueNotification = notifications
                        .filter(n => n.serviceId === service.submissionId && n.type === 'overdue-alert')
                        .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())[0];

                    let shouldSend = true;
                    if (lastOverdueNotification) {
                        const minutesSinceLastAlert = (now.getTime() - new Date(lastOverdueNotification.timestamp).getTime()) / 60000;
                        if (minutesSinceLastAlert < 60) { // Don't send more than once per hour
                            shouldSend = false;
                        }
                    }

                    if (shouldSend) {
                        const message = `OVERDUE: Service for ${service.customerFirstName} is more than 1 hour past its scheduled time.`;
                        const usersToNotify = users.filter(u => u.username === service.assignedTo || u.role === 'admin' || u.role === 'manager');

                        usersToNotify.forEach(user => {
