// Helper function to ensure notification preferences are always complete and valid.
const mergeWithDefaultPrefs = (prefs?: Partial<NotificationPreferences>): NotificationPreferences => {
    // Perform a deep merge to ensure the nested `enabled` object is also handled correctly.
    return {
        ...defaultNotificationPrefs,
        ...(prefs || {}), // Overwrite top-level keys like sound, vibration
        enabled: {
            ...defaultNotificationPrefs.enabled,
            ...(prefs?.enabled || {}), // Overwrite specific enabled/disabled keys
        }
    };
};

const mergeSubmissions = (cloudSubs: Service[], localSubs: Service[]): Service[] => {
    const submissionMap = new Map<string, Service>();

    // Cloud submissions are the baseline
    for (const sub of cloudSubs) {
        submissionMap.set(sub.submissionId, sub);
    }

    // Local submissions can override if they are newer, or add if they don't exist
    for (const sub of localSubs) {
        const existing = submissionMap.get(sub.submissionId);
        // A local draft will always be kept. A submitted local item will overwrite a cloud one if it's newer.
        if (!existing || new Date(sub.timestamp) > new Date(existing.timestamp)) {
            submissionMap.set(sub.submissionId, sub);
        }
    }
    return Array.from(submissionMap.values());
};

const cleanSubmissionsArray = (submissions: Service[]): Service[] => {
    return submissions.map(sub => {
        const cleanedSub = {...sub};
        let finalStatus = cleanedSub.status;
        const validStatuses = Object.values(ServiceStatus);

        // Data migration for legacy statuses
        if ((finalStatus as any) === 'Submitted') finalStatus = ServiceStatus.Completed;
        else if ((finalStatus as any) === 'Order Created') finalStatus = ServiceStatus.Queued;

        // Self-healing for invalid or missing status
        if (!finalStatus || !validStatuses.includes(finalStatus as ServiceStatus)) {
            finalStatus = ServiceStatus.Queued;
        }

        // --- DATA MIGRATION for legacy Add-ons ---
        if ((cleanedSub as any).predefinedAddonQuantities && !cleanedSub.dynamicAddons) {
            // This is an old record. We'll move old addons to categorizedAddons
            // to preserve the data without breaking the new UI.
            cleanedSub.categorizedAddons = cleanedSub.categorizedAddons || [];
            // Note: This requires an old copy of addons data, which is complex to handle here.
            // For now, we will just ensure the new field exists.
            // A more robust migration would look up old addon names/prices.
            cleanedSub.dynamicAddons = []; 
            delete (cleanedSub as any).predefinedAddonQuantities;
        }

        // --- DATA MIGRATION for Car Wash ---
        if (cleanedSub.carwashTotalAmount && !cleanedSub.carWashDetails) {
            cleanedSub.vehicleCategoryTag = getCategoryForVehicle(cleanedSub.carBrandModel);
            cleanedSub.carWashDetails = {
                washType: 'Basic Wash', // Assumption for legacy data
                price: robustParseFloat(cleanedSub.carwashTotalAmount),
                mrp: robustParseFloat(cleanedSub.carwashTotalAmount) * 1.5,
            };
        }
        delete cleanedSub.carwashQuantity;
        delete cleanedSub.carWashPrice;
        delete cleanedSub.carwashTotalAmount;

        // --- DATA MIGRATION for Car Care ---
        if (cleanedSub.carCareTotalAmount && !cleanedSub.carCareDetails) {
            cleanedSub.carCareDetails = {
                careType: 'Legacy Package', // Assumption for legacy data
                price: robustParseFloat(cleanedSub.carCareTotalAmount),
                mrp: robustParseFloat(cleanedSub.carCareTotalAmount) * 1.5,
            };
        }
        delete cleanedSub.carCareSelection;
        delete cleanedSub.carCareTotalAmount;


        return {
            ...cleanedSub,
            status: finalStatus,
            dynamicAddons: cleanedSub.dynamicAddons || [],
            customFieldData: cleanedSub.customFieldData || [],
            dependsOn: cleanedSub.dependsOn || [],
            grandTotal: robustParseFloat(cleanedSub.grandTotal),
            tyreReplacementTotalAmount: robustParseFloat(cleanedSub.tyreReplacementTotalAmount),
            tyreReplacementPrice: robustParseFloat(cleanedSub.tyreReplacementPrice),
            tyreReplacementQuantity: robustParseInt(cleanedSub.tyreReplacementQuantity),
            batteryReplacementTotalAmount: robustParseFloat(cleanedSub.batteryReplacementTotalAmount),
            batteryReplacementQuantity: robustParseInt(cleanedSub.batteryReplacementQuantity),
            addonsTotal: robustParseFloat(cleanedSub.addonsTotal),
            categorizedAddonsTotal: robustParseFloat(cleanedSub.categorizedAddonsTotal),
            customServicesTotal: robustParseFloat(cleanedSub.customServicesTotal),
            batteryDetails: (cleanedSub.batteryDetails || []).map(bd => ({
                ...bd,
                exchangeValue: robustParseFloat(bd.exchangeValue),
                newBatteryAmount: robustParseFloat(bd.newBatteryAmount),
            })),
            customServices: (cleanedSub.customServices || []).map(cs => ({
                ...cs,
                amount: robustParseFloat(cs.amount),
            })),
            categorizedAddons: (cleanedSub.categorizedAddons || []).map(ca => ({
                ...ca,
                quantity: robustParseInt(ca.quantity),
                amount: robustParseFloat(ca.amount),
            })),
            internalNotes: cleanedSub.internalNotes || '',
            isFollowUp: cleanedSub.isFollowUp || false,
            appointmentId: cleanedSub.appointmentId || cleanedSub.submissionId
        };
    });
};

const sendPushNotification = async (subscription: PushSubscriptionJSON, title: string, body: string, prefs: NotificationPreferences) => {
    try {
        const payload = {
            title,
            body,
            vibrate: prefs.vibration ? [200, 100, 200] : undefined,
            silent: prefs.sound === 'none',
        };

        await fetch('/.netlify/functions/trigger-push', {
            method: 'POST',
            body: JSON.stringify({ subscription, payload }),
            headers: { 'Content-Type': 'application/json' },
        });
    } catch (error) {
        console.error('Error sending push notification:', error);
    }
};

const playNotificationAlert = (prefs: NotificationPreferences | undefined) => {
    if(!prefs) return;
    notificationService.playNotificationAlert(prefs);
}

const parseServiceDateTime = (service: Service): Date | null => {
    if (!service.scheduledDate || !service.scheduledTime) return null;
    try {
        const timePart = service.scheduledTime.split(' - ')[0]; // e.g., "09:00"
        const [hour, minute] = timePart.split(':').map(Number);
        const d = new Date(service.scheduledDate);
        const localDate = new Date(d.getFullYear(), d.getMonth(), d.getDate(), hour, minute);

        return isNaN(localDate.getTime()) ? null : localDate;
    } catch (e) {
        console.error("Error parsing date/time for service:", service.submissionId, e);
        return null;
    }
};

const sendCustomerEmailNotification = async (service: Service) => {
    if (!service.customerEmail) {
        console.log(`Skipping email for service ${service.submissionId}: no customer email.`);
        return;
    }

    if (service.status !== ServiceStatus.InProgress && service.status !== ServiceStatus.Completed) {
        return; // Only send for these statuses
    }

    try {
        console.log(`Sending ${service.status} email to ${service.customerEmail}`);
        const response = await fetch('/.netlify/functions/send-email', {
            method: 'POST',
            body: JSON.stringify({ service }),
            headers: { 'Content-Type': 'application/json' },
        });

        if (!response.ok) {
            const errorData = await response.json();
            throw new Error(errorData.error || 'Failed to send email.');
        }

        const result = await response.json();
        console.log('Email notification result:', result.message);
    } catch (error) {
        console.error('Error sending customer email notification:', error);
    }
};

