            }
            if (!finalUser.permissions || finalUser.permissions.length === 0) {
                 finalUser.permissions = authService.getDefaultPermissionsForRole(finalUser.role);
            }
            return finalUser;
        });

        if (usersWithDefaults.length === 0) {
