                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </Card>
                ))}
                {Object.keys(completedServicesByDate).length === 0 && (
                    <Card>
                        <p className="text-center text-slate-500 py-10">No completed services found to track profit/loss.</p>
                    </Card>
                )}
            </div>
        </div>
    );
};

