import { useReducer, useMemo, useCallback, useEffect } from 'react';
import { Service, ServiceStatus, TyreDetail, BatteryDetail, CustomService, CategorizedAddon, VehicleCategoryTag, DynamicAddon, PricingConfig } from '../types';
import { SERVICE_PRICES, ADDON_CATEGORIES, DEFAULT_WASH_PRICING_MATRIX, DEFAULT_CAR_CARE_PRICING_MATRIX, DEFAULT_ADDON_PRICING_MATRIX, DEFAULT_PRICING_CONFIG } from '../constants';

type FormAction =
  | { type: 'UPDATE_FIELD'; field: keyof Service; value: any }
  | { type: 'SET_FORM_DATA'; payload: Service }
  | { type: 'ADD_TYRE_DETAIL' }
  | { type: 'REMOVE_TYRE_DETAIL'; index: number }
  | { type: 'UPDATE_TYRE_DETAIL'; index: number; field: keyof TyreDetail; value: any }
  | { type: 'ADD_BATTERY_DETAIL' }
  | { type: 'REMOVE_BATTERY_DETAIL'; index: number }
  | { type: 'UPDATE_BATTERY_DETAIL'; index: number; field: keyof BatteryDetail; value: any }
  | { type: 'ADD_CUSTOM_SERVICE' }
  | { type: 'REMOVE_CUSTOM_SERVICE'; index: number }
  | { type: 'UPDATE_CUSTOM_SERVICE'; index: number; field: keyof CustomService; value: any }
  | { type: 'ADD_CATEGORIZED_ADDON' }
  | { type: 'REMOVE_CATEGORIZED_ADDON'; index: number }
  | { type: 'UPDATE_CATEGORIZED_ADDON'; index: number; field: keyof CategorizedAddon; value: any }
  | { type: 'UPDATE_DYNAMIC_ADDON_QTY'; name: string; quantity: number }
  | { type: 'UPDATE_CUSTOM_FIELD_DATA'; fieldId: string; value: string | number };

const createInitialState = (initialService?: Service | null): Service => {
  if (initialService) return JSON.parse(JSON.stringify(initialService));

  const submissionId = `SUB-${Date.now()}`;
  return {
    submissionId,
    appointmentId: submissionId,
    timestamp: new Date().toISOString(),
    customerFirstName: '',
    customerLastName: '',
    streetAddress: '',
    mobileNumber: '',
    carNumber: '',
    carBrandModel: '',
    vehicleCategoryTag: VehicleCategoryTag.Hatch,
    serviceSelection: [],

    isSubscription: false,
    carWashDetails: undefined,
    carCareDetails: undefined,

    beforeWashingPhoto: '',
    beforeVideoInventory: '',
    beforeVideoTopBody: '',
    beforeVideoUnderchassis: '',
    afterWashingPhoto: '',
    afterVideoInterior: '',
    afterVideoExterior: '',
    afterVideoUnderchassis: '',

    tyreReplacementQuantity: 0,
    tyreReplacementPrice: SERVICE_PRICES.tyreReplacement,
    tyreReplacementTotalAmount: 0,
    tyreLaborCost: 0,
    tyreMaterialCost: 0,
    tyreDetails: [],

    batteryReplacementQuantity: 0,
    batteryReplacementTotalAmount: 0,
    batteryDetails: [],

    dynamicAddons: [],
    addonsTotal: 0,

    categorizedAddons: [],
    categorizedAddonsTotal: 0,

    customServices: [],
    customServicesTotal: 0,

    customFieldData: [],

    grandTotal: 0,
    acknowledgement: false,
    status: ServiceStatus.Draft,
    scheduledDate: undefined,
    scheduledTime: undefined,
    assignedTo: undefined,

    paymentMode: 'Cash',
    cashAmount: 0,
    onlineAmount: 0,
    paymentNotes: '',
  };
};

const formReducer = (state: Service, action: FormAction, pricingConfig?: PricingConfig): Service => {
  let nextState = state;

  switch (action.type) {
    case 'UPDATE_FIELD':
      nextState = { ...state, [action.field]: action.value };
      break;
    case 'SET_FORM_DATA':
      return action.payload; // Direct return, logic re-runs in effects
    case 'ADD_TYRE_DETAIL':
      nextState = { ...state, tyreDetails: [...state.tyreDetails, { tyreId: `T-${Date.now()}`, relatedServiceId: state.submissionId, dotCode: '', dotSerialNumberImage: '', tyreSize: '', brand: '', model: '' }] };
      break;
    case 'REMOVE_TYRE_DETAIL':
      nextState = { ...state, tyreDetails: state.tyreDetails.filter((_, i) => i !== action.index) };
      break;
    case 'UPDATE_TYRE_DETAIL':
      const newTyreDetails = state.tyreDetails.map((detail, i) => 
          i === action.index ? { ...detail, [action.field]: action.value } : detail
      );
      nextState = { ...state, tyreDetails: newTyreDetails };
      break;
    case 'ADD_BATTERY_DETAIL':
      nextState = { ...state, batteryDetails: [...state.batteryDetails, { batteryId: `B-${Date.now()}`, relatedServiceId: state.submissionId, serialNumber: '', brand: '', exchangeValue: 0, newBatteryAmount: 0 }] };
      break;
    case 'REMOVE_BATTERY_DETAIL':
      nextState = { ...state, batteryDetails: state.batteryDetails.filter((_, i) => i !== action.index) };
      break;
    case 'UPDATE_BATTERY_DETAIL':
      const newBatteryDetails = state.batteryDetails.map((detail, i) => 
          i === action.index ? { ...detail, [action.field]: action.value } : detail
      );
      nextState = { ...state, batteryDetails: newBatteryDetails };
      break;
    case 'ADD_CUSTOM_SERVICE':
      nextState = { ...state, customServices: [...state.customServices, { customServiceId: `CS-${Date.now()}`, relatedServiceId: state.submissionId, serviceDescription: '', amount: 0 }] };
      break;
    case 'REMOVE_CUSTOM_SERVICE':
      nextState = { ...state, customServices: state.customServices.filter((_, i) => i !== action.index) };
      break;
    case 'UPDATE_CUSTOM_SERVICE':
      const newCustomServices = state.customServices.map((service, i) =>
          i === action.index ? { ...service, [action.field]: action.value } : service
      );
      nextState = { ...state, customServices: newCustomServices };
      break;
    case 'ADD_CATEGORIZED_ADDON':
      nextState = { ...state, categorizedAddons: [...state.categorizedAddons, { id: `CA-${Date.now()}`, relatedServiceId: state.submissionId, category: ADDON_CATEGORIES[0], productName: '', quantity: 1, amount: 0 }] };
      break;
    case 'REMOVE_CATEGORIZED_ADDON':
      nextState = { ...state, categorizedAddons: state.categorizedAddons.filter((_, i) => i !== action.index) };
      break;
    case 'UPDATE_CATEGORIZED_ADDON':
      const newCategorizedAddons = state.categorizedAddons.map((addon, i) =>
          i === action.index ? { ...addon, [action.field]: action.value } : addon
      );
      nextState = { ...state, categorizedAddons: newCategorizedAddons };
      break;
    case 'UPDATE_DYNAMIC_ADDON_QTY':
      {
          const { name, quantity } = action;
          const category = state.vehicleCategoryTag;
          const currentAddons = state.dynamicAddons ? [...state.dynamicAddons] : [];

          let price = 0;
          let mrp = 0;

          // Use provided pricingConfig or fallback to constants
          if (pricingConfig && category) {
             const priceData = pricingConfig.addons[name]?.[category];
             price = priceData?.price || 0;
             mrp = priceData?.mrp || 0;
          } else if (category) {
             const priceData = DEFAULT_ADDON_PRICING_MATRIX[name as keyof typeof DEFAULT_ADDON_PRICING_MATRIX]?.[category];
             price = priceData?.price || 0;
             mrp = priceData?.mrp || 0;
          }

          const existingIndex = currentAddons.findIndex(item => item.name === name);

          if (quantity <= 0) {
              nextState = { ...state, dynamicAddons: currentAddons.filter(item => item.name !== name) };
          } else {
              if (existingIndex > -1) {
                  // Keep price if quantity changes but item is same, allowing override to persist if needed.
                  // BUT: If the vehicle category changed (handled in effect), we might need to reset.
                  // For simple qty updates, we re-fetch standard price unless we want to support price override there too.
                  // Current implementation: fetches standard price on qty change.
                  currentAddons[existingIndex] = { ...currentAddons[existingIndex], quantity, price, mrp };
              } else {
                  currentAddons.push({ name, quantity, price, mrp });
              }
              nextState = { ...state, dynamicAddons: currentAddons };
          }
      }
      break;
    case 'UPDATE_CUSTOM_FIELD_DATA':
        {
            const { fieldId, value } = action;
            const existingIndex = (state.customFieldData || []).findIndex(item => item.fieldId === fieldId);
            let newCustomData = [...(state.customFieldData || [])];

            if (value === '' || value === undefined) {
                newCustomData = newCustomData.filter(item => item.fieldId !== fieldId);
            } else if (existingIndex > -1) {
                newCustomData[existingIndex] = { ...newCustomData[existingIndex], value };
            } else {
                newCustomData.push({ fieldId, value });
            }
            nextState = { ...state, customFieldData: newCustomData };
        }
        break;
    default:
      return state;
  }
  return nextState;
};

const LOCAL_STORAGE_KEY = 'service_form_in_progress';

export const useServiceForm = (initialService: Service | null | undefined, pricingConfig: PricingConfig = DEFAULT_PRICING_CONFIG) => {

  const initializer = (initialValue?: Service | null): Service => {
    try {
      const savedFormJson = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (savedFormJson) {
        const savedFormState: Service = JSON.parse(savedFormJson);
        if (!initialValue || initialValue.submissionId === savedFormState.submissionId) {
          console.log("Restoring in-progress form from local storage.");
          return savedFormState;
        }
      }
    } catch (e) {
      console.error("Could not load form state from localStorage. Starting fresh.", e);
      localStorage.removeItem(LOCAL_STORAGE_KEY);
    }
    return createInitialState(initialValue);
  };

  const [state, dispatch] = useReducer((state: Service, action: FormAction) => formReducer(state, action, pricingConfig), initialService, initializer);

  useEffect(() => {
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(state));
    } catch (e) {
        console.warn("Failed to save form draft to local storage", e);
    }
  }, [state]);

  const updateField = useCallback(<K extends keyof Service>(field: K, value: Service[K]) => {
    dispatch({ type: 'UPDATE_FIELD', field, value });
  }, []);

  // Recalculate Car Wash totals
  useEffect(() => {
    const washType = state.carWashDetails?.washType;
    const category = state.vehicleCategoryTag;

    if (state.isSubscription && state.serviceSelection.includes('Car Washing')) {
        updateField('carWashDetails', { ...state.carWashDetails!, price: 0 });
    } else if (washType && category) {
        let price = 0;
        let mrp = 0;

        if (pricingConfig && pricingConfig.wash[washType]?.[category]) {
             price = pricingConfig.wash[washType][category].price;
             mrp = pricingConfig.wash[washType][category].mrp;
        } else if (DEFAULT_WASH_PRICING_MATRIX[washType as keyof typeof DEFAULT_WASH_PRICING_MATRIX]?.[category]) {
             price = DEFAULT_WASH_PRICING_MATRIX[washType as keyof typeof DEFAULT_WASH_PRICING_MATRIX][category].price;
             mrp = DEFAULT_WASH_PRICING_MATRIX[washType as keyof typeof DEFAULT_WASH_PRICING_MATRIX][category].mrp;
        }

        if (price !== undefined) {
             // Only auto-update if the price is different from current AND it wasn't manually overridden.
             // We can't easily detect manual override without complex state.
             // Strategy: We ALWAYS update when washType or Category changes.
             // The inputs in ServiceDetailsStep call updateField('carWashDetails', ...).
             // If updateField updates the whole object, this effect will re-run but since dependencies haven't changed, it won't overwrite?
             // Actually, `updateField` changes `state`.
             // If we change price manually, `state` changes. `washType` and `category` do NOT change.
             // So this effect will NOT re-run. Perfect.
             // BUT: If user changes category, this effect runs and overwrites the manual price. Correct behavior.
            updateField('carWashDetails', { washType, price, mrp });
        }
    }
  }, [state.carWashDetails?.washType, state.vehicleCategoryTag, state.isSubscription, state.serviceSelection, pricingConfig, updateField]);

  // Recalculate Car Care totals
  useEffect(() => {
    const careType = state.carCareDetails?.careType;
    const category = state.vehicleCategoryTag;

    if (careType && category) {
        let price = 0;
        let mrp = 0;

        if (pricingConfig && pricingConfig.carCare[careType]?.[category]) {
             price = pricingConfig.carCare[careType][category].price;
             mrp = pricingConfig.carCare[careType][category].mrp;
        } else if (DEFAULT_CAR_CARE_PRICING_MATRIX[careType as keyof typeof DEFAULT_CAR_CARE_PRICING_MATRIX]?.[category]) {
             price = DEFAULT_CAR_CARE_PRICING_MATRIX[careType as keyof typeof DEFAULT_CAR_CARE_PRICING_MATRIX][category].price;
             mrp = DEFAULT_CAR_CARE_PRICING_MATRIX[careType as keyof typeof DEFAULT_CAR_CARE_PRICING_MATRIX][category].mrp;
        }

        if (price !== undefined) {
            updateField('carCareDetails', { careType, price, mrp });
        }
    }
  }, [state.carCareDetails?.careType, state.vehicleCategoryTag, pricingConfig, updateField]);

  // Recalculate dynamic addon prices if vehicle category changes
  useEffect(() => {
      const category = state.vehicleCategoryTag;
      if (!category || !state.dynamicAddons || state.dynamicAddons.length === 0) return;

      const updatedAddons = state.dynamicAddons.map(addon => {
          let price = 0;
          let mrp = 0;

          if (pricingConfig && pricingConfig.addons[addon.name]?.[category]) {
             price = pricingConfig.addons[addon.name][category].price;
             mrp = pricingConfig.addons[addon.name][category].mrp;
          } else {
             const priceData = DEFAULT_ADDON_PRICING_MATRIX[addon.name as keyof typeof DEFAULT_ADDON_PRICING_MATRIX]?.[category];
             price = priceData?.price || 0;
             mrp = priceData?.mrp || 0;
          }

          return {
              ...addon,
              price,
              mrp,
          };
      });

      if (JSON.stringify(updatedAddons) !== JSON.stringify(state.dynamicAddons)) {
          updateField('dynamicAddons', updatedAddons);
      }
  }, [state.vehicleCategoryTag, state.dynamicAddons, pricingConfig, updateField]);


  useEffect(() => {
    const tyreTotal = state.tyreReplacementQuantity * (state.tyreReplacementPrice || 0);
    updateField('tyreReplacementTotalAmount', tyreTotal);
  }, [state.tyreReplacementQuantity, state.tyreReplacementPrice, updateField]);

  useEffect(() => {
    const batteryTotal = state.batteryDetails.reduce((total, battery) => {
      return total + ((battery.newBatteryAmount || 0) - (battery.exchangeValue || 0));
    }, 0);
    updateField('batteryReplacementTotalAmount', batteryTotal);
  }, [state.batteryDetails, updateField]);

  useEffect(() => {
    const dynamicAddonsTotal = (state.dynamicAddons || []).reduce((total, item) => {
        return total + (item.price * item.quantity);
    }, 0);

    const customAddonsTotal = state.categorizedAddons.reduce((sum, addon) => {
        return sum + ((addon.quantity || 0) * (addon.amount || 0));
    }, 0);

    updateField('categorizedAddonsTotal', customAddonsTotal);
    updateField('addonsTotal', dynamicAddonsTotal + customAddonsTotal);
  }, [state.dynamicAddons, state.categorizedAddons, updateField]);

  useEffect(() => {
    const customServicesTotal = state.customServices.reduce((sum, service) => sum + Number(service.amount || 0), 0);
    updateField('customServicesTotal', customServicesTotal);
  }, [state.customServices, updateField]);

  // Grand Total Calculation
  const grandTotal = useMemo(() => {
    let total = 0;
    if (state.serviceSelection.includes("Car Washing")) total += state.carWashDetails?.price || 0;
    if (state.serviceSelection.includes("Car Care")) total += state.carCareDetails?.price || 0;
    if (state.serviceSelection.includes("Tyre Replacement")) total += state.tyreReplacementTotalAmount;
    if (state.serviceSelection.includes("Battery Replacement")) total += state.batteryReplacementTotalAmount;
    total += state.addonsTotal;
    total += state.customServicesTotal;
    return total;
  }, [state.serviceSelection, state.carWashDetails, state.carCareDetails, state.tyreReplacementTotalAmount, state.batteryReplacementTotalAmount, state.addonsTotal, state.customServicesTotal]);

  useEffect(() => {
      updateField('grandTotal', grandTotal);
  }, [grandTotal, updateField]);

  // Sync child table rows with quantity
  useEffect(() => {
    if (!state.serviceSelection.includes("Tyre Replacement")) return;
    const diff = state.tyreReplacementQuantity - state.tyreDetails.length;
    if (diff > 0) {
      for (let i = 0; i < diff; i++) dispatch({ type: 'ADD_TYRE_DETAIL' });
    } else if (diff < 0) {
      for (let i = 0; i < -diff; i++) dispatch({ type: 'REMOVE_TYRE_DETAIL', index: state.tyreDetails.length - 1 - i });
    }
  }, [state.tyreReplacementQuantity, state.tyreDetails.length, state.serviceSelection]);

  useEffect(() => {
    if (!state.serviceSelection.includes("Battery Replacement")) return;
    const diff = state.batteryReplacementQuantity - state.batteryDetails.length;
    if (diff > 0) {
      for (let i = 0; i < diff; i++) dispatch({ type: 'ADD_BATTERY_DETAIL' });
    } else if (diff < 0) {
      for (let i = 0; i < -diff; i++) dispatch({ type: 'REMOVE_BATTERY_DETAIL', index: state.batteryDetails.length - 1 - i });
    }
  }, [state.batteryReplacementQuantity, state.batteryDetails.length, state.serviceSelection]);

  return { state, dispatch, updateField };
};

import React from 'react';
// FIX: Removed obsolete 'PredefinedAddon' from imports.
import { Service, TyreDetail, BatteryDetail, ServiceTemplate, CustomField, UserSubscription, VehicleCategoryTag, CarWashDetails, TyreData, PricingConfig } from '../types';
import Input from './ui/Input';
import QuantityInput from './ui/QuantityInput';
import FileUpload from './ui/FileUpload';
import { ValidationErrors } from '../services/validationService';
import Accordion from './ui/Accordion';
import SelfLearningInput from './ui/SelfLearningInput';
import { VEHICLE_CATEGORY_TAGS, WASH_TYPES, DEFAULT_PRICING_CONFIG } from '../constants';


interface Props {
  state: Service;
  updateField: <K extends keyof Service>(field: K, value: Service[K]) => void;
  dispatch: React.Dispatch<any>;
  googleDriveUploadUrl: string;
  serviceTemplates: ServiceTemplate[];
  errors: ValidationErrors;
  tyreData: TyreData;
  onUpdateTyreData: (type: keyof TyreData, value: string) => void;
  userSubscriptions?: UserSubscription[];
  allSubmissions?: Service[];
  pricingConfig?: PricingConfig;
}

export const ServiceDetailsStep: React.FC<Props> = ({ state, updateField, dispatch, googleDriveUploadUrl, serviceTemplates, errors, tyreData, onUpdateTyreData, pricingConfig = DEFAULT_PRICING_CONFIG }) => {

  const handleUpdateTyreDetail = (index: number, field: keyof TyreDetail, value: any) => {
    dispatch({ type: 'UPDATE_TYRE_DETAIL', index, field, value });
  };

  const handleUpdateBatteryDetail = (index: number, field: keyof BatteryDetail, value: any) => {
    dispatch({ type: 'UPDATE_BATTERY_DETAIL', index, field, value });
  };

  const handleUpdateCustomField = (fieldId: string, value: string | number) => {
    dispatch({ type: 'UPDATE_CUSTOM_FIELD_DATA', fieldId, value });
  };

  const handleWashDetailsChange = (field: keyof CarWashDetails, value: any) => {
    const newDetails = { ...state.carWashDetails, [field]: value };
    // If washType is cleared, reset the whole object
    if (field === 'washType' && !value) {
        updateField('carWashDetails', undefined);
    } else {
        updateField('carWashDetails', newDetails);
    }
  };

  const getCustomFieldValue = (fieldId: string): string | number => {
      const fieldData = (state.customFieldData || []).find(f => f.fieldId === fieldId);
      return fieldData ? fieldData.value : '';
  };

  const renderCustomField = (field: CustomField) => {
    switch (field.type) {
        case 'TEXT':
            return <Input 
                      label={field.label} 
                      id={field.id} 
                      value={getCustomFieldValue(field.id) as string}
                      onChange={(e) => handleUpdateCustomField(field.id, e.target.value)} 
                    />;
        case 'NUMBER':
            return <Input 
                      label={field.label} 
                      id={field.id} 
                      type="number"
                      value={getCustomFieldValue(field.id)}
                      onChange={(e) => handleUpdateCustomField(field.id, parseFloat(e.target.value) || 0)} 
                    />;
        case 'QUANTITY':
             // FIX: Replaced Input with a proper label and QuantityInput for better UX.
             return (
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">{field.label}</label>
                  <QuantityInput
                      value={getCustomFieldValue(field.id) as number || 0}
                      onChange={(v) => handleUpdateCustomField(field.id, v)}
                  />
                </div>
            );
        case 'PHOTO':
            return <FileUpload 
                      uploadType="photo" 
                      label={field.label} 
                      fileUrl={getCustomFieldValue(field.id) as string} 
                      onUpload={(url) => handleUpdateCustomField(field.id, url)} 
                      carNumber={state.carNumber} 
                      uploadUrl={googleDriveUploadUrl} 
                    />;
        default:
            return null;
    }
  };

  const dynamicServices = state.serviceSelection.filter(name => !["Car Washing", "Tyre Replacement", "Battery Replacement", "Car Care"].includes(name));

  return (
    <div className="space-y-4">
      {state.serviceSelection.includes("Car Washing") && (
        <Accordion
          title="Car Washing Details"
          summary={<span className="font-semibold">{state.carWashDetails?.washType || 'Select Wash'} - ₹{(state.carWashDetails?.price || 0).toFixed(2)}</span>}
          defaultOpen={true}
        >
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-start mb-6">
              <div>
                <label htmlFor="washType" className="block text-sm font-medium text-slate-700 mb-1">Wash Type</label>
                <select id="washType" value={state.carWashDetails?.washType || ''} onChange={(e) => handleWashDetailsChange('washType', e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm">
                    <option value="">-- Select Wash Type --</option>
                    {WASH_TYPES.map(type => <option key={type} value={type}>{type}</option>)}
                </select>
              </div>
              <div>
                <label htmlFor="vehicleCategoryTagWash" className="block text-sm font-medium text-slate-700 mb-1">Vehicle Category</label>
                 <select id="vehicleCategoryTagWash" value={state.vehicleCategoryTag || ''} onChange={(e) => updateField('vehicleCategoryTag', e.target.value as VehicleCategoryTag)} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm">
                    <option value="">-- Select Category --</option>
                    {VEHICLE_CATEGORY_TAGS.map(tag => <option key={tag} value={tag}>{tag}</option>)}
                </select>
              </div>
          </div>
           <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 p-4 bg-slate-50 rounded-lg">
                <div className="space-y-2">
                    <label htmlFor="isSubscription" className="font-medium text-slate-700 flex items-center space-x-2 cursor-pointer">
                        <input type="checkbox" id="isSubscription" checked={state.isSubscription} onChange={(e) => updateField('isSubscription', e.target.checked)} className="h-4 w-4 rounded border-gray-300 text-brand-accent focus:ring-brand-accent"/>
                        <span>Is this a subscription wash? (Price will be zero)</span>
                    </label>
                </div>
                <div className="text-right flex space-x-4">
                    <div className="w-32">
                        <Input 
                            label="Total (₹)" 
                            type="number" 
                            id="washTotal"
                            value={state.carWashDetails?.price || 0} 
                            onChange={(e) => handleWashDetailsChange('price', parseFloat(e.target.value) || 0)}
                            className="text-right font-bold"
                        />
                    </div>
                </div>
           </div>
          <div className="space-y-4 mt-6">
              <h4 className="font-semibold text-slate-700 mt-4 border-b pb-2">Media Upload</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <FileUpload uploadType="photo" label="Before Washing Photo" fileUrl={state.beforeWashingPhoto} onUpload={(url) => updateField('beforeWashingPhoto', url)} carNumber={state.carNumber} uploadUrl={googleDriveUploadUrl} />
                <FileUpload uploadType="video" label="Inventory & Dirtiness" fileUrl={state.beforeVideoInventory} onUpload={(url) => updateField('beforeVideoInventory', url)} carNumber={state.carNumber} uploadUrl={googleDriveUploadUrl} />
                <FileUpload uploadType="video" label="Top Body" fileUrl={state.beforeVideoTopBody} onUpload={(url) => updateField('beforeVideoTopBody', url)} carNumber={state.carNumber} uploadUrl={googleDriveUploadUrl} />
                <FileUpload uploadType="video" label="Underchassis" fileUrl={state.beforeVideoUnderchassis} onUpload={(url) => updateField('beforeVideoUnderchassis', url)} carNumber={state.carNumber} uploadUrl={googleDriveUploadUrl} />
                <FileUpload uploadType="photo" label="After Washing Photo" fileUrl={state.afterWashingPhoto} onUpload={(url) => updateField('afterWashingPhoto', url)} carNumber={state.carNumber} uploadUrl={googleDriveUploadUrl} />
                <FileUpload uploadType="video" label="Interior" fileUrl={state.afterVideoInterior} onUpload={(url) => updateField('afterVideoInterior', url)} carNumber={state.carNumber} uploadUrl={googleDriveUploadUrl} />
                <FileUpload uploadType="video" label="Exterior" fileUrl={state.afterVideoExterior} onUpload={(url) => updateField('afterVideoExterior', url)} carNumber={state.carNumber} uploadUrl={googleDriveUploadUrl} />
                <FileUpload uploadType="video" label="After Underchassis" fileUrl={state.afterVideoUnderchassis} onUpload={(url) => updateField('afterVideoUnderchassis', url)} carNumber={state.carNumber} uploadUrl={googleDriveUploadUrl} />
              </div>
          </div>
        </Accordion>
      )}

      {state.serviceSelection.includes("Tyre Replacement") && (
        <Accordion
          title="Tyre Replacement Details"
          summary={<span className="font-semibold">{state.tyreReplacementQuantity} tyre(s) - ₹{state.tyreReplacementTotalAmount.toFixed(2)}</span>}
          defaultOpen={true}
        >
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6 items-start">
              <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Quantity</label>
                  <QuantityInput value={state.tyreReplacementQuantity} onChange={v => updateField('tyreReplacementQuantity', v)} />
                  {errors.tyreReplacementQuantity && <p className="mt-1 text-xs text-red-600">{errors.tyreReplacementQuantity as string}</p>}
              </div>
              <div>
                <Input
                    label="Price per Tyre (₹)"
                    id="tyreReplacementPrice"
                    type="number"
                    value={state.tyreReplacementPrice}
                    onChange={(e) => updateField('tyreReplacementPrice', parseFloat(e.target.value) || 0)}
                />
              </div>
               <div>
                <Input
                    label="Internal Labor Cost (₹)"
                    id="tyreLaborCost"
                    type="number"
                    value={state.tyreLaborCost}
                    onChange={(e) => updateField('tyreLaborCost', parseFloat(e.target.value) || 0)}
                />
              </div>
               <div>
                <Input
                    label="Internal Material Cost (₹)"
                    id="tyreMaterialCost"
                    type="number"
                    value={state.tyreMaterialCost}
                    onChange={(e) => updateField('tyreMaterialCost', parseFloat(e.target.value) || 0)}
                />
              </div>
              <div className="lg:col-span-4 flex justify-end pb-2">
                <p className="text-xl font-bold text-slate-800">Total Customer Price: ₹{state.tyreReplacementTotalAmount.toFixed(2)}</p>
              </div>
          </div>
          <div className="space-y-4">
          {state.tyreDetails.map((tyre, index) => (
             <div key={tyre.tyreId} className="p-4 bg-slate-50 rounded-lg border space-y-4">
                <h4 className="font-semibold text-slate-700">Tyre {index + 1}</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Input label="DOT Code" id={`tyre-dot-${index}`} value={tyre.dotCode} onChange={e => handleUpdateTyreDetail(index, 'dotCode', e.target.value)} error={errors.tyreDetails?.[index]?.dotCode} />
                    <SelfLearningInput label="Tyre Size" id={`tyre-size-${index}`} value={tyre.tyreSize} onChange={v => handleUpdateTyreDetail(index, 'tyreSize', v)} onNewValue={v => onUpdateTyreData('sizes', v)} suggestions={tyreData.sizes} error={errors.tyreDetails?.[index]?.tyreSize} />
                    <SelfLearningInput label="Brand" id={`tyre-brand-${index}`} value={tyre.brand} onChange={v => handleUpdateTyreDetail(index, 'brand', v)} onNewValue={v => onUpdateTyreData('brands', v)} suggestions={tyreData.brands} />
                    <SelfLearningInput label="Model" id={`tyre-model-${index}`} value={tyre.model} onChange={v => handleUpdateTyreDetail(index, 'model', v)} onNewValue={v => onUpdateTyreData('models', v)} suggestions={tyreData.models} />
                </div>
                <FileUpload uploadType="photo" label="DOT Serial Number Image" fileUrl={tyre.dotSerialNumberImage} onUpload={(url) => handleUpdateTyreDetail(index, 'dotSerialNumberImage', url)} carNumber={state.carNumber} uploadUrl={googleDriveUploadUrl} />
             </div>
          ))}
          </div>
        </Accordion>
      )}

      {state.serviceSelection.includes("Battery Replacement") && (
        <Accordion
            title="Battery Replacement Details"
            summary={<span className="font-semibold">{state.batteryReplacementQuantity} battery(s) - ₹{state.batteryReplacementTotalAmount.toFixed(2)}</span>}
            defaultOpen={true}
        >
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6 items-start">
              <div>
                  {/* FIX: Replaced Input with a proper label and QuantityInput for better UX. */}
                  <label className="block text-sm font-medium text-slate-700 mb-1">Quantity</label>
                  <QuantityInput value={state.batteryReplacementQuantity} onChange={v => updateField('batteryReplacementQuantity', v)} />
                   {errors.batteryReplacementQuantity && <p className="mt-1 text-xs text-red-600">{errors.batteryReplacementQuantity as string}</p>}
              </div>
              <p className="text-lg font-semibold text-slate-700 self-center">Total: ₹{state.batteryReplacementTotalAmount.toFixed(2)}</p>
          </div>
          <div className="space-y-4">
            {state.batteryDetails.map((battery, index) => (
              <div key={battery.batteryId} className="p-4 bg-slate-50 rounded-lg border space-y-4">
                 <h4 className="font-semibold text-slate-700">Battery {index + 1}</h4>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Input label="Serial Number" id={`batt-serial-${index}`} value={battery.serialNumber} onChange={e => handleUpdateBatteryDetail(index, 'serialNumber', e.target.value)} error={errors.batteryDetails?.[index]?.serialNumber} />
                    <Input label="Brand" id={`batt-brand-${index}`} value={battery.brand} onChange={e => handleUpdateBatteryDetail(index, 'brand', e.target.value)} />
                    <Input label="New Battery Amount (₹)" id={`batt-new-amt-${index}`} type="number" value={battery.newBatteryAmount} onChange={e => handleUpdateBatteryDetail(index, 'newBatteryAmount', parseFloat(e.target.value) || 0)} error={errors.batteryDetails?.[index]?.newBatteryAmount} />
                    <Input label="Battery Exchange Value (₹)" id={`batt-exchange-${index}`} type="number" value={battery.exchangeValue} onChange={e => handleUpdateBatteryDetail(index, 'exchangeValue', parseFloat(e.target.value) || 0)} />
                 </div>
                 <p className="text-md font-semibold text-slate-600 text-right">Sub-total: ₹{(battery.newBatteryAmount - battery.exchangeValue).toFixed(2)}</p>
              </div>
            ))}
          </div>
        </Accordion>
      )}

      {/* DYNAMIC SERVICE DETAILS */}
      {dynamicServices.map(serviceName => {
        const template = serviceTemplates.find(t => t.name === serviceName);
        if (!template || !template.customFields || template.customFields.length === 0) {
            return null;
        }

        return (
            <Accordion key={template.id} title={`${template.name} Details`} defaultOpen={true}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {template.customFields.map(field => (
                        <div key={field.id}>
                            {renderCustomField(field)}
                        </div>
                    ))}
                </div>
            </Accordion>
        );
      })}
    </div>
  );
};

