// Helper to clean array strings from Google Sheets (e.g. "[A, B]" -> ["A", "B"])
const parseServiceSelection = (raw: any): string[] => {
    if (Array.isArray(raw)) {
        return raw.flatMap(item => parseServiceSelection(item));
    }
    if (typeof raw === 'string') {
        const trimmed = raw.trim();
        if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
            try {
                const parsed = JSON.parse(trimmed);
                if (Array.isArray(parsed)) return parseServiceSelection(parsed);
            } catch (e) { /* ignore */ }
        }
        return trimmed.split(',').map(s => s.replace(/[\[\]"']/g, '').trim()).filter(Boolean);
    }
    return [];
};


export const loadAppData = async (currentSettings: Settings): Promise<AppData> => {
    const sheetsUrl = currentSettings.googleSheetsUrl;
    if (!sheetsUrl) {
        console.log("Cloud URL not set. Using default initial data.");
        return getDefaultAppData(currentSettings);
    }

    console.log("Fetching relational data from cloud backend...");
    try {
        const url = new URL(sheetsUrl);
        url.searchParams.set('action', 'loadAllData');

        const response = await fetch(url.toString(), {
            method: 'GET',
            mode: 'cors',
        });

        const responseText = await response.text();
        if (!response.ok) {
             if (responseText.includes('<title>Error</title>')) {
                throw new Error(`The server returned a Google error page. This usually means the Cloud Data URL is incorrect (e.g., using a '/dev' link instead of the '/exec' link from your deployment) or that the script permissions are not set to 'Anyone'.`);
            }
            throw new Error(`Failed to fetch. Server responded with status: ${response.status}. Response: ${responseText}`);
        }

        const result = JSON.parse(responseText);
        if (result.status !== 'success') {
             throw new Error(result.message || 'Cloud script returned an error.');
        }

        console.log("Successfully loaded flat data from cloud. Re-hydrating...");

        const flatData = result.data;

        const tyreDetails: TyreDetail[] = (flatData.TyreDetails || []).map((d: any) => ({ ...d }));
        const batteryDetails: BatteryDetail[] = (flatData.BatteryDetails || []).map((d: any) => ({ 
            ...d, 
            exchangeValue: robustParseFloat(d.exchangeValue), 
            newBatteryAmount: robustParseFloat(d.newBatteryAmount)
        }));
        const customServices: CustomService[] = (flatData.CustomServices || []).map((d: any) => ({
             ...d, 
             amount: robustParseFloat(d.amount)
        }));
        const categorizedAddons: CategorizedAddon[] = (flatData.CategorizedAddons || []).map((d: any) => ({
            ...d,
            quantity: robustParseInt(d.quantity),
            amount: robustParseFloat(d.amount)
        }));
        const predefinedAddonQuantities = flatData.PredefinedAddonQuantities || [];
        const customFieldData = flatData.CustomFieldData || [];
        const serviceTemplateFields = flatData.ServiceTemplateFields || [];
        const locationHistory: LocationHistory[] = (flatData.LocationHistory || []).map((d: any) => ({
            ...d,
            latitude: robustParseFloat(d.latitude),
            longitude: robustParseFloat(d.longitude),
        }));
        const miscSpends: MiscSpend[] = (flatData.MiscSpends || []).map((s: any) => ({
            ...s,
            amount: robustParseFloat(s.amount),
        }));
        const bookkeeping: BookkeepingEntry[] = (flatData.Bookkeeping || []).map((b: any) => ({
            ...b,
            amount: robustParseFloat(b.amount),
        }));
        const profitLoss: ProfitLoss[] = (flatData.ProfitLoss || []).map((pl: any) => ({
            ...pl,
            materialCost: robustParseFloat(pl.materialCost),
            laborCost: robustParseFloat(pl.laborCost),
            otherExpenses: robustParseFloat(pl.otherExpenses),
            calculatedProfit: robustParseFloat(pl.calculatedProfit),
        }));


        const vehicleData = (flatData.VehicleData && flatData.VehicleData[0] && typeof flatData.VehicleData[0].data === 'string')
            ? JSON.parse(flatData.VehicleData[0].data)
            : CAR_BRANDS;

        const tyreData = (flatData.TyreData && flatData.TyreData[0] && typeof flatData.TyreData[0].data === 'string')
            ? JSON.parse(flatData.TyreData[0].data)
            : { brands: TIRE_BRANDS, models: [], sizes: [] };

        const pricingConfig: PricingConfig = (flatData.PricingConfig && flatData.PricingConfig[0] && typeof flatData.PricingConfig[0].data === 'string')
            ? JSON.parse(flatData.PricingConfig[0].data)
            : DEFAULT_PRICING_CONFIG;


        const subscriptionPlans: SubscriptionPlan[] = (flatData.SubscriptionPlans || []).map((p: any) => ({
            ...p,
            price: robustParseFloat(p.price),
            totalWashes: robustParseInt(p.totalWashes),
            features: p.features ? String(p.features).split(',').map(f => f.trim()) : [],
        }));

        const userSubscriptions: UserSubscription[] = (flatData.UserSubscriptions || []).map((s: any) => ({
            ...s,
            washesRemaining: robustParseInt(s.washesRemaining),
        }));

        const serviceRequests: ServiceRequest[] = (flatData.ServiceRequests || []).map((r: any) => ({...r}));

        const notifications: AppNotification[] = (flatData.Notifications || []).map((n: any) => ({
            ...n,
            isRead: String(n.isRead).toUpperCase() === 'TRUE',
        }));

        const serviceTemplates: ServiceTemplate[] = (flatData.ServiceTemplates || []).map((t: any) => ({
            ...t,
            isEnabled: String(t.isEnabled).toUpperCase() === 'TRUE',
            customFields: serviceTemplateFields
                .filter((f: any) => f.relatedTemplateId === t.id)
                .map(({ relatedTemplateId, ...rest }: any) => rest),
        }));

        const submissions: Service[] = (flatData.Submissions || []).map((sub: any): Service => {
            let status = sub.status;
            const validStatuses = Object.values(ServiceStatus);

            // Data migration for legacy statuses
            if ((status as any) === 'Submitted') status = ServiceStatus.Completed;
            else if ((status as any) === 'Order Created') status = ServiceStatus.Queued;

            // Self-healing for invalid or missing status
            if (!status || !validStatuses.includes(status as ServiceStatus)) {
                status = ServiceStatus.Queued;
            }

            let dynamicAddons = [];
            try {
                if (sub.dynamicAddons && typeof sub.dynamicAddons === 'string') dynamicAddons = JSON.parse(sub.dynamicAddons);
                else if (Array.isArray(sub.dynamicAddons)) dynamicAddons = sub.dynamicAddons;
            } catch(e) { console.warn(`Could not parse dynamicAddons for submission ${sub.submissionId}`); }

            let carWashDetails = undefined;
            try {
                if (sub.carWashDetails && typeof sub.carWashDetails === 'string') carWashDetails = JSON.parse(sub.carWashDetails);
                else if (typeof sub.carWashDetails === 'object' && sub.carWashDetails !== null) carWashDetails = sub.carWashDetails;
            } catch(e) { console.warn(`Could not parse carWashDetails for submission ${sub.submissionId}`); }

            let carCareDetails = undefined;
            try {
                if (sub.carCareDetails && typeof sub.carCareDetails === 'string') carCareDetails = JSON.parse(sub.carCareDetails);
                else if (typeof sub.carCareDetails === 'object' && sub.carCareDetails !== null) carCareDetails = sub.carCareDetails;
            } catch(e) { console.warn(`Could not parse carCareDetails for submission ${sub.submissionId}`); }

            return {
                ...sub,
                status: status,
                dynamicAddons,
                carWashDetails,
                carCareDetails,
                isSubscription: String(sub.isSubscription).toUpperCase() === 'TRUE',
                isFollowUp: String(sub.isFollowUp).toUpperCase() === 'TRUE',
                isAutoScheduled: String(sub.isAutoScheduled).toUpperCase() === 'TRUE',
                acknowledgement: String(sub.acknowledgement).toUpperCase() === 'TRUE',
                carwashQuantity: robustParseInt(sub.carwashQuantity),
                carWashPrice: robustParseFloat(sub.carWashPrice),
                carwashTotalAmount: robustParseFloat(sub.carwashTotalAmount),
                tyreReplacementQuantity: robustParseInt(sub.tyreReplacementQuantity),
                tyreReplacementPrice: robustParseFloat(sub.tyreReplacementPrice),
                tyreReplacementTotalAmount: robustParseFloat(sub.tyreReplacementTotalAmount),
                tyreLaborCost: robustParseFloat(sub.tyreLaborCost),
                tyreMaterialCost: robustParseFloat(sub.tyreMaterialCost),
                batteryReplacementQuantity: robustParseInt(sub.batteryReplacementQuantity),
                batteryReplacementTotalAmount: robustParseFloat(sub.batteryReplacementTotalAmount),
                addonsTotal: robustParseFloat(sub.addonsTotal),
                categorizedAddonsTotal: robustParseFloat(sub.categorizedAddonsTotal),
                customServicesTotal: robustParseFloat(sub.customServicesTotal),
                grandTotal: robustParseFloat(sub.grandTotal),
                appointmentId: sub.appointmentId || sub.submissionId,
                submittedBy: sub.submittedBy || undefined,
                scheduledDate: sub.scheduledDate || undefined,
                scheduledTime: sub.scheduledTime || undefined,
                assignedTo: sub.assignedTo || undefined,
                internalNotes: sub.internalNotes || '',
                tyreDetails: tyreDetails.filter((d: TyreDetail) => d.relatedServiceId === sub.submissionId),
                batteryDetails: batteryDetails.filter((d: BatteryDetail) => d.relatedServiceId === sub.submissionId),
                customServices: customServices.filter((d: CustomService) => d.relatedServiceId === sub.submissionId),
                categorizedAddons: categorizedAddons.filter((d: CategorizedAddon) => d.relatedServiceId === sub.submissionId),
                customFieldData: customFieldData
                    .filter((d: any) => d.relatedServiceId === sub.submissionId)
                    .map(({ relatedServiceId, ...rest }: any) => rest),
                serviceSelection: parseServiceSelection(sub.serviceSelection),
                 dependsOn: sub.dependsOn ? String(sub.dependsOn).split(',').map(s => s.trim()) : [],
            };
        });

        const cloudSettingsPartial: Partial<Settings> = (flatData.Settings && flatData.Settings[0]) ? flatData.Settings[0] : {};
        let kpiTargets: RetentionKpiTargets | undefined;
        try {
            if (cloudSettingsPartial.retentionKpiTargets) {
                kpiTargets = typeof cloudSettingsPartial.retentionKpiTargets === 'string' 
                    ? JSON.parse(cloudSettingsPartial.retentionKpiTargets) 
                    : cloudSettingsPartial.retentionKpiTargets;
            }
        } catch(e) { console.warn("Could not parse KPI targets from cloud."); }

        const settings: Settings = {
            googleSheetsUrl: cloudSettingsPartial.googleSheetsUrl || currentSettings.googleSheetsUrl,
            googleDriveUploadUrl: cloudSettingsPartial.googleDriveUploadUrl || currentSettings.googleDriveUploadUrl,
            customLogoUrl: cloudSettingsPartial.customLogoUrl || currentSettings.customLogoUrl,
            retentionKpiTargets: kpiTargets || currentSettings.retentionKpiTargets
        };

        // Return an empty user array if the 'Users' sheet is empty from the cloud,
        // allowing the App to handle the initial admin creation more safely.
        const users: User[] = (flatData.Users && flatData.Users.length > 0) 
            ? (flatData.Users || []).map((u: any) => {
                let notificationPreferences: Partial<NotificationPreferences> = {};
                let pushSubscription = null;
                let attendanceHistory = [];
                let permissions = [];
                try { if (u.notificationPreferences) notificationPreferences = JSON.parse(u.notificationPreferences); } catch (e) { console.warn(`Could not parse notificationPreferences for user ${u.username}`) }
                try { if (u.pushSubscription) pushSubscription = JSON.parse(u.pushSubscription); } catch (e) { console.warn(`Could not parse pushSubscription for user ${u.username}`) }
                try { if (u.attendanceHistory) attendanceHistory = JSON.parse(u.attendanceHistory); } catch (e) { console.warn(`Could not parse attendanceHistory for user ${u.username}`) }
                try { if (u.permissions) permissions = JSON.parse(u.permissions); } catch (e) { console.warn(`Could not parse permissions for user ${u.username}`) }


                return { 
                    ...u,
                    notificationPreferences,
                    attendanceHistory,
                    permissions,
                    pushSubscription: pushSubscription || undefined,
                    latitude: u.latitude ? robustParseFloat(u.latitude) : undefined,
                    longitude: u.longitude ? robustParseFloat(u.longitude) : undefined,
                };
            })
            : getDefaultAppData(settings).users;

        return { submissions, users, settings, subscriptionPlans, userSubscriptions, serviceTemplates, serviceRequests, notifications, locationHistory, miscSpends, bookkeeping, profitLoss, vehicleData, tyreData, pricingConfig, predefinedAddons: [] };

    } catch (error) {
        console.error("Critical error loading data from cloud backend.", error);
        let detailedMessage = "An unknown error occurred during cloud data loading.";
        if (error instanceof Error) {
            if (error.message.includes('Failed to fetch')) {
                detailedMessage = "Network error. Please check your internet connection, ad-blockers, and ensure the Cloud Data App URL is correct and accessible.";
            } else if (error.name === 'SyntaxError') {
                 detailedMessage = "The server returned an invalid response (not JSON). This often means the Google Apps Script URL is incorrect or permissions are not set correctly.";
            } else {
                detailedMessage = error.message;
            }
        }
        throw new Error(detailedMessage);
    }
};

