        return hasPermission(Permission.CAN_VIEW_ANALYTICS) ? <AnalyticsPage
                 submissions={submissions}
                 users={users.map(({password, ...rest}) => rest)}
                 serviceTemplates={serviceTemplates}
                 profitLossData={profitLossData}
               /> : <DashboardPage {...dashboardProps} />;
       case 'CUSTOMER_HISTORY':
        return hasPermission(Permission.CAN_VIEW_CUSTOMER_HISTORY) ? <CustomerHistoryPage
                 submissions={submissions}
                 currentUser={currentUser}
                 onShareOrder={handleShareOrder}
               /> : <DashboardPage {...dashboardProps} />;
      case 'RETENTION':
        return hasPermission(Permission.CAN_VIEW_RETENTION_DASHBOARD) ? <RetentionDashboard
                 submissions={submissions}
                 onCreateFollowUp={handleCreateFollowUp}
                 settings={settings}
                 onUpdateKpiTargets={handleUpdateKpiTargets}
               /> : <DashboardPage {...dashboardProps} />;
      case 'BOOKKEEPING':
        return hasPermission(Permission.CAN_LOG_EXPENSES) ? <BookkeepingPage
            currentUser={currentUser}
            miscSpends={miscSpends}
            users={users.map(({password, ...rest}) => rest)}
            googleDriveUploadUrl={settings.googleDriveUploadUrl}
            onSaveNewSpend={handleSaveNewSpend}
            onUpdateSpendStatus={handleUpdateSpendStatus}
            bookkeeping={bookkeeping}
        /> : <DashboardPage {...dashboardProps} />;
      case 'PROFIT_LOSS':
        return hasPermission(Permission.CAN_VIEW_PROFIT_LOSS) ? <ProfitLossPage
            submissions={submissions}
            profitLossData={profitLossData}
            onSave={handleUpdateProfitLoss}
        /> : <DashboardPage {...dashboardProps} />;
      case 'DASHBOARD':
        return hasPermission(Permission.CAN_VIEW_DASHBOARD) ? <DashboardPage {...dashboardProps} /> : <div>Access Denied</div>;
      default:
        return <div>Unknown view</div>;
    }
  };

  const dashboardProps = {
    submissions,
    users: users.map(({password, ...rest}) => rest),
    currentUser,
    onCreateOrder: handleCreateOrder,
    onAssignOrder: handleAssignOrder,
    onStartOrder: handleStartOrder,
    onUpdateOrder: handleEditService,
    onSelfAssignOrder: handleSelfAssignOrder,
    onDeleteOrder: handleDeleteRequest,
    onScheduleDroppedOrder: handleScheduleDroppedOrder,
    onNotifyForOrder: handleNotifyForOrder,
    onUpdateAttendanceStatus: handleUpdateAttendanceStatus,
    userSubscriptions,
    serviceTemplates,
    setIsChatbotOpen,
    settings,
    locationHistory,
    vehicleData,
    tyreData,
    onShareOrder: handleShareOrder,
  };

  return (
    <div className="min-h-screen bg-slate-100 flex">
      {isSettingsOpen && currentUser.permissions.includes(Permission.CAN_EDIT_SETTINGS) && (
        <SettingsModal 
          initialSettings={settings}
          onClose={() => setIsSettingsOpen(false)} 
          onSave={handleSaveSettings}
        />
      )}

      {summarizingService && (
          <SummaryModal 
            service={summarizingService}
            onClose={() => setSummarizingService(null)}
          />
      )}

      {sharingService && (
        <ShareOrderModal 
          service={sharingService}
          onClose={() => setSharingService(null)}
        />
      )}

      {isChatbotOpen && (
        <ChatbotModal
            isOpen={isChatbotOpen}
            onClose={() => setIsChatbotOpen(false)}
            onSubmit={handleSaveDraftFromChatbot}
            serviceTemplates={serviceTemplates}
        />
       )}

      {deletingService && (
        <DeleteConfirmationModal
            isOpen={!!deletingService}
            onClose={() => setDeletingService(null)}
            onConfirm={handleConfirmDelete}
            service={deletingService}
        />
      )}

      <Sidebar
          currentUser={currentUser}
          currentView={view}
          onNavigate={handleNavigate}
          onNewService={() => handleEditService(null)}
          onOpenSettings={() => setIsSettingsOpen(true)}
          onLogout={handleLogout}
          logoUrl={settings.customLogoUrl}
          logoHasError={logoHasError}
          onLogoError={() => setLogoHasError(true)}
          isMinimized={isSidebarMinimized}
          isOpenOnMobile={isMobileMenuOpen}
          onToggleDesktop={() => setIsSidebarMinimized(!isSidebarMinimized)}
          onCloseMobile={() => setIsMobileMenuOpen(false)}
      />

       {isMobileMenuOpen && <div className="fixed inset-0 bg-black/60 z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)}></div>}

      <div className={`flex-1 transition-all duration-300 ${isSidebarMinimized ? 'md:pl-20' : 'md:pl-64'}`}>
          <header className="sticky top-0 bg-slate-100/80 backdrop-blur-md z-30 border-b border-slate-200 no-print">
              <div className="relative flex items-center justify-between min-h-16 px-4 md:px-6 py-2 gap-2">
                  <button className="md:hidden text-slate-600" onClick={() => setIsMobileMenuOpen(true)} aria-label="Open menu">
