import React, { useState } from 'react';
import { SpendCategory } from '../../types';
import Card from '../ui/Card';
import Button from '../ui/Button';
import Input from '../ui/Input';
import { IconPlus, IconPencil, IconTrash, IconDeviceFloppy } from '../ui/Icon';

interface Props {
  categories: SpendCategory[];
  onUpdateCategories: (categories: SpendCategory[]) => void;
}

const SpendCategoryManagementPage: React.FC<Props> = ({ categories, onUpdateCategories }) => {
  const [editingCategory, setEditingCategory] = useState<SpendCategory | null>(null);
  const [isCreating, setIsCreating] = useState(false);

  const handleSave = (catToSave: SpendCategory) => {
    if (!catToSave.name.trim()) {
      alert("Category name cannot be empty.");
      return;
    }

    const existingIndex = categories.findIndex(c => c.id === catToSave.id);
    let updatedCategories;
    if (existingIndex > -1) {
      updatedCategories = categories.map(c => (c.id === catToSave.id ? catToSave : c));
    } else {
      updatedCategories = [...categories, catToSave];
    }
    onUpdateCategories(updatedCategories);
    setEditingCategory(null);
    setIsCreating(false);
  };

  const handleDelete = (catId: string) => {
    if (window.confirm('Are you sure you want to delete this category? Any existing expenses in this category will remain, but the category will no longer be available for new expenses.')) {
      const updatedCategories = categories.filter(c => c.id !== catId);
      onUpdateCategories(updatedCategories);
    }
  };

  const startCreating = () => {
    const newId = `cat_${Date.now()}`;
    setEditingCategory({ id: newId, name: '' });
    setIsCreating(true);
  };

  const CategoryEditor: React.FC<{ category: SpendCategory, onSave: (cat: SpendCategory) => void, onCancel: () => void }> = ({ category, onSave, onCancel }) => {
    const [localCat, setLocalCat] = useState(category);

    return (
      <div className="p-4 bg-slate-100 rounded-lg border my-4">
        <h3 className="text-lg font-semibold mb-2">{isCreating ? "Create New Category" : "Edit Category"}</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 items-end">
            <Input 
                label="Category Name" 
                id="name" 
                value={localCat.name} 
                onChange={e => setLocalCat(prev => ({ ...prev, name: e.target.value }))} 
                placeholder="e.g., Office Supplies, Tooling, Fuel"
            />
            <div className="flex space-x-2">
                <Button onClick={onCancel} variant="secondary">Cancel</Button>
                <Button onClick={() => onSave(localCat)}>
                    <IconDeviceFloppy className="w-5 h-5 mr-2"/> Save
                </Button>
            </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-8">
        <div className="flex justify-between items-center">
             <h1 className="text-3xl font-bold text-slate-800 tracking-tight">Spend Categories</h1>
             <Button onClick={startCreating} disabled={!!editingCategory}>
                <IconPlus className="w-5 h-5 mr-2" />
                Add Category
             </Button>
        </div>

        {editingCategory && <CategoryEditor category={editingCategory} onSave={handleSave} onCancel={() => { setEditingCategory(null); setIsCreating(false); }} />}

        <Card title="Available Categories">
             <div className="space-y-3">
                {categories.map(cat => (
                    <div key={cat.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border">
                       <div>
                            <p className="font-semibold text-slate-800">{cat.name}</p>
                       </div>
                       <div className="space-x-2">
                            <Button variant="ghost" size="sm" className="p-1 h-8 w-8" onClick={() => setEditingCategory(cat)}><IconPencil className="w-4 h-4" /></Button>
                            <Button variant="danger" size="sm" className="p-1 h-8 w-8" onClick={() => handleDelete(cat.id)}><IconTrash className="w-4 h-4" /></Button>
                       </div>
                    </div>
                ))}
                {categories.length === 0 && (
                    <div className="text-center py-8">
                        <p className="text-slate-500">No categories defined yet. Click "Add Category" to set up your expense types.</p>
                    </div>
                )}
