            }
        });

        const netProfit = totalRevenue - totalCost;
        const profitMargin = totalRevenue > 0 ? (netProfit / totalRevenue) * 100 : 0;
        const completedServices = filteredSubmissions.length;
        const avgRevenue = completedServices > 0 ? totalRevenue / completedServices : 0;

        return { totalRevenue, totalCost, netProfit, profitMargin, completedServices, avgRevenue };
