  const handleCreateOrder = useCallback((details: { 
    customer: Pick<Customer, 'firstName' | 'lastName' | 'mobileNumber' | 'carNumber' | 'carBrandModel' | 'streetAddress' | 'customerEmail'>, 
    scheduledDate?: string, 
    scheduledTime?: string, 
    serviceSelection: string[], 
    vehicleCategoryTag?: VehicleCategoryTag,
    assignedTo?: string 
  }) => {
    // This function creates the initial 'shell' of a service order.
    // Pricing and detailed service data are added when the order is opened for editing in the ServiceForm.

    // 1. Generate a unique ID and timestamp for the new service.
    const submissionId = `SUB-${Date.now()}`;
    const newService: Service = {
      ...createDefaultServiceState(), // Start with a clean, default service object.
      submissionId: submissionId,
      appointmentId: submissionId,
      timestamp: new Date().toISOString(),
      status: ServiceStatus.Queued, // New orders are always 'Queued' by default.

      // 2. Populate core details collected from the 'Create New Order' modal.
      customerFirstName: details.customer.firstName,
      customerLastName: details.customer.lastName,
      mobileNumber: details.customer.mobileNumber,
      customerEmail: details.customer.customerEmail,
      carNumber: details.customer.carNumber,
      carBrandModel: details.customer.carBrandModel,
      streetAddress: details.customer.streetAddress,

      // 3. Apply service selections and scheduling information.
      serviceSelection: details.serviceSelection,
      vehicleCategoryTag: details.vehicleCategoryTag, // This is auto-detected in the modal.
      scheduledDate: details.scheduledDate,
      scheduledTime: details.scheduledTime,
      assignedTo: details.assignedTo,
    };

    // Auto-update status if assigned
    if (newService.assignedTo) {
        newService.status = ServiceStatus.Assigned;
    }

    // 4. Update local state for immediate UI feedback.
    setSubmissions(prev => [...prev, newService]);

    // 5. Persist the new service record to the cloud (or offline queue).
    cloudDataService.saveRecord('Submissions', newService, settings.googleSheetsUrl);

    // 6. Notify relevant users (admins and managers) about the new queued order.
    const adminsAndManagers = users.filter(u => u.permissions.includes(Permission.CAN_ASSIGN_ORDERS));
    const newNotifications: AppNotification[] = [];

    if (!newService.assignedTo) {
        adminsAndManagers.forEach(admin => {
            const message = `New Order: #${newService.appointmentId?.split('-').pop()} for ${newService.customerFirstName} has been queued.`;
            const notif: AppNotification = {
                id: `notif_queued_${newService.submissionId}_${admin.username}`,
                userId: admin.username,
                serviceId: newService.submissionId,
                message,
                timestamp: new Date().toISOString(),
                isRead: false,
                type: 'queued'
            };
            newNotifications.push(notif);

            // Check user preferences before sending alerts.
            const prefs = admin.notificationPreferences || defaultNotificationPrefs;
            if (prefs.enabled.queued) {
                playNotificationAlert(prefs);
                if(admin.pushSubscription) {
                    sendPushNotification(admin.pushSubscription, "New Order Queued", message, prefs);
                }
            }
        });
    } else {
        // Notify the assigned user
        const assignedUser = users.find(u => u.username === newService.assignedTo);
        if (assignedUser) {
            const message = `Assigned: You have a new order for ${newService.customerFirstName}.`;
            const notif: AppNotification = {
                id: `notif_assign_${newService.submissionId}`,
                userId: assignedUser.username,
                serviceId: newService.submissionId,
                message,
                timestamp: new Date().toISOString(),
                isRead: false,
                type: 'assigned'
            };
            newNotifications.push(notif);
            const prefs = assignedUser.notificationPreferences || defaultNotificationPrefs;
            if (prefs.enabled.assigned) {
                playNotificationAlert(prefs);
                if (assignedUser.pushSubscription) sendPushNotification(assignedUser.pushSubscription, "New Assignment", message, prefs);
            }
        }
    }

    // 7. Update local state with new notifications and persist them to the cloud.
    if (newNotifications.length > 0) {
        setNotifications(prev => [...prev, ...newNotifications]);
        newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
    }

    // 8. Provide haptic feedback for a better user experience on mobile.
    triggerHapticFeedback('success');
  }, [users, settings.googleSheetsUrl]);

