  const handleAutoSchedule = (subscription: UserSubscription) => {
    const plan = subscriptionPlans.find(p => p.id === subscription.planId);
    if (!plan || plan.totalWashes <= 0) { return; }

    const today = new Date();
    if (today.getDate() > 7) {
        alert("Auto-scheduling for this month has been skipped because it is past the first week. You can schedule washes manually.");
        return;
    }

    const year = today.getFullYear();
    const month = today.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const washesToSchedule = plan.totalWashes;
    const interval = Math.floor(daysInMonth / washesToSchedule);
    const newServices: Service[] = [];

    for (let i = 0; i < washesToSchedule; i++) {
      const scheduledDay = Math.round((i * interval) + (interval / 2));
      const scheduledDate = new Date(year, month, scheduledDay);
      if (scheduledDate < new Date(today.getFullYear(), today.getMonth(), today.getDate())) { continue; }

      const submissionId = `SUB-${Date.now()}-${i}`;
      const newService: Service = {
        ...createDefaultServiceState(),
        submissionId, appointmentId: submissionId, timestamp: new Date().toISOString(), status: ServiceStatus.Queued,
        customerFirstName: subscription.customerFirstName, customerLastName: subscription.customerLastName, mobileNumber: subscription.mobileNumber,
        customerEmail: subscription.customerEmail,
        carNumber: subscription.carNumber, carBrandModel: subscription.carBrandModel, streetAddress: subscription.streetAddress,
        serviceSelection: ['Car Washing'], isSubscription: true, isAutoScheduled: true,
        scheduledDate: scheduledDate.toISOString().split('T')[0], scheduledTime: "09:00 - 10:00",
        acknowledgement: true,
      };
      newServices.push(newService);
    }

    if (newServices.length > 0) {
      setSubmissions(prev => [...prev, ...newServices]);
      newServices.forEach(s => cloudDataService.saveRecord('Submissions', s, settings.googleSheetsUrl));
      alert(`${newServices.length} washes have been automatically scheduled for this month.`);
    }
  };

  const handleMarkNotificationAsRead = (notificationId: string) => {
    let notifToSave: AppNotification | undefined;
    setNotifications(prev => prev.map(n => {
        if(n.id === notificationId) {
            notifToSave = { ...n, isRead: true };
            return notifToSave;
        }
        return n;
    }));
    // FIX: Changed 'n' to 'notifToSave' to fix variable not defined error.
    if(notifToSave) cloudDataService.saveRecord('Notifications', notifToSave, settings.googleSheetsUrl);
  };

  const handleMarkAllAsRead = () => {
    if (!currentUser) return;
    const notificationsToUpdate: AppNotification[] = [];
    setNotifications(prev => prev.map(n => {
        if((n.userId === currentUser.username || currentUser.role === 'admin' || currentUser.role === 'manager') && !n.isRead) {
            const updated = { ...n, isRead: true };
            notificationsToUpdate.push(updated);
            return updated;
        }
        return n;
    }));
    notificationsToUpdate.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
  };

  const handleManualNotifyAll = useCallback(() => {
    if (!currentUser || currentUser.role !== 'admin') return;

    const newNotifications: AppNotification[] = [];
    users.forEach(user => {
        const message = `Admin Broadcast from ${currentUser.username}: Please check the dashboard for updates.`;
        const notif: AppNotification = {
            id: `notif_manual_${Date.now()}_${user.username}`,
            userId: user.username, serviceId: 'manual_broadcast', message,
            timestamp: new Date().toISOString(), isRead: false, type: 'manual-admin'
        };
        newNotifications.push(notif);
        const prefs = user.notificationPreferences || defaultNotificationPrefs;
        if(prefs.enabled.manual) {
            playNotificationAlert(prefs);
            if(user.pushSubscription) sendPushNotification(user.pushSubscription, "Admin Broadcast", message, prefs);
        }
    });

    setNotifications(prev => [...prev, ...newNotifications]);
    newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
    setIsNotificationHistoryOpen(true);
}, [currentUser, users, settings.googleSheetsUrl]);

const handleNotifyForOrder = useCallback((serviceId: string) => {
    const service = submissions.find(s => s.submissionId === serviceId);
    if (!service || service.status === ServiceStatus.Completed || service.status === ServiceStatus.Draft) return;

    let newNotifications: AppNotification[] = [];
    let usersToNotify: User[] = [];

    if (service.status === ServiceStatus.Queued) {
        usersToNotify = users.filter(u => u.role === 'admin' || u.role === 'manager');
        usersToNotify.forEach(admin => {
            newNotifications.push({
                id: `notif_manual_order_${Date.now()}_${admin.username}`, userId: admin.username, serviceId: service.submissionId,
                message: `Admin Reminder: The queued order for ${service.customerFirstName} needs attention.`,
                timestamp: new Date().toISOString(), isRead: false, type: 'manual-order'
            });
        });
    } else if ((service.status === ServiceStatus.Assigned || service.status === ServiceStatus.InProgress) && service.assignedTo) {
        const assignedUser = users.find(u => u.username === service.assignedTo);
        if (assignedUser) {
            usersToNotify.push(assignedUser);
            newNotifications.push({
                id: `notif_manual_order_${Date.now()}_${service.assignedTo}`, userId: service.assignedTo, serviceId: service.submissionId,
                message: `Reminder: Please check on your assigned order for ${service.customerFirstName}.`,
                timestamp: new Date().toISOString(), isRead: false, type: 'manual-order'
            });
        }
    }

    if (newNotifications.length > 0) {
        setNotifications(prev => [...prev, ...newNotifications]);
        newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
        usersToNotify.forEach(user => {
            const prefs = user.notificationPreferences || defaultNotificationPrefs;
            if(prefs.enabled.manual) {
                playNotificationAlert(prefs);
                const message = newNotifications.find(n => n.userId === user.username)?.message || "Order Reminder";
                if(user.pushSubscription) sendPushNotification(user.pushSubscription, "Order Reminder", message, prefs);
            }
        });
    }
}, [submissions, users, settings.googleSheetsUrl]);

const handleUpdateNotificationPreferences = (username: string, prefs: NotificationPreferences) => {
    let userToSave: User | undefined;
    setUsers(prev => prev.map(u => {
        if(u.username === username) {
            userToSave = { ...u, notificationPreferences: prefs };
            return userToSave;
        }
        return u;
    }));
    if(currentUser?.username === username) {
        setCurrentUser(prev => prev ? ({...prev, notificationPreferences: prefs}) : null);
    }
    if(userToSave) cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
  };

const handleUpdatePushSubscription = (username: string, subscription: PushSubscriptionJSON | null) => {
    let userToSave: User | undefined;
    setUsers(prev => prev.map(u => {
        if(u.username === username) {
            userToSave = { ...u, pushSubscription: subscription || undefined };
            return userToSave;
        }
        return u;
    }));
    if(currentUser?.username === username) {
        setCurrentUser(prev => prev ? ({ ...prev, pushSubscription: subscription || undefined }) : null);
    }
    if(userToSave) cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
};

const handleSaveNewSpend = (spendData: Omit<MiscSpend, 'spendId' | 'userId' | 'timestamp' | 'status'>) => {
    if (!currentUser) return;
    const newSpend: MiscSpend = {
        ...spendData,
        spendId: `spend_${Date.now()}`,
        userId: currentUser.username,
        timestamp: new Date().toISOString(),
        status: MiscSpendStatus.Pending,
    };
    setMiscSpends(prev => [...prev, newSpend]);
    cloudDataService.saveRecord('MiscSpends', newSpend, settings.googleSheetsUrl);
    triggerHapticFeedback('success');
};

const handleUpdateSpendStatus = (spendId: string, status: MiscSpendStatus) => {
    const originalSpend = miscSpends.find(s => s.spendId === spendId);
    if (!originalSpend) {
        console.error(`Could not find MiscSpend with id ${spendId} to update.`);
        return;
    }

    const updatedSpend = { ...originalSpend, status };

    setMiscSpends(prevSpends => prevSpends.map(s => s.spendId === spendId ? updatedSpend : s));

    cloudDataService.saveRecord('MiscSpends', updatedSpend, settings.googleSheetsUrl);

    const wasPaid = originalSpend.status === MiscSpendStatus.Paid;
    const isNowPaid = status === MiscSpendStatus.Paid;

    if (!wasPaid && isNowPaid) {
        // Add income entry to bookkeeping
        const newExpenseEntry: BookkeepingEntry = {
            id: `bk_exp_${spendId}`,
            timestamp: new Date().toISOString(),
            type: BookkeepingEntryType.Expense,
            description: `${updatedSpend.spendType} by ${updatedSpend.userId}`,
            amount: updatedSpend.amount,
            relatedId: spendId,
            recordedBy: currentUser?.username || 'system',
        };
        setBookkeeping(prev => [...prev.filter(b => b.id !== newExpenseEntry.id), newExpenseEntry]);
        cloudDataService.saveRecord('Bookkeeping', newExpenseEntry, settings.googleSheetsUrl);
    } else if (wasPaid && !isNowPaid) {
        // Remove expense entry from bookkeeping
        setBookkeeping(prev => prev.filter(b => b.relatedId !== spendId));
        cloudDataService.deleteRecord('Bookkeeping', `bk_exp_${spendId}`, settings.googleSheetsUrl);
    }

    triggerHapticFeedback('success');
};

const handleUpdateAttendanceStatus = (username: string, status: AttendanceStatus) => {
    const newRecord = { timestamp: new Date().toISOString(), status };
    let userToSave: User | undefined;

    const updatedUsers = users.map(u => {
        if (u.username === username) {
            userToSave = {
                ...u,
                attendanceStatus: status,
                attendanceHistory: [...(u.attendanceHistory || []), newRecord]
            };
            return userToSave;
        }
        return u;
    });
    setUsers(updatedUsers);

    if (currentUser?.username === username) {
        const updatedCurrentUser = updatedUsers.find(u => u.username === username)!;
        setCurrentUser(updatedCurrentUser);
        localStorage.setItem('service_app_current_user', JSON.stringify(updatedCurrentUser));
    }
    if(userToSave) {
        cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
        triggerHapticFeedback('success');
    }
};

  const handleShareOrder = (service: Service) => {
    setSharingService(service);
  };

  const handlePermanentDelete = (service: Service) => {
      setSubmissions(prev => prev.filter(s => s.submissionId !== service.submissionId));
      cloudDataService.deleteRecord('Submissions', service.submissionId, settings.googleSheetsUrl);
  };

  const handleRestoreFromTrash = (service: Service) => {
      const restored = { ...service, isDeleted: false, timestamp: new Date().toISOString() };
      setSubmissions(prev => prev.map(s => s.submissionId === restored.submissionId ? restored : s));
      cloudDataService.saveRecord('Submissions', restored, settings.googleSheetsUrl);
  };

  if (publicService) {
    return <PublicServiceSummary serviceData={publicService.data} logoUrl={settings.customLogoUrl} />;
  }

  if (appIsLoading) {
    return <LoadingScreen />;
  }

  if (!currentUser) {
    return <LoginPage onLoginAttempt={handleLoginAttempt} error={loginError} />;
  }

  if (printingService) {
    return <PrintPreview service={printingService} onClose={() => setPrintingService(null)} serviceTemplates={serviceTemplates} />;
  }

  const currentUserNotifications = notifications
    .filter(n => n.userId === currentUser.username || currentUser.role === 'admin' || currentUser.role === 'manager')
    .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

  const unreadCount = currentUserNotifications.filter(n => !n.isRead).length;

  const renderView = () => {
    const hasPermission = (p: Permission) => currentUser.permissions.includes(p);

    switch(view) {
      case 'FORM':
        return hasPermission(Permission.CAN_CREATE_ORDERS) ? <ServiceForm 
                 initialService={editingService} 
                 allSubmissions={submissions}
                 onComplete={handleCompleteOrder}
                 onSaveDraft={handleSaveDraft}
                 onAdminUpdate={handleAdminUpdate}
                 onExit={() => { setView('DASHBOARD'); setEditingService(null); }}
                 googleDriveUploadUrl={settings.googleDriveUploadUrl}
                 currentUser={currentUser}
                 allUsers={users.map(({password, ...rest}) => rest)}
                 userSubscriptions={userSubscriptions}
                 serviceTemplates={serviceTemplates}
                 vehicleData={vehicleData}
                 tyreData={tyreData}
                 onUpdateVehicleData={handleUpdateVehicleData}
                 onUpdateTyreData={handleUpdateTyreData}
                 pricingConfig={settings.pricingConfig}
               /> : <DashboardPage {...dashboardProps} />;
      case 'LIST':
        return hasPermission(Permission.CAN_VIEW_SERVICE_HISTORY) ? <SubmissionList 
                 submissions={submissions.filter(s => !s.isDeleted)}
                 users={users.map(({password, ...rest}) => rest)}
                 onEdit={handleEditService}
                 onPrint={setPrintingService}
                 onSummarize={setSummarizingService}
                 currentUser={currentUser}
                 serviceTemplates={serviceTemplates}
               /> : <DashboardPage {...dashboardProps} />;
      case 'APPOINTMENTS_OVERVIEW':
        return hasPermission(Permission.CAN_VIEW_APPOINTMENTS_OVERVIEW) ? <AppointmentsOverviewPage
                    currentUser={currentUser}
                    submissions={submissions.filter(s => !s.isDeleted)}
                    onUpdateOrder={handleEditService}
                    onStartOrder={handleStartOrder}
                    onShareOrder={handleShareOrder}
                /> : <DashboardPage {...dashboardProps} />;
      case 'NOTIFICATION_PREFERENCES':
        return <NotificationPreferencesPage
                 currentUser={currentUser}
                 onSave={handleUpdateNotificationPreferences}
                 onUpdatePushSubscription={handleUpdatePushSubscription}
               />;
      case 'USER_MANAGEMENT':
        return hasPermission(Permission.CAN_MANAGE_USERS) ? <UserManagementPage
                 users={users.map(({password, ...rest}) => rest)}
                 onUpdateUsers={handleUpdateUsers}
                 fullUserList={users}
                 currentUser={currentUser}
               /> : <DashboardPage {...dashboardProps} />;
      case 'SERVICE_TEMPLATE_MANAGEMENT':
        return hasPermission(Permission.CAN_MANAGE_SERVICES) ? <ServiceTemplateManagementPage
                  templates={serviceTemplates}
                  onUpdateTemplates={handleUpdateServiceTemplates}
                  onEditTemplate={handleEditTemplate}
                /> : <DashboardPage {...dashboardProps} />;
       case 'SERVICE_TEMPLATE_EDITOR':
        return hasPermission(Permission.CAN_MANAGE_SERVICES) ? <ServiceTemplateEditorPage
                  template={editingTemplate!}
                  onSave={handleSaveServiceTemplate}
                  onExit={() => { setView('SERVICE_TEMPLATE_MANAGEMENT'); setEditingTemplate(null); }}
               /> : <DashboardPage {...dashboardProps} />;
      case 'PLAN_MANAGEMENT':
          return hasPermission(Permission.CAN_MANAGE_PLANS) ? <SubscriptionPlanManagementPage
                    plans={subscriptionPlans}
                    onUpdatePlans={handleUpdateSubscriptionPlans}
                /> : <DashboardPage {...dashboardProps} />;
      case 'USER_SUBSCRIPTION_MANAGEMENT':
          return hasPermission(Permission.CAN_MANAGE_SUBSCRIPTIONS) ? <UserSubscriptionManagementPage
                    userSubscriptions={userSubscriptions}
                    subscriptionPlans={subscriptionPlans}
                    onUpdateUserSubscriptions={handleUpdateUserSubscriptions}
                    onAutoSchedule={handleAutoSchedule}
                 /> : <DashboardPage {...dashboardProps} />;
      case 'SERVICE_REQUEST':
        return hasPermission(Permission.CAN_VIEW_SERVICE_REQUESTS) ? <ServiceRequestPage
                 serviceRequests={serviceRequests}
               /> : <DashboardPage {...dashboardProps} />;
       case 'LIVE_MAP':
        return hasPermission(Permission.CAN_VIEW_LIVE_MAP) ? <LiveMapPage
                 users={users.map(({password, ...rest}) => rest)}
                 currentUser={currentUser}
                 submissions={submissions.filter(s => !s.isDeleted)}
                 onRefresh={handleManualRefresh}
                 isRefreshing={isManualRefreshing}
                 locationHistory={locationHistory}
               /> : <DashboardPage {...dashboardProps} />;
      case 'ANALYTICS':
        return hasPermission(Permission.CAN_VIEW_ANALYTICS) ? <AnalyticsPage
                 submissions={submissions.filter(s => !s.isDeleted)}
                 users={users.map(({password, ...rest}) => rest)}
                 serviceTemplates={serviceTemplates}
                 profitLossData={profitLossData}
                 onSaveProfitLoss={handleUpdateProfitLoss}
               /> : <DashboardPage {...dashboardProps} />;
       case 'CUSTOMER_HISTORY':
        return hasPermission(Permission.CAN_VIEW_CUSTOMER_HISTORY) ? <CustomerHistoryPage
                 submissions={submissions.filter(s => !s.isDeleted)}
                 currentUser={currentUser}
                 onShareOrder={handleShareOrder}
               /> : <DashboardPage {...dashboardProps} />;
      case 'RETENTION':
        return hasPermission(Permission.CAN_VIEW_RETENTION_DASHBOARD) ? <RetentionDashboard
                 submissions={submissions.filter(s => !s.isDeleted)}
                 onCreateFollowUp={handleCreateFollowUp}
                 settings={settings}
                 onUpdateKpiTargets={handleUpdateKpiTargets}
               /> : <DashboardPage {...dashboardProps} />;
      case 'BOOKKEEPING':
        return hasPermission(Permission.CAN_LOG_EXPENSES) ? <BookkeepingPage
            currentUser={currentUser}
            miscSpends={miscSpends}
            users={users.map(({password, ...rest}) => rest)}
            googleDriveUploadUrl={settings.googleDriveUploadUrl}
            onSaveNewSpend={handleSaveNewSpend}
            onUpdateSpendStatus={handleUpdateSpendStatus}
            bookkeeping={bookkeeping}
            spendCategories={spendCategories}
        /> : <DashboardPage {...dashboardProps} />;
      case 'SPEND_CATEGORY_MANAGEMENT':
        return hasPermission(Permission.CAN_MANAGE_SPEND_CATEGORIES) ? <SpendCategoryManagementPage
            categories={spendCategories}
            onUpdateCategories={handleUpdateSpendCategories}
        /> : <DashboardPage {...dashboardProps} />;
      case 'TRASH':
          return hasPermission(Permission.CAN_VIEW_TRASH) ? <TrashPage
              deletedSubmissions={submissions.filter(s => s.isDeleted)}
              onRestore={handleRestoreFromTrash}
              onPermanentDelete={handlePermanentDelete}
          /> : <DashboardPage {...dashboardProps} />;
      case 'PRICING_MANAGEMENT':
          return hasPermission(Permission.CAN_MANAGE_PRICING) ? <PricingManagementPage
              pricingConfig={settings.pricingConfig || DEFAULT_PRICING_CONFIG}
              onUpdatePricing={(cfg) => {
                  const newSettings = { ...settings, pricingConfig: cfg };
                  setSettings(newSettings);
                  cloudDataService.saveRecord('Settings', newSettings, settings.googleSheetsUrl);
              }}
          /> : <DashboardPage {...dashboardProps} />;
      case 'DASHBOARD':
        return hasPermission(Permission.CAN_VIEW_DASHBOARD) ? <DashboardPage {...dashboardProps} /> : <div>Access Denied</div>;
      default:
        return <div>Unknown view</div>;
    }
  };

  const dashboardProps = {
    submissions: submissions.filter(s => !s.isDeleted),
    users: users.map(({password, ...rest}) => rest),
    currentUser,
    onCreateOrder: handleCreateOrder,
    onAssignOrder: handleAssignOrder,
    onStartOrder: handleStartOrder,
    onUpdateOrder: handleEditService,
    onSelfAssignOrder: handleSelfAssignOrder,
    onDeleteOrder: handleDeleteRequest,
    onScheduleDroppedOrder: handleScheduleDroppedOrder,
    onNotifyForOrder: handleNotifyForOrder,
    onUpdateAttendanceStatus: handleUpdateAttendanceStatus,
    userSubscriptions,
    serviceTemplates,
    setIsChatbotOpen,
    settings,
    locationHistory,
    vehicleData,
    tyreData,
    onShareOrder: handleShareOrder,
  };

  return (
    <div className="min-h-screen bg-slate-100 flex">
      {isSettingsOpen && currentUser.permissions.includes(Permission.CAN_EDIT_SETTINGS) && (
        <SettingsModal 
          initialSettings={settings}
          onClose={() => setIsSettingsOpen(false)} 
          onSave={handleSaveSettings}
        />
      )}

      {summarizingService && (
          <SummaryModal 
            service={summarizingService}
            onClose={() => setSummarizingService(null)}
          />
      )}

      {sharingService && (
        <ShareOrderModal 
          service={sharingService}
          onClose={() => setSharingService(null)}
        />
      )}

      {isChatbotOpen && (
        <ChatbotModal
            isOpen={isChatbotOpen}
            onClose={() => setIsChatbotOpen(false)}
            onSubmit={handleSaveDraftFromChatbot}
            serviceTemplates={serviceTemplates}
        />
       )}

      {deletingService && (
        <DeleteConfirmationModal
            isOpen={!!deletingService}
            onClose={() => setDeletingService(null)}
            onConfirm={handleConfirmDelete}
            service={deletingService}
        />
      )}

      <Sidebar
          currentUser={currentUser}
          currentView={view}
          onNavigate={handleNavigate}
          onNewService={() => handleEditService(null)}
          onOpenSettings={() => setIsSettingsOpen(true)}
          onLogout={handleLogout}
          logoUrl={settings.customLogoUrl}
          logoHasError={logoHasError}
          onLogoError={() => setLogoHasError(true)}
          isMinimized={isSidebarMinimized}
          isOpenOnMobile={isMobileMenuOpen}
          onToggleDesktop={() => setIsSidebarMinimized(!isSidebarMinimized)}
          onCloseMobile={() => setIsMobileMenuOpen(false)}
      />

       {isMobileMenuOpen && <div className="fixed inset-0 bg-black/60 z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)}></div>}

      <div className={`flex-1 transition-all duration-300 ${isSidebarMinimized ? 'md:pl-20' : 'md:pl-64'}`}>
          <header className="sticky top-0 bg-slate-100/80 backdrop-blur-md z-30 border-b border-slate-200 no-print">
              <div className="relative flex items-center justify-between min-h-16 px-4 md:px-6 py-2 gap-2">
                  <button className="md:hidden text-slate-600" onClick={() => setIsMobileMenuOpen(true)} aria-label="Open menu">
                      <IconMenu2 className="w-6 h-6" />
                  </button>
                  <div className="flex items-center gap-2 flex-wrap justify-end">
                      <RealTimeClock />
                      <div className="h-6 w-px bg-slate-300 hidden sm:block"></div>
                      <NotificationBell 
                          unreadCount={unreadCount}
                          onClick={() => setIsNotificationHistoryOpen(prev => !prev)}
                      />
                      {currentUser.role === 'admin' && (
                          <button
                              onClick={handleManualNotifyAll}
                              className="p-2 text-slate-500 hover:text-slate-800 hover:bg-slate-200 rounded-full transition-colors"
                              aria-label="Send broadcast notification to all users"
                              title="Send a notification to all users"
                          >
                              <IconBellRinging className="w-6 h-6" />
                          </button>
                      )}
                      <button
                          onClick={handleManualRefresh}
                          disabled={isManualRefreshing || !settings.googleSheetsUrl}
                          className="p-2 text-slate-500 hover:text-slate-800 hover:bg-slate-200 rounded-full transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                          aria-label="Refresh data from cloud"
                          title={!settings.googleSheetsUrl ? "Cloud sync is offline. Check settings." : "Refresh data from cloud"}
                      >
                          <IconRefresh className={`w-6 h-6 ${isManualRefreshing ? 'animate-spin' : ''}`} />
                      </button>
                      <SyncStatusIndicator status={syncStatus} errorMessage={syncError} />
                  </div>
                   {isNotificationHistoryOpen && (
                        <NotificationHistory
                            notifications={currentUserNotifications}
                            onMarkAsRead={handleMarkNotificationAsRead}
                            onMarkAllAsRead={handleMarkAllAsRead}
                            onClose={() => setIsNotificationHistoryOpen(false)}
                        />
                    )}
              </div>
          </header>

          <main className="p-4 sm:p-6 lg:p-8 w-full">
            {syncStatus === 'ERROR' && syncError && (
                <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 relative mb-6 rounded-r-md" role="alert">
                    <strong className="font-bold">Sync Error:</strong>
                    <span className="block sm:inline ml-2">{syncError}</span>
                    <button 
                      onClick={() => setSyncError(null)} 
                      className="absolute top-0 bottom-0 right-0 px-4 py-3"
                      aria-label="Dismiss error message"
                    >
                      <IconX className="h-6 w-6 text-red-500" />
                    </button>
                </div>
            )}

            {renderView()}
          </main>
      </div>
    </div>
  );
};

// FIX: Added PaymentMode type for service billing.
