// --- ROBUST PARSING HELPERS ---
export const robustParseFloat = (value: any): number => {
    if (typeof value === 'number') return value;
    if (typeof value !== 'string') return 0;

    // Remove currency symbols (e.g., ₹, $), commas, and whitespace
