  const handleCompleteOrder = (service: Service) => {
    const isUpdating = submissions.some(s => s.submissionId === service.submissionId);
    let serviceToSave: Service;
    let wasSubscriptionUpdated = false;
    let finalUserSubscriptions = userSubscriptions;
    let serviceWithCleanedQuantities = { ...service };

    let newNotifications: AppNotification[] = [];

    const canAdminEdit = currentUser?.permissions.includes(Permission.CAN_EDIT_ANY_ORDER);

    if (isUpdating) {
        const originalService = submissions.find(s => s.submissionId === service.submissionId)!;

        const finalStatus = canAdminEdit 
            ? service.status
            : ServiceStatus.Completed;

        serviceToSave = {
            ...serviceWithCleanedQuantities, 
            status: finalStatus,
            timestamp: new Date().toISOString(),
            submittedBy: originalService.submittedBy || currentUser?.username,
        };

        const wasCompleted = originalService.status === ServiceStatus.Completed;
        const isNowCompleted = finalStatus === ServiceStatus.Completed;

        if (!wasCompleted && isNowCompleted) {
            // Add income entry to bookkeeping
            const newIncomeEntry: BookkeepingEntry = {
                id: `bk_inc_${serviceToSave.submissionId}`,
                timestamp: new Date().toISOString(),
                type: BookkeepingEntryType.Income,
                description: `Service for ${serviceToSave.customerFirstName} (#${serviceToSave.appointmentId?.split('-').pop()})`,
                amount: serviceToSave.grandTotal,
                relatedId: serviceToSave.submissionId,
                recordedBy: serviceToSave.submittedBy || currentUser?.username || 'system',
            };
            setBookkeeping(prev => [...prev.filter(b => b.id !== newIncomeEntry.id), newIncomeEntry]);
            cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);

            if (serviceToSave.isSubscription && serviceToSave.serviceSelection.includes('Car Washing')) {
                const userSubIndex = userSubscriptions.findIndex(sub => sub.mobileNumber === serviceToSave.mobileNumber);
                if (userSubIndex > -1) {
                    const updatedSubs = [...userSubscriptions];
                    const subToUpdate = {...updatedSubs[userSubIndex]};
                    const washesUsed = serviceToSave.carWashDetails ? 1 : (serviceToSave.carwashQuantity || 1);
                    subToUpdate.washesRemaining = Math.max(0, subToUpdate.washesRemaining - washesUsed);
                    updatedSubs[userSubIndex] = subToUpdate;
                    finalUserSubscriptions = updatedSubs;
                    wasSubscriptionUpdated = true;
                    cloudDataService.saveRecord('UserSubscriptions', subToUpdate, settings.googleSheetsUrl);
                }
            }
            if (serviceToSave.assignedTo) {
                 const message = `Completed: Order #${serviceToSave.appointmentId?.split('-').pop()} for ${serviceToSave.customerFirstName} is complete.`;
                 newNotifications.push({
                    id: `notif_complete_${serviceToSave.submissionId}`,
                    userId: serviceToSave.assignedTo,
                    serviceId: serviceToSave.submissionId,
                    message,
                    timestamp: new Date().toISOString(),
                    isRead: false,
                    type: 'completed'
                });
            }
            sendCustomerEmailNotification(serviceToSave);
        } else if (wasCompleted && !isNowCompleted) {
            // Remove income entry from bookkeeping
            setBookkeeping(prev => prev.filter(b => b.relatedId !== serviceToSave.submissionId));
            cloudDataService.deleteRecord('Bookkeeping', `bk_inc_${serviceToSave.submissionId}`, settings.googleSheetsUrl);
        }

    } else {
        serviceToSave = {
            ...serviceWithCleanedQuantities,
            status: ServiceStatus.Completed,
            assignedTo: currentUser?.username,
            submittedBy: currentUser?.username,
            timestamp: new Date().toISOString(),
        };

        const newIncomeEntry: BookkeepingEntry = {
            id: `bk_inc_${serviceToSave.submissionId}`,
            timestamp: new Date().toISOString(),
            type: BookkeepingEntryType.Income,
            description: `Service for ${serviceToSave.customerFirstName} (#${serviceToSave.appointmentId?.split('-').pop()})`,
            amount: serviceToSave.grandTotal,
            relatedId: serviceToSave.submissionId,
            recordedBy: serviceToSave.submittedBy || currentUser?.username || 'system',
        };
        setBookkeeping(prev => [...prev.filter(b => b.id !== newIncomeEntry.id), newIncomeEntry]);
        cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);

        if (serviceToSave.isSubscription && serviceToSave.serviceSelection.includes('Car Washing')) {
             const userSubIndex = userSubscriptions.findIndex(sub => sub.mobileNumber === serviceToSave.mobileNumber);
            if (userSubIndex > -1) {
                const updatedSubs = [...userSubscriptions];
                const subToUpdate = {...updatedSubs[userSubIndex]};
                const washesUsed = serviceToSave.carWashDetails ? 1 : (serviceToSave.carwashQuantity || 1);
                subToUpdate.washesRemaining = Math.max(0, subToUpdate.washesRemaining - washesUsed);
                updatedSubs[userSubIndex] = subToUpdate;
                finalUserSubscriptions = updatedSubs;
                wasSubscriptionUpdated = true;
                cloudDataService.saveRecord('UserSubscriptions', subToUpdate, settings.googleSheetsUrl);
            }
        }
         if (serviceToSave.assignedTo) {
             const message = `Completed: Order #${serviceToSave.appointmentId?.split('-').pop()} for ${serviceToSave.customerFirstName} is complete.`;
             newNotifications.push({
                id: `notif_complete_${serviceToSave.submissionId}`,
                userId: serviceToSave.assignedTo,
                serviceId: serviceToSave.submissionId,
                message,
                timestamp: new Date().toISOString(),
                isRead: false,
                type: 'completed'
            });
        }
        sendCustomerEmailNotification(serviceToSave);
    }

    const updatedSubmissions = isUpdating 
        ? submissions.map(s => s.submissionId === service.submissionId ? serviceToSave : s)
        : [...submissions, serviceToSave];

    setSubmissions(updatedSubmissions);
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);

    if(wasSubscriptionUpdated) {
        setUserSubscriptions(finalUserSubscriptions);
    }

    if (newNotifications.length > 0) {
        setNotifications(prev => [...prev, ...newNotifications]);
        newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));

        const targetUser = users.find(u => u.username === serviceToSave.assignedTo);
        const prefs = targetUser?.notificationPreferences || defaultNotificationPrefs;
        if (prefs.enabled.completed) {
            playNotificationAlert(prefs);
            if(targetUser?.pushSubscription) sendPushNotification(targetUser.pushSubscription, "Order Completed", newNotifications[0].message, prefs);
        }
    }

    triggerHapticFeedback('success');
    setView('DASHBOARD');
    setEditingService(null);
  };

