        cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);
        sendCustomerEmailNotification(service);
    } else if (wasCompleted && !isNowCompleted) {
        setBookkeeping(prev => prev.filter(b => b.relatedId !== service.submissionId));
        cloudDataService.deleteRecord('Bookkeeping', `bk_inc_${service.submissionId}`, settings.googleSheetsUrl);
