   const handleUpdateVehicleData = useCallback((newBrand: string, newModel: string) => {
    setVehicleData(prev => {
        if (!newBrand || !newModel) return prev;
        const newData = JSON.parse(JSON.stringify(prev)); // Deep copy
        if (!newData[newBrand]) {
            newData[newBrand] = [];
        }
        if (!newData[newBrand].includes(newModel)) {
            newData[newBrand].push(newModel);
            cloudDataService.saveRecord('VehicleData', { id: 'singleton', data: JSON.stringify(newData) }, settings.googleSheetsUrl);
        }
        return newData;
    });
