// Modal for managing predefined costs
const PredefinedCostSettingsModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    costs: PredefinedCost[];
    onUpdate: (costs: PredefinedCost[]) => void;
}> = ({ isOpen, onClose, costs, onUpdate }) => {
    const [localCosts, setLocalCosts] = useState<PredefinedCost[]>(costs);

    useEffect(() => {
        if (isOpen) setLocalCosts(costs);
    }, [isOpen, costs]);

    if (!isOpen) return null;

    const handleAdd = () => {
        setLocalCosts(prev => [...prev, { id: `pc_${Date.now()}`, name: '', value: 0 }]);
    };

    const handleUpdate = (id: string, field: keyof PredefinedCost, val: string | number) => {
        setLocalCosts(prev => prev.map(c => c.id === id ? { ...c, [field]: val } : c));
    };

    const handleDelete = (id: string) => {
        setLocalCosts(prev => prev.filter(c => c.id !== id));
    };

    const handleSave = () => {
        onUpdate(localCosts.filter(c => c.name.trim() !== ''));
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-[70] p-4 modal-backdrop" onClick={onClose}>
            <div onClick={(e) => e.stopPropagation()} className="w-full max-w-lg modal-content">
                <Card title="Manage Quick-Add Costs">
                    <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-2">
                        {localCosts.map((cost) => (
                            <div key={cost.id} className="flex gap-2 items-end p-2 bg-slate-50 rounded border">
                                <div className="flex-grow">
                                    <Input 
                                        label="Name" 
                                        id={`pc-name-${cost.id}`}
                                        value={cost.name} 
                                        onChange={e => handleUpdate(cost.id, 'name', e.target.value)} 
                                        placeholder="e.g., Oil Filter"
                                    />
                                </div>
                                <div className="w-24">
                                    <Input 
                                        label="Cost" 
                                        id={`pc-val-${cost.id}`}
                                        type="number" 
                                        value={cost.value} 
                                        onChange={e => handleUpdate(cost.id, 'value', parseFloat(e.target.value) || 0)} 
                                    />
                                </div>
                                <Button variant="danger" size="sm" className="mb-0.5 p-2 h-10 w-10" onClick={() => handleDelete(cost.id)}>
                                    <IconTrash className="w-5 h-5" />
                                </Button>
                            </div>
                        ))}
                        <Button variant="ghost" onClick={handleAdd} className="w-full">
                            <IconPlus className="w-4 h-4 mr-2" /> Add New Cost Preset
                        </Button>
                    </div>
                    <div className="mt-6 flex justify-end gap-2 pt-4 border-t">
                        <Button variant="ghost" onClick={onClose}>Cancel</Button>
                        <Button onClick={handleSave}>Save Presets</Button>
                    </div>
                </Card>
            </div>
        </div>
    );
};

// Sub-component for individual P&L Entry
const ProfitLossEntryRow: React.FC<{ 
    service: Service, 
    profitLoss: ProfitLoss | undefined, 
    onSave: (pl: ProfitLoss) => void,
    predefinedCosts: PredefinedCost[]
}> = ({ service, profitLoss, onSave, predefinedCosts }) => {
    const defaultMaterial = service.tyreMaterialCost || 0;
    const defaultLabor = service.tyreLaborCost || 0;

    const [pl, setPl] = useState<ProfitLoss>(profitLoss || {
        serviceId: service.submissionId,
        materialCost: defaultMaterial,
        laborCost: defaultLabor,
        otherExpenses: 0,
        calculatedProfit: service.grandTotal - defaultMaterial - defaultLabor,
        notes: ''
    });

    const [isSaved, setIsSaved] = useState(!!profitLoss);

    const calculateProfit = (material: number, labor: number, other: number) => {
        return service.grandTotal - material - labor - other;
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        const numValue = name !== 'notes' ? parseFloat(value) || 0 : 0;

        setPl(prev => {
            const updated = { ...prev, [name]: name === 'notes' ? value : numValue };
            if (name !== 'notes') {
                updated.calculatedProfit = calculateProfit(
                    name === 'materialCost' ? numValue : updated.materialCost,
                    name === 'laborCost' ? numValue : updated.laborCost,
                    name === 'otherExpenses' ? numValue : updated.otherExpenses
                );
            }
            return updated;
        });
        setIsSaved(false);
    };

    const applyPreset = (cost: number, name: string) => {
        setPl(prev => {
            const updatedOther = prev.otherExpenses + cost;
            const updatedNotes = prev.notes ? `${prev.notes}, ${name}` : name;
            return {
                ...prev,
                otherExpenses: updatedOther,
                notes: updatedNotes,
                calculatedProfit: calculateProfit(prev.materialCost, prev.laborCost, updatedOther)
            };
        });
        setIsSaved(false);
    };

    return (
        <div className="p-4 bg-slate-50 rounded-lg border border-slate-200 mb-4">
            <div className="flex justify-between items-start mb-4">
                <div>
                    <p className="font-bold text-slate-800 flex items-center gap-2">
                        <span>#{service.appointmentId?.split('-').pop()} - {service.customerFirstName} {service.customerLastName}</span>
                    </p>
                    <p className="text-xs text-slate-500 mt-0.5">{service.carBrandModel} • {service.serviceSelection.join(', ')}</p>
                </div>
                <div className="text-right">
                    <p className="text-xs text-slate-400 font-semibold uppercase">Job Total</p>
                    <p className="text-lg font-bold text-slate-800">₹{service.grandTotal.toFixed(2)}</p>
                </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 items-end">
                <Input label="Material Cost (₹)" name="materialCost" type="number" value={pl.materialCost} onChange={handleChange} className="bg-white" />
                <Input label="Labor Cost (₹)" name="laborCost" type="number" value={pl.laborCost} onChange={handleChange} className="bg-white" />
                <Input label="Other Exp. (₹)" name="otherExpenses" type="number" value={pl.otherExpenses} onChange={handleChange} className="bg-white" />
                <div className="flex flex-col h-full justify-end pb-1 px-2 bg-slate-100 rounded border border-slate-200">
                    <p className="text-[10px] font-bold text-slate-500 uppercase">Est. Net Profit</p>
                    <p className={`text-xl font-bold ${pl.calculatedProfit >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                        ₹{pl.calculatedProfit.toFixed(2)}
                    </p>
                </div>
            </div>

            {predefinedCosts.length > 0 && (
                <div className="mt-3 flex flex-wrap gap-2 items-center">
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Quick Add:</span>
                    {predefinedCosts.map(cost => (
                        <button 
                            key={cost.id} 
                            onClick={() => applyPreset(cost.value, cost.name)}
                            className="px-2 py-1 text-xs bg-white border border-slate-200 rounded hover:border-brand-accent hover:text-brand-blue transition-all shadow-sm flex items-center gap-1"
                        >
                            <span className="font-semibold">{cost.name}</span>
                            <span className="text-slate-400">₹{cost.value}</span>
                        </button>
                    ))}
                </div>
            )}

            <div className="mt-4 flex items-center gap-4">
                <div className="flex-grow">
                     <textarea
                        name="notes"
                        value={pl.notes || ''}
                        onChange={handleChange}
                        rows={1}
                        className="w-full px-3 py-1.5 border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-brand-accent sm:text-sm bg-white"
                        placeholder="Expense notes..."
                    />
                </div>
                <Button 
                    onClick={() => { onSave(pl); setIsSaved(true); }} 
                    size="sm" 
                    variant={isSaved ? "ghost" : "primary"}
                    className="flex-shrink-0 h-10"
                >
                    {isSaved ? <><IconCheck className="w-4 h-4 mr-1.5 text-green-600" /> Saved</> : <><IconDeviceFloppy className="w-4 h-4 mr-1.5" /> Save</>}
                </Button>
            </div>
        </div>
    );
};

