export const AnalyticsPage: React.FC<AnalyticsPageProps> = ({ submissions, users, serviceTemplates, profitLossData, onSaveProfitLoss, predefinedCosts, onUpdatePredefinedCosts }) => {
    const today = new Date().toISOString().split('T')[0];
    const thirtyDaysAgo = new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0];

    const [filters, setFilters] = useState({
        startDate: thirtyDaysAgo,
        endDate: today,
        user: '',
        serviceType: ''
    });
    const [view, setView] = useState<'dashboard' | 'table' | 'profit-loss'>('dashboard');
    const [isExportModalOpen, setIsExportModalOpen] = useState(false);
    const [isCostSettingsOpen, setIsCostSettingsOpen] = useState(false);
    const [isExporting, setIsExporting] = useState(false);
    const [openMonths, setOpenMonths] = useState<Record<string, boolean>>({});

    const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFilters(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const filteredSubmissions = useMemo(() => {
        const completed = submissions.filter(s => s.status === ServiceStatus.Completed);

        const startDate = filters.startDate ? new Date(filters.startDate) : null;
        if(startDate) startDate.setHours(0,0,0,0);

        const endDate = filters.endDate ? new Date(filters.endDate) : null;
        if(endDate) endDate.setHours(23,59,59,999);

        return completed.filter(s => {
            const serviceDate = new Date(s.timestamp);
            const matchesDate = (!startDate || serviceDate >= startDate) && (!endDate || serviceDate <= endDate);
            const matchesUser = !filters.user || s.assignedTo === filters.user;
            const matchesService = !filters.serviceType || s.serviceSelection.includes(filters.serviceType);
            return matchesDate && matchesUser && matchesService;
        });
    }, [submissions, filters]);

    const pnlGroupedData = useMemo(() => {
        const grouped: Record<string, Service[]> = {};
        filteredSubmissions.forEach(s => {
            const date = new Date(s.timestamp);
            const monthYear = `${date.toLocaleString('default', { month: 'long' })} ${date.getFullYear()}`;
            if (!grouped[monthYear]) grouped[monthYear] = [];
            grouped[monthYear].push(s);
        });
        return Object.entries(grouped).sort((a, b) => new Date(b[1][0].timestamp).getTime() - new Date(a[1][0].timestamp).getTime());
    }, [filteredSubmissions]);

    const kpiData = useMemo(() => {
        let totalRevenue = 0;
        let totalCost = 0;

        filteredSubmissions.forEach(s => {
            totalRevenue += s.grandTotal;
            const pl = (profitLossData || []).find(p => p.serviceId === s.submissionId);
            if (pl) {
                totalCost += (pl.materialCost || 0) + (pl.laborCost || 0) + (pl.otherExpenses || 0);
            }
        });

        const netProfit = totalRevenue - totalCost;
        const profitMargin = totalRevenue > 0 ? (netProfit / totalRevenue) * 100 : 0;
        const completedServices = filteredSubmissions.length;

        return { totalRevenue, totalCost, netProfit, profitMargin, completedServices };
    }, [filteredSubmissions, profitLossData]);

    const handleExport = async () => {
        setIsExportModalOpen(false);
        // Export logic here
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4">
                 <h1 className="text-3xl font-bold text-slate-800 tracking-tight">Business Intelligence</h1>
                 <div className="flex items-center gap-2">
                    <div className="flex bg-slate-200 p-1 rounded-lg">
                        <button onClick={() => setView('dashboard')} className={`px-4 py-2 text-xs font-bold rounded-md transition-all flex items-center gap-2 ${view === 'dashboard' ? 'bg-white text-brand-blue shadow-sm' : 'text-slate-600 hover:text-slate-800'}`}>
                            <IconChartBar className="w-4 h-4" /> DASHBOARD
                        </button>
                        <button onClick={() => setView('profit-loss')} className={`-ml-px px-4 py-2 text-xs font-bold rounded-md transition-all flex items-center gap-2 ${view === 'profit-loss' ? 'bg-white text-brand-blue shadow-sm' : 'text-slate-600 hover:text-slate-800'}`}>
                            <IconFileAnalytics className="w-4 h-4" /> COST ENTRY
                        </button>
                        <button onClick={() => setView('table')} className={`-ml-px px-4 py-2 text-xs font-bold rounded-md transition-all flex items-center gap-2 ${view === 'table' ? 'bg-white text-brand-blue shadow-sm' : 'text-slate-600 hover:text-slate-800'}`}>
                            <IconTable className="w-4 h-4" /> LEDGER
                        </button>
                    </div>
                    <Button variant="secondary" onClick={() => setIsExportModalOpen(true)}>
                        <IconFileAnalytics className="w-5 h-5 mr-2"/>
                        Export
                    </Button>
                </div>
            </div>

            <Card title="Query Filter">
                 <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                    <Input label="From Date" name="startDate" type="date" value={filters.startDate} onChange={handleFilterChange} />
                    <Input label="To Date" name="endDate" type="date" value={filters.endDate} onChange={handleFilterChange} />
                    <div>
                        <label htmlFor="user" className="block text-sm font-medium text-slate-700 mb-1">Agent</label>
                        <select id="user" name="user" value={filters.user} onChange={handleFilterChange} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm">
                            <option value="">All Agents</option>
                            {users.map(u => <option key={u.username} value={u.username}>{u.username}</option>)}
                        </select>
                    </div>
                     <div>
                        <label htmlFor="serviceType" className="block text-sm font-medium text-slate-700 mb-1">Service Type</label>
                        <select id="serviceType" name="serviceType" value={filters.serviceType} onChange={handleFilterChange} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm">
                            <option value="">All Services</option>
                            {serviceTemplates.map(t => <option key={t.id} value={t.name}>{t.name}</option>)}
                        </select>
                    </div>
                </div>
            </Card>

            {view === 'dashboard' && (
                <>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                        <StatCard title="Total Revenue" value={`₹${kpiData.totalRevenue.toLocaleString('en-IN')}`} icon={<IconReceipt className="w-6 h-6 text-green-600"/>} iconBg="bg-green-100" />
                        <StatCard title="Total Operating Cost" value={`₹${kpiData.totalCost.toLocaleString('en-IN')}`} icon={<IconCreditCard className="w-6 h-6 text-red-600"/>} iconBg="bg-red-100" />
                        <StatCard title="Net Profit" value={`₹${kpiData.netProfit.toLocaleString('en-IN')}`} icon={<IconChartBar className="w-6 h-6 text-blue-600"/>} iconBg="bg-blue-100" subtext={`Profit Margin: ${kpiData.profitMargin.toFixed(1)}%`} />
                    </div>
                </>
            )}

            {view === 'profit-loss' && (
                <div className="space-y-4">
                    <Card>
                        <div className="flex justify-between items-center mb-6">
                            <div>
                                <h2 className="text-xl font-bold text-slate-800">Job-by-Job Cost Entry</h2>
                                <p className="text-sm text-slate-500">Track actual profitability for each completed service.</p>
                            </div>
                            <Button variant="ghost" onClick={() => setIsCostSettingsOpen(true)}>
                                <IconSettings className="w-5 h-5 mr-2" />
                                Quick Add Settings
                            </Button>
                        </div>

                        <div className="space-y-6">
                            {pnlGroupedData.map(([month, services]) => (
                                <div key={month} className="border-b border-slate-200 last:border-0 pb-6">
                                    <button 
                                        onClick={() => setOpenMonths(prev => ({ ...prev, [month]: !prev[month] }))}
                                        className="w-full flex justify-between items-center py-2 text-lg font-bold text-slate-700"
                                    >
                                        <span>{month}</span>
                                        <IconChevronDown className={`w-5 h-5 transition-transform ${openMonths[month] ? 'rotate-180' : ''}`} />
                                    </button>

                                    {openMonths[month] && (
                                        <div className="mt-4 space-y-4">
                                            {services.map(service => (
                                                <ProfitLossEntryRow 
                                                    key={service.submissionId}
                                                    service={service}
                                                    profitLoss={profitLossData.find(p => p.serviceId === service.submissionId)}
                                                    onSave={onSaveProfitLoss || (() => {})}
                                                    predefinedCosts={predefinedCosts}
                                                />
                                            ))}
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </Card>
                </div>
            )}

            {view === 'table' && <DataTableReport submissions={filteredSubmissions} profitLossData={profitLossData} />}

            <PredefinedCostSettingsModal 
                isOpen={isCostSettingsOpen} 
                onClose={() => setIsCostSettingsOpen(false)} 
                costs={predefinedCosts} 
                onUpdate={onUpdatePredefinedCosts || (() => {})} 
            />

            <ExportReportModal 
                isOpen={isExportModalOpen}
                onClose={() => setIsExportModalOpen(false)}
                onExport={handleExport}
                isExporting={isExporting}
            />
        </div>
    );
};

