// --- QUOTA MANAGEMENT UTILITIES ---

/**
 * Strips massive strings (like base64 images) from objects before local storage persistence.
 * Critical for keeping the 5MB localStorage quota from being exceeded.
 */
const prepareForLocalStorage = (data: any): any => {
    if (!data) return data;
    if (Array.isArray(data)) return data.map(item => prepareForLocalStorage(item));
    if (typeof data === 'object') {
        const cleaned = { ...data };
        for (const key in cleaned) {
            const val = cleaned[key];
            if (typeof val === 'string' && val.length > 5000 && val.startsWith('data:')) {
                cleaned[key] = "(removed to save space)";
            } else if (typeof val === 'object') {
                cleaned[key] = prepareForLocalStorage(val);
            }
        }
        return cleaned;
    }
    return data;
};

/**
 * Safely sets an item in localStorage, handling QuotaExceededErrors by clearing non-essential data.
 */
const safeLocalStorageSet = (key: string, value: any) => {
    try {
        const serializedValue = JSON.stringify(prepareForLocalStorage(value));
        localStorage.setItem(key, serializedValue);
    } catch (e) {
        if (e instanceof DOMException && (e.name === 'QuotaExceededError' || e.name === 'NS_ERROR_DOM_QUOTA_REACHED')) {
            console.warn(`LocalStorage quota exceeded while saving ${key}. Performing emergency cleanup...`);
            // Emergency Purge Strategy
            localStorage.removeItem('service_app_location_history'); // High volume, non-critical
            localStorage.removeItem('service_app_notifications');    // Re-loads from cloud anyway
            localStorage.removeItem('service_form_in_progress');     // Clear stuck drafts

            // Try again after purge
            try {
                localStorage.setItem(key, JSON.stringify(prepareForLocalStorage(value)));
            } catch (retryError) {
                console.error("Critical: LocalStorage is completely full even after purge.", retryError);
            }
        } else {
            console.error(`LocalStorage error for ${key}:`, e);
        }
    }
};

