  // --- DEFENSIVE PERSISTENCE LOGIC (Fixes Quota Errors) ---

  useEffect(() => { 
      if (!isInitialLoad.current) {
          // Cap local storage for submissions to last 30 items for performance and quota
          safeLocalStorageSet('service_app_submissions', submissions.slice(-30));
      }
