      };
      const watchOptions: PositionOptions = { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 };
      locationWatcherIdRef.current = navigator.geolocation.watchPosition(successCallback, (err) => console.error(err), watchOptions);
