        const newIncomeEntry: BookkeepingEntry = { id: `bk_inc_${serviceToSave.submissionId}`, timestamp: new Date().toISOString(), type: BookkeepingEntryType.Income, description: `Service for ${serviceToSave.customerFirstName} (#${serviceToSave.appointmentId?.split('-').pop()})`, amount: serviceToSave.grandTotal, relatedId: serviceToSave.submissionId, recordedBy: serviceToSave.submittedBy || currentUser?.username || 'system' };
        setBookkeeping(prev => [...prev.filter(b => b.id !== newIncomeEntry.id), newIncomeEntry]);
        cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);
        if (serviceToSave.isSubscription && serviceToSave.serviceSelection.includes('Car Washing')) {
             const userSubIndex = userSubscriptions.findIndex(sub => sub.mobileNumber === serviceToSave.mobileNumber);
            if (userSubIndex > -1) {
                const updatedSubs = [...userSubscriptions];
                const subToUpdate = {...updatedSubs[userSubIndex]};
                subToUpdate.washesRemaining = Math.max(0, subToUpdate.washesRemaining - 1);
                updatedSubs[userSubIndex] = subToUpdate;
                finalUserSubscriptions = updatedSubs;
                wasSubscriptionUpdated = true;
                cloudDataService.saveRecord('UserSubscriptions', subToUpdate, settings.googleSheetsUrl);
            }
        }
        if (serviceToSave.assignedTo) newNotifications.push({ id: `notif_complete_${serviceToSave.submissionId}`, userId: serviceToSave.assignedTo, serviceId: serviceToSave.submissionId, message: `Completed: Order #${serviceToSave.appointmentId?.split('-').pop()} for ${serviceToSave.customerFirstName} is complete.`, timestamp: new Date().toISOString(), isRead: false, type: 'completed' });
        sendCustomerEmailNotification(serviceToSave);
    }

    setSubmissions(prev => isUpdating ? prev.map(s => s.submissionId === service.submissionId ? serviceToSave : s) : [...prev, serviceToSave]);
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
