import { useReducer, useMemo, useCallback, useEffect } from 'react';
import { Service, ServiceStatus, TyreDetail, BatteryDetail, CustomService, CategorizedAddon, VehicleCategoryTag, DynamicAddon, PricingConfig } from '../types';
import { SERVICE_PRICES, ADDON_CATEGORIES, DEFAULT_WASH_PRICING_MATRIX, DEFAULT_CAR_CARE_PRICING_MATRIX, DEFAULT_ADDON_PRICING_MATRIX, DEFAULT_PRICING_CONFIG } from '../constants';

type FormAction =
  | { type: 'UPDATE_FIELD'; field: keyof Service; value: any }
  | { type: 'SET_FORM_DATA'; payload: Service }
  | { type: 'ADD_TYRE_DETAIL' }
  | { type: 'REMOVE_TYRE_DETAIL'; index: number }
  | { type: 'UPDATE_TYRE_DETAIL'; index: number; field: keyof TyreDetail; value: any }
  | { type: 'ADD_BATTERY_DETAIL' }
  | { type: 'REMOVE_BATTERY_DETAIL'; index: number }
  | { type: 'UPDATE_BATTERY_DETAIL'; index: number; field: keyof BatteryDetail; value: any }
  | { type: 'ADD_CUSTOM_SERVICE' }
  | { type: 'REMOVE_CUSTOM_SERVICE'; index: number }
  | { type: 'UPDATE_CUSTOM_SERVICE'; index: number; field: keyof CustomService; value: any }
  | { type: 'ADD_CATEGORIZED_ADDON' }
  | { type: 'REMOVE_CATEGORIZED_ADDON'; index: number }
  | { type: 'UPDATE_CATEGORIZED_ADDON'; index: number; field: keyof CategorizedAddon; value: any }
  | { type: 'UPDATE_DYNAMIC_ADDON_QTY'; name: string; quantity: number }
  | { type: 'UPDATE_CUSTOM_FIELD_DATA'; fieldId: string; value: string | number };

const createInitialState = (initialService?: Service | null): Service => {
  if (initialService) return JSON.parse(JSON.stringify(initialService));
  const submissionId = `SUB-${Date.now()}`;
  return {
    submissionId, appointmentId: submissionId, timestamp: new Date().toISOString(),
    customerFirstName: '', customerLastName: '', streetAddress: '', mobileNumber: '', carNumber: '', carBrandModel: '',
    vehicleCategoryTag: VehicleCategoryTag.Hatch, serviceSelection: [], isSubscription: false, carWashDetails: undefined, carCareDetails: undefined,
    beforeWashingPhoto: '', beforeVideoInventory: '', beforeVideoTopBody: '', beforeVideoUnderchassis: '',
    afterWashingPhoto: '', afterVideoInterior: '', afterVideoExterior: '', afterVideoUnderchassis: '',
    tyreReplacementQuantity: 0, tyreReplacementPrice: SERVICE_PRICES.tyreReplacement, tyreReplacementTotalAmount: 0, tyreLaborCost: 0, tyreMaterialCost: 0, tyreDetails: [],
    batteryReplacementQuantity: 0, batteryReplacementTotalAmount: 0, batteryDetails: [],
    dynamicAddons: [], addonsTotal: 0, categorizedAddons: [], categorizedAddonsTotal: 0,
    customServices: [], customServicesTotal: 0, customFieldData: [], grandTotal: 0, acknowledgement: false,
    status: ServiceStatus.Draft, scheduledDate: undefined, scheduledTime: undefined, assignedTo: undefined,
    paymentMode: 'Cash', cashAmount: 0, onlineAmount: 0, paymentNotes: '',
  };
};

const formReducer = (state: Service, action: FormAction, pricingConfig?: PricingConfig): Service => {
  switch (action.type) {
    case 'UPDATE_FIELD': return { ...state, [action.field]: action.value };
    case 'SET_FORM_DATA': return action.payload;
    case 'ADD_TYRE_DETAIL': return { ...state, tyreDetails: [...state.tyreDetails, { tyreId: `T-${Date.now()}`, relatedServiceId: state.submissionId, dotCode: '', dotSerialNumberImage: '', tyreSize: '', brand: '', model: '' }] };
    case 'REMOVE_TYRE_DETAIL': return { ...state, tyreDetails: state.tyreDetails.filter((_, i) => i !== action.index) };
    case 'UPDATE_TYRE_DETAIL': return { ...state, tyreDetails: state.tyreDetails.map((detail, i) => i === action.index ? { ...detail, [action.field]: action.value } : detail) };
    case 'ADD_BATTERY_DETAIL': return { ...state, batteryDetails: [...state.batteryDetails, { batteryId: `B-${Date.now()}`, relatedServiceId: state.submissionId, serialNumber: '', brand: '', exchangeValue: 0, newBatteryAmount: 0 }] };
    case 'REMOVE_BATTERY_DETAIL': return { ...state, batteryDetails: state.batteryDetails.filter((_, i) => i !== action.index) };
    case 'UPDATE_BATTERY_DETAIL': return { ...state, batteryDetails: state.batteryDetails.map((detail, i) => i === action.index ? { ...detail, [action.field]: action.value } : detail) };
    case 'ADD_CUSTOM_SERVICE': return { ...state, customServices: [...state.customServices, { customServiceId: `CS-${Date.now()}`, relatedServiceId: state.submissionId, serviceDescription: '', amount: 0 }] };
    case 'REMOVE_CUSTOM_SERVICE': return { ...state, customServices: state.customServices.filter((_, i) => i !== action.index) };
    case 'UPDATE_CUSTOM_SERVICE': return { ...state, customServices: state.customServices.map((service, i) => i === action.index ? { ...service, [action.field]: action.value } : service) };
    case 'ADD_CATEGORIZED_ADDON': return { ...state, categorizedAddons: [...state.categorizedAddons, { id: `CA-${Date.now()}`, relatedServiceId: state.submissionId, category: ADDON_CATEGORIES[0], productName: '', quantity: 1, amount: 0 }] };
    case 'REMOVE_CATEGORIZED_ADDON': return { ...state, categorizedAddons: state.categorizedAddons.filter((_, i) => i !== action.index) };
    case 'UPDATE_CATEGORIZED_ADDON': return { ...state, categorizedAddons: state.categorizedAddons.map((addon, i) => i === action.index ? { ...addon, [action.field]: action.value } : addon) };
    case 'UPDATE_DYNAMIC_ADDON_QTY':
      {
          const { name, quantity } = action;
          const category = state.vehicleCategoryTag;
          const currentAddons = state.dynamicAddons ? [...state.dynamicAddons] : [];
          let price = 0, mrp = 0;
          if (pricingConfig && category) {
             const priceData = pricingConfig.addons[name]?.[category];
             price = priceData?.price || 0; mrp = priceData?.mrp || 0;
          } else if (category) {
             const priceData = DEFAULT_ADDON_PRICING_MATRIX[name as keyof typeof DEFAULT_ADDON_PRICING_MATRIX]?.[category];
             price = priceData?.price || 0; mrp = priceData?.mrp || 0;
          }
          const existingIndex = currentAddons.findIndex(item => item.name === name);
          if (quantity <= 0) return { ...state, dynamicAddons: currentAddons.filter(item => item.name !== name) };
          if (existingIndex > -1) currentAddons[existingIndex] = { ...currentAddons[existingIndex], quantity, price, mrp };
          else currentAddons.push({ name, quantity, price, mrp });
          return { ...state, dynamicAddons: currentAddons };
      }
    case 'UPDATE_CUSTOM_FIELD_DATA':
        {
            const { fieldId, value } = action;
            const existingIndex = (state.customFieldData || []).findIndex(item => item.fieldId === fieldId);
            let newCustomData = [...(state.customFieldData || [])];
            if (value === '' || value === undefined) newCustomData = newCustomData.filter(item => item.fieldId !== fieldId);
            else if (existingIndex > -1) newCustomData[existingIndex] = { ...newCustomData[existingIndex], value };
            else newCustomData.push({ fieldId, value });
            return { ...state, customFieldData: newCustomData };
        }
    default: return state;
  }
};

const LOCAL_STORAGE_KEY = 'service_form_in_progress';

// Quota-safe helper for hook
const safeFormPersist = (data: any) => {
    try {
        const cleaned = JSON.parse(JSON.stringify(data));
        // Strip base64 before saving draft
        const stripBase64 = (obj: any) => {
            if (typeof obj !== 'object' || !obj) return;
            for (const key in obj) {
                if (typeof obj[key] === 'string' && obj[key].startsWith('data:') && obj[key].length > 5000) {
                    obj[key] = ""; // Discard large base64 strings in local draft to save space
                } else if (typeof obj[key] === 'object') {
                    stripBase64(obj[key]);
                }
            }
        };
        stripBase64(cleaned);
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(cleaned));
    } catch (e) { console.warn("Failed to save form draft", e); }
};

export const useServiceForm = (initialService: Service | null | undefined, pricingConfig: PricingConfig = DEFAULT_PRICING_CONFIG) => {
  const initializer = (initialValue?: Service | null): Service => {
    try {
      const savedFormJson = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (savedFormJson) {
        const savedFormState: Service = JSON.parse(savedFormJson);
        if (!initialValue || initialValue.submissionId === savedFormState.submissionId) return savedFormState;
      }
    } catch (e) { localStorage.removeItem(LOCAL_STORAGE_KEY); }
    return createInitialState(initialValue);
  };

  const [state, dispatch] = useReducer((state: Service, action: FormAction) => formReducer(state, action, pricingConfig), initialService, initializer);
  useEffect(() => { safeFormPersist(state); }, [state]);
  const updateField = useCallback(<K extends keyof Service>(field: K, value: Service[K]) => { dispatch({ type: 'UPDATE_FIELD', field, value }); }, []);

  useEffect(() => {
    const washType = state.carWashDetails?.washType;
    const category = state.vehicleCategoryTag;
    if (state.isSubscription && state.serviceSelection.includes('Car Washing')) updateField('carWashDetails', { ...state.carWashDetails!, price: 0 });
    else if (washType && category) {
        let price = 0, mrp = 0;
        if (pricingConfig && pricingConfig.wash[washType]?.[category]) { price = pricingConfig.wash[washType][category].price; mrp = pricingConfig.wash[washType][category].mrp; }
        else if (DEFAULT_WASH_PRICING_MATRIX[washType as keyof typeof DEFAULT_WASH_PRICING_MATRIX]?.[category]) { price = DEFAULT_WASH_PRICING_MATRIX[washType as keyof typeof DEFAULT_WASH_PRICING_MATRIX][category].price; mrp = DEFAULT_WASH_PRICING_MATRIX[washType as keyof typeof DEFAULT_WASH_PRICING_MATRIX][category].mrp; }
        if (price !== undefined) updateField('carWashDetails', { washType, price, mrp });
    }
  }, [state.carWashDetails?.washType, state.vehicleCategoryTag, state.isSubscription, state.serviceSelection, pricingConfig, updateField]);

  useEffect(() => {
    const careType = state.carCareDetails?.careType;
    const category = state.vehicleCategoryTag;
    if (careType && category) {
        let price = 0, mrp = 0;
        if (pricingConfig && pricingConfig.carCare[careType]?.[category]) { price = pricingConfig.carCare[careType][category].price; mrp = pricingConfig.carCare[careType][category].mrp; }
        else if (DEFAULT_CAR_CARE_PRICING_MATRIX[careType as keyof typeof DEFAULT_CAR_CARE_PRICING_MATRIX]?.[category]) { price = DEFAULT_CAR_CARE_PRICING_MATRIX[careType as keyof typeof DEFAULT_CAR_CARE_PRICING_MATRIX][category].price; mrp = DEFAULT_CAR_CARE_PRICING_MATRIX[careType as keyof typeof DEFAULT_CAR_CARE_PRICING_MATRIX][category].mrp; }
        if (price !== undefined) updateField('carCareDetails', { careType, price, mrp });
    }
  }, [state.carCareDetails?.careType, state.vehicleCategoryTag, pricingConfig, updateField]);

  useEffect(() => {
      const category = state.vehicleCategoryTag;
      if (!category || !state.dynamicAddons || state.dynamicAddons.length === 0) return;
      const updatedAddons = state.dynamicAddons.map(addon => {
          let price = 0, mrp = 0;
          if (pricingConfig && pricingConfig.addons[addon.name]?.[category]) { price = pricingConfig.addons[addon.name][category].price; mrp = pricingConfig.addons[addon.name][category].mrp; }
          else { const priceData = DEFAULT_ADDON_PRICING_MATRIX[addon.name as keyof typeof DEFAULT_ADDON_PRICING_MATRIX]?.[category]; price = priceData?.price || 0; mrp = priceData?.mrp || 0; }
          return { ...addon, price, mrp };
      });
      if (JSON.stringify(updatedAddons) !== JSON.stringify(state.dynamicAddons)) updateField('dynamicAddons', updatedAddons);
  }, [state.vehicleCategoryTag, state.dynamicAddons, pricingConfig, updateField]);

  useEffect(() => { updateField('tyreReplacementTotalAmount', state.tyreReplacementQuantity * (state.tyreReplacementPrice || 0)); }, [state.tyreReplacementQuantity, state.tyreReplacementPrice, updateField]);
  useEffect(() => { updateField('batteryReplacementTotalAmount', state.batteryDetails.reduce((t, b) => t + ((b.newBatteryAmount || 0) - (b.exchangeValue || 0)), 0)); }, [state.batteryDetails, updateField]);
  useEffect(() => {
    const daTotal = (state.dynamicAddons || []).reduce((t, i) => t + (i.price * i.quantity), 0);
    const caTotal = state.categorizedAddons.reduce((s, a) => s + ((a.quantity || 0) * (a.amount || 0)), 0);
    updateField('categorizedAddonsTotal', caTotal);
    updateField('addonsTotal', daTotal + caTotal);
  }, [state.dynamicAddons, state.categorizedAddons, updateField]);
  useEffect(() => { updateField('customServicesTotal', state.customServices.reduce((s, ser) => s + Number(ser.amount || 0), 0)); }, [state.customServices, updateField]);
  const grandTotal = useMemo(() => {
    let t = 0;
    if (state.serviceSelection.includes("Car Washing")) t += state.carWashDetails?.price || 0;
    if (state.serviceSelection.includes("Car Care")) t += state.carCareDetails?.price || 0;
    if (state.serviceSelection.includes("Tyre Replacement")) t += state.tyreReplacementTotalAmount;
    if (state.serviceSelection.includes("Battery Replacement")) t += state.batteryReplacementTotalAmount;
    t += state.addonsTotal; t += state.customServicesTotal;
    return t;
  }, [state.serviceSelection, state.carWashDetails, state.carCareDetails, state.tyreReplacementTotalAmount, state.batteryReplacementTotalAmount, state.addonsTotal, state.customServicesTotal]);
  useEffect(() => { updateField('grandTotal', grandTotal); }, [grandTotal, updateField]);

  return { state, dispatch, updateField };
};

import { AppData, User, Settings, Service, TyreDetail, BatteryDetail, CustomService, CategorizedAddon, ServiceStatus, SubscriptionPlan, UserSubscription, ServiceTemplate, ServiceRequest, AppNotification, NotificationPreferences, LocationHistory, RetentionKpiTargets, MiscSpend, BookkeepingEntry, TyreData, ProfitLoss, PricingConfig, SpendCategory, PredefinedCost } from '../types';
import { getDefaultPermissionsForRole } from './authService';
import { CAR_BRANDS, TIRE_BRANDS } from '../data/vehicleData';
import { DEFAULT_PRICING_CONFIG } from '../constants';
import { SyncStatus } from '../components/ui/SyncStatusIndicator';

// --- ROBUST PARSING HELPERS ---
export const robustParseFloat = (value: any): number => {
    if (typeof value === 'number') return value;
    if (typeof value !== 'string') return 0;
    const cleanedString = value.replace(/[^0-9.-]+/g, "");
    const number = parseFloat(cleanedString);
    return isNaN(number) ? 0 : number;
};

export const robustParseInt = (value: any): number => {
    const floatVal = robustParseFloat(value);
    return parseInt(String(floatVal), 10);
};

// --- OFFLINE QUEUE MANAGEMENT ---
const QUEUE_STORAGE_KEY = 'service_app_offline_queue';
let operationQueue: any[] = [];
let isProcessingQueue = false;
let callbacks = {
    onSyncStatusChange: (status: SyncStatus) => {},
    onSyncError: (error: string | null) => {},
};

// Load queue from storage on startup
const loadQueueFromStorage = () => {
    try {
        const savedQueue = localStorage.getItem(QUEUE_STORAGE_KEY);
        operationQueue = savedQueue ? JSON.parse(savedQueue) : [];
        if (operationQueue.length > 0) {
            callbacks.onSyncStatusChange('UNSAVED');
        }
    } catch (e) {
        console.error("Failed to load offline queue:", e);
        operationQueue = [];
    }
};

const saveQueueToStorage = () => {
    try {
        localStorage.setItem(QUEUE_STORAGE_KEY, JSON.stringify(operationQueue));
    } catch (e) {
        // If the queue contains base64 media, it might exceed quota
        console.error("Failed to save offline queue to local storage (Quota Exceeded?):", e);
        // We cannot strip the queue because that would lose the data being synced.
        // We just log it and the user stays with an unsynced local state.
    }
};

const addToQueue = (operation: any) => {
    operationQueue.push(operation);
    saveQueueToStorage();
    callbacks.onSyncStatusChange('UNSAVED');
    callbacks.onSyncError('You are offline. Changes have been saved locally and will sync when you reconnect.');
};

const processQueue = async (sheetsUrl: string) => {
    if (isProcessingQueue || !navigator.onLine || operationQueue.length === 0) {
        return;
    }
    isProcessingQueue = true;
    callbacks.onSyncStatusChange('SYNCING');
    callbacks.onSyncError(null);

    while (operationQueue.length > 0) {
        const operation = operationQueue[0];
        try {
            await executeOperation(operation, sheetsUrl);
            operationQueue.shift(); // Remove successful operation
            saveQueueToStorage();
        } catch (error) {
            console.error("Failed to process queued operation. Halting queue.", error);
            const errorMessage = error instanceof Error ? error.message : "An unknown sync error occurred.";
            callbacks.onSyncStatusChange('ERROR');
            callbacks.onSyncError(`Sync failed: ${errorMessage}`);
            isProcessingQueue = false;
            return; // Stop processing on failure
        }
    }

    callbacks.onSyncStatusChange('SYNCED');
    isProcessingQueue = false;
};

const PROXY_URL = '/.netlify/functions/google-sheets-proxy';
let bypassProxy = false;

const executeOperation = async (operation: any, sheetsUrl: string) => {
    const gasPayload = {
        action: operation.type === 'delete' ? 'deleteRecord' : 'upsertRecord',
        ...operation.payload
    };

    if (bypassProxy) {
         console.warn("Using direct (blind) sync due to previous proxy failure.");
         return fetch(sheetsUrl, {
            method: 'POST',
            body: JSON.stringify(gasPayload),
            mode: 'no-cors',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        }).then(() => {
             return { status: 'success', message: 'Saved via direct fallback.' };
        });
    }

    const proxyPayload = {
        sheetsUrl: sheetsUrl,
        payload: gasPayload
    };

    try {
        const response = await fetch(PROXY_URL, {
            method: 'POST',
            body: JSON.stringify(proxyPayload),
            headers: { 'Content-Type': 'application/json' },
        });

        if (!response.ok) {
            if (response.status === 404 || response.status === 500) {
                 console.error(`Proxy failed with ${response.status}. Switching to direct sync mode.`);
                 bypassProxy = true;
                 return executeOperation(operation, sheetsUrl);
            }
             const errorBody = await response.json().catch(() => ({ error: 'Proxy returned a non-JSON error response.', details: response.statusText }));
             const details = typeof errorBody === 'object' ? errorBody.details || errorBody.error : errorBody;
             throw new Error(`Request via proxy failed (${response.status}): ${details}`);
        }

        const result = await response.json();
        if (result.status !== 'success') {
            throw new Error(result.message || 'The cloud script returned an error via the proxy.');
        }
        return result;
    } catch (e) {
        console.warn("Proxy sync failed, attempting direct connection (Blind Sync)...", e);
        bypassProxy = true;
        return executeOperation(operation, sheetsUrl);
    }
};

export const init = (appCallbacks: { onSyncStatusChange: (s: SyncStatus) => void, onSyncError: (e: string | null) => void }, sheetsUrl: string) => {
    callbacks = appCallbacks;
    loadQueueFromStorage();
    window.addEventListener('online', () => processQueue(sheetsUrl));
    if (navigator.onLine) {
        processQueue(sheetsUrl);
    }
};

const getIdField = (sheetName: string): string => {
    switch (sheetName) {
        case 'Users': return 'username';
        case 'Submissions': return 'submissionId';
        case 'SubscriptionPlans': return 'id';
        case 'UserSubscriptions': return 'id';
        case 'ServiceTemplates': return 'id';
        case 'ServiceRequests': return 'id';
        case 'Notifications': return 'id';
        case 'LocationHistory': return 'historyId';
        case 'MiscSpends': return 'spendId';
        case 'Bookkeeping': return 'id';
        case 'ProfitLoss': return 'serviceId';
        case 'SpendCategories': return 'id';
        case 'PredefinedCosts': return 'id';
        case 'Settings': return 'googleSheetsUrl';
        case 'VehicleData': return 'id';
        case 'TyreData': return 'id';
        case 'PricingConfig': return 'id';
        default: throw new Error(`No ID field defined for sheet: ${sheetName}`);
    }
};

export const saveRecord = async (sheetName: string, record: any, sheetsUrl: string) => {
    if ((sheetName === 'VehicleData' || sheetName === 'TyreData' || sheetName === 'PricingConfig') && !record.id) {
        record.id = 'singleton';
    }
    const idField = getIdField(sheetName);
    if (!record[idField]) {
        console.error(`Record for sheet "${sheetName}" is missing its ID field "${idField}".`, record);
        throw new Error(`Cannot save record: Missing ID field "${idField}".`);
    }

    const operation = { type: 'upsert', payload: { sheetName, idField, record } };

    try {
        if (!navigator.onLine) throw new Error("Offline");
        await executeOperation(operation, sheetsUrl);
        await processQueue(sheetsUrl);
    } catch (error) {
        console.warn(`Save failed for ${sheetName}, adding to offline queue.`, error);
        addToQueue(operation);
    }
};

export const deleteRecord = async (sheetName: string, recordId: string, sheetsUrl: string) => {
     const operation = { type: 'delete', payload: { sheetName, idField: getIdField(sheetName), recordId } };
    try {
        if (!navigator.onLine) throw new Error("Offline");
        await executeOperation(operation, sheetsUrl);
        await processQueue(sheetsUrl);
    } catch (error) {
        console.warn(`Delete failed for ${sheetName}, adding to offline queue.`, error);
        addToQueue(operation);
    }
};

export const testCloudDataConnection = async (sheetsUrl: string): Promise<{ success: boolean; message: string; details?: string; }> => {
    if (!sheetsUrl) return { success: false, message: "URL is empty." };
    try {
        const url = new URL(sheetsUrl);
        url.searchParams.set('action', 'loadAllData');
        const response = await fetch(url.toString(), { method: 'GET', mode: 'cors' });
        const text = await response.text();
        if (!response.ok) return { success: false, message: `Status ${response.status}`, details: text };
        const data = JSON.parse(text);
        if (data.status === 'success') return { success: true, message: "Connection successful!" };
        else return { success: false, message: data.message || 'Unknown error' };
    } catch (error) {
        return { success: false, message: error instanceof Error ? error.message : "Error" };
    }
};

const getDefaultAppData = (settings: Settings): AppData => {
    const defaultNotificationPrefs: NotificationPreferences = { enabled: { assigned: true, reminder: true, queued: true, completed: true, manual: true, overdue: true }, sound: 'default', vibration: true };
    const defaultKpiTargets: RetentionKpiTargets = { monthlyFollowUps: 20, conversionRatePercentage: 50, monthlyRevenue: 15000 };
    return {
        submissions: [], users: [], settings: {...settings, retentionKpiTargets: defaultKpiTargets},
        subscriptionPlans: [], userSubscriptions: [], serviceTemplates: [], serviceRequests: [], notifications: [], locationHistory: [],
        miscSpends: [], bookkeeping: [], profitLoss: [], spendCategories: [], predefinedCosts: [], vehicleData: CAR_BRANDS,
        tyreData: { brands: TIRE_BRANDS, models: [], sizes: [] }, predefinedAddons: [], pricingConfig: DEFAULT_PRICING_CONFIG,
    };
};

const parseServiceSelection = (raw: any): string[] => {
    if (Array.isArray(raw)) return raw.flatMap(item => parseServiceSelection(item));
    if (typeof raw === 'string') {
        const trimmed = raw.trim();
        if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
            try {
                const parsed = JSON.parse(trimmed);
                if (Array.isArray(parsed)) return parseServiceSelection(parsed);
            } catch (e) { }
        }
        return trimmed.split(',').map(s => s.replace(/[\[\]"']/g, '').trim()).filter(Boolean);
    }
    return [];
};

export const loadAppData = async (currentSettings: Settings): Promise<AppData> => {
    const sheetsUrl = currentSettings.googleSheetsUrl;
    if (!sheetsUrl) return getDefaultAppData(currentSettings);
    try {
        const url = new URL(sheetsUrl);
        url.searchParams.set('action', 'loadAllData');
        const response = await fetch(url.toString(), { method: 'GET', mode: 'cors' });
        const result = await response.json();
        if (result.status !== 'success') throw new Error(result.message || 'Cloud error.');

        const flatData = result.data;
        const tyreDetails = (flatData.TyreDetails || []);
        const batteryDetails = (flatData.BatteryDetails || []).map(d => ({ ...d, exchangeValue: robustParseFloat(d.exchangeValue), newBatteryAmount: robustParseFloat(d.newBatteryAmount) }));
        const customServices = (flatData.CustomServices || []).map(d => ({ ...d, amount: robustParseFloat(d.amount) }));
        const categorizedAddons = (flatData.CategorizedAddons || []).map(d => ({ ...d, quantity: robustParseInt(d.quantity), amount: robustParseFloat(d.amount) }));
        const customFieldData = flatData.CustomFieldData || [];
        const serviceTemplateFields = flatData.ServiceTemplateFields || [];
        const locationHistory = (flatData.LocationHistory || []).map(d => ({ ...d, latitude: robustParseFloat(d.latitude), longitude: robustParseFloat(d.longitude) }));
        const miscSpends = (flatData.MiscSpends || []).map(s => ({ ...s, amount: robustParseFloat(s.amount) }));
        const bookkeeping = (flatData.Bookkeeping || []).map(b => ({ ...b, amount: robustParseFloat(b.amount) }));
        const profitLoss = (flatData.ProfitLoss || []).map(pl => ({ ...pl, materialCost: robustParseFloat(pl.materialCost), laborCost: robustParseFloat(pl.laborCost), otherExpenses: robustParseFloat(pl.otherExpenses), calculatedProfit: robustParseFloat(pl.calculatedProfit) }));
        const spendCategories = (flatData.SpendCategories || []).map(c => ({ ...c }));
        const predefinedCosts = (flatData.PredefinedCosts || []).map(c => ({ ...c, value: robustParseFloat(c.value) }));
        const vehicleData = (flatData.VehicleData && flatData.VehicleData[0]?.data) ? JSON.parse(flatData.VehicleData[0].data) : CAR_BRANDS;
        const tyreData = (flatData.TyreData && flatData.TyreData[0]?.data) ? JSON.parse(flatData.TyreData[0].data) : { brands: TIRE_BRANDS, models: [], sizes: [] };
        const pricingConfig = (flatData.PricingConfig && flatData.PricingConfig[0]?.data) ? JSON.parse(flatData.PricingConfig[0].data) : DEFAULT_PRICING_CONFIG;
        const subscriptionPlans = (flatData.SubscriptionPlans || []).map(p => ({ ...p, price: robustParseFloat(p.price), totalWashes: robustParseInt(p.totalWashes), features: p.features ? String(p.features).split(',').map(f => f.trim()) : [] }));
        const userSubscriptions = (flatData.UserSubscriptions || []).map(s => ({ ...s, washesRemaining: robustParseInt(s.washesRemaining) }));
        const serviceRequests = (flatData.ServiceRequests || []);
        const notifications = (flatData.Notifications || []).map(n => ({ ...n, isRead: String(n.isRead).toUpperCase() === 'TRUE' }));
        const serviceTemplates = (flatData.ServiceTemplates || []).map(t => ({ ...t, isEnabled: String(t.isEnabled).toUpperCase() === 'TRUE', customFields: serviceTemplateFields.filter(f => f.relatedTemplateId === t.id).map(({ relatedTemplateId, ...rest }) => rest) }));

        const submissions = (flatData.Submissions || []).map((sub: any): Service => {
            let status = sub.status;
            if (status === "Submitted") status = ServiceStatus.Completed;
            else if (status === "Order Created") status = ServiceStatus.Queued;
            if (!status || !Object.values(ServiceStatus).includes(status as ServiceStatus)) status = ServiceStatus.Queued;

            let dynamicAddons = [];
            try { if (sub.dynamicAddons) dynamicAddons = typeof sub.dynamicAddons === 'string' ? JSON.parse(sub.dynamicAddons) : sub.dynamicAddons; } catch(e) { }
            let carWashDetails = undefined;
            try { if (sub.carWashDetails) carWashDetails = typeof sub.carWashDetails === 'string' ? JSON.parse(sub.carWashDetails) : sub.carWashDetails; } catch(e) { }
            let carCareDetails = undefined;
            try { if (sub.carCareDetails) carCareDetails = typeof sub.carCareDetails === 'string' ? JSON.parse(sub.carCareDetails) : sub.carCareDetails; } catch(e) { }

            return {
                ...sub, status, dynamicAddons, carWashDetails, carCareDetails,
                isSubscription: String(sub.isSubscription).toUpperCase() === 'TRUE',
                isFollowUp: String(sub.isFollowUp).toUpperCase() === 'TRUE',
                isAutoScheduled: String(sub.isAutoScheduled).toUpperCase() === 'TRUE',
                acknowledgement: String(sub.acknowledgement).toUpperCase() === 'TRUE',
                grandTotal: robustParseFloat(sub.grandTotal),
                appointmentId: sub.appointmentId || sub.submissionId,
                tyreDetails: tyreDetails.filter(d => d.relatedServiceId === sub.submissionId),
                batteryDetails: batteryDetails.filter(d => d.relatedServiceId === sub.submissionId),
                customServices: customServices.filter(d => d.relatedServiceId === sub.submissionId),
                categorizedAddons: categorizedAddons.filter(d => d.relatedServiceId === sub.submissionId),
                customFieldData: customFieldData.filter(d => d.relatedServiceId === sub.submissionId).map(({ relatedServiceId, ...rest }) => rest),
                serviceSelection: parseServiceSelection(sub.serviceSelection),
                dependsOn: sub.dependsOn ? String(sub.dependsOn).split(',').map(s => s.trim()) : [],
            };
        });

        const cloudSettingsPartial = (flatData.Settings && flatData.Settings[0]) ? flatData.Settings[0] : {};
        const settings: Settings = {
            googleSheetsUrl: cloudSettingsPartial.googleSheetsUrl || currentSettings.googleSheetsUrl,
            googleDriveUploadUrl: cloudSettingsPartial.googleDriveUploadUrl || currentSettings.googleDriveUploadUrl,
            customLogoUrl: cloudSettingsPartial.customLogoUrl || currentSettings.customLogoUrl,
            retentionKpiTargets: cloudSettingsPartial.retentionKpiTargets ? (typeof cloudSettingsPartial.retentionKpiTargets === 'string' ? JSON.parse(cloudSettingsPartial.retentionKpiTargets) : cloudSettingsPartial.retentionKpiTargets) : currentSettings.retentionKpiTargets
        };

        const users = (flatData.Users && flatData.Users.length > 0) 
            ? (flatData.Users).map(u => ({ ...u, notificationPreferences: u.notificationPreferences ? JSON.parse(u.notificationPreferences) : {}, attendanceHistory: u.attendanceHistory ? JSON.parse(u.attendanceHistory) : [], permissions: u.permissions ? JSON.parse(u.permissions) : [], latitude: u.latitude ? robustParseFloat(u.latitude) : undefined, longitude: u.longitude ? robustParseFloat(u.longitude) : undefined }))
            : getDefaultAppData(settings).users;

        return { submissions, users, settings, subscriptionPlans, userSubscriptions, serviceTemplates, serviceRequests, notifications, locationHistory, miscSpends, bookkeeping, profitLoss, vehicleData, tyreData, pricingConfig, spendCategories, predefinedCosts, predefinedAddons: [] };
    } catch (error) { throw new Error(error instanceof Error ? error.message : "Load failed"); }
};

