  const [tyreData, setTyreData] = useState<TyreData>({ brands: TIRE_BRANDS, models: [], sizes: [] });

  const [editingService, setEditingService] = useState<Service | null>(null);
  const [editingTemplate, setEditingTemplate] = useState<ServiceTemplate | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [printingService, setPrintingService] = useState<Service | null>(null);
  const [summarizingService, setSummarizingService] = useState<Service | null>(null);
  const [deletingService, setDeletingService] = useState<Service | null>(null);
  const [sharingService, setSharingService] = useState<Service | null>(null);

  const [syncStatus, setSyncStatus] = useState<SyncStatus>('OFFLINE');
  const [syncError, setSyncError] = useState<string | null>(null);
  const [logoHasError, setLogoHasError] = useState(false);

  const [isManualRefreshing, setIsManualRefreshing] = useState(false);
  const isInitialLoad = useRef(true);

  const [isSidebarMinimized, setIsSidebarMinimized] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [isNotificationHistoryOpen, setIsNotificationHistoryOpen] = useState(false);
  const locationWatcherIdRef = useRef<number | null>(null);
  const [isChatbotOpen, setIsChatbotOpen] = useState(false);
  const [publicService, setPublicService] = useState<{ data: any } | null>(null);

  const loadAndMergeData = useCallback(async (isInitial: boolean = false) => {
    if (isInitial) setAppIsLoading(true);
    setSyncError(null);
    setSyncStatus('SYNCING');

    const persistedSettings = {
        googleSheetsUrl: PERMANENT_SHEET_URL,
        googleDriveUploadUrl: PERMANENT_DRIVE_URL,
        customLogoUrl: localStorage.getItem('customLogoUrl') || '',
        retentionKpiTargets: JSON.parse(localStorage.getItem('retentionKpiTargets') || 'null') || defaultKpiTargets,
    };

    try {
        const cloudData = await cloudDataService.loadAppData(persistedSettings);
        let usersToSet = cloudData.users;

        if (usersToSet.length === 0 && cloudData.submissions.length === 0) {
            const defaultAdmin: User = { 
                username: 'admin', password: 'admin@123', role: 'admin', 
                notificationPreferences: defaultNotificationPrefs, 
                permissions: authService.getDefaultPermissionsForRole('admin'),
                attendanceStatus: 'CHECKED_OUT',
                attendanceHistory: [],
            };
            usersToSet = [defaultAdmin];
            cloudDataService.saveRecord('Users', defaultAdmin, PERMANENT_SHEET_URL);
        }

        usersToSet = usersToSet.map(user => {
            const finalUser = { ...user };
            let needsSave = false;
            if (!finalUser.notificationPreferences) { finalUser.notificationPreferences = mergeWithDefaultPrefs(); needsSave = true; }
            if ((finalUser.role as any) === 'user') { finalUser.role = 'agent'; needsSave = true; }
            if (!finalUser.attendanceStatus) { finalUser.attendanceStatus = 'CHECKED_OUT'; needsSave = true; }
            if (!finalUser.attendanceHistory) { finalUser.attendanceHistory = []; needsSave = true; }
            if (!finalUser.permissions || finalUser.permissions.length === 0) { finalUser.permissions = authService.getDefaultPermissionsForRole(finalUser.role); needsSave = true; }
            if (needsSave) cloudDataService.saveRecord('Users', finalUser, PERMANENT_SHEET_URL);
            return finalUser;
        });

        const localSubmissionsJson = localStorage.getItem('service_app_submissions');
        const rawLocalSubmissions: Service[] = localSubmissionsJson ? JSON.parse(localSubmissionsJson) : [];
        const cleanedLocalSubmissions = cleanSubmissionsArray(rawLocalSubmissions);
        const mergedSubmissions = mergeSubmissions(cleanSubmissionsArray(cloudData.submissions), cleanedLocalSubmissions);

        setSubmissions(mergedSubmissions);
        setUsers(usersToSet);
        setSettings({ ...cloudData.settings, googleSheetsUrl: PERMANENT_SHEET_URL, googleDriveUploadUrl: PERMANENT_DRIVE_URL, retentionKpiTargets: cloudData.settings.retentionKpiTargets || defaultKpiTargets });
        setSubscriptionPlans(cloudData.subscriptionPlans || []);
        setUserSubscriptions(cloudData.userSubscriptions || []);
        setServiceTemplates(cloudData.serviceTemplates.length > 0 ? cloudData.serviceTemplates : DEFAULT_SERVICE_TEMPLATES);
        setServiceRequests(cloudData.serviceRequests || []);
        setNotifications(cloudData.notifications || []);
        setLocationHistory(cloudData.locationHistory || []);
        setMiscSpends(cloudData.miscSpends || []);
        setBookkeeping(cloudData.bookkeeping || []);
        setProfitLossData(cloudData.profitLoss || []);
        setSpendCategories(cloudData.spendCategories || []);
        setPredefinedCosts(cloudData.predefinedCosts || []);
        setVehicleData(cloudData.vehicleData || CAR_BRANDS);
        setTyreData(cloudData.tyreData || { brands: TIRE_BRANDS, models: [], sizes: [] });

        if(cloudData.serviceTemplates.length === 0) DEFAULT_SERVICE_TEMPLATES.forEach(t => cloudDataService.saveRecord('ServiceTemplates', t, PERMANENT_SHEET_URL));
        if(!cloudData.settings.retentionKpiTargets) cloudDataService.saveRecord('Settings', { ...settings, retentionKpiTargets: defaultKpiTargets, googleSheetsUrl: PERMANENT_SHEET_URL}, PERMANENT_SHEET_URL);

        setSyncStatus('SYNCED');

    } catch (e) {
        setSyncStatus('ERROR');
        const errorMessage = e instanceof Error ? e.message : "Could not load data from cloud. Check settings and connection.";
        setSyncError(errorMessage);
        const rawLocalSubmissions: Service[] = JSON.parse(localStorage.getItem('service_app_submissions') || '[]');
        setSubmissions(cleanSubmissionsArray(rawLocalSubmissions));
        setUsers(JSON.parse(localStorage.getItem('service_app_users') || '[]').map(u => ({...u, notificationPreferences: mergeWithDefaultPrefs(u.notificationPreferences)})));
        setSettings(persistedSettings);
        setSubscriptionPlans(JSON.parse(localStorage.getItem('service_app_subscription_plans') || '[]'));
        setUserSubscriptions(JSON.parse(localStorage.getItem('service_app_user_subscriptions') || '[]'));
        setServiceTemplates(JSON.parse(localStorage.getItem('service_app_service_templates') || JSON.stringify(DEFAULT_SERVICE_TEMPLATES)));
        setNotifications(JSON.parse(localStorage.getItem('service_app_notifications') || '[]'));
    } finally {
        if (isInitial) setAppIsLoading(false);
        isInitialLoad.current = false;
    }
  }, []);

  useEffect(() => {
    const hash = window.location.hash;
    if (hash.startsWith('#service=')) {
      setAppIsLoading(true);
      try {
        const encodedData = decodeURIComponent(hash.substring('#service='.length));
        const jsonString = atob(encodedData);
        setPublicService({ data: JSON.parse(jsonString) });
        setAppIsLoading(false);
      } catch (e) {
        window.location.hash = '';
        cloudDataService.init({ onSyncStatusChange: setSyncStatus, onSyncError: setSyncError }, settings.googleSheetsUrl);
        loadAndMergeData(true);
      }
    } else {
      cloudDataService.init({ onSyncStatusChange: setSyncStatus, onSyncError: setSyncError }, settings.googleSheetsUrl);
      loadAndMergeData(true);
    }
  }, [loadAndMergeData, settings.googleSheetsUrl]);

  // --- DEFENSIVE PERSISTENCE LOGIC (Fixes Quota Errors) ---

  useEffect(() => { 
      if (!isInitialLoad.current) {
          // Cache up to 100 items locally but surgically remove images to stay under 5MB quota.
          // This keeps all add-ons and history but saves significant space.
          safeLocalStorageSet('service_app_submissions', submissions.slice(-100), { stripMedia: true });
      }
  }, [submissions]);

  useEffect(() => { 
      if (!isInitialLoad.current) {
          safeLocalStorageSet('service_app_users', users);
      }
  }, [users]);

  useEffect(() => { 
      if (!isInitialLoad.current) {
          safeLocalStorageSet('service_app_subscription_plans', subscriptionPlans);
      }
  }, [subscriptionPlans]);

  useEffect(() => { 
      if (!isInitialLoad.current) {
          safeLocalStorageSet('service_app_user_subscriptions', userSubscriptions);
      }
  }, [userSubscriptions]);

  useEffect(() => { 
      if (!isInitialLoad.current) {
          safeLocalStorageSet('service_app_service_templates', serviceTemplates);
      }
  }, [serviceTemplates]);

  useEffect(() => { 
      if (!isInitialLoad.current) {
          // Keep only most recent notifications locally
          safeLocalStorageSet('service_app_notifications', notifications.slice(-50));
      }
  }, [notifications]);

  useEffect(() => { 
      if (!isInitialLoad.current) {
          // Location history is very high volume. Keep only last 20 points locally.
          safeLocalStorageSet('service_app_location_history', locationHistory.slice(-20));
      }
  }, [locationHistory]);

  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_misc_spends', miscSpends); }, [miscSpends]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_bookkeeping', bookkeeping); }, [bookkeeping]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_profit_loss', profitLossData); }, [profitLossData]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_spend_categories', spendCategories); }, [spendCategories]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_predefined_costs', predefinedCosts); }, [predefinedCosts]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_vehicle_data', vehicleData); }, [vehicleData]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_tyre_data', tyreData); }, [tyreData]);

  // Effect for real-time location tracking based on attendance status
  useEffect(() => {
    if (!currentUser || currentUser.attendanceStatus !== 'CHECKED_IN') {
      if (locationWatcherIdRef.current !== null) {
        navigator.geolocation.clearWatch(locationWatcherIdRef.current);
        locationWatcherIdRef.current = null;
      }
      return;
    }

    if ('geolocation' in navigator) {
      const successCallback = (position: GeolocationPosition) => {
        const { latitude, longitude } = position.coords;
        const activeService = submissions.find(s => s.assignedTo === currentUser.username && s.status === ServiceStatus.InProgress);
        const newHistoryRecord: LocationHistory = { historyId: `hist_${Date.now()}`, userId: currentUser.username, latitude, longitude, timestamp: new Date().toISOString(), relatedServiceId: activeService?.submissionId };
        setLocationHistory(currentHistory => [...currentHistory.slice(-100), newHistoryRecord]);
        cloudDataService.saveRecord('LocationHistory', newHistoryRecord, settings.googleSheetsUrl);
        setUsers(currentUsers => {
            const updatedUsers = currentUsers.map(u => u.username === currentUser.username ? { ...u, latitude, longitude, lastLocationUpdate: new Date().toISOString() } : u);
            const userToSave = updatedUsers.find(u => u.username === currentUser.username);
            if(userToSave) cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
            return updatedUsers;
        });
      };
      const watchOptions: PositionOptions = { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 };
      locationWatcherIdRef.current = navigator.geolocation.watchPosition(successCallback, (err) => console.error(err), watchOptions);
    }

    return () => { if (locationWatcherIdRef.current !== null) navigator.geolocation.clearWatch(locationWatcherIdRef.current); };
  }, [currentUser, submissions, settings.googleSheetsUrl]);

  // Effect for auto-refreshing data for admins (for live map)
  useEffect(() => {
      const isAdminOrManager = currentUser?.permissions.includes(Permission.CAN_VIEW_LIVE_MAP);
      if (isAdminOrManager && view === 'LIVE_MAP') {
          const intervalId = setInterval(() => { if (!isManualRefreshing) loadAndMergeData(false); }, 30000);
          return () => clearInterval(intervalId);
      }
  }, [currentUser, view, isManualRefreshing, loadAndMergeData]);

  const handleManualRefresh = async () => { if (isManualRefreshing) return; setIsManualRefreshing(true); await loadAndMergeData(false); setIsManualRefreshing(false); };

  const handleLoginAttempt = useCallback((username: string, password?: string) => {
    setLoginError('');
    const validatedUser = authService.validateLogin(username, password, users);
    if (validatedUser) {
        const userFromFullList = users.find(u => u.username === validatedUser.username);
        const finalUser = { ...(userFromFullList || validatedUser), notificationPreferences: mergeWithDefaultPrefs(userFromFullList?.notificationPreferences) };
        localStorage.setItem('service_app_current_user', JSON.stringify(finalUser));
        setCurrentUser(finalUser);
        setView('DASHBOARD');
    } else { setLoginError('Invalid username or password.'); }
  }, [users]);

  const handleLogout = () => {
    if (currentUser?.attendanceStatus === 'CHECKED_IN') handleUpdateAttendanceStatus(currentUser.username, 'CHECKED_OUT');
    setCurrentUser(null);
    localStorage.removeItem('service_app_current_user');
    setSyncError(null);
    setView('DASHBOARD');
  };

  const handleEditService = (service: Service | null) => { setEditingService(service); setView('FORM'); setIsMobileMenuOpen(false); };
  const handleNavigate = (view: AppView) => { setView(view); setIsMobileMenuOpen(false); }
  const handleEditTemplate = (template: ServiceTemplate) => { setEditingTemplate(template); setView('SERVICE_TEMPLATE_EDITOR'); setIsMobileMenuOpen(false); };

  const handleSaveDraftFromChatbot = (serviceDataFromAi: Partial<Service>) => {
    const submissionId = `SUB-${Date.now()}`;
    const newService: Service = { ...createDefaultServiceState(), ...serviceDataFromAi, submissionId: submissionId, appointmentId: submissionId, timestamp: new Date().toISOString(), status: ServiceStatus.Draft, submittedBy: `AI Assistant via ${currentUser?.username}` };
    setSubmissions(prev => [...prev, newService]);
    cloudDataService.saveRecord('Submissions', newService, settings.googleSheetsUrl);
  };

  const handleCreateFollowUp = (customer: Customer, serviceSelection: string[]) => {
    const prefilledService: Service = { ...createDefaultServiceState(), customerFirstName: customer.firstName, customerLastName: customer.lastName, mobileNumber: customer.mobileNumber, carNumber: customer.carNumber, carBrandModel: customer.carBrandModel, streetAddress: customer.streetAddress, customerEmail: customer.customerEmail, serviceSelection: serviceSelection, status: ServiceStatus.Draft, isFollowUp: true };
    handleEditService(prefilledService);
  };

  const handleCompleteOrder = (service: Service) => {
    const isUpdating = submissions.some(s => s.submissionId === service.submissionId);
    let serviceToSave: Service;
    let wasSubscriptionUpdated = false;
    let finalUserSubscriptions = userSubscriptions;
    let newNotifications: AppNotification[] = [];
    const canAdminEdit = currentUser?.permissions.includes(Permission.CAN_EDIT_ANY_ORDER);

    if (isUpdating) {
        const originalService = submissions.find(s => s.submissionId === service.submissionId)!;
        serviceToSave = { ...service, status: canAdminEdit ? service.status : ServiceStatus.Completed, timestamp: new Date().toISOString(), submittedBy: originalService.submittedBy || currentUser?.username };
        const wasCompleted = originalService.status === ServiceStatus.Completed;
        const isNowCompleted = serviceToSave.status === ServiceStatus.Completed;
        if (!wasCompleted && isNowCompleted) {
            const newIncomeEntry: BookkeepingEntry = { id: `bk_inc_${serviceToSave.submissionId}`, timestamp: new Date().toISOString(), type: BookkeepingEntryType.Income, description: `Service for ${serviceToSave.customerFirstName} (#${serviceToSave.appointmentId?.split('-').pop()})`, amount: serviceToSave.grandTotal, relatedId: serviceToSave.submissionId, recordedBy: serviceToSave.submittedBy || currentUser?.username || 'system' };
            setBookkeeping(prev => [...prev.filter(b => b.id !== newIncomeEntry.id), newIncomeEntry]);
            cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);
            if (serviceToSave.isSubscription && serviceToSave.serviceSelection.includes('Car Washing')) {
                const userSubIndex = userSubscriptions.findIndex(sub => sub.mobileNumber === serviceToSave.mobileNumber);
                if (userSubIndex > -1) {
                    const updatedSubs = [...userSubscriptions];
                    const subToUpdate = {...updatedSubs[userSubIndex]};
                    subToUpdate.washesRemaining = Math.max(0, subToUpdate.washesRemaining - 1);
                    updatedSubs[userSubIndex] = subToUpdate;
                    finalUserSubscriptions = updatedSubs;
                    wasSubscriptionUpdated = true;
                    cloudDataService.saveRecord('UserSubscriptions', subToUpdate, settings.googleSheetsUrl);
                }
            }
            if (serviceToSave.assignedTo) newNotifications.push({ id: `notif_complete_${serviceToSave.submissionId}`, userId: serviceToSave.assignedTo, serviceId: serviceToSave.submissionId, message: `Completed: Order #${serviceToSave.appointmentId?.split('-').pop()} for ${serviceToSave.customerFirstName} is complete.`, timestamp: new Date().toISOString(), isRead: false, type: 'completed' });
            sendCustomerEmailNotification(serviceToSave);
        } else if (wasCompleted && !isNowCompleted) {
            setBookkeeping(prev => prev.filter(b => b.relatedId !== serviceToSave.submissionId));
            cloudDataService.deleteRecord('Bookkeeping', `bk_inc_${serviceToSave.submissionId}`, settings.googleSheetsUrl);
        }
    } else {
        serviceToSave = { ...service, status: ServiceStatus.Completed, assignedTo: currentUser?.username, submittedBy: currentUser?.username, timestamp: new Date().toISOString() };
        const newIncomeEntry: BookkeepingEntry = { id: `bk_inc_${serviceToSave.submissionId}`, timestamp: new Date().toISOString(), type: BookkeepingEntryType.Income, description: `Service for ${serviceToSave.customerFirstName} (#${serviceToSave.appointmentId?.split('-').pop()})`, amount: serviceToSave.grandTotal, relatedId: serviceToSave.submissionId, recordedBy: serviceToSave.submittedBy || currentUser?.username || 'system' };
        setBookkeeping(prev => [...prev.filter(b => b.id !== newIncomeEntry.id), newIncomeEntry]);
        cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);
        if (serviceToSave.isSubscription && serviceToSave.serviceSelection.includes('Car Washing')) {
             const userSubIndex = userSubscriptions.findIndex(sub => sub.mobileNumber === serviceToSave.mobileNumber);
            if (userSubIndex > -1) {
                const updatedSubs = [...userSubscriptions];
                const subToUpdate = {...updatedSubs[userSubIndex]};
                subToUpdate.washesRemaining = Math.max(0, subToUpdate.washesRemaining - 1);
                updatedSubs[userSubIndex] = subToUpdate;
                finalUserSubscriptions = updatedSubs;
                wasSubscriptionUpdated = true;
                cloudDataService.saveRecord('UserSubscriptions', subToUpdate, settings.googleSheetsUrl);
            }
        }
        if (serviceToSave.assignedTo) newNotifications.push({ id: `notif_complete_${serviceToSave.submissionId}`, userId: serviceToSave.assignedTo, serviceId: serviceToSave.submissionId, message: `Completed: Order #${serviceToSave.appointmentId?.split('-').pop()} for ${serviceToSave.customerFirstName} is complete.`, timestamp: new Date().toISOString(), isRead: false, type: 'completed' });
        sendCustomerEmailNotification(serviceToSave);
    }

    setSubmissions(prev => isUpdating ? prev.map(s => s.submissionId === service.submissionId ? serviceToSave : s) : [...prev, serviceToSave]);
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
    if(wasSubscriptionUpdated) setUserSubscriptions(finalUserSubscriptions);
    if (newNotifications.length > 0) {
        setNotifications(prev => [...prev, ...newNotifications]);
        newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
        const targetUser = users.find(u => u.username === serviceToSave.assignedTo);
        const prefs = targetUser?.notificationPreferences || defaultNotificationPrefs;
        if (prefs.enabled.completed) {
            playNotificationAlert(prefs);
            if(targetUser?.pushSubscription) sendPushNotification(targetUser.pushSubscription, "Order Completed", newNotifications[0].message, prefs);
        }
    }
    triggerHapticFeedback('success');
    setView('DASHBOARD');
    setEditingService(null);
  };

  const handleSaveDraft = (service: Service) => {
    let serviceToSave = { ...service, status: ServiceStatus.Draft, timestamp: new Date().toISOString() };
    const existingIndex = submissions.findIndex(s => s.submissionId === service.submissionId);
    if (existingIndex > -1) setSubmissions(prev => { const updated = [...prev]; updated[existingIndex] = serviceToSave; return updated; });
    else setSubmissions(prev => [...prev, serviceToSave]);
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
    setView('DASHBOARD');
    setEditingService(null);
  };

  const handleAdminUpdate = (service: Service) => {
    const originalService = submissions.find(s => s.submissionId === service.submissionId);
    if (!originalService) return;
    const wasCompleted = originalService.status === ServiceStatus.Completed;
    const isNowCompleted = service.status === ServiceStatus.Completed;
    if (!wasCompleted && isNowCompleted) {
        const newIncomeEntry: BookkeepingEntry = { id: `bk_inc_${service.submissionId}`, timestamp: new Date().toISOString(), type: BookkeepingEntryType.Income, description: `Service for ${service.customerFirstName} (#${service.appointmentId?.split('-').pop()})`, amount: service.grandTotal, relatedId: service.submissionId, recordedBy: service.submittedBy || currentUser?.username || 'system' };
        setBookkeeping(prev => [...prev.filter(b => b.id !== newIncomeEntry.id), newIncomeEntry]);
        cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);
        sendCustomerEmailNotification(service);
    } else if (wasCompleted && !isNowCompleted) {
        setBookkeeping(prev => prev.filter(b => b.relatedId !== service.submissionId));
        cloudDataService.deleteRecord('Bookkeeping', `bk_inc_${service.submissionId}`, settings.googleSheetsUrl);
    }
    if (originalService.status !== ServiceStatus.InProgress && service.status === ServiceStatus.InProgress) sendCustomerEmailNotification(service);
    const serviceToSave = { ...service, timestamp: new Date().toISOString() };
    setSubmissions(prev => prev.map(s => s.submissionId === service.submissionId ? serviceToSave : s));
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
    setEditingService(serviceToSave);
  };

  const handleCreateOrder = useCallback((details: { customer: Pick<Customer, 'firstName' | 'lastName' | 'mobileNumber' | 'carNumber' | 'carBrandModel' | 'streetAddress' | 'customerEmail' | 'latitude' | 'longitude'>, scheduledDate?: string, scheduledTime?: string, serviceSelection: string[], vehicleCategoryTag?: VehicleCategoryTag, assignedTo?: string }) => {
    const submissionId = `SUB-${Date.now()}`;
    const newService: Service = { ...createDefaultServiceState(), submissionId: submissionId, appointmentId: submissionId, timestamp: new Date().toISOString(), status: details.assignedTo ? ServiceStatus.Assigned : ServiceStatus.Queued, customerFirstName: details.customer.firstName, customerLastName: details.customer.lastName, mobileNumber: details.customer.mobileNumber, customerEmail: details.customer.customerEmail, carNumber: details.customer.carNumber, carBrandModel: details.customer.carBrandModel, streetAddress: details.customer.streetAddress, serviceSelection: details.serviceSelection, vehicleCategoryTag: details.vehicleCategoryTag, scheduledDate: details.scheduledDate, scheduledTime: details.scheduledTime, assignedTo: details.assignedTo };
    setSubmissions(prev => [...prev, newService]);
    cloudDataService.saveRecord('Submissions', newService, settings.googleSheetsUrl);
    const adminsAndManagers = users.filter(u => u.permissions.includes(Permission.CAN_ASSIGN_ORDERS));
    const newNotifications: AppNotification[] = [];
    if (!newService.assignedTo) {
        adminsAndManagers.forEach(admin => {
            const message = `New Order: #${newService.appointmentId?.split('-').pop()} for ${newService.customerFirstName} has been queued.`;
            const notif: AppNotification = { id: `notif_queued_${newService.submissionId}_${admin.username}`, userId: admin.username, serviceId: newService.submissionId, message, timestamp: new Date().toISOString(), isRead: false, type: 'queued' };
            newNotifications.push(notif);
            const prefs = admin.notificationPreferences || defaultNotificationPrefs;
            if (prefs.enabled.queued) { playNotificationAlert(prefs); if(admin.pushSubscription) sendPushNotification(admin.pushSubscription, "New Order Queued", message, prefs); }
        });
    } else {
        const assignedUser = users.find(u => u.username === newService.assignedTo);
        if (assignedUser) {
            const message = `Assigned: You have a new order for ${newService.customerFirstName}.`;
            const notif: AppNotification = { id: `notif_assign_${newService.submissionId}`, userId: assignedUser.username, serviceId: newService.submissionId, message, timestamp: new Date().toISOString(), isRead: false, type: 'assigned' };
            newNotifications.push(notif);
            const prefs = assignedUser.notificationPreferences || defaultNotificationPrefs;
            if (prefs.enabled.assigned) { playNotificationAlert(prefs); if (assignedUser.pushSubscription) sendPushNotification(assignedUser.pushSubscription, "New Assignment", message, prefs); }
        }
    }
    if (newNotifications.length > 0) { setNotifications(prev => [...prev, ...newNotifications]); newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl)); }
    triggerHapticFeedback('success');
  }, [users, settings.googleSheetsUrl]);

  const handleAssignOrder = (serviceId: string, assignedTo: string) => {
    let serviceToUpdate: Service | undefined;
    setSubmissions(prev => prev.map(s => {
      if(s.submissionId === serviceId) { serviceToUpdate = { ...s, assignedTo, status: ServiceStatus.Assigned, timestamp: new Date().toISOString() }; return serviceToUpdate; }
      return s;
    }));
    if (serviceToUpdate) {
        cloudDataService.saveRecord('Submissions', serviceToUpdate, settings.googleSheetsUrl);
        const message = `Assigned: You have a new order for ${serviceToUpdate.customerFirstName}.`;
        const newNotification: AppNotification = { id: `notif_assign_${serviceId}`, userId: assignedTo, serviceId: serviceId, message, timestamp: new Date().toISOString(), isRead: false, type: 'assigned' };
        setNotifications(prev => [...prev, newNotification]);
        cloudDataService.saveRecord('Notifications', newNotification, settings.googleSheetsUrl);
        const targetUser = users.find(u => u.username === assignedTo);
        const prefs = targetUser?.notificationPreferences || defaultNotificationPrefs;
        if(prefs.enabled.assigned) { playNotificationAlert(prefs); if(targetUser?.pushSubscription) sendPushNotification(targetUser.pushSubscription, "New Assignment", newNotification.message, prefs); }
    }
  };

  const handleStartOrder = (serviceId: string) => {
    let serviceToUpdate: Service | undefined;
    setSubmissions(prev => prev.map(s => {
      if(s.submissionId === serviceId) { serviceToUpdate = { ...s, status: ServiceStatus.InProgress, timestamp: new Date().toISOString() }; return serviceToUpdate; }
      return s;
    }));
    if(serviceToUpdate) { cloudDataService.saveRecord('Submissions', serviceToUpdate, settings.googleSheetsUrl); sendCustomerEmailNotification(serviceToUpdate); }
  };

  const handleSelfAssignOrder = (serviceId: string) => { if (!currentUser) return; handleAssignOrder(serviceId, currentUser.username); };
  const handleDeleteRequest = (service: Service) => { setDeletingService(service); };
  const handleConfirmDelete = () => {
    if (!deletingService) return;
    const serviceWithDeleteFlag = { ...deletingService, isDeleted: true, timestamp: new Date().toISOString() };
    setSubmissions(prev => prev.map(s => s.submissionId === serviceWithDeleteFlag.submissionId ? serviceWithDeleteFlag : s));
    cloudDataService.saveRecord('Submissions', serviceWithDeleteFlag, settings.googleSheetsUrl);
    setDeletingService(null);
  };

  const handleScheduleDroppedOrder = (serviceId: string, scheduledDate: string, assignedTo: string) => {
    let serviceToUpdate: Service | undefined;
    setSubmissions(prev => prev.map(s => {
        if(s.submissionId === serviceId) { serviceToUpdate = { ...s, assignedTo, scheduledDate, scheduledTime: s.scheduledTime || APPOINTMENT_TIME_SLOTS[0], status: ServiceStatus.Assigned, timestamp: new Date().toISOString() }; return serviceToUpdate; }
        return s;
    }));
    if (serviceToUpdate) {
        cloudDataService.saveRecord('Submissions', serviceToUpdate, settings.googleSheetsUrl);
        const message = `Assigned: You have a new order for ${serviceToUpdate.customerFirstName}.`;
        const newNotification: AppNotification = { id: `notif_assign_${serviceId}`, userId: assignedTo, serviceId: serviceId, message, timestamp: new Date().toISOString(), isRead: false, type: 'assigned' };
        setNotifications(prev => [...prev, newNotification]);
        cloudDataService.saveRecord('Notifications', newNotification, settings.googleSheetsUrl);
        const targetUser = users.find(u => u.username === assignedTo);
        const prefs = targetUser?.notificationPreferences || defaultNotificationPrefs;
        if (prefs.enabled.assigned) { playNotificationAlert(prefs); if(targetUser?.pushSubscription) sendPushNotification(targetUser.pushSubscription, "New Assignment", newNotification.message, prefs); }
    }
  };

  const handleSaveSettings = (newSettings: Settings) => { localStorage.setItem('customLogoUrl', newSettings.customLogoUrl); setSettings(newSettings); cloudDataService.saveRecord('Settings', newSettings, settings.googleSheetsUrl); setLogoHasError(false); triggerHapticFeedback('success'); };
  const handleUpdateUsers = (allUsers: User[]) => { const usersWithDefaults = allUsers.map(u => ({ ...u, notificationPreferences: mergeWithDefaultPrefs(u.notificationPreferences), permissions: u.permissions || authService.getDefaultPermissionsForRole(u.role) })); setUsers(usersWithDefaults); usersWithDefaults.forEach(u => cloudDataService.saveRecord('Users', u, settings.googleSheetsUrl)); triggerHapticFeedback('success'); };
  const handleUpdateSubscriptionPlans = (plans: SubscriptionPlan[]) => { setSubscriptionPlans(plans); plans.forEach(p => cloudDataService.saveRecord('SubscriptionPlans', p, settings.googleSheetsUrl)); };
  const handleUpdateUserSubscriptions = (subs: UserSubscription[]) => { setUserSubscriptions(subs); subs.forEach(s => cloudDataService.saveRecord('UserSubscriptions', s, settings.googleSheetsUrl)); }
  const handleUpdateServiceTemplates = (templates: ServiceTemplate[]) => { setServiceTemplates(templates); templates.forEach(t => cloudDataService.saveRecord('ServiceTemplates', t, settings.googleSheetsUrl)); };
  const handleSaveServiceTemplate = (template: ServiceTemplate) => { setServiceTemplates(prev => prev.map(t => t.id === template.id ? template : t)); cloudDataService.saveRecord('ServiceTemplates', template, settings.googleSheetsUrl); triggerHapticFeedback('success'); setView('SERVICE_TEMPLATE_MANAGEMENT'); setEditingTemplate(null); }
  const handleUpdateSpendCategories = (cats: SpendCategory[]) => { setSpendCategories(cats); cats.forEach(c => cloudDataService.saveRecord('SpendCategories', c, settings.googleSheetsUrl)); };
  const handleUpdatePredefinedCosts = (costs: PredefinedCost[]) => { setPredefinedCosts(costs); costs.forEach(c => cloudDataService.saveRecord('PredefinedCosts', c, settings.googleSheetsUrl)); };
  const handleUpdateKpiTargets = (targets: RetentionKpiTargets) => { const newSettings = { ...settings, retentionKpiTargets: targets }; setSettings(newSettings); cloudDataService.saveRecord('Settings', newSettings, settings.googleSheetsUrl); };
  const handleUpdateProfitLoss = (pl: ProfitLoss) => { setProfitLossData(prev => { const index = prev.findIndex(p => p.serviceId === pl.serviceId); if (index > -1) { const updated = [...prev]; updated[index] = pl; return updated; } return [...prev, pl]; }); cloudDataService.saveRecord('ProfitLoss', pl, settings.googleSheetsUrl); }
  const handleUpdateVehicleData = useCallback((newBrand: string, newModel: string) => { setVehicleData(prev => { if (!newBrand || !newModel) return prev; const newData = JSON.parse(JSON.stringify(prev)); if (!newData[newBrand]) newData[newBrand] = []; if (!newData[newBrand].includes(newModel)) { newData[newBrand].push(newModel); cloudDataService.saveRecord('VehicleData', { id: 'singleton', data: JSON.stringify(newData) }, settings.googleSheetsUrl); } return newData; }); }, [settings.googleSheetsUrl]);
  const handleUpdateTyreData = useCallback((type: keyof TyreData, value: string) => { if (!value) return; setTyreData(prev => { if (prev[type].includes(value)) return prev; const newTyreData = { ...prev }; newTyreData[type] = [...newTyreData[type], value].sort(); cloudDataService.saveRecord('TyreData', { id: 'singleton', data: JSON.stringify(newTyreData) }, settings.googleSheetsUrl); return newTyreData; }); }, [settings.googleSheetsUrl]);

  const handleAutoSchedule = (subscription: UserSubscription) => {
    const plan = subscriptionPlans.find(p => p.id === subscription.planId);
    if (!plan || plan.totalWashes <= 0) return;
    const today = new Date();
    if (today.getDate() > 7) { alert("Auto-scheduling for this month has been skipped because it is past the first week."); return; }
    const year = today.getFullYear();
    const month = today.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const washesToSchedule = plan.totalWashes;
    const interval = Math.floor(daysInMonth / washesToSchedule);
    const newServices: Service[] = [];
    for (let i = 0; i < washesToSchedule; i++) {
      const scheduledDay = Math.round((i * interval) + (interval / 2));
      const scheduledDate = new Date(year, month, scheduledDay);
      if (scheduledDate < new Date(today.getFullYear(), today.getMonth(), today.getDate())) continue;
      const submissionId = `SUB-${Date.now()}-${i}`;
      newServices.push({ ...createDefaultServiceState(), submissionId, appointmentId: submissionId, timestamp: new Date().toISOString(), status: ServiceStatus.Queued, customerFirstName: subscription.customerFirstName, customerLastName: subscription.customerLastName, mobileNumber: subscription.mobileNumber, carNumber: subscription.carNumber, carBrandModel: subscription.carBrandModel, streetAddress: subscription.streetAddress, serviceSelection: ['Car Washing'], isSubscription: true, isAutoScheduled: true, scheduledDate: scheduledDate.toISOString().split('T')[0], scheduledTime: "09:00 - 10:00", acknowledgement: true });
    }
    if (newServices.length > 0) { setSubmissions(prev => [...prev, ...newServices]); newServices.forEach(s => cloudDataService.saveRecord('Submissions', s, settings.googleSheetsUrl)); }
  };

  const handleMarkNotificationAsRead = (notificationId: string) => {
    let notifToSave: AppNotification | undefined;
    setNotifications(prev => prev.map(n => { if(n.id === notificationId) { notifToSave = { ...n, isRead: true }; return notifToSave; } return n; }));
    if(notifToSave) cloudDataService.saveRecord('Notifications', notifToSave, settings.googleSheetsUrl);
  };

  const handleMarkAllAsRead = () => {
    if (!currentUser) return;
    const notificationsToUpdate: AppNotification[] = [];
    setNotifications(prev => prev.map(n => { if((n.userId === currentUser.username || currentUser.role === 'admin' || currentUser.role === 'manager') && !n.isRead) { const updated = { ...n, isRead: true }; notificationsToUpdate.push(updated); return updated; } return n; }));
    notificationsToUpdate.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
  };

  const handleManualNotifyAll = useCallback(() => {
    if (!currentUser || currentUser.role !== 'admin') return;
    const newNotifications: AppNotification[] = [];
    users.forEach(user => {
        const message = `Admin Broadcast from ${currentUser.username}: Please check the dashboard for updates.`;
        const notif: AppNotification = { id: `notif_manual_${Date.now()}_${user.username}`, userId: user.username, serviceId: 'manual_broadcast', message, timestamp: new Date().toISOString(), isRead: false, type: 'manual-admin' };
        newNotifications.push(notif);
        const prefs = user.notificationPreferences || defaultNotificationPrefs;
        if(prefs.enabled.manual) { playNotificationAlert(prefs); if(user.pushSubscription) sendPushNotification(user.pushSubscription, "Admin Broadcast", message, prefs); }
    });
    setNotifications(prev => [...prev, ...newNotifications]);
    newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
    setIsNotificationHistoryOpen(true);
  }, [currentUser, users, settings.googleSheetsUrl]);

const handleNotifyForOrder = useCallback((serviceId: string) => {
    const service = submissions.find(s => s.submissionId === serviceId);
    if (!service || service.status === ServiceStatus.Completed || service.status === ServiceStatus.Draft) return;
    let newNotifications: AppNotification[] = [];
    let usersToNotify: User[] = [];
    if (service.status === ServiceStatus.Queued) {
        usersToNotify = users.filter(u => u.role === 'admin' || u.role === 'manager');
        usersToNotify.forEach(admin => { newNotifications.push({ id: `notif_manual_order_${Date.now()}_${admin.username}`, userId: admin.username, serviceId: service.submissionId, message: `Admin Reminder: The queued order for ${service.customerFirstName} needs attention.`, timestamp: new Date().toISOString(), isRead: false, type: 'manual-order' }); });
    } else if ((service.status === ServiceStatus.Assigned || service.status === ServiceStatus.InProgress) && service.assignedTo) {
        const assignedUser = users.find(u => u.username === service.assignedTo);
        if (assignedUser) {
            usersToNotify.push(assignedUser);
            newNotifications.push({ id: `notif_manual_order_${Date.now()}_${service.assignedTo}`, userId: service.assignedTo, serviceId: service.submissionId, message: `Reminder: Please check on your assigned order for ${service.customerFirstName}.`, timestamp: new Date().toISOString(), isRead: false, type: 'manual-order' });
        }
    }
    if (newNotifications.length > 0) {
        setNotifications(prev => [...prev, ...newNotifications]);
        newNotifications.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
        usersToNotify.forEach(user => {
            const prefs = user.notificationPreferences || defaultNotificationPrefs;
            if(prefs.enabled.manual) { playNotificationAlert(prefs); const message = newNotifications.find(n => n.userId === user.username)?.message || "Order Reminder"; if(user.pushSubscription) sendPushNotification(user.pushSubscription, "Order Reminder", message, prefs); }
        });
    }
}, [submissions, users, settings.googleSheetsUrl]);

const handleUpdateNotificationPreferences = (username: string, prefs: NotificationPreferences) => {
    let userToSave: User | undefined;
    setUsers(prev => prev.map(u => { if(u.username === username) { userToSave = { ...u, notificationPreferences: prefs }; return userToSave; } return u; }));
    if(currentUser?.username === username) setCurrentUser(prev => prev ? ({...prev, notificationPreferences: prefs}) : null);
    if(userToSave) cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
  };

const handleUpdatePushSubscription = (username: string, subscription: PushSubscriptionJSON | null) => {
    let userToSave: User | undefined;
    setUsers(prev => prev.map(u => { if(u.username === username) { userToSave = { ...u, pushSubscription: subscription || undefined }; return userToSave; } return u; }));
    if(currentUser?.username === username) setCurrentUser(prev => prev ? ({ ...prev, pushSubscription: subscription || undefined }) : null);
    if(userToSave) cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
};

const handleSaveNewSpend = (spendData: Omit<MiscSpend, 'spendId' | 'userId' | 'timestamp' | 'status'>) => {
    if (!currentUser) return;
    const newSpend: MiscSpend = { ...spendData, spendId: `spend_${Date.now()}`, userId: currentUser.username, timestamp: new Date().toISOString(), status: MiscSpendStatus.Pending };
    setMiscSpends(prev => [...prev, newSpend]);
    cloudDataService.saveRecord('MiscSpends', newSpend, settings.googleSheetsUrl);
    triggerHapticFeedback('success');
};

const handleUpdateSpendStatus = (spendId: string, status: MiscSpendStatus) => {
    const originalSpend = miscSpends.find(s => s.spendId === spendId);
    if (!originalSpend) return;
    const updatedSpend = { ...originalSpend, status };
    setMiscSpends(prevSpends => prevSpends.map(s => s.spendId === spendId ? updatedSpend : s));
    cloudDataService.saveRecord('MiscSpends', updatedSpend, settings.googleSheetsUrl);
    const wasPaid = originalSpend.status === MiscSpendStatus.Paid;
    const isNowPaid = status === MiscSpendStatus.Paid;
    if (!wasPaid && isNowPaid) {
        const newExpenseEntry: BookkeepingEntry = { id: `bk_exp_${spendId}`, timestamp: new Date().toISOString(), type: BookkeepingEntryType.Expense, description: `${updatedSpend.spendType} by ${updatedSpend.userId}`, amount: updatedSpend.amount, relatedId: spendId, recordedBy: currentUser?.username || 'system' };
        setBookkeeping(prev => [...prev.filter(b => b.id !== newExpenseEntry.id), newExpenseEntry]);
        cloudDataService.saveRecord('Bookkeeping', newExpenseEntry, settings.googleSheetsUrl);
    } else if (wasPaid && !isNowPaid) {
        setBookkeeping(prev => prev.filter(b => b.relatedId !== spendId));
        cloudDataService.deleteRecord('Bookkeeping', `bk_exp_${spendId}`, settings.googleSheetsUrl);
    }
    triggerHapticFeedback('success');
};

const handleUpdateAttendanceStatus = (username: string, status: AttendanceStatus) => {
    const newRecord = { timestamp: new Date().toISOString(), status };
    let userToSave: User | undefined;
    const updatedUsers = users.map(u => { if (u.username === username) { userToSave = { ...u, attendanceStatus: status, attendanceHistory: [...(u.attendanceHistory || []), newRecord] }; return userToSave; } return u; });
    setUsers(updatedUsers);
    if (currentUser?.username === username) { const updatedCurrentUser = updatedUsers.find(u => u.username === username)!; setCurrentUser(updatedCurrentUser); localStorage.setItem('service_app_current_user', JSON.stringify(updatedCurrentUser)); }
    if(userToSave) { cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl); triggerHapticFeedback('success'); }
};

  const handleShareOrder = (service: Service) => setSharingService(service);
  const handlePermanentDelete = (service: Service) => { setSubmissions(prev => prev.filter(s => s.submissionId !== service.submissionId)); cloudDataService.deleteRecord('Submissions', service.submissionId, settings.googleSheetsUrl); };
  const handleRestoreFromTrash = (service: Service) => { const restored = { ...service, isDeleted: false, timestamp: new Date().toISOString() }; setSubmissions(prev => prev.map(s => s.submissionId === restored.submissionId ? restored : s)); cloudDataService.saveRecord('Submissions', restored, settings.googleSheetsUrl); };

  if (publicService) return <PublicServiceSummary serviceData={publicService.data} logoUrl={settings.customLogoUrl} />;
  if (appIsLoading) return <LoadingScreen />;
  if (!currentUser) return <LoginPage onLoginAttempt={handleLoginAttempt} error={loginError} />;
  if (printingService) return <PrintPreview service={printingService} onClose={() => setPrintingService(null)} serviceTemplates={serviceTemplates} />;
  const currentUserNotifications = notifications.filter(n => n.userId === currentUser.username || currentUser.role === 'admin' || currentUser.role === 'manager').sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  const unreadCount = currentUserNotifications.filter(n => !n.isRead).length;

  const renderView = () => {
    const hasPermission = (p: Permission) => currentUser.permissions.includes(p);
    switch(view) {
      case 'FORM': return hasPermission(Permission.CAN_CREATE_ORDERS) ? <ServiceForm initialService={editingService} allSubmissions={submissions} onComplete={handleCompleteOrder} onSaveDraft={handleSaveDraft} onAdminUpdate={handleAdminUpdate} onExit={() => { setView('DASHBOARD'); setEditingService(null); }} googleDriveUploadUrl={settings.googleDriveUploadUrl} currentUser={currentUser} allUsers={users.map(({password, ...rest}) => rest)} userSubscriptions={userSubscriptions} serviceTemplates={serviceTemplates} vehicleData={vehicleData} tyreData={tyreData} onUpdateVehicleData={handleUpdateVehicleData} onUpdateTyreData={handleUpdateTyreData} pricingConfig={settings.pricingConfig} /> : <DashboardPage {...dashboardProps} />;
      case 'LIST': return hasPermission(Permission.CAN_VIEW_SERVICE_HISTORY) ? <SubmissionList submissions={submissions.filter(s => !s.isDeleted)} users={users.map(({password, ...rest}) => rest)} onEdit={handleEditService} onPrint={setPrintingService} onSummarize={setSummarizingService} currentUser={currentUser} serviceTemplates={serviceTemplates} /> : <DashboardPage {...dashboardProps} />;
      case 'APPOINTMENTS_OVERVIEW': return hasPermission(Permission.CAN_VIEW_APPOINTMENTS_OVERVIEW) ? <AppointmentsOverviewPage currentUser={currentUser} submissions={submissions.filter(s => !s.isDeleted)} onUpdateOrder={handleEditService} onStartOrder={handleStartOrder} onShareOrder={handleShareOrder} /> : <DashboardPage {...dashboardProps} />;
      case 'NOTIFICATION_PREFERENCES': return <NotificationPreferencesPage currentUser={currentUser} onSave={handleUpdateNotificationPreferences} onUpdatePushSubscription={handleUpdatePushSubscription} />;
      case 'USER_MANAGEMENT': return hasPermission(Permission.CAN_MANAGE_USERS) ? <UserManagementPage users={users.map(({password, ...rest}) => rest)} onUpdateUsers={handleUpdateUsers} fullUserList={users} currentUser={currentUser} /> : <DashboardPage {...dashboardProps} />;
      case 'SERVICE_TEMPLATE_MANAGEMENT': return hasPermission(Permission.CAN_MANAGE_SERVICES) ? <ServiceTemplateManagementPage templates={serviceTemplates} onUpdateTemplates={handleUpdateServiceTemplates} onEditTemplate={handleEditTemplate} /> : <DashboardPage {...dashboardProps} />;
       case 'SERVICE_TEMPLATE_EDITOR': return hasPermission(Permission.CAN_MANAGE_SERVICES) ? <ServiceTemplateEditorPage template={editingTemplate!} onSave={handleSaveServiceTemplate} onExit={() => { setView('SERVICE_TEMPLATE_MANAGEMENT'); setEditingTemplate(null); }} /> : <DashboardPage {...dashboardProps} />;
      case 'PLAN_MANAGEMENT': return hasPermission(Permission.CAN_MANAGE_PLANS) ? <SubscriptionPlanManagementPage plans={subscriptionPlans} onUpdatePlans={handleUpdateSubscriptionPlans} /> : <DashboardPage {...dashboardProps} />;
      case 'USER_SUBSCRIPTION_MANAGEMENT': return hasPermission(Permission.CAN_MANAGE_SUBSCRIPTIONS) ? <UserSubscriptionManagementPage userSubscriptions={userSubscriptions} subscriptionPlans={subscriptionPlans} onUpdateUserSubscriptions={handleUpdateUserSubscriptions} onAutoSchedule={handleAutoSchedule} /> : <DashboardPage {...dashboardProps} />;
      case 'SERVICE_REQUEST': return hasPermission(Permission.CAN_VIEW_SERVICE_REQUESTS) ? <ServiceRequestPage serviceRequests={serviceRequests} /> : <DashboardPage {...dashboardProps} />;
       case 'LIVE_MAP': return hasPermission(Permission.CAN_VIEW_LIVE_MAP) ? <LiveMapPage users={users.map(({password, ...rest}) => rest)} currentUser={currentUser} submissions={submissions.filter(s => !s.isDeleted)} onRefresh={handleManualRefresh} isRefreshing={isManualRefreshing} locationHistory={locationHistory} /> : <DashboardPage {...dashboardProps} />;
      case 'ANALYTICS': return hasPermission(Permission.CAN_VIEW_ANALYTICS) ? <AnalyticsPage submissions={submissions.filter(s => !s.isDeleted)} users={users.map(({password, ...rest}) => rest)} serviceTemplates={serviceTemplates} profitLossData={profitLossData} onSaveProfitLoss={handleUpdateProfitLoss} predefinedCosts={predefinedCosts} onUpdatePredefinedCosts={handleUpdatePredefinedCosts} /> : <DashboardPage {...dashboardProps} />;
       case 'CUSTOMER_HISTORY': return hasPermission(Permission.CAN_VIEW_CUSTOMER_HISTORY) ? <CustomerHistoryPage submissions={submissions.filter(s => !s.isDeleted)} currentUser={currentUser} onShareOrder={handleShareOrder} /> : <DashboardPage {...dashboardProps} />;
      case 'RETENTION': return hasPermission(Permission.CAN_VIEW_RETENTION_DASHBOARD) ? <RetentionDashboard submissions={submissions.filter(s => !s.isDeleted)} onCreateFollowUp={handleCreateFollowUp} settings={settings} onUpdateKpiTargets={handleUpdateKpiTargets} /> : <DashboardPage {...dashboardProps} />;
      case 'BOOKKEEPING': return hasPermission(Permission.CAN_LOG_EXPENSES) ? <BookkeepingPage currentUser={currentUser} miscSpends={miscSpends} users={users.map(({password, ...rest}) => rest)} googleDriveUploadUrl={settings.googleDriveUploadUrl} onSaveNewSpend={handleSaveNewSpend} onUpdateSpendStatus={handleUpdateSpendStatus} bookkeeping={bookkeeping} spendCategories={spendCategories} /> : <DashboardPage {...dashboardProps} />;
      case 'SPEND_CATEGORY_MANAGEMENT': return hasPermission(Permission.CAN_MANAGE_SPEND_CATEGORIES) ? <SpendCategoryManagementPage categories={spendCategories} onUpdateCategories={handleUpdateSpendCategories} /> : <DashboardPage {...dashboardProps} />;
      case 'TRASH': return hasPermission(Permission.CAN_VIEW_TRASH) ? <TrashPage deletedSubmissions={submissions.filter(s => s.isDeleted)} onRestore={handleRestoreFromTrash} onPermanentDelete={handlePermanentDelete} /> : <DashboardPage {...dashboardProps} />;
      case 'PRICING_MANAGEMENT': return hasPermission(Permission.CAN_MANAGE_PRICING) ? <PricingManagementPage pricingConfig={settings.pricingConfig || DEFAULT_PRICING_CONFIG} onUpdatePricing={(cfg) => { const newSettings = { ...settings, pricingConfig: cfg }; setSettings(newSettings); cloudDataService.saveRecord('Settings', newSettings, settings.googleSheetsUrl); }} /> : <DashboardPage {...dashboardProps} />;
      case 'ATTENDANCE_MANAGEMENT': return hasPermission(Permission.CAN_MANAGE_USERS) ? <AttendancePage users={users.map(({password, ...rest}) => rest)} /> : <DashboardPage {...dashboardProps} />;
      case 'DASHBOARD': return hasPermission(Permission.CAN_VIEW_DASHBOARD) ? <DashboardPage {...dashboardProps} /> : <div>Access Denied</div>;
      default: return <div>Unknown view</div>;
    }
  };

  const dashboardProps = { submissions: submissions.filter(s => !s.isDeleted), users: users.map(({password, ...rest}) => rest), currentUser, onCreateOrder: handleCreateOrder, onAssignOrder: handleAssignOrder, onStartOrder: handleStartOrder, onUpdateOrder: handleEditService, onSelfAssignOrder: handleSelfAssignOrder, onDeleteOrder: handleDeleteRequest, onScheduleDroppedOrder: handleScheduleDroppedOrder, onNotifyForOrder: handleNotifyForOrder, onUpdateAttendanceStatus: handleUpdateAttendanceStatus, userSubscriptions, serviceTemplates, setIsChatbotOpen, settings, locationHistory, vehicleData, tyreData, onShareOrder: handleShareOrder };

  return (
    <div className="min-h-screen bg-slate-100 flex">
      {isSettingsOpen && currentUser.permissions.includes(Permission.CAN_EDIT_SETTINGS) && <SettingsModal initialSettings={settings} onClose={() => setIsSettingsOpen(false)} onSave={handleSaveSettings} />}
      {summarizingService && <SummaryModal service={summarizingService} onClose={() => setSummarizingService(null)} />}
      {sharingService && <ShareOrderModal service={sharingService} onClose={() => setSharingService(null)} />}
      {isChatbotOpen && <ChatbotModal isOpen={isChatbotOpen} onClose={() => setIsChatbotOpen(false)} onSubmit={handleSaveDraftFromChatbot} serviceTemplates={serviceTemplates} />}
      {deletingService && <DeleteConfirmationModal isOpen={!!deletingService} onClose={() => setDeletingService(null)} onConfirm={handleConfirmDelete} service={deletingService} />}
      <Sidebar currentUser={currentUser} currentView={view} onNavigate={handleNavigate} onNewService={() => handleEditService(null)} onOpenSettings={() => setIsSettingsOpen(true)} onLogout={handleLogout} logoUrl={settings.customLogoUrl} logoHasError={logoHasError} onLogoError={() => setLogoHasError(true)} isMinimized={isSidebarMinimized} isOpenOnMobile={isMobileMenuOpen} onToggleDesktop={() => setIsSidebarMinimized(!isSidebarMinimized)} onCloseMobile={() => setIsMobileMenuOpen(false)} />
      <div className={`flex-1 transition-all duration-300 ${isSidebarMinimized ? 'md:pl-20' : 'md:pl-64'}`}>
          <header className="sticky top-0 bg-slate-100/80 backdrop-blur-md z-30 border-b border-slate-200 no-print">
              <div className="relative flex items-center justify-between min-h-16 px-4 md:px-6 py-2 gap-2">
                  <button className="md:hidden text-slate-600" onClick={() => setIsMobileMenuOpen(true)} aria-label="Open menu"><IconMenu2 className="w-6 h-6" /></button>
                  <div className="flex items-center gap-2 flex-wrap justify-end">
                      <RealTimeClock />
                      <div className="h-6 w-px bg-slate-300 hidden sm:block"></div>
                      <NotificationBell unreadCount={unreadCount} onClick={() => setIsNotificationHistoryOpen(prev => !prev)} />
                      {currentUser.role === 'admin' && <button onClick={handleManualNotifyAll} className="p-2 text-slate-500 hover:text-slate-800 hover:bg-slate-200 rounded-full transition-colors" aria-label="Send broadcast notification to all users" title="Send a notification to all users"><IconBellRinging className="w-6 h-6" /></button>}
                      <button onClick={handleManualRefresh} disabled={isManualRefreshing || !settings.googleSheetsUrl} className="p-2 text-slate-500 hover:text-slate-800 hover:bg-slate-200 rounded-full transition-colors disabled:opacity-50 disabled:cursor-not-allowed" aria-label="Refresh data from cloud" title={!settings.googleSheetsUrl ? "Cloud sync is offline. Check settings." : "Refresh data from cloud"}><IconRefresh className={`w-6 h-6 ${isManualRefreshing ? 'animate-spin' : ''}`} /></button>
                      <SyncStatusIndicator status={syncStatus} errorMessage={syncError} />
                  </div>
                   {isNotificationHistoryOpen && <NotificationHistory notifications={currentUserNotifications} onMarkAsRead={handleMarkNotificationAsRead} onMarkAllAsRead={handleMarkAllAsRead} onClose={() => setIsNotificationHistoryOpen(false)} />}
              </div>
          </header>
          <main className="p-4 sm:p-6 lg:p-8 w-full">
            {syncStatus === 'ERROR' && syncError && <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 relative mb-6 rounded-r-md" role="alert"><strong className="font-bold">Sync Error:</strong><span className="block sm:inline ml-2">{syncError}</span><button onClick={() => setSyncError(null)} className="absolute top-0 bottom-0 right-0 px-4 py-3" aria-label="Dismiss error message"><IconX className="h-6 w-6 text-red-500" /></button></div>}
            {renderView()}
          </main>
      </div>
    </div>
  );
};

