// --- ROBUST PARSING HELPERS ---
export const robustParseFloat = (value: any): number => {
    if (typeof value === 'number') return value;
    if (typeof value !== 'string') return 0;
    const cleanedString = value.replace(/[^0-9.-]+/g, "");
    const number = parseFloat(cleanedString);
    return isNaN(number) ? 0 : number;
};

export const robustParseInt = (value: any): number => {
    const floatVal = robustParseFloat(value);
    return parseInt(String(floatVal), 10);
};

// --- OFFLINE QUEUE MANAGEMENT ---
const QUEUE_STORAGE_KEY = 'service_app_offline_queue';
let operationQueue: any[] = [];
let isProcessingQueue = false;
let callbacks = {
    onSyncStatusChange: (status: SyncStatus) => {},
    onSyncError: (error: string | null) => {},
};

const loadQueueFromStorage = () => {
    try {
        const savedQueue = localStorage.getItem(QUEUE_STORAGE_KEY);
        operationQueue = savedQueue ? JSON.parse(savedQueue) : [];
        if (operationQueue.length > 0) {
            callbacks.onSyncStatusChange('UNSAVED');
        }
    } catch (e) {
        console.error("Failed to load offline queue:", e);
        operationQueue = [];
    }
};

const saveQueueToStorage = () => {
    try {
        localStorage.setItem(QUEUE_STORAGE_KEY, JSON.stringify(operationQueue));
    } catch (e) {
        console.error("Failed to save offline queue to local storage (Quota Exceeded?):", e);
    }
};

const addToQueue = (operation: any) => {
    operationQueue.push(operation);
    saveQueueToStorage();
    callbacks.onSyncStatusChange('UNSAVED');
    callbacks.onSyncError('You are offline. Changes have been saved locally and will sync when you reconnect.');
};

const processQueue = async (sheetsUrl: string) => {
    if (isProcessingQueue || !navigator.onLine || operationQueue.length === 0) {
        return;
    }
    isProcessingQueue = true;
    callbacks.onSyncStatusChange('SYNCING');
    callbacks.onSyncError(null);

    while (operationQueue.length > 0) {
        const operation = operationQueue[0];
        try {
            await executeOperation(operation, sheetsUrl);
            operationQueue.shift();
            saveQueueToStorage();
        } catch (error) {
            console.error("Failed to process queued operation. Halting queue.", error);
            const errorMessage = error instanceof Error ? error.message : "An unknown sync error occurred.";
            callbacks.onSyncStatusChange('ERROR');
            callbacks.onSyncError(`Sync failed: ${errorMessage}`);
            isProcessingQueue = false;
            return;
        }
    }

    callbacks.onSyncStatusChange('SYNCED');
    isProcessingQueue = false;
};

const PROXY_URL = '/.netlify/functions/google-sheets-proxy';
let bypassProxy = false;

const executeOperation = async (operation: any, sheetsUrl: string) => {
    const gasPayload = {
        action: operation.type === 'delete' ? 'deleteRecord' : 'upsertRecord',
        ...operation.payload
    };

    if (bypassProxy) {
         console.warn("Using direct (blind) sync due to previous proxy failure.");
         return fetch(sheetsUrl, {
            method: 'POST',
            body: JSON.stringify(gasPayload),
            mode: 'no-cors',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        }).then(() => {
             return { status: 'success', message: 'Saved via direct fallback.' };
        });
    }

    const proxyPayload = {
        sheetsUrl: sheetsUrl,
        payload: gasPayload
    };

    try {
        const response = await fetch(PROXY_URL, {
            method: 'POST',
            body: JSON.stringify(proxyPayload),
            headers: { 'Content-Type': 'application/json' },
        });

        if (!response.ok) {
            if (response.status === 404 || response.status === 500) {
                 bypassProxy = true;
                 return executeOperation(operation, sheetsUrl);
            }
             const errorBody = await response.json().catch(() => ({ error: 'Proxy failed' }));
             throw new Error(`Proxy error: ${errorBody.error}`);
        }

        const result = await response.json();
        if (result.status !== 'success') throw new Error(result.message || 'Script error');
        return result;
    } catch (e) {
        bypassProxy = true;
        return executeOperation(operation, sheetsUrl);
    }
};

export const init = (appCallbacks: { onSyncStatusChange: (s: SyncStatus) => void, onSyncError: (e: string | null) => void }, sheetsUrl: string) => {
    callbacks = appCallbacks;
    loadQueueFromStorage();
    window.addEventListener('online', () => processQueue(sheetsUrl));
    if (navigator.onLine) processQueue(sheetsUrl);
};

const getIdField = (sheetName: string): string => {
    switch (sheetName) {
        case 'Users': return 'username';
        case 'Submissions': return 'submissionId';
        case 'SubscriptionPlans': return 'id';
        case 'UserSubscriptions': return 'id';
        case 'ServiceTemplates': return 'id';
        case 'ServiceRequests': return 'id';
        case 'Notifications': return 'id';
        case 'LocationHistory': return 'historyId';
        case 'MiscSpends': return 'spendId';
        case 'Bookkeeping': return 'id';
        case 'ProfitLoss': return 'serviceId';
        case 'SpendCategories': return 'id';
        case 'PredefinedCosts': return 'id';
        case 'Settings': return 'googleSheetsUrl';
        case 'VehicleData': return 'id';
        case 'TyreData': return 'id';
        case 'PricingConfig': return 'id';
        default: throw new Error(`No ID field defined for sheet: ${sheetName}`);
    }
};

export const saveRecord = async (sheetName: string, record: any, sheetsUrl: string) => {
    if ((sheetName === 'VehicleData' || sheetName === 'TyreData' || sheetName === 'PricingConfig') && !record.id) {
        record.id = 'singleton';
    }
    const idField = getIdField(sheetName);
    if (!record[idField]) throw new Error(`Missing ID field "${idField}".`);

    const operation = { type: 'upsert', payload: { sheetName, idField, record } };

    try {
        if (!navigator.onLine) throw new Error("Offline");
        await executeOperation(operation, sheetsUrl);
        await processQueue(sheetsUrl);
    } catch (error) {
        addToQueue(operation);
    }
};

export const deleteRecord = async (sheetName: string, recordId: string, sheetsUrl: string) => {
     const operation = { type: 'delete', payload: { sheetName, idField: getIdField(sheetName), recordId } };
    try {
        if (!navigator.onLine) throw new Error("Offline");
        await executeOperation(operation, sheetsUrl);
        await processQueue(sheetsUrl);
    } catch (error) {
        addToQueue(operation);
    }
};

export const testCloudDataConnection = async (sheetsUrl: string): Promise<{ success: boolean; message: string; details?: string; }> => {
    if (!sheetsUrl) return { success: false, message: "URL is empty." };
    try {
        const url = new URL(sheetsUrl);
        url.searchParams.set('action', 'loadAllData');
        const response = await fetch(url.toString(), { method: 'GET', mode: 'cors' });
        const text = await response.text();
        if (!response.ok) return { success: false, message: `Status ${response.status}`, details: text };
        const data = JSON.parse(text);
        if (data.status === 'success') return { success: true, message: "Connection successful!" };
        return { success: false, message: data.message || 'Unknown error' };
    } catch (error) {
        return { success: false, message: error instanceof Error ? error.message : "Error" };
    }
};

const getDefaultAppData = (settings: Settings): AppData => {
    const defaultNotificationPrefs: NotificationPreferences = { enabled: { assigned: true, reminder: true, queued: true, completed: true, manual: true, overdue: true }, sound: 'default', vibration: true };
    const defaultKpiTargets: RetentionKpiTargets = { monthlyFollowUps: 20, conversionRatePercentage: 50, monthlyRevenue: 15000 };
    return {
        submissions: [], users: [], settings: {...settings, retentionKpiTargets: defaultKpiTargets},
        subscriptionPlans: [], userSubscriptions: [], serviceTemplates: [], serviceRequests: [], notifications: [], locationHistory: [],
        miscSpends: [], bookkeeping: [], profitLoss: [], spendCategories: [], predefinedCosts: [], vehicleData: CAR_BRANDS,
        tyreData: { brands: TIRE_BRANDS, models: [], sizes: [] }, predefinedAddons: [], pricingConfig: DEFAULT_PRICING_CONFIG,
    };
};

const parseServiceSelection = (raw: any): string[] => {
    if (Array.isArray(raw)) return raw.flatMap(item => parseServiceSelection(item));
    if (typeof raw === 'string') {
        const trimmed = raw.trim();
        if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
            try {
                const parsed = JSON.parse(trimmed);
                if (Array.isArray(parsed)) return parseServiceSelection(parsed);
            } catch (e) { }
        }
        return trimmed.split(',').map(s => s.replace(/[\[\]"']/g, '').trim()).filter(Boolean);
    }
    return [];
};

export const loadAppData = async (currentSettings: Settings): Promise<AppData> => {
    const sheetsUrl = currentSettings.googleSheetsUrl;
    if (!sheetsUrl) return getDefaultAppData(currentSettings);
    try {
        const url = new URL(sheetsUrl);
        url.searchParams.set('action', 'loadAllData');
        const response = await fetch(url.toString(), { method: 'GET', mode: 'cors' });
        const result = await response.json();
        if (result.status !== 'success') throw new Error(result.message || 'Cloud script returned an error.');

        const flatData = result.data;
        const tyreDetails = (flatData.TyreDetails || []);
        const batteryDetails = (flatData.BatteryDetails || []).map(d => ({ ...d, exchangeValue: robustParseFloat(d.exchangeValue), newBatteryAmount: robustParseFloat(d.newBatteryAmount) }));
        const customServices = (flatData.CustomServices || []).map(d => ({ ...d, amount: robustParseFloat(d.amount) }));
        const categorizedAddonsArr = (flatData.CategorizedAddons || []).map(d => ({ ...d, quantity: robustParseInt(d.quantity), amount: robustParseFloat(d.amount) }));
        const locationHistory = (flatData.LocationHistory || []).map(d => ({ ...d, latitude: robustParseFloat(d.latitude), longitude: robustParseFloat(d.longitude) }));
        const miscSpends = (flatData.MiscSpends || []).map(s => ({ ...s, amount: robustParseFloat(s.amount) }));
        const bookkeeping = (flatData.Bookkeeping || []).map(b => ({ ...b, amount: robustParseFloat(b.amount) }));
        const profitLoss = (flatData.ProfitLoss || []).map(pl => ({ ...pl, materialCost: robustParseFloat(pl.materialCost), laborCost: robustParseFloat(pl.laborCost), otherExpenses: robustParseFloat(pl.otherExpenses), calculatedProfit: robustParseFloat(pl.calculatedProfit) }));
        const spendCategories = (flatData.SpendCategories || []).map(c => ({ ...c }));
        const predefinedCosts = (flatData.PredefinedCosts || []).map(c => ({ ...c, value: robustParseFloat(c.value) }));
        const vehicleData = (flatData.VehicleData && flatData.VehicleData[0]?.data) ? JSON.parse(flatData.VehicleData[0].data) : CAR_BRANDS;
        const tyreData = (flatData.TyreData && flatData.TyreData[0]?.data) ? JSON.parse(flatData.TyreData[0].data) : { brands: TIRE_BRANDS, models: [], sizes: [] };
        const pricingConfig = (flatData.PricingConfig && flatData.PricingConfig[0]?.data) ? JSON.parse(flatData.PricingConfig[0].data) : DEFAULT_PRICING_CONFIG;
        const subscriptionPlans = (flatData.SubscriptionPlans || []).map(p => ({ ...p, price: robustParseFloat(p.price), totalWashes: robustParseInt(p.totalWashes), features: p.features ? String(p.features).split(',').map(f => f.trim()) : [] }));
        const userSubscriptions = (flatData.UserSubscriptions || []).map(s => ({ ...s, washesRemaining: robustParseInt(s.washesRemaining) }));
        const serviceRequests = (flatData.ServiceRequests || []);
        const notifications = (flatData.Notifications || []).map(n => ({ ...n, isRead: String(n.isRead).toUpperCase() === 'TRUE' }));
        const serviceTemplates = (flatData.ServiceTemplates || []).map(t => ({ ...t, isEnabled: String(t.isEnabled).toUpperCase() === 'TRUE', customFields: (flatData.ServiceTemplateFields || []).filter(f => f.relatedTemplateId === t.id).map(({ relatedTemplateId, ...rest }) => rest) }));

        const submissions = (flatData.Submissions || []).map((sub: any): Service => {
            let status = sub.status;
            if (status === "Submitted") status = ServiceStatus.Completed;
            else if (status === "Order Created") status = ServiceStatus.Queued;
            if (!status || !Object.values(ServiceStatus).includes(status as ServiceStatus)) status = ServiceStatus.Queued;

            let dynamicAddons = [];
            try { if (sub.dynamicAddons) dynamicAddons = typeof sub.dynamicAddons === 'string' ? JSON.parse(sub.dynamicAddons) : sub.dynamicAddons; } catch(e) { }
            let carWashDetails = undefined;
            try { if (sub.carWashDetails) carWashDetails = typeof sub.carWashDetails === 'string' ? JSON.parse(sub.carWashDetails) : sub.carWashDetails; } catch(e) { }
            let carCareDetails = undefined;
            try { if (sub.carCareDetails) carCareDetails = typeof sub.carCareDetails === 'string' ? JSON.parse(sub.carCareDetails) : sub.carCareDetails; } catch(e) { }

            return {
                ...sub, status, 
                dynamicAddons: Array.isArray(dynamicAddons) ? dynamicAddons : [], 
                carWashDetails, carCareDetails,
                isSubscription: String(sub.isSubscription).toUpperCase() === 'TRUE',
                isFollowUp: String(sub.isFollowUp).toUpperCase() === 'TRUE',
                isAutoScheduled: String(sub.isAutoScheduled).toUpperCase() === 'TRUE',
                acknowledgement: String(sub.acknowledgement).toUpperCase() === 'TRUE',
                grandTotal: robustParseFloat(sub.grandTotal),
                appointmentId: sub.appointmentId || sub.submissionId,
                tyreDetails: tyreDetails.filter(d => d.relatedServiceId === sub.submissionId),
                batteryDetails: batteryDetails.filter(d => d.relatedServiceId === sub.submissionId),
                customServices: customServices.filter(d => d.relatedServiceId === sub.submissionId),
                categorizedAddons: categorizedAddonsArr.filter(d => d.relatedServiceId === sub.submissionId),
                customFieldData: (flatData.CustomFieldData || []).filter(d => d.relatedServiceId === sub.submissionId).map(({ relatedServiceId, ...rest }) => rest),
                serviceSelection: parseServiceSelection(sub.serviceSelection),
                dependsOn: sub.dependsOn ? String(sub.dependsOn).split(',').map(s => s.trim()) : [],
            };
        });

        const cloudSettingsPartial = (flatData.Settings && flatData.Settings[0]) ? flatData.Settings[0] : {};
        const settings: Settings = {
            googleSheetsUrl: cloudSettingsPartial.googleSheetsUrl || currentSettings.googleSheetsUrl,
            googleDriveUploadUrl: cloudSettingsPartial.googleDriveUploadUrl || currentSettings.googleDriveUploadUrl,
            customLogoUrl: cloudSettingsPartial.customLogoUrl || currentSettings.customLogoUrl,
            retentionKpiTargets: cloudSettingsPartial.retentionKpiTargets ? (typeof cloudSettingsPartial.retentionKpiTargets === 'string' ? JSON.parse(cloudSettingsPartial.retentionKpiTargets) : cloudSettingsPartial.retentionKpiTargets) : currentSettings.retentionKpiTargets
        };

        const users = (flatData.Users && flatData.Users.length > 0) 
            ? (flatData.Users).map(u => ({ ...u, notificationPreferences: u.notificationPreferences ? JSON.parse(u.notificationPreferences) : {}, attendanceHistory: u.attendanceHistory ? JSON.parse(u.attendanceHistory) : [], permissions: u.permissions ? JSON.parse(u.permissions) : [], latitude: u.latitude ? robustParseFloat(u.latitude) : undefined, longitude: u.longitude ? robustParseFloat(u.longitude) : undefined }))
            : getDefaultAppData(settings).users;

        return { submissions, users, settings, subscriptionPlans, userSubscriptions, serviceTemplates, serviceRequests, notifications, locationHistory, miscSpends, bookkeeping, profitLoss, vehicleData, tyreData, pricingConfig, spendCategories, predefinedCosts, predefinedAddons: [] };
    } catch (error) { throw new Error(error instanceof Error ? error.message : "Load failed"); }
};

