        cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);
        sendCustomerEmailNotification(serviceToSave);
    }

    setSubmissions(prev => isUpdating ? prev.map(s => s.submissionId === service.submissionId ? serviceToSave : s) : [...prev, serviceToSave]);
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
    triggerHapticFeedback('success');
    setView('DASHBOARD');
    setEditingService(null);
  };

  const handleSaveDraft = (service: Service) => {
    let serviceToSave = { ...service, status: ServiceStatus.Draft, timestamp: new Date().toISOString() };
    const existingIndex = submissions.findIndex(s => s.submissionId === service.submissionId);
    if (existingIndex > -1) setSubmissions(prev => { const updated = [...prev]; updated[existingIndex] = serviceToSave; return updated; });
    else setSubmissions(prev => [...prev, serviceToSave]);
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
    setView('DASHBOARD');
    setEditingService(null);
  };

  const handleAdminUpdate = (service: Service) => {
    const originalService = submissions.find(s => s.submissionId === service.submissionId);
    if (!originalService) return;
    const serviceToSave = { ...service, timestamp: new Date().toISOString() };
    setSubmissions(prev => prev.map(s => s.submissionId === service.submissionId ? serviceToSave : s));
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
    setEditingService(serviceToSave);
  };

