    if (currentUser?.username === username) { const updatedCurrentUser = updatedUsers.find(u => u.username === username)!; setCurrentUser(updatedCurrentUser); localStorage.setItem('service_app_current_user', JSON.stringify(updatedCurrentUser)); }
