    };

    try {
        const cloudData = await cloudDataService.loadAppData(persistedSettings);
        let usersToSet = cloudData.users;

        if (usersToSet.length === 0 && cloudData.submissions.length === 0) {
            const defaultAdmin: User = { 
                username: 'admin', password: 'admin@123', role: 'admin', 
                notificationPreferences: defaultNotificationPrefs, 
                permissions: authService.getDefaultPermissionsForRole('admin'),
                attendanceStatus: 'CHECKED_OUT',
                attendanceHistory: [],
            };
            usersToSet = [defaultAdmin];
            cloudDataService.saveRecord('Users', defaultAdmin, PERMANENT_SHEET_URL);
        }

        // --- SAFEGUARD: Inject CAN_MANAGE_PRICING for admins ---
        usersToSet = usersToSet.map(user => {
            const finalUser = { ...user };
            let needsSave = false;

            // Ensure permissions are updated for admin roles
            if (finalUser.role === 'admin' && !finalUser.permissions.includes(Permission.CAN_MANAGE_PRICING)) {
                finalUser.permissions = [...new Set([...finalUser.permissions, Permission.CAN_MANAGE_PRICING, Permission.CAN_MANAGE_ADMINS, Permission.CAN_EDIT_SETTINGS])];
                needsSave = true;
            }

            if (!finalUser.notificationPreferences) { finalUser.notificationPreferences = mergeWithDefaultPrefs(); needsSave = true; }
            if ((finalUser.role as any) === 'user') { finalUser.role = 'agent'; needsSave = true; }
            if (!finalUser.attendanceStatus) { finalUser.attendanceStatus = 'CHECKED_OUT'; needsSave = true; }
            if (!finalUser.attendanceHistory) { finalUser.attendanceHistory = []; needsSave = true; }
            if (!finalUser.permissions || finalUser.permissions.length === 0) { finalUser.permissions = authService.getDefaultPermissionsForRole(finalUser.role); needsSave = true; }
            if (needsSave) cloudDataService.saveRecord('Users', finalUser, PERMANENT_SHEET_URL);
            return finalUser;
        });

        const localSubmissionsJson = localStorage.getItem('service_app_submissions');
        const rawLocalSubmissions: Service[] = localSubmissionsJson ? JSON.parse(localSubmissionsJson) : [];
        const cleanedLocalSubmissions = cleanSubmissionsArray(rawLocalSubmissions);
        const mergedSubmissions = mergeSubmissions(cleanSubmissionsArray(cloudData.submissions), cleanedLocalSubmissions);

        setSubmissions(mergedSubmissions);
        setUsers(usersToSet);
        setSettings({ ...cloudData.settings, googleSheetsUrl: PERMANENT_SHEET_URL, googleDriveUploadUrl: PERMANENT_DRIVE_URL, retentionKpiTargets: cloudData.settings.retentionKpiTargets || defaultKpiTargets });
        setSubscriptionPlans(cloudData.subscriptionPlans || []);
        setUserSubscriptions(cloudData.userSubscriptions || []);
        setServiceTemplates(cloudData.serviceTemplates.length > 0 ? cloudData.serviceTemplates : DEFAULT_SERVICE_TEMPLATES);
        setServiceRequests(cloudData.serviceRequests || []);
        setNotifications(cloudData.notifications || []);
        setLocationHistory(cloudData.locationHistory || []);
        setMiscSpends(cloudData.miscSpends || []);
        setBookkeeping(cloudData.bookkeeping || []);
        setProfitLossData(cloudData.profitLoss || []);
        setSpendCategories(cloudData.spendCategories || []);
        setPredefinedCosts(cloudData.predefinedCosts || []);
        setVehicleData(cloudData.vehicleData || CAR_BRANDS);
        setTyreData(cloudData.tyreData || { brands: TIRE_BRANDS, models: [], sizes: [] });

        if(cloudData.serviceTemplates.length === 0) DEFAULT_SERVICE_TEMPLATES.forEach(t => cloudDataService.saveRecord('ServiceTemplates', t, PERMANENT_SHEET_URL));
        if(!cloudData.settings.retentionKpiTargets) cloudDataService.saveRecord('Settings', { ...settings, retentionKpiTargets: defaultKpiTargets, googleSheetsUrl: PERMANENT_SHEET_URL}, PERMANENT_SHEET_URL);

        setSyncStatus('SYNCED');

    } catch (e) {
        setSyncStatus('ERROR');
        const errorMessage = e instanceof Error ? e.message : "Could not load data from cloud. Check settings and connection.";
        setSyncError(errorMessage);
        const rawLocalSubmissions: Service[] = JSON.parse(localStorage.getItem('service_app_submissions') || '[]');
        setSubmissions(cleanSubmissionsArray(rawLocalSubmissions));
        setUsers(JSON.parse(localStorage.getItem('service_app_users') || '[]').map(u => ({...u, notificationPreferences: mergeWithDefaultPrefs(u.notificationPreferences)})));
        setSettings(persistedSettings);
        setSubscriptionPlans(JSON.parse(localStorage.getItem('service_app_subscription_plans') || '[]'));
        setUserSubscriptions(JSON.parse(localStorage.getItem('service_app_user_subscriptions') || '[]'));
        setServiceTemplates(JSON.parse(localStorage.getItem('service_app_service_templates') || JSON.stringify(DEFAULT_SERVICE_TEMPLATES)));
        setNotifications(JSON.parse(localStorage.getItem('service_app_notifications') || '[]'));
    } finally {
        if (isInitial) setAppIsLoading(false);
        isInitialLoad.current = false;
    }
  }, []);

  useEffect(() => {
    const hash = window.location.hash;
    if (hash.startsWith('#service=')) {
      setAppIsLoading(true);
      try {
        const encodedData = decodeURIComponent(hash.substring('#service='.length));
        const jsonString = atob(encodedData);
        setPublicService({ data: JSON.parse(jsonString) });
        setAppIsLoading(false);
      } catch (e) {
        window.location.hash = '';
        cloudDataService.init({ onSyncStatusChange: setSyncStatus, onSyncError: setSyncError }, settings.googleSheetsUrl);
        loadAndMergeData(true);
      }
    } else {
      cloudDataService.init({ onSyncStatusChange: setSyncStatus, onSyncError: setSyncError }, settings.googleSheetsUrl);
      loadAndMergeData(true);
    }
  }, [loadAndMergeData, settings.googleSheetsUrl]);

  // Persistence logic...
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_submissions', submissions.slice(-100), { stripMedia: true }); }, [submissions]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_users', users); }, [users]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_subscription_plans', subscriptionPlans); }, [subscriptionPlans]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_user_subscriptions', userSubscriptions); }, [userSubscriptions]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_service_templates', serviceTemplates); }, [serviceTemplates]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_notifications', notifications.slice(-50)); }, [notifications]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_location_history', locationHistory.slice(-20)); }, [locationHistory]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_misc_spends', miscSpends); }, [miscSpends]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_bookkeeping', bookkeeping); }, [bookkeeping]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_profit_loss', profitLossData); }, [profitLossData]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_spend_categories', spendCategories); }, [spendCategories]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_predefined_costs', predefinedCosts); }, [predefinedCosts]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_vehicle_data', vehicleData); }, [vehicleData]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_tyre_data', tyreData); }, [tyreData]);

  // Rest of state logic...

  const handleLoginAttempt = useCallback((username: string, password?: string) => {
    setLoginError('');
    const validatedUser = authService.validateLogin(username, password, users);
    if (validatedUser) {
        const userFromFullList = users.find(u => u.username === validatedUser.username);
        const finalUser = { ...(userFromFullList || validatedUser), notificationPreferences: mergeWithDefaultPrefs(userFromFullList?.notificationPreferences) };
        localStorage.setItem('service_app_current_user', JSON.stringify(finalUser));
        setCurrentUser(finalUser);
        setView('DASHBOARD');
    } else { setLoginError('Invalid username or password.'); }
  }, [users]);

  const handleLogout = () => {
    if (currentUser?.attendanceStatus === 'CHECKED_IN') handleUpdateAttendanceStatus(currentUser.username, 'CHECKED_OUT');
    setCurrentUser(null);
    localStorage.removeItem('service_app_current_user');
    setSyncError(null);
    setView('DASHBOARD');
  };

  const handleEditService = (service: Service | null) => { setEditingService(service); setView('FORM'); setIsMobileMenuOpen(false); };
  const handleNavigate = (view: AppView) => { setView(view); setIsMobileMenuOpen(false); }
  const handleEditTemplate = (template: ServiceTemplate) => { setEditingTemplate(template); setView('SERVICE_TEMPLATE_EDITOR'); setIsMobileMenuOpen(false); };

  const handleCompleteOrder = (service: Service) => {
    const isUpdating = submissions.some(s => s.submissionId === service.submissionId);
    let serviceToSave: Service;
    const canAdminEdit = currentUser?.permissions.includes(Permission.CAN_EDIT_ANY_ORDER);

    if (isUpdating) {
        const originalService = submissions.find(s => s.submissionId === service.submissionId)!;
        serviceToSave = { ...service, status: canAdminEdit ? service.status : ServiceStatus.Completed, timestamp: new Date().toISOString(), submittedBy: originalService.submittedBy || currentUser?.username };
        const wasCompleted = originalService.status === ServiceStatus.Completed;
        const isNowCompleted = serviceToSave.status === ServiceStatus.Completed;
        if (!wasCompleted && isNowCompleted) {
            const newIncomeEntry: BookkeepingEntry = { id: `bk_inc_${serviceToSave.submissionId}`, timestamp: new Date().toISOString(), type: BookkeepingEntryType.Income, description: `Service for ${serviceToSave.customerFirstName} (#${serviceToSave.appointmentId?.split('-').pop()})`, amount: serviceToSave.grandTotal, relatedId: serviceToSave.submissionId, recordedBy: serviceToSave.submittedBy || currentUser?.username || 'system' };
            setBookkeeping(prev => [...prev.filter(b => b.id !== newIncomeEntry.id), newIncomeEntry]);
            cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);
            sendCustomerEmailNotification(serviceToSave);
        }
    } else {
        serviceToSave = { ...service, status: ServiceStatus.Completed, assignedTo: currentUser?.username, submittedBy: currentUser?.username, timestamp: new Date().toISOString() };
        const newIncomeEntry: BookkeepingEntry = { id: `bk_inc_${serviceToSave.submissionId}`, timestamp: new Date().toISOString(), type: BookkeepingEntryType.Income, description: `Service for ${serviceToSave.customerFirstName} (#${serviceToSave.appointmentId?.split('-').pop()})`, amount: serviceToSave.grandTotal, relatedId: serviceToSave.submissionId, recordedBy: serviceToSave.submittedBy || currentUser?.username || 'system' };
        setBookkeeping(prev => [...prev.filter(b => b.id !== newIncomeEntry.id), newIncomeEntry]);
        cloudDataService.saveRecord('Bookkeeping', newIncomeEntry, settings.googleSheetsUrl);
        sendCustomerEmailNotification(serviceToSave);
    }

    setSubmissions(prev => isUpdating ? prev.map(s => s.submissionId === service.submissionId ? serviceToSave : s) : [...prev, serviceToSave]);
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
    triggerHapticFeedback('success');
    setView('DASHBOARD');
    setEditingService(null);
  };

  const handleSaveDraft = (service: Service) => {
    let serviceToSave = { ...service, status: ServiceStatus.Draft, timestamp: new Date().toISOString() };
    const existingIndex = submissions.findIndex(s => s.submissionId === service.submissionId);
    if (existingIndex > -1) setSubmissions(prev => { const updated = [...prev]; updated[existingIndex] = serviceToSave; return updated; });
    else setSubmissions(prev => [...prev, serviceToSave]);
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
    setView('DASHBOARD');
    setEditingService(null);
  };

  const handleAdminUpdate = (service: Service) => {
    const originalService = submissions.find(s => s.submissionId === service.submissionId);
    if (!originalService) return;
    const serviceToSave = { ...service, timestamp: new Date().toISOString() };
    setSubmissions(prev => prev.map(s => s.submissionId === service.submissionId ? serviceToSave : s));
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
    setEditingService(serviceToSave);
  };

  // FIX: Added missing handleManualRefresh function.
  const handleManualRefresh = async () => {
    if (isManualRefreshing) return;
    setIsManualRefreshing(true);
    await loadAndMergeData(false);
    setIsManualRefreshing(false);
  };

  // FIX: Added missing handleSaveSettings function.
  const handleSaveSettings = (newSettings: Settings) => {
    localStorage.setItem('customLogoUrl', newSettings.customLogoUrl || '');
