import React, { useState, useMemo } from 'react';
import { Service, ServiceStatus, User, ServiceTemplate, Permission } from '../types';
import Card from './ui/Card';
import Button from './ui/Button';
import { IconChevronDown, IconSparkles, IconFilter, IconChevronUp } from './ui/Icon';
import { MetricsReport } from './MetricsReport';
import Input from './ui/Input';

interface SubmissionListProps {
  submissions: Service[];
  users: Omit<User, 'password'>[];
  onEdit: (service: Service) => void;
  onPrint: (service: Service) => void;
  onSummarize: (service: Service) => void;
  currentUser: User;
  serviceTemplates: ServiceTemplate[];
}

const ITEMS_PER_PAGE = 10;
type SortField = 'scheduledDate' | 'timestamp';
type SortOrder = 'asc' | 'desc';

// Robust helper to format date strings safely
const formatDateString = (dateStr?: string): string => {
    if (!dateStr) return 'N/A';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return 'N/A';
        return d.toLocaleString('en-IN', { 
            day: '2-digit', 
            month: 'short', 
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
            hour12: true
        });
    } catch (e) {
        return 'N/A';
    }
};

const parseDateTime = (service: Service): Date | null => {
    if (!service.scheduledDate || !service.scheduledTime) return null;
    try {
        const timePart = service.scheduledTime.split(' - ')[0];
        const [hour, minute] = timePart.split(':').map(Number);
        const d = new Date(service.scheduledDate);
        const localDate = new Date(d.getFullYear(), d.getMonth(), d.getDate(), hour, minute);
        return isNaN(localDate.getTime()) ? null : localDate;
    } catch (e) {
        console.error("Error parsing date/time for service:", service.submissionId, e);
        return null;
    }
};

const DetailItem: React.FC<{ label: string; value?: React.ReactNode | null; children?: React.ReactNode }> = ({ label, value, children }) => {
    const displayValue = value ?? children;
    if (!displayValue && typeof displayValue !== 'number' && displayValue !== '0') return null;
    return (
        <div className="py-2 break-words">
            <dt className="text-xs font-semibold text-slate-500 uppercase tracking-wider">{label}</dt>
            <dd className="text-sm text-slate-800">{displayValue}</dd>
        </div>
    );
};

const ServiceDetailsView: React.FC<{ service: Service, serviceTemplates: ServiceTemplate[] }> = ({ service, serviceTemplates }) => {
    const customFieldDetails = useMemo(() => {
        if (!service.customFieldData || service.customFieldData.length === 0) return null;
        const allCustomFields = serviceTemplates.flatMap(st => st.customFields);
        return (
            <div>
                <h5 className="font-semibold text-brand-blue mt-2">Service-Specific Details</h5>
                <dl className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-x-4">
                    {service.customFieldData.map(data => {
                        const fieldDef = allCustomFields.find(f => f.id === data.fieldId);
                        if (!fieldDef) return null;
                        let displayValue: React.ReactNode = data.value;
                        if (fieldDef.type === 'PHOTO' && typeof data.value === 'string') {
                            displayValue = <a href={data.value} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:underline">View Photo</a>;
                        }
                        return <DetailItem key={data.fieldId} label={fieldDef.label} value={displayValue} />;
                    })}
                </dl>
            </div>
        );
    }, [service.customFieldData, serviceTemplates]);

    return (
        <div className="space-y-4 text-sm">
            <h4 className="font-bold text-slate-700 mt-2 border-b pb-1">Full Details</h4>
             <dl className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-x-4">
                <DetailItem label="Appointment ID" value={service.appointmentId ? `#${String(service.appointmentId).split('-').pop()}`: undefined} />
                <DetailItem label="Submitted By" value={service.submittedBy} />
                <DetailItem label="Assigned To" value={service.assignedTo} />
                <DetailItem label="Scheduled Date" value={service.scheduledDate ? new Date(service.scheduledDate).toLocaleDateString() : undefined} />
                <DetailItem label="Scheduled Time" value={service.scheduledTime} />
            </dl>

            {service.serviceSelection && service.serviceSelection.includes("Car Washing") && (
                <div>
                    <h5 className="font-semibold text-brand-blue mt-2">Car Washing</h5>
                    {service.carWashDetails ? (
                        <dl className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-x-4">
                            <DetailItem label="Wash Type" value={service.carWashDetails.washType} />
                            <DetailItem label="Is Subscription?" value={service.isSubscription ? 'Yes' : 'No'} />
                            <DetailItem label="Total" value={`₹${(service.carWashDetails.price || 0).toFixed(2)}`} />
                        </dl>
                    ) : <DetailItem label="Details" value="N/A (Legacy Record)" />}

                    <div className="mt-2 space-y-2">
                        <DetailItem label="Before Wash Photo" value={service.beforeWashingPhoto} />
                        <DetailItem label="Before Inventory Video" value={service.beforeVideoInventory} />
                        <DetailItem label="Before Top Body Video" value={service.beforeVideoTopBody} />
                        <DetailItem label="Before Underchassis Video" value={service.beforeVideoUnderchassis} />
                        <DetailItem label="After Wash Photo" value={service.afterWashingPhoto} />
                        <DetailItem label="After Interior Video" value={service.afterVideoInterior} />
                        <DetailItem label="After Exterior Video" value={service.afterVideoExterior} />
                        <DetailItem label="After Underchassis Video" value={service.afterVideoUnderchassis} />
                    </div>
                </div>
            )}

            {service.serviceSelection && service.serviceSelection.includes("Car Care") && (
                <div>
                    <h5 className="font-semibold text-brand-blue mt-2">Car Care</h5>
                    {service.carCareDetails ? (
                        <dl className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-x-4">
                            <DetailItem label="Package Type" value={service.carCareDetails.careType} />
                            <DetailItem label="Total" value={`₹${(service.carCareDetails.price || 0).toFixed(2)}`} />
                        </dl>
                    ) : <DetailItem label="Details" value="N/A (Legacy Record)" />}
                </div>
            )}

            {service.serviceSelection && service.serviceSelection.includes("Tyre Replacement") && service.tyreDetails && service.tyreDetails.length > 0 && (
                <div>
                    <h5 className="font-semibold text-brand-blue mt-2">Tyre Replacement</h5>
                     {service.tyreDetails.map((tyre, index) => (
                        <div key={tyre.tyreId} className="p-2 mt-2 bg-slate-100 rounded-md border">
                           <p className="font-semibold text-xs text-slate-600">Tyre {index + 1}</p>
                           <dl className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-x-4">
                                <DetailItem label="DOT Code" value={tyre.dotCode} />
                                <DetailItem label="Tyre Size" value={tyre.tyreSize} />
                                <DetailItem label="Brand" value={tyre.brand} />
                                <DetailItem label="Model" value={tyre.model} />
                           </dl>
                           <DetailItem label="Serial Image" value={tyre.dotSerialNumberImage} />
                        </div>
                    ))}
                </div>
            )}

            {service.serviceSelection && service.serviceSelection.includes("Battery Replacement") && service.batteryDetails && service.batteryDetails.length > 0 && (
                <div>
                    <h5 className="font-semibold text-brand-blue mt-2">Battery Replacement</h5>
                     {service.batteryDetails.map((battery, index) => (
                        <div key={battery.batteryId} className="p-2 mt-2 bg-slate-100 rounded-md border">
                           <p className="font-semibold text-xs text-slate-600">Battery {index + 1}</p>
                           <dl className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-x-4">
                                <DetailItem label="Serial #" value={battery.serialNumber} />
                                <DetailItem label="Brand" value={battery.brand} />
                                <DetailItem label="New Cost" value={`₹${battery.newBatteryAmount}`} />
                                <DetailItem label="Exchange Value" value={`₹${battery.exchangeValue}`} />
                           </dl>
                        </div>
                    ))}
                </div>
            )}

            {customFieldDetails}

            {((service.dynamicAddons && service.dynamicAddons.length > 0) || (service.categorizedAddons && service.categorizedAddons.length > 0)) && (
                 <div>
                    <h5 className="font-semibold text-brand-blue mt-2">Add-ons</h5>
                    {(service.dynamicAddons || []).map(item => (
                         <div key={item.name} className="p-2 mt-1 bg-slate-100 rounded-md border">
                            <DetailItem label={item.name} value={`Qty: ${item.quantity} @ ₹${item.price.toFixed(2)}`} />
                         </div>
                    ))}
                    {(service.categorizedAddons || []).map((addon, index) => (
                        <div key={addon.id} className="p-2 mt-1 bg-slate-100 rounded-md border">
                            <DetailItem label={`${addon.productName} (${addon.category})`} value={`Qty: ${addon.quantity} @ ₹${addon.amount}`} />
                        </div>
                    ))}
                </div>
            )}

            {service.customServices && service.customServices.length > 0 && (
                 <div>
                    <h5 className="font-semibold text-brand-blue mt-2">Custom Services</h5>
                     {service.customServices.map((cs, index) => (
                        <div key={cs.customServiceId} className="p-2 mt-1 bg-slate-100 rounded-md border">
                            <DetailItem label={cs.serviceDescription || `Custom Service ${index+1}`} value={`₹${cs.amount}`} />
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};


export const SubmissionList: React.FC<SubmissionListProps> = ({ submissions, users, onEdit, onPrint, onSummarize, currentUser, serviceTemplates }) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [filters, setFilters] = useState({ textSearch: '', startDate: '', endDate: '', status: '', assignedUser: '' });
  const [sortField, setSortField] = useState<SortField>('scheduledDate');
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');
  const [currentPage, setCurrentPage] = useState(1);
  const [isFilterPanelOpen, setIsFilterPanelOpen] = useState(false);

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
    setCurrentPage(1);
  };

  const handleToggleDetails = (id: string) => {
    setExpandedId(currentId => (currentId === id ? null : id));
  };

  const filteredAndSortedSubmissions = useMemo(() => {
    const filtered = submissions.filter(service => {
        const searchTerm = filters.textSearch.toLowerCase().trim();
        const name = `${service.customerFirstName || ''} ${service.customerLastName || ''}`.toLowerCase();
        const mobile = String(service.mobileNumber || '').toLowerCase();
        const carNum = String(service.carNumber || '').toLowerCase();
        const appIdSuffix = (service.appointmentId ? String(service.appointmentId).split('-').pop() || '' : '').toLowerCase();

        const matchesSearch = searchTerm === '' ||
            name.includes(searchTerm) ||
            mobile.includes(searchTerm) ||
            carNum.includes(searchTerm) ||
            appIdSuffix.includes(searchTerm);

        const serviceDate = new Date(service.timestamp);
        const startDate = filters.startDate ? new Date(filters.startDate) : null;
        const endDate = filters.endDate ? new Date(filters.endDate) : null;

        if (startDate) startDate.setHours(0, 0, 0, 0);
        if (endDate) endDate.setHours(23, 59, 59, 999);

        const matchesDate = (!startDate || serviceDate >= startDate) && (!endDate || serviceDate <= endDate);
        const matchesStatus = !filters.status || service.status === filters.status;
        const matchesUser = !filters.assignedUser || service.assignedTo === filters.assignedUser;

        return matchesSearch && matchesDate && matchesStatus && matchesUser;
    });

    filtered.sort((a, b) => {
        if (sortField === 'scheduledDate') {
            const dateA = parseDateTime(a);
            const dateB = parseDateTime(b);
            if (!dateA && !dateB) return 0;
            if (!dateA) return 1;
            if (!dateB) return -1;
            return sortOrder === 'asc' ? dateA.getTime() - dateB.getTime() : dateB.getTime() - dateA.getTime();
        }
        const timeA = new Date(a.timestamp).getTime();
        const timeB = new Date(b.timestamp).getTime();
        return sortOrder === 'asc' ? timeA - timeB : timeB - timeA;
    });

    return filtered;
  }, [submissions, filters, sortField, sortOrder]);

  const totalPages = Math.ceil(filteredAndSortedSubmissions.length / ITEMS_PER_PAGE);
  const paginatedSubmissions = useMemo(() => {
      const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
      return filteredAndSortedSubmissions.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [filteredAndSortedSubmissions, currentPage]);

  const statusConfig = {
    [ServiceStatus.Completed]: 'bg-green-100 text-green-800',
    [ServiceStatus.InProgress]: 'bg-purple-100 text-purple-800',
    [ServiceStatus.Assigned]: 'bg-blue-100 text-blue-800',
    [ServiceStatus.Queued]: 'bg-slate-100 text-slate-800',
    [ServiceStatus.Draft]: 'bg-yellow-100 text-yellow-800',
  };

  return (
    <div className="space-y-6">
       <MetricsReport submissions={filteredAndSortedSubmissions} users={users} currentUser={currentUser} />

       <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Service History</h2>

       <Card>
            <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4">
                <div className="flex-grow">
                    <Input
                        label="Search by Name, Number, or ID"
                        id="textSearch"
                        name="textSearch"
                        value={filters.textSearch}
                        onChange={handleFilterChange}
                        placeholder="e.g., John Doe, 987..."
                        className="sm:max-w-sm"
                    />
                </div>
                <Button variant="secondary" onClick={() => setIsFilterPanelOpen(prev => !prev)} className="w-full sm:w-auto">
                    <IconFilter className="w-5 h-5 mr-2" />
                    <span>Filter & Sort</span>
                     <IconChevronDown className={`w-4 h-4 ml-2 transition-transform duration-300 ${isFilterPanelOpen ? 'rotate-180' : ''}`} />
                </Button>
            </div>
             {isFilterPanelOpen && (
                <div className="mt-4 pt-4 border-t border-slate-200">
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
                        <div className="space-y-4">
                            <div>
                                <label htmlFor="status" className="block text-sm font-medium text-slate-700 mb-1">Filter by Status</label>
                                <select
                                    id="status"
                                    name="status"
                                    value={filters.status}
                                    onChange={handleFilterChange}
                                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                                >
                                    <option value="">All Statuses</option>
                                    {Object.values(ServiceStatus).map(status => (
                                        <option key={status} value={status}>{status}</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label htmlFor="assignedUser" className="block text-sm font-medium text-slate-700 mb-1">Filter by Assigned User</label>
                                <select
                                    id="assignedUser"
                                    name="assignedUser"
                                    value={filters.assignedUser}
                                    onChange={handleFilterChange}
                                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                                >
                                    <option value="">All Users</option>
                                    {users.map(user => (
                                        <option key={user.username} value={user.username}>{user.username}</option>
                                    ))}
                                </select>
                            </div>
                        </div>
                        <div className="space-y-4">
                             <div>
                                <p className="block text-sm font-medium text-slate-700 mb-1">Filter by Submission Date Range</p>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                                    <Input
                                        label="From"
                                        id="startDate"
                                        name="startDate"
                                        type="date"
                                        value={filters.startDate}
                                        onChange={handleFilterChange}
                                    />
                                    <Input
                                        label="To"
                                        id="endDate"
                                        name="endDate"
                                        type="date"
                                        value={filters.endDate}
                                        onChange={handleFilterChange}
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Sort Results</label>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                                    <select
                                        id="sortField"
                                        name="sortField"
                                        value={sortField}
                                        onChange={(e) => setSortField(e.target.value as SortField)}
                                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                                    >
                                        <option value="scheduledDate">Scheduled Date</option>
                                        <option value="timestamp">Submission Date</option>
                                    </select>
                                    <div className="flex rounded-md shadow-sm">
                                        <button
                                            type="button"
                                            onClick={() => setSortOrder('asc')}
                                            className={`relative inline-flex items-center justify-center px-3 py-2 rounded-l-md border border-slate-300 text-sm font-medium transition-colors ${sortOrder === 'asc' ? 'bg-brand-accent text-brand-blue z-10' : 'bg-white text-slate-500 hover:bg-slate-50'}`}
                                            title="Ascending"
                                        >
                                            <IconChevronUp className="w-5 h-5" />
                                        </button>
                                        <button
                                            type="button"
                                            onClick={() => setSortOrder('desc')}
                                            className={`-ml-px relative inline-flex items-center justify-center px-3 py-2 rounded-r-md border border-slate-300 text-sm font-medium transition-colors ${sortOrder === 'desc' ? 'bg-brand-accent text-brand-blue z-10' : 'bg-white text-slate-500 hover:bg-slate-50'}`}
                                            title="Descending"
                                        >
                                            <IconChevronDown className="w-5 h-5" />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
             )}
        </Card>

       {submissions.length === 0 ? (
          <Card className="text-center">
            <p className="text-slate-500 mt-2">No service history found.</p>
          </Card>
        ) : filteredAndSortedSubmissions.length === 0 ? (
          <Card className="text-center">
            <p className="text-slate-500 mt-2">No services found matching your filters.</p>
          </Card>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {paginatedSubmissions.map(service => {
                    const selections = Array.isArray(service.serviceSelection) 
                        ? service.serviceSelection 
                        : typeof service.serviceSelection === 'string' 
                            ? (service.serviceSelection as string).split(',').filter(Boolean)
                            : [];

                    return (
                        <Card key={service.submissionId} className="flex flex-col justify-between hover:shadow-xl transition-shadow duration-300">
                            <div>
                            <div className="px-6 py-4 bg-slate-50 border-b border-slate-200">
                                <div className="flex justify-between items-start">
                                    <div>
                                    <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2 flex-wrap">
                                        <span>{service.customerFirstName} {service.customerLastName}</span>
                                        {service.appointmentId && <span className="text-sm font-mono text-brand-blue bg-blue-100 px-2 py-0.5 rounded-md">#{String(service.appointmentId).split('-').pop()}</span>}
                                    </h3>
                                    <p className="text-sm text-slate-500">{service.carBrandModel} ({service.carNumber})</p>
                                    </div>
                                    <div className="flex flex-col items-end space-y-1 flex-shrink-0 ml-2">
                                    <span className={`px-3 py-1 text-xs font-semibold rounded-full text-right ${statusConfig[service.status] || 'bg-gray-100 text-gray-800'}`}>
                                        {service.status}
                                        </span>
                                    </div>
                                </div>
                            </div>
                            <div className="p-6">
                                <div className="space-y-3 text-sm">
                                <p><strong className="font-semibold text-slate-600">Services:</strong> {selections.join(', ') || 'N/A'}</p>
                                <p><strong className="font-semibold text-slate-600">Last Update:</strong> {formatDateString(service.timestamp)}</p>
                                {service.scheduledDate && <p><strong className="font-semibold text-slate-600">Scheduled for:</strong> {new Date(service.scheduledDate).toLocaleDateString()} {service.scheduledTime ? `at ${service.scheduledTime}` : ''}</p>}
                                <p><strong className="font-semibold text-slate-600">Total:</strong> <span className="text-xl font-bold text-slate-800">₹{(service.grandTotal || 0).toFixed(2)}</span></p>
                                </div>
                            </div>
                            <div className={`transition-all duration-500 ease-in-out overflow-hidden ${expandedId === service.submissionId ? 'max-h-[2000px]' : 'max-h-0'}`}>
                                <div className="px-6 pb-6">
                                    <ServiceDetailsView service={service} serviceTemplates={serviceTemplates} />
                                </div>
                            </div>
                            </div>
                            <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-between items-center">
                            <Button variant="ghost" onClick={() => handleToggleDetails(service.submissionId)} size="sm">
                                {expandedId === service.submissionId ? 'Hide Details' : 'View All Fields'}
                                <IconChevronDown className={`w-4 h-4 ml-2 transition-transform duration-300 ${expandedId === service.submissionId ? 'rotate-180' : ''}`} />
                            </Button>
                            <div className="flex items-center space-x-2">
                                {service.status === ServiceStatus.Completed && (
                                    <>
                                        <Button
                                        variant="ghost"
                                        size="sm"
                                        onClick={() => onSummarize(service)}
                                        className="text-brand-blue hover:bg-brand-blue/10"
                                        title="Get AI-powered summary"
                                        >
                                        <IconSparkles className="w-5 h-5 mr-1" />
                                        Summarize
                                        </Button>
                                        <Button variant="secondary" size="sm" onClick={() => onPrint(service)}>Print</Button>
                                    </>
                                )}
                            </div>
                            </div>
                        </Card>
                    );
                })}
            </div>
            {totalPages > 1 && (
                <div className="flex justify-center items-center space-x-4 mt-8">
                    <Button 
                        onClick={() => setCurrentPage(p => Math.max(1, p - 1))} 
                        disabled={currentPage === 1}
                        variant="secondary"
                    >
                        Previous
                    </Button>
                    <span className="font-semibold text-slate-700">
                        Page {currentPage} of {totalPages}
                    </span>
                    <Button 
                        onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} 
                        disabled={currentPage === totalPages}
                        variant="secondary"
                    >
                        Next
                    </Button>
                </div>
            )}
          </>
       )}
    </div>
  );
};

