type SortOrder = 'asc' | 'desc';

// Robust helper to format date strings safely
const formatDateString = (dateStr?: string): string => {
    if (!dateStr) return 'N/A';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return 'N/A';
        return d.toLocaleString('en-IN', { 
            day: '2-digit', 
            month: 'short', 
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
            hour12: true
        });
    } catch (e) {
        return 'N/A';
    }
};

const parseDateTime = (service: Service): Date | null => {
    if (!service.scheduledDate || !service.scheduledTime) return null;
    try {
        const timePart = service.scheduledTime.split(' - ')[0];
        const [hour, minute] = timePart.split(':').map(Number);
        const d = new Date(service.scheduledDate);
        const localDate = new Date(d.getFullYear(), d.getMonth(), d.getDate(), hour, minute);
        return isNaN(localDate.getTime()) ? null : localDate;
    } catch (e) {
        console.error("Error parsing date/time for service:", service.submissionId, e);
        return null;
    }
};

const DetailItem: React.FC<{ label: string; value?: React.ReactNode | null; children?: React.ReactNode }> = ({ label, value, children }) => {
    const displayValue = value ?? children;
    if (!displayValue && typeof displayValue !== 'number' && displayValue !== '0') return null;
    return (
        <div className="py-2 break-words">
            <dt className="text-xs font-semibold text-slate-500 uppercase tracking-wider">{label}</dt>
            <dd className="text-sm text-slate-900 font-medium">{displayValue}</dd>
        </div>
    );
};

