                                    <div className="flex flex-col items-end space-y-1 flex-shrink-0 ml-2">
                                    <span className={`px-3 py-1 text-xs font-semibold rounded-full text-right ${statusConfig[service.status] || 'bg-gray-100 text-gray-800'}`}>
