// --- ENHANCED QUOTA MANAGEMENT ---

const MEDIA_KEYS = [
    'beforeWashingPhoto', 'beforeVideoInventory', 'beforeVideoTopBody', 'beforeVideoUnderchassis',
    'afterWashingPhoto', 'afterVideoInterior', 'afterVideoExterior', 'afterVideoUnderchassis',
    'dotSerialNumberImage'
];

/**
 * Surgically removes massive media strings but PRESERVES all text data (like Add-ons).
 */
const stripMediaForStorage = (data: any): any => {
    if (!data) return data;
    if (Array.isArray(data)) return data.map(item => stripMediaForStorage(item));
    if (typeof data === 'object') {
        const cleaned = { ...data };
        for (const key in cleaned) {
            if (MEDIA_KEYS.includes(key) && typeof cleaned[key] === 'string' && cleaned[key].startsWith('data:')) {
                cleaned[key] = "(image removed to save space)";
            } else if (key === 'tyreDetails' && Array.isArray(cleaned[key])) {
                cleaned[key] = cleaned[key].map((t: any) => ({
                    ...t,
                    dotSerialNumberImage: (t.dotSerialNumberImage?.startsWith('data:')) ? "(image removed)" : t.dotSerialNumberImage
                }));
            } else if (typeof cleaned[key] === 'object') {
                cleaned[key] = stripMediaForStorage(cleaned[key]);
            }
        }
        return cleaned;
    }
    return data;
};

/**
 * Safe persistence that prioritizes current work and handles storage limits gracefully.
 */
const safeLocalStorageSet = (key: string, value: any, options: { stripMedia?: boolean } = {}) => {
    try {
        const dataToSave = options.stripMedia ? stripMediaForStorage(value) : value;
        localStorage.setItem(key, JSON.stringify(dataToSave));
    } catch (e) {
        if (e instanceof DOMException && (e.name === 'QuotaExceededError' || e.name === 'NS_ERROR_DOM_QUOTA_REACHED')) {
            console.warn(`LocalStorage quota exceeded while saving ${key}. Cleaning non-critical logs...`);
            localStorage.removeItem('service_app_location_history');
            localStorage.removeItem('service_app_notifications');

            if (key === 'service_app_submissions') {
                try {
                    const smallerWindow = stripMediaForStorage(Array.isArray(value) ? value.slice(-20) : value);
                    localStorage.setItem(key, JSON.stringify(smallerWindow));
                    return;
                } catch (innerError) { /* fail silent */ }
            }

            try {
                localStorage.setItem(key, JSON.stringify(stripMediaForStorage(value)));
            } catch (retryError) {
                console.error("Storage full. Critical data might not be cached locally. Ensure cloud sync is active.", retryError);
            }
        }
    }
};

