          permissions: u.permissions || authService.getDefaultPermissionsForRole(u.role)
        }));
      setUsers(usersWithDefaults);
      usersWithDefaults.forEach(u => cloudDataService.saveRecord('Users', u, settings.googleSheetsUrl));
      triggerHapticFeedback('success');
  };

  const handleUpdateSubscriptionPlans = (plans: SubscriptionPlan[]) => {
    setSubscriptionPlans(plans);
    plans.forEach(p => cloudDataService.saveRecord('SubscriptionPlans', p, settings.googleSheetsUrl));
  };

  const handleUpdateUserSubscriptions = (subs: UserSubscription[]) => {
    setUserSubscriptions(subs);
    subs.forEach(s => cloudDataService.saveRecord('UserSubscriptions', s, settings.googleSheetsUrl));
  };

  const handleUpdateProfitLoss = (pl: ProfitLoss) => {
      setProfitLossData(prev => {
          const index = prev.findIndex(p => p.serviceId === pl.serviceId);
          if (index > -1) {
              const updated = [...prev];
              updated[index] = pl;
              return updated;
          }
          return [...prev, pl];
      });
      cloudDataService.saveRecord('ProfitLoss', pl, settings.googleSheetsUrl);
  };

  const handleUpdatePredefinedCosts = (costs: PredefinedCost[]) => {
    setPredefinedCosts(costs);
    costs.forEach(c => cloudDataService.saveRecord('PredefinedCosts', c, settings.googleSheetsUrl));
  };

  const handleUpdateServiceTemplates = (templates: ServiceTemplate[]) => {
    setServiceTemplates(templates);
    templates.forEach(t => cloudDataService.saveRecord('ServiceTemplates', t, settings.googleSheetsUrl));
  };

  const handleSaveServiceTemplate = (template: ServiceTemplate) => {
    setServiceTemplates(prev => prev.map(t => t.id === template.id ? template : t));
    cloudDataService.saveRecord('ServiceTemplates', template, settings.googleSheetsUrl);
    triggerHapticFeedback('success');
    setView('SERVICE_TEMPLATE_MANAGEMENT');
    setEditingTemplate(null);
  };

  const handleMarkNotificationAsRead = (notificationId: string) => {
    let notifToSave: AppNotification | undefined;
    setNotifications(prev => prev.map(n => {
        if(n.id === notificationId) {
            notifToSave = { ...n, isRead: true };
            return notifToSave;
        }
        return n;
    }));
    if(notifToSave) cloudDataService.saveRecord('Notifications', notifToSave, settings.googleSheetsUrl);
  };

  const handleMarkAllAsRead = () => {
    if (!currentUser) return;
    const notificationsToUpdate: AppNotification[] = [];
    setNotifications(prev => prev.map(n => {
        if((n.userId === currentUser.username || currentUser.role === 'admin' || currentUser.role === 'manager') && !n.isRead) {
            const updated = { ...n, isRead: true };
            notificationsToUpdate.push(updated);
            return updated;
        }
        return n;
    }));
    notificationsToUpdate.forEach(n => cloudDataService.saveRecord('Notifications', n, settings.googleSheetsUrl));
  };

  const handleUpdateAttendanceStatus = (username: string, status: AttendanceStatus) => {
    const newRecord = { timestamp: new Date().toISOString(), status };
    let userToSave: User | undefined;
    const updatedUsers = users.map(u => { if (u.username === username) { userToSave = { ...u, attendanceStatus: status, attendanceHistory: [...(u.attendanceHistory || []), newRecord] }; return userToSave; } return u; });
    setUsers(updatedUsers);
    if (currentUser?.username === username) { const updatedCurrentUser = updatedUsers.find(u => u.username === username)!; setCurrentUser(updatedCurrentUser); localStorage.setItem('service_app_current_user', JSON.stringify(updatedCurrentUser)); }
    if(userToSave) { cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl); triggerHapticFeedback('success'); }
  };

  const handleAutoSchedule = (subscription: UserSubscription) => {
    const plan = subscriptionPlans.find(p => p.id === subscription.planId);
    if (!plan || plan.totalWashes <= 0) return;

    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const washesToSchedule = plan.totalWashes;
    const interval = Math.floor(daysInMonth / washesToSchedule);
    const newServices: Service[] = [];

    for (let i = 0; i < washesToSchedule; i++) {
      const scheduledDay = Math.round((i * interval) + (interval / 2));
      const scheduledDate = new Date(year, month, scheduledDay);
      if (scheduledDate < new Date(today.getFullYear(), today.getMonth(), today.getDate())) continue;

      const submissionId = `SUB-${Date.now()}-${i}`;
      const newService: Service = {
        ...createDefaultServiceState(),
        submissionId, appointmentId: submissionId, timestamp: new Date().toISOString(), status: ServiceStatus.Queued,
        customerFirstName: subscription.customerFirstName, customerLastName: subscription.customerLastName, mobileNumber: subscription.mobileNumber,
        customerEmail: subscription.customerEmail,
        carNumber: subscription.carNumber, carBrandModel: subscription.carBrandModel, streetAddress: subscription.streetAddress,
        serviceSelection: ['Car Washing'], isSubscription: true,
        scheduledDate: scheduledDate.toISOString().split('T')[0], scheduledTime: "09:00 - 10:00",
        acknowledgement: true,
      };
      newServices.push(newService);
    }

    if (newServices.length > 0) {
      setSubmissions(prev => [...prev, ...newServices]);
      newServices.forEach(s => cloudDataService.saveRecord('Submissions', s, settings.googleSheetsUrl));
    }
  };

  const handleShareOrder = (service: Service) => setSharingService(service);

  if (publicService) return <PublicServiceSummary serviceData={publicService.data} logoUrl={settings.customLogoUrl} />;
  if (appIsLoading) return <LoadingScreen />;
  if (!currentUser) return <LoginPage onLoginAttempt={handleLoginAttempt} error={loginError} />;
  if (printingService) return <PrintPreview service={printingService} onClose={() => setPrintingService(null)} serviceTemplates={serviceTemplates} />;

  const currentUserNotifications = notifications.filter(n => n.userId === currentUser.username || currentUser.role === 'admin' || currentUser.role === 'manager').sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  const unreadCount = currentUserNotifications.filter(n => !n.isRead).length;

  const dashboardProps = { submissions: submissions.filter(s => !s.isDeleted), users: users.map(({password, ...rest}) => rest), currentUser, onCreateOrder: (d: any) => {}, onAssignOrder: (sid: string, u: string) => {}, onStartOrder: (sid: string) => {}, onUpdateOrder: handleEditService, onSelfAssignOrder: (sid: string) => {}, onDeleteOrder: (s: Service) => {}, onScheduleDroppedOrder: (sid: string, d: string, u: string) => {}, onNotifyForOrder: (sid: string) => {}, onUpdateAttendanceStatus: handleUpdateAttendanceStatus, userSubscriptions, serviceTemplates, setIsChatbotOpen, settings, locationHistory, vehicleData, tyreData, onShareOrder: handleShareOrder };

  return (
    <div className="min-h-screen bg-slate-100 flex">
      {isSettingsOpen && currentUser.permissions.includes(Permission.CAN_EDIT_SETTINGS) && <SettingsModal initialSettings={settings} onClose={() => setIsSettingsOpen(false)} onSave={handleSaveSettings} />}
      {summarizingService && <SummaryModal service={summarizingService} onClose={() => setSummarizingService(null)} />}
      {sharingService && <ShareOrderModal service={sharingService} onClose={() => setSummarizingService(null)} />}
      {isChatbotOpen && <ChatbotModal isOpen={isChatbotOpen} onClose={() => setIsChatbotOpen(false)} onSubmit={(d) => {}} serviceTemplates={serviceTemplates} />}
      {deletingService && <DeleteConfirmationModal isOpen={!!deletingService} onClose={() => setDeletingService(null)} onConfirm={() => {}} service={deletingService} />}

      <Sidebar currentUser={currentUser} currentView={view} onNavigate={handleNavigate} onNewService={() => handleEditService(null)} onOpenSettings={() => setIsSettingsOpen(true)} onLogout={handleLogout} logoUrl={settings.customLogoUrl} logoHasError={logoHasError} onLogoError={() => setLogoHasError(true)} isMinimized={isSidebarMinimized} isOpenOnMobile={isMobileMenuOpen} onToggleDesktop={() => setIsSidebarMinimized(!isSidebarMinimized)} onCloseMobile={() => setIsMobileMenuOpen(false)} />

      <div className={`flex-1 transition-all duration-300 ${isSidebarMinimized ? 'md:pl-20' : 'md:pl-64'}`}>
          <header className="sticky top-0 bg-slate-100/80 backdrop-blur-md z-30 border-b border-slate-200 no-print">
              <div className="relative flex items-center justify-between min-h-16 px-4 md:px-6 py-2 gap-2">
                  <button className="md:hidden text-slate-600" onClick={() => setIsMobileMenuOpen(true)} aria-label="Open menu"><IconMenu2 className="w-6 h-6" /></button>
                  <div className="flex items-center gap-2 flex-wrap justify-end">
                      <RealTimeClock />
                      <div className="h-6 w-px bg-slate-300 hidden sm:block"></div>
                      <NotificationBell unreadCount={unreadCount} onClick={() => setIsNotificationHistoryOpen(prev => !prev)} />
                      <button onClick={handleManualRefresh} disabled={isManualRefreshing || !settings.googleSheetsUrl} className="p-2 text-slate-500 hover:text-slate-800 hover:bg-slate-200 rounded-full transition-colors disabled:opacity-50 disabled:cursor-not-allowed" aria-label="Refresh data from cloud" title={!settings.googleSheetsUrl ? "Cloud sync is offline. Check settings." : "Refresh data from cloud"}><IconRefresh className={`w-6 h-6 ${isManualRefreshing ? 'animate-spin' : ''}`} /></button>
                      <SyncStatusIndicator status={syncStatus} errorMessage={syncError} />
                  </div>
                   {isNotificationHistoryOpen && <NotificationHistory notifications={currentUserNotifications} onMarkAsRead={handleMarkNotificationAsRead} onMarkAllAsRead={handleMarkAllAsRead} onClose={() => setIsNotificationHistoryOpen(false)} />}
              </div>
          </header>
          <main className="p-4 sm:p-6 lg:p-8 w-full">
            {syncStatus === 'ERROR' && syncError && <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 relative mb-6 rounded-r-md" role="alert"><strong className="font-bold">Sync Error:</strong><span className="block sm:inline ml-2">{syncError}</span><button onClick={() => setSyncError(null)} className="absolute top-0 bottom-0 right-0 px-4 py-3" aria-label="Dismiss error message"><IconX className="h-6 w-6 text-red-500" /></button></div>}
            {/* Standard render logic switch based on 'view' state */}
            {view === 'DASHBOARD' && <DashboardPage {...dashboardProps} />}
            {view === 'LIST' && <SubmissionList submissions={submissions.filter(s => !s.isDeleted)} users={users.map(({password, ...rest}) => rest)} onEdit={handleEditService} onPrint={setPrintingService} onSummarize={setSummarizingService} currentUser={currentUser} serviceTemplates={serviceTemplates} />}
            {view === 'PRICING_MANAGEMENT' && <PricingManagementPage pricingConfig={settings.pricingConfig || DEFAULT_PRICING_CONFIG} onUpdatePricing={(cfg) => { const newSettings = { ...settings, pricingConfig: cfg }; setSettings(newSettings); cloudDataService.saveRecord('Settings', newSettings, settings.googleSheetsUrl); }} />}
            {view === 'USER_MANAGEMENT' && <UserManagementPage users={users.map(({password, ...rest}) => rest)} onUpdateUsers={handleUpdateUsers} fullUserList={users} currentUser={currentUser} />}
            {view === 'ATTENDANCE_MANAGEMENT' && <AttendancePage users={users.map(({password, ...rest}) => rest)} />}
            {view === 'ANALYTICS' && <AnalyticsPage submissions={submissions.filter(s => !s.isDeleted)} users={users.map(({password, ...rest}) => rest)} serviceTemplates={serviceTemplates} profitLossData={profitLossData} onSaveProfitLoss={handleUpdateProfitLoss} predefinedCosts={predefinedCosts} onUpdatePredefinedCosts={handleUpdatePredefinedCosts} />}
            {view === 'BOOKKEEPING' && <BookkeepingPage currentUser={currentUser} miscSpends={miscSpends} users={users.map(({password, ...rest}) => rest)} googleDriveUploadUrl={settings.googleDriveUploadUrl} onSaveNewSpend={(s) => {}} onUpdateSpendStatus={(id, st) => {}} bookkeeping={bookkeeping} spendCategories={spendCategories} />}
            {view === 'SERVICE_TEMPLATE_MANAGEMENT' && <ServiceTemplateManagementPage templates={serviceTemplates} onUpdateTemplates={handleUpdateServiceTemplates} onEditTemplate={handleEditTemplate} />}
            {view === 'SERVICE_TEMPLATE_EDITOR' && <ServiceTemplateEditorPage template={editingTemplate!} onSave={handleSaveServiceTemplate} onExit={() => setView('SERVICE_TEMPLATE_MANAGEMENT')} />}
            {view === 'NOTIFICATION_PREFERENCES' && <NotificationPreferencesPage currentUser={currentUser} onSave={(u, p) => {}} onUpdatePushSubscription={(u, s) => {}} />}
            {view === 'LIVE_MAP' && <LiveMapPage users={users.map(({password, ...rest}) => rest)} currentUser={currentUser} submissions={submissions.filter(s => !s.isDeleted)} onRefresh={handleManualRefresh} isRefreshing={isManualRefreshing} locationHistory={locationHistory} />}
            {view === 'CUSTOMER_HISTORY' && <CustomerHistoryPage submissions={submissions.filter(s => !s.isDeleted)} currentUser={currentUser} onShareOrder={handleShareOrder} />}
            {view === 'RETENTION' && <RetentionDashboard submissions={submissions.filter(s => !s.isDeleted)} onCreateFollowUp={(c, s) => {}} settings={settings} onUpdateKpiTargets={(t) => {}} />}
            {view === 'APPOINTMENTS_OVERVIEW' && <AppointmentsOverviewPage currentUser={currentUser} submissions={submissions.filter(s => !s.isDeleted)} onUpdateOrder={handleEditService} onStartOrder={(sid) => {}} onShareOrder={handleShareOrder} />}
            {view === 'PLAN_MANAGEMENT' && <SubscriptionPlanManagementPage plans={subscriptionPlans} onUpdatePlans={handleUpdateSubscriptionPlans} />}
            {view === 'USER_SUBSCRIPTION_MANAGEMENT' && <UserSubscriptionManagementPage userSubscriptions={userSubscriptions} subscriptionPlans={subscriptionPlans} onUpdateUserSubscriptions={handleUpdateUserSubscriptions} onAutoSchedule={handleAutoSchedule} />}
            {view === 'SPEND_CATEGORY_MANAGEMENT' && <SpendCategoryManagementPage categories={spendCategories} onUpdateCategories={(cats) => { setSpendCategories(cats); cats.forEach(c => cloudDataService.saveRecord('SpendCategories', c, settings.googleSheetsUrl)); }} />}
            {view === 'TRASH' && <TrashPage deletedSubmissions={submissions.filter(s => s.isDeleted)} onRestore={(s) => handleAdminUpdate({ ...s, isDeleted: false })} onPermanentDelete={(s) => { setSubmissions(prev => prev.filter(item => item.submissionId !== s.submissionId)); cloudDataService.deleteRecord('Submissions', s.submissionId, settings.googleSheetsUrl); }} />}
            {view === 'PROFIT_LOSS' && <ProfitLossPage submissions={submissions.filter(s => !s.isDeleted)} profitLossData={profitLossData} onSave={handleUpdateProfitLoss} predefinedCosts={predefinedCosts} onUpdatePredefinedCosts={handleUpdatePredefinedCosts} />}
            {view === 'FORM' && <ServiceForm initialService={editingService} allSubmissions={submissions} onComplete={handleCompleteOrder} onSaveDraft={handleSaveDraft} onAdminUpdate={handleAdminUpdate} onExit={() => { setView('DASHBOARD'); setEditingService(null); }} googleDriveUploadUrl={settings.googleDriveUploadUrl} currentUser={currentUser} allUsers={users.map(({password, ...rest}) => rest)} userSubscriptions={userSubscriptions} serviceTemplates={serviceTemplates} vehicleData={vehicleData} tyreData={tyreData} onUpdateVehicleData={(b, m) => {}} onUpdateTyreData={(t, v) => {}} pricingConfig={settings.pricingConfig} />}
          </main>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { Service, ServiceStatus, ProfitLoss, PredefinedCost } from '../../types';
import Card from '../ui/Card';
import Input from '../ui/Input';
import Button from '../ui/Button';
import { IconDeviceFloppy, IconCheck, IconChevronDown, IconSettings, IconPlus, IconTrash } from '../ui/Icon';

interface ProfitLossPageProps {
  submissions: Service[];
  profitLossData: ProfitLoss[];
  onSave: (pl: ProfitLoss) => void;
  predefinedCosts: PredefinedCost[];
  onUpdatePredefinedCosts: (costs: PredefinedCost[]) => void;
}

// Internal Settings Modal for Defining Presets
const CostPresetsModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    costs: PredefinedCost[];
    onUpdate: (costs: PredefinedCost[]) => void;
}> = ({ isOpen, onClose, costs, onUpdate }) => {
    const [localCosts, setLocalCosts] = useState<PredefinedCost[]>(costs);

    useEffect(() => {
        if (isOpen) setLocalCosts(costs);
    }, [isOpen, costs]);

    if (!isOpen) return null;

    const handleAdd = () => {
        setLocalCosts(prev => [...prev, { id: `pc_${Date.now()}`, name: '', value: 0 }]);
    };

    const handleUpdate = (id: string, field: keyof PredefinedCost, val: string | number) => {
        setLocalCosts(prev => prev.map(c => c.id === id ? { ...c, [field]: val } : c));
    };

    const handleDelete = (id: string) => {
        setLocalCosts(prev => prev.filter(c => c.id !== id));
    };

    const handleSave = () => {
        onUpdate(localCosts.filter(c => c.name.trim() !== ''));
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-[70] p-4 modal-backdrop" onClick={onClose}>
            <div onClick={(e) => e.stopPropagation()} className="w-full max-w-lg modal-content">
                <Card title="Manage Quick-Add Costs">
                    <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-2">
                        <p className="text-sm text-slate-600">Create presets for common operating costs like overhead, rent shares, or base labor to quickly apply them to services.</p>
                        {localCosts.map((cost) => (
                            <div key={cost.id} className="flex gap-2 items-end p-2 bg-slate-50 rounded border border-slate-200">
                                <div className="flex-grow">
                                    <Input 
                                        label="Cost Label" 
                                        id={`pc-name-${cost.id}`}
                                        value={cost.name} 
                                        onChange={e => handleUpdate(cost.id, 'name', e.target.value)} 
                                        placeholder="e.g., Overhead"
                                    />
                                </div>
                                <div className="w-24">
                                    <Input 
                                        label="Value (₹)" 
                                        id={`pc-val-${cost.id}`}
                                        type="number" 
                                        value={cost.value} 
                                        onChange={e => handleUpdate(cost.id, 'value', parseFloat(e.target.value) || 0)} 
                                    />
                                </div>
                                <Button variant="danger" size="sm" className="mb-0.5 p-2 h-10 w-10" onClick={() => handleDelete(cost.id)}>
                                    <IconTrash className="w-5 h-5" />
                                </Button>
                            </div>
                        ))}
                        <Button variant="ghost" onClick={handleAdd} className="w-full py-3 border-dashed border-2">
                            <IconPlus className="w-4 h-4 mr-2" /> Add New Cost Preset
                        </Button>
                    </div>
                    <div className="mt-6 flex justify-end gap-2 pt-4 border-t border-slate-200">
                        <Button variant="ghost" onClick={onClose}>Cancel</Button>
                        <Button onClick={handleSave}>Save Settings</Button>
                    </div>
                </Card>
            </div>
        </div>
    );
};

const ProfitLossCalculator: React.FC<{ 
    service: Service, 
    profitLoss: ProfitLoss | undefined, 
    onSave: (pl: ProfitLoss) => void,
    predefinedCosts: PredefinedCost[]
}> = ({ service, profitLoss, onSave, predefinedCosts }) => {

    const [pl, setPl] = useState<ProfitLoss>(profitLoss || {
        serviceId: service.submissionId,
        materialCost: service.tyreMaterialCost || 0,
        laborCost: service.tyreLaborCost || 0,
        otherExpenses: 0,
        calculatedProfit: service.grandTotal - (service.tyreMaterialCost || 0) - (service.tyreLaborCost || 0),
        notes: ''
    });

    const [isSaved, setIsSaved] = useState(!!profitLoss);

    const calculateProfit = useCallback((material: number, labor: number, other: number) => {
        return service.grandTotal - material - labor - other;
    }, [service.grandTotal]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        const numValue = name !== 'notes' ? parseFloat(value) || 0 : 0;

        setPl(prev => {
            const updated = { ...prev, [name]: name === 'notes' ? value : numValue };
            if (name !== 'notes') {
                updated.calculatedProfit = calculateProfit(
                    name === 'materialCost' ? numValue : updated.materialCost,
                    name === 'laborCost' ? numValue : updated.laborCost,
                    name === 'otherExpenses' ? numValue : updated.otherExpenses
                );
            }
            return updated;
        });
        setIsSaved(false);
    };

    const applyPreset = (cost: number, name: string) => {
        setPl(prev => {
            const updatedOther = prev.otherExpenses + cost;
            const updatedNotes = prev.notes ? `${prev.notes}, ${name}` : name;
            return {
                ...prev,
                otherExpenses: updatedOther,
                notes: updatedNotes,
                calculatedProfit: calculateProfit(prev.materialCost, prev.laborCost, updatedOther)
            };
        });
        setIsSaved(false);
    };

    const handleSave = () => {
        onSave(pl);
        setIsSaved(true);
    };

    const isNegative = pl.calculatedProfit < 0;

    return (
        <div className="p-4 bg-slate-50 rounded-lg border-l-4 border-slate-300 space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 items-end">
                <Input label="Material Cost (₹)" name="materialCost" type="number" value={pl.materialCost} onChange={handleChange} className="bg-white" />
                <Input label="Labor Cost (₹)" name="laborCost" type="number" value={pl.laborCost} onChange={handleChange} className="bg-white" />
                <Input label="Other Expenses (₹)" name="otherExpenses" type="number" value={pl.otherExpenses} onChange={handleChange} className="bg-white" />
                <div className="flex flex-col h-full justify-end pb-1 px-3 bg-white rounded border border-slate-200">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Estimated Profit</p>
                    <p className={`text-2xl font-bold ${isNegative ? 'text-red-600' : 'text-green-600'}`}>
                        ₹{pl.calculatedProfit.toFixed(2)}
                    </p>
                </div>
            </div>

            {predefinedCosts.length > 0 && (
                <div className="flex flex-wrap gap-2 items-center">
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Quick Add:</span>
                    {predefinedCosts.map(cost => (
                        <button 
                            key={cost.id} 
                            onClick={() => applyPreset(cost.value, cost.name)}
                            className="px-2 py-1 text-xs bg-white border border-slate-200 rounded-full hover:border-brand-accent hover:text-brand-blue transition-all shadow-sm flex items-center gap-1 active:scale-95"
                        >
                            <span className="font-semibold">{cost.name}</span>
                            <span className="text-slate-400">₹{cost.value}</span>
                        </button>
                    ))}
                </div>
            )}

            <div className="flex items-center gap-4">
                <div className="flex-grow">
                     <textarea
                        name="notes"
                        value={pl.notes || ''}
                        onChange={handleChange}
                        rows={1}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-brand-accent sm:text-sm bg-white"
                        placeholder="Cost details or specific parts used..."
                    />
                </div>
                <Button 
                    onClick={handleSave} 
                    size="sm" 
                    variant={isSaved ? "ghost" : "primary"}
                    className="flex-shrink-0 min-w-[100px]"
                >
                    {isSaved ? <><IconCheck className="w-4 h-4 mr-2 text-green-600" /> Saved</> : <><IconDeviceFloppy className="w-4 h-4 mr-2" /> Save</>}
                </Button>
            </div>
        </div>
    );
};


const ProfitLossPage: React.FC<ProfitLossPageProps> = ({ submissions, profitLossData, onSave, predefinedCosts, onUpdatePredefinedCosts }) => {
    const [openMonths, setOpenMonths] = useState<Record<string, boolean>>({});
    const [isSettingsOpen, setIsSettingsOpen] = useState(false);

    const completedServicesByDate = useMemo(() => {
        const grouped: Record<string, Record<string, Service[]>> = {};

        submissions
            .filter(s => s.status === ServiceStatus.Completed)
            .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
            .forEach(service => {
                const date = new Date(service.timestamp);
                const monthYear = `${date.toLocaleString('default', { month: 'long' })} ${date.getFullYear()}`;
                const day = date.toISOString().split('T')[0];

                if (!grouped[monthYear]) {
                    grouped[monthYear] = {};
                }
                if (!grouped[monthYear][day]) {
                    grouped[monthYear][day] = [];
                }
                grouped[monthYear][day].push(service);
            });

        // Set most recent month to be open
        const firstMonth = Object.keys(grouped)[0];
        if (firstMonth && Object.keys(openMonths).length === 0) {
            setOpenMonths({ [firstMonth]: true });
        }

        return grouped;
    }, [submissions]);

    const totalNetProfit = useMemo(() => {
        return submissions
            .filter(s => s.status === ServiceStatus.Completed)
            .reduce((sum, s) => {
                const pl = profitLossData.find(p => p.serviceId === s.submissionId);
                if (pl) return sum + pl.calculatedProfit;
                return sum + s.grandTotal;
            }, 0);
    }, [submissions, profitLossData]);

    const toggleMonth = (monthYear: string) => {
        setOpenMonths(prev => ({ ...prev, [monthYear]: !prev[monthYear] }));
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-slate-800 tracking-tight">Profit & Loss</h1>
                    <p className="text-slate-600">Analyze job profitability by logging material, labor, and overhead costs.</p>
                </div>
                <div className="flex items-center gap-3">
                    <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm flex items-center gap-3">
                        <div className="p-2 bg-blue-100 rounded-full text-brand-blue">
                            <IconCheck className="w-5 h-5" />
                        </div>
                        <div>
                            <p className="text-[10px] font-bold text-slate-400 uppercase">Total Net Profit</p>
                            <p className={`text-xl font-bold ${totalNetProfit >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                                ₹{totalNetProfit.toLocaleString('en-IN')}
                            </p>
                        </div>
                    </div>
                    <Button variant="secondary" onClick={() => setIsSettingsOpen(true)}>
                        <IconSettings className="w-5 h-5 mr-2" />
                        Quick Add Settings
                    </Button>
                </div>
            </div>

            <div className="space-y-8">
                {Object.entries(completedServicesByDate).map(([monthYear, days]) => (
                    <Card key={monthYear} className="overflow-visible">
                        <button onClick={() => toggleMonth(monthYear)} className="w-full flex justify-between items-center text-left group">
                            <h2 className="text-2xl font-bold text-slate-700 group-hover:text-brand-blue transition-colors">{monthYear}</h2>
                            <IconChevronDown className={`w-6 h-6 text-slate-500 transition-transform duration-300 ${openMonths[monthYear] ? 'rotate-180' : ''}`} />
                        </button>

                        {openMonths[monthYear] && (
                            <div className="mt-6 space-y-8">
                                {Object.entries(days).map(([day, services]) => (
                                    <div key={day} className="space-y-4">
                                        <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest pb-1 border-b border-slate-100">
                                            {new Date(day).toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'short' })}
                                        </h3>
                                        <div className="space-y-6">
                                            {services.map(service => (
                                                <div key={service.submissionId}>
                                                    <div className="flex justify-between items-center mb-3">
                                                        <div>
                                                            <p className="font-bold text-slate-800">
                                                                <span className="text-brand-blue mr-2 font-mono">#{service.appointmentId?.split('-').pop()}</span>
                                                                {service.customerFirstName} {service.customerLastName}
                                                            </p>
                                                            <p className="text-xs text-slate-500">{service.carBrandModel} • {service.serviceSelection.join(', ')}</p>
                                                        </div>
                                                        <div className="text-right">
                                                            <p className="text-[10px] text-slate-400 uppercase font-bold">Revenue</p>
                                                            <p className="text-lg font-bold text-slate-800">₹{service.grandTotal.toFixed(2)}</p>
                                                        </div>
                                                    </div>
                                                    <ProfitLossCalculator
                                                        service={service}
                                                        profitLoss={profitLossData.find(pl => pl.serviceId === service.submissionId)}
                                                        onSave={onSave}
                                                        predefinedCosts={predefinedCosts}
                                                    />
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </Card>
                ))}
                {Object.keys(completedServicesByDate).length === 0 && (
                    <Card>
                        <p className="text-center text-slate-500 py-12">No completed services found in your records.</p>
                    </Card>
                )}
            </div>

            <CostPresetsModal 
                isOpen={isSettingsOpen} 
                onClose={() => setIsSettingsOpen(false)} 
                costs={predefinedCosts} 
                onUpdate={onUpdatePredefinedCosts}
            />
        </div>
    );
};

