    { id: 'plans', label: 'Plan Templates', icon: <IconCreditCard className="w-4 h-4" />, permission: Permission.CAN_MANAGE_PLANS },
    { id: 'members', label: 'Member Subs', icon: <IconTrophy className="w-4 h-4" />, permission: Permission.CAN_MANAGE_SUBSCRIPTIONS },
    { id: 'alerts', label: 'Alert Settings', icon: <IconBellCog className="w-4 h-4" /> },
