          {activeTab === 'plans' && (
            <div className="animate-fadeIn">
              <SubscriptionPlanManagementPage 
                plans={props.subscriptionPlans} 
                onUpdatePlans={props.onUpdatePlans} 
              />
            </div>
          )}
          {activeTab === 'members' && (
            <div className="animate-fadeIn">
              <UserSubscriptionManagementPage 
                userSubscriptions={props.userSubscriptions} 
                subscriptionPlans={props.subscriptionPlans} 
                onUpdateUserSubscriptions={props.onUpdateUserSubscriptions} 
                onAutoSchedule={props.onAutoSchedule} 
              />
            </div>
          )}
          {activeTab === 'alerts' && (
            <div className="animate-fadeIn">
              <NotificationPreferencesPage 
                currentUser={props.currentUser} 
                onSave={props.onUpdateNotificationPreferences} 
                onUpdatePushSubscription={props.onUpdatePushSubscription} 
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import Card from '../ui/Card';
import Input from '../ui/Input';
import Button from '../ui/Button';
import { Settings } from '../../types';
import { IconLoader } from '../ui/Icon';
import { testCloudDataConnection } from '../../services/cloudDataService';

interface SettingsModalContentProps {
  initialSettings: Settings;
  onSave: (newSettings: Settings) => void;
}

export const SettingsModalContent: React.FC<SettingsModalContentProps> = ({ initialSettings, onSave }) => {
  const [settings, setSettings] = useState<Settings>(initialSettings);
  const [saveMessage, setSaveMessage] = useState('');
  const [isTestingData, setIsTestingData] = useState(false);
  const [dataTestResult, setDataTestResult] = useState<{message: string, success: boolean} | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setSettings(prev => ({...prev, [e.target.id]: e.target.value}));
  };

  const handleSave = () => {
    onSave(settings);
    setSaveMessage('Cloud configuration updated.');
    setTimeout(() => setSaveMessage(''), 3000);
  };

  const handleTest = async () => {
      setIsTestingData(true);
      const result = await testCloudDataConnection(settings.googleSheetsUrl);
      setDataTestResult(result);
      setIsTestingData(false);
  };

  return (
    <Card title="Cloud Configuration">
      <div className="space-y-6">
        <div>
          <p className="text-sm text-slate-600 mb-4">Core backend URLs for data synchronization and file storage.</p>
          <div className="flex items-start gap-2">
            <Input
              label="Google Sheets Data URL"
              id="googleSheetsUrl"
              value={settings.googleSheetsUrl}
              onChange={handleChange}
              readOnly
              className="bg-slate-50"
            />
            <div className="pt-7">
              <Button variant="secondary" onClick={handleTest} disabled={isTestingData}>
                {isTestingData ? <IconLoader className="w-5 h-5 animate-spin" /> : 'Test'}
              </Button>
            </div>
          </div>
          {dataTestResult && (
            <p className={`mt-2 text-xs font-semibold ${dataTestResult.success ? 'text-green-600' : 'text-red-600'}`}>
              {dataTestResult.message}
            </p>
          )}
        </div>
        <Input
          label="Google Drive Upload URL"
          id="googleDriveUploadUrl"
          value={settings.googleDriveUploadUrl}
          onChange={handleChange}
          readOnly
          className="bg-slate-50"
        />
        <Input
          label="Custom Logo URL"
          id="customLogoUrl"
          value={settings.customLogoUrl}
          onChange={handleChange}
          placeholder="https://example.com/logo.png"
        />
        <div className="pt-4 border-t flex justify-between items-center">
          <p className="text-sm font-semibold text-green-600">{saveMessage}</p>
          <Button onClick={handleSave}>Save Config</Button>
        </div>
      </div>
    </Card>
  );
};

