            let needsSave = false;
            if (!finalUser.notificationPreferences) { finalUser.notificationPreferences = mergeWithDefaultPrefs(); needsSave = true; }
            if (!finalUser.attendanceStatus) { finalUser.attendanceStatus = 'CHECKED_OUT'; needsSave = true; }
            if (!finalUser.attendanceHistory) { finalUser.attendanceHistory = []; needsSave = true; }
            if (!finalUser.permissions || finalUser.permissions.length === 0) { finalUser.permissions = authService.getDefaultPermissionsForRole(finalUser.role); needsSave = true; }
            if (needsSave) cloudDataService.saveRecord('Users', finalUser, PERMANENT_SHEET_URL);
            return finalUser;
        });

        const localSubmissionsJson = localStorage.getItem('service_app_submissions');
        const rawLocalSubmissions: Service[] = localSubmissionsJson ? JSON.parse(localSubmissionsJson) : [];
        const cleanedLocalSubmissions = cleanSubmissionsArray(rawLocalSubmissions);
        const mergedSubmissions = mergeSubmissions(cleanSubmissionsArray(cloudData.submissions), cleanedLocalSubmissions);

        setSubmissions(mergedSubmissions);
        setUsers(usersToSet);
        setSettings({ ...cloudData.settings, googleSheetsUrl: PERMANENT_SHEET_URL, googleDriveUploadUrl: PERMANENT_DRIVE_URL });
        setSubscriptionPlans(cloudData.subscriptionPlans || []);
        setUserSubscriptions(cloudData.userSubscriptions || []);
        setServiceTemplates(cloudData.serviceTemplates.length > 0 ? cloudData.serviceTemplates : DEFAULT_SERVICE_TEMPLATES);
        setServiceRequests(cloudData.serviceRequests || []);
        setNotifications(cloudData.notifications || []);
        setLocationHistory(cloudData.locationHistory || []);
        setProfitLossData(cloudData.profitLoss || []);
        setPredefinedCosts(cloudData.predefinedCosts || []);
        setVehicleData(cloudData.vehicleData || CAR_BRANDS);
        setTyreData(cloudData.tyreData || { brands: TIRE_BRANDS, models: [], sizes: [] });

        setSyncStatus('SYNCED');

    } catch (e) {
        setSyncStatus('ERROR');
        setSyncError(e instanceof Error ? e.message : "Load failed");
    } finally {
        if (isInitial) setAppIsLoading(false);
        isInitialLoad.current = false;
    }
  }, []);

  useEffect(() => {
    cloudDataService.init({ onSyncStatusChange: setSyncStatus, onSyncError: setSyncError }, settings.googleSheetsUrl);
    loadAndMergeData(true);
  }, [loadAndMergeData, settings.googleSheetsUrl]);

  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_submissions', submissions.slice(-100), { stripMedia: true }); }, [submissions]);
  useEffect(() => { if (!isInitialLoad.current) safeLocalStorageSet('service_app_users', users); }, [users]);

  const handleLoginAttempt = useCallback((username: string, password?: string) => {
    const validatedUser = authService.validateLogin(username, password, users);
    if (validatedUser) {
        const finalUser = { ...validatedUser, notificationPreferences: mergeWithDefaultPrefs(validatedUser.notificationPreferences) };
        localStorage.setItem('service_app_current_user', JSON.stringify(finalUser));
        setCurrentUser(finalUser);
        setView('DASHBOARD');
    } else { setLoginError('Invalid credentials'); }
  }, [users]);

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('service_app_current_user');
    setView('DASHBOARD');
  };

  const handleEditService = (service: Service | null) => { setEditingService(service); setView('FORM'); setIsMobileMenuOpen(false); };
  const handleNavigate = (v: AppView) => { setView(v); setIsMobileMenuOpen(false); }

  const handleCompleteOrder = (service: Service) => {
    const isUpdating = submissions.some(s => s.submissionId === service.submissionId);
    let serviceToSave = { ...service, timestamp: new Date().toISOString() };
    setSubmissions(prev => isUpdating ? prev.map(s => s.submissionId === service.submissionId ? serviceToSave : s) : [...prev, serviceToSave]);
    cloudDataService.saveRecord('Submissions', serviceToSave, settings.googleSheetsUrl);
    triggerHapticFeedback('success');
    setView('DASHBOARD');
  };

  const handleSaveSettings = (newSettings: Settings) => {
    localStorage.setItem('customLogoUrl', newSettings.customLogoUrl || '');
    setSettings(newSettings);
    cloudDataService.saveRecord('Settings', newSettings, settings.googleSheetsUrl);
    triggerHapticFeedback('success');
  };

  const handleUpdateUsers = (allUsers: User[]) => {
      setUsers(allUsers);
      allUsers.forEach(u => cloudDataService.saveRecord('Users', u, settings.googleSheetsUrl));
      triggerHapticFeedback('success');
  };

  const handleUpdatePricing = (cfg: PricingConfig) => {
      const newSettings = { ...settings, pricingConfig: cfg };
      setSettings(newSettings);
      cloudDataService.saveRecord('Settings', newSettings, settings.googleSheetsUrl);
  };

  const handleUpdatePlans = (plans: SubscriptionPlan[]) => {
    setSubscriptionPlans(plans);
    plans.forEach(p => cloudDataService.saveRecord('SubscriptionPlans', p, settings.googleSheetsUrl));
  };

  const handleUpdateSubs = (subs: UserSubscription[]) => {
    setUserSubscriptions(subs);
    subs.forEach(s => cloudDataService.saveRecord('UserSubscriptions', s, settings.googleSheetsUrl));
  };

  const handleUpdateAttendanceStatus = (username: string, status: AttendanceStatus) => {
    const updatedUsers = users.map(u => u.username === username ? { ...u, attendanceStatus: status } : u);
    setUsers(updatedUsers);
    const userToSave = updatedUsers.find(u => u.username === username);
    if(userToSave) cloudDataService.saveRecord('Users', userToSave, settings.googleSheetsUrl);
  };

  if (publicService) return <PublicServiceSummary serviceData={publicService.data} logoUrl={settings.customLogoUrl} />;
  if (appIsLoading) return <LoadingScreen />;
  if (!currentUser) return <LoginPage onLoginAttempt={handleLoginAttempt} error={loginError} />;
  if (printingService) return <PrintPreview service={printingService} onClose={() => setPrintingService(null)} serviceTemplates={serviceTemplates} />;

  const dashboardProps = { submissions: submissions.filter(s => !s.isDeleted), users, currentUser, onCreateOrder: (d: any) => {}, onAssignOrder: (sid: string, u: string) => {}, onStartOrder: (sid: string) => {}, onUpdateOrder: handleEditService, onSelfAssignOrder: (sid: string) => {}, onDeleteOrder: (s: Service) => {}, onScheduleDroppedOrder: (sid: string, d: string, u: string) => {}, onNotifyForOrder: (sid: string) => {}, onUpdateAttendanceStatus: handleUpdateAttendanceStatus, userSubscriptions, serviceTemplates, setIsChatbotOpen, settings, locationHistory, vehicleData, tyreData, onShareOrder: (s: Service) => setSharingService(s) };

  return (
    <div className="min-h-screen bg-slate-100 flex">
      {summarizingService && <SummaryModal service={summarizingService} onClose={() => setSummarizingService(null)} />}
      {sharingService && <ShareOrderModal service={sharingService} onClose={() => setSharingService(null)} />}

      <Sidebar currentUser={currentUser} currentView={view} onNavigate={handleNavigate} onNewService={() => handleEditService(null)} onOpenSettings={() => setView('SETTINGS')} onLogout={handleLogout} logoUrl={settings.customLogoUrl} logoHasError={logoHasError} onLogoError={() => setLogoHasError(true)} isMinimized={isSidebarMinimized} isOpenOnMobile={isMobileMenuOpen} onToggleDesktop={() => setIsSidebarMinimized(!isSidebarMinimized)} onCloseMobile={() => setIsMobileMenuOpen(false)} />

      <div className={`flex-1 transition-all duration-300 ${isSidebarMinimized ? 'md:pl-20' : 'md:pl-64'}`}>
          <header className="sticky top-0 bg-slate-100/80 backdrop-blur-md z-30 border-b border-slate-200 no-print">
              <div className="relative flex items-center justify-between min-h-16 px-4 md:px-6 py-2">
                  <button className="md:hidden text-slate-600" onClick={() => setIsMobileMenuOpen(true)}><IconMenu2 className="w-6 h-6" /></button>
                  <div className="flex items-center gap-2 flex-wrap justify-end">
                      <RealTimeClock />
                      <NotificationBell unreadCount={0} onClick={() => setIsNotificationHistoryOpen(prev => !prev)} />
                      <button onClick={handleManualRefresh} className="p-2 text-slate-500"><IconRefresh className={`w-6 h-6 ${isManualRefreshing ? 'animate-spin' : ''}`} /></button>
                      <SyncStatusIndicator status={syncStatus} errorMessage={syncError} />
                  </div>
              </div>
          </header>
          <main className="p-4 sm:p-6 lg:p-8 w-full">
            {view === 'DASHBOARD' && <DashboardPage {...dashboardProps} />}
            {view === 'LIST' && <SubmissionList submissions={submissions} users={users} onEdit={handleEditService} onPrint={setPrintingService} onSummarize={setSummarizingService} currentUser={currentUser} serviceTemplates={serviceTemplates} />}
            {view === 'SETTINGS' && (
              <SettingsPage 
                currentUser={currentUser} 
                settings={settings} 
                onSaveSettings={handleSaveSettings} 
                subscriptionPlans={subscriptionPlans}
                onUpdatePlans={handleUpdatePlans}
                userSubscriptions={userSubscriptions}
