// FIX: Added cleanSelectionArray helper used by PublicServiceSummary.
const cleanSelectionArray = (arr: any[] | undefined): string[] => {
    if (!arr || !Array.isArray(arr)) return [];

    const cleaned: string[] = [];
    arr.forEach(item => {
        if (typeof item === 'string') {
            try {
                if (item.startsWith('[') && item.endsWith(']')) {
                    const parsed = JSON.parse(item);
                    if (Array.isArray(parsed)) {
                        cleaned.push(...cleanSelectionArray(parsed));
                    } else if (parsed) {
                        cleaned.push(String(parsed));
                    }
                } else if (item) {
                    cleaned.push(item);
                }
            } catch (e) {
                if(item) cleaned.push(item);
            }
        }
    });
    return [...new Set(cleaned)].filter(Boolean);
};

