import React, { useMemo, useEffect, useRef, useState } from 'react';
import { Service, ServiceStatus, User, ServiceTemplate, ProfitLoss, PredefinedCost } from '../../types';
import Card from '../ui/Card';
import Button from '../ui/Button';
import { 
    IconChartBar, IconReceipt, IconFileAnalytics, IconTable, 
    IconCheck, IconSettings, IconPlus, IconTrash, IconChevronDown, 
    IconDeviceFloppy, IconClock 
} from '../ui/Icon';
import Input from '../ui/Input';
import ExportReportModal from './ExportReportModal';
import DataTableReport from './DataTableReport';

// Declare Chart.js from CDN
declare const Chart: any;

interface AnalyticsPageProps {
  submissions: Service[];
  users: Omit<User, 'password'>[];
  serviceTemplates: ServiceTemplate[];
  profitLossData: ProfitLoss[];
  onSaveProfitLoss?: (pl: ProfitLoss) => void;
  predefinedCosts: PredefinedCost[];
  onUpdatePredefinedCosts?: (costs: PredefinedCost[]) => void;
}

// Chart Component Helper
const ChartComponent: React.FC<{ type: string, data: any, options: any, height?: number }> = ({ type, data, options, height = 300 }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const chartInstanceRef = useRef<any>(null);

    useEffect(() => {
        if (!canvasRef.current || typeof Chart === 'undefined') return;
        const ctx = canvasRef.current.getContext('2d');
        if (!ctx) return;

        if (chartInstanceRef.current) {
            chartInstanceRef.current.destroy();
        }

        chartInstanceRef.current = new Chart(ctx, { type, data, options });

        return () => {
            if (chartInstanceRef.current) {
                chartInstanceRef.current.destroy();
            }
        };
    }, [type, data, options]);

    return (
        <div style={{ height: `${height}px`, position: 'relative' }}>
            <canvas ref={canvasRef}></canvas>
        </div>
    );
};

const StatCard: React.FC<{ title: string; value: string; icon: React.ReactNode; iconBg: string; subtext?: string }> = ({ title, value, icon, iconBg, subtext }) => (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex items-center space-x-4">
        <div className={`p-3 rounded-full ${iconBg}`}>
            {icon}
        </div>
        <div>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">{title}</p>
            <p className="text-2xl font-bold text-slate-800">{value}</p>
            {subtext && <p className="text-xs text-slate-400 mt-1">{subtext}</p>}
        </div>
    </div>
);

export const AnalyticsPage: React.FC<AnalyticsPageProps> = ({ submissions, users, serviceTemplates, profitLossData, onSaveProfitLoss, predefinedCosts, onUpdatePredefinedCosts }) => {
    const today = new Date().toISOString().split('T')[0];
    const thirtyDaysAgo = new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0];

    const [filters, setFilters] = useState({
        startDate: thirtyDaysAgo,
        endDate: today,
        user: '',
        serviceType: ''
    });
    const [view, setView] = useState<'dashboard' | 'table' | 'profit-loss'>('dashboard');
    const [isExportModalOpen, setIsExportModalOpen] = useState(false);
    const [isCostSettingsOpen, setIsCostSettingsOpen] = useState(false);

    const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFilters(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const filteredSubmissions = useMemo(() => {
        const completed = submissions.filter(s => s.status === ServiceStatus.Completed && !s.isDeleted);

        const start = filters.startDate ? new Date(filters.startDate) : null;
        if(start) start.setHours(0,0,0,0);

        const end = filters.endDate ? new Date(filters.endDate) : null;
        if(end) end.setHours(23,59,59,999);

        return completed.filter(s => {
            const serviceDate = new Date(s.timestamp);
            const matchesDate = (!start || serviceDate >= start) && (!end || serviceDate <= end);
            const matchesUser = !filters.user || s.assignedTo === filters.user;
            const matchesService = !filters.serviceType || s.serviceSelection.includes(filters.serviceType);
            return matchesDate && matchesUser && matchesService;
        });
    }, [submissions, filters]);

    // Data Aggregation for Charts
    const chartData = useMemo(() => {
        const dailyMap = new Map<string, { revenue: number, jobs: number }>();
        const serviceMap = new Map<string, number>();
        const agentMap = new Map<string, number>();

        // Fill in all dates in range to avoid gaps
        if (filters.startDate && filters.endDate) {
            let curr = new Date(filters.startDate);
            const end = new Date(filters.endDate);
            while (curr <= end) {
                dailyMap.set(curr.toISOString().split('T')[0], { revenue: 0, jobs: 0 });
                curr.setDate(curr.getDate() + 1);
            }
        }

        filteredSubmissions.forEach(s => {
            const date = s.timestamp.split('T')[0];
            const currentDaily = dailyMap.get(date) || { revenue: 0, jobs: 0 };
            dailyMap.set(date, { 
                revenue: currentDaily.revenue + s.grandTotal, 
                jobs: currentDaily.jobs + 1 
            });

            s.serviceSelection.forEach(svc => {
                serviceMap.set(svc, (serviceMap.get(svc) || 0) + 1);
            });

            if (s.assignedTo) {
                agentMap.set(s.assignedTo, (agentMap.get(s.assignedTo) || 0) + s.grandTotal);
            }
        });

        const dailySorted = Array.from(dailyMap.entries()).sort();

        return {
            timeline: {
                labels: dailySorted.map(d => new Date(d[0]).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })),
                revenue: dailySorted.map(d => d[1].revenue),
                jobs: dailySorted.map(d => d[1].jobs)
            },
            services: {
                labels: Array.from(serviceMap.keys()),
                data: Array.from(serviceMap.values())
            },
            agents: {
                labels: Array.from(agentMap.keys()),
                data: Array.from(agentMap.values())
            }
        };
    }, [filteredSubmissions, filters.startDate, filters.endDate]);

    const kpiData = useMemo(() => {
        let totalRevenue = 0;
        let totalCost = 0;
        filteredSubmissions.forEach(s => {
            totalRevenue += s.grandTotal;
            const pl = (profitLossData || []).find(p => p.serviceId === s.submissionId);
            if (pl) totalCost += (pl.materialCost || 0) + (pl.laborCost || 0) + (pl.otherExpenses || 0);
        });
        const netProfit = totalRevenue - totalCost;
        const profitMargin = totalRevenue > 0 ? (netProfit / totalRevenue) * 100 : 0;
        return { totalRevenue, totalCost, netProfit, profitMargin, count: filteredSubmissions.length };
    }, [filteredSubmissions, profitLossData]);

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4">
                 <h1 className="text-3xl font-bold text-slate-800 tracking-tight">Business Intelligence</h1>
                 <div className="flex items-center gap-2">
                    <div className="flex bg-slate-200 p-1 rounded-lg">
                        <button onClick={() => setView('dashboard')} className={`px-4 py-2 text-xs font-bold rounded-md transition-all flex items-center gap-2 ${view === 'dashboard' ? 'bg-white text-brand-blue shadow-sm' : 'text-slate-600 hover:text-slate-800'}`}>
                            <IconChartBar className="w-4 h-4" /> DASHBOARD
                        </button>
                        <button onClick={() => setView('table')} className={`-ml-px px-4 py-2 text-xs font-bold rounded-md transition-all flex items-center gap-2 ${view === 'table' ? 'bg-white text-brand-blue shadow-sm' : 'text-slate-600 hover:text-slate-800'}`}>
                            <IconTable className="w-4 h-4" /> LEDGER
                        </button>
                    </div>
                </div>
            </div>

            <Card title="Query Filters">
                 <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                    <Input label="From" name="startDate" type="date" value={filters.startDate} onChange={handleFilterChange} />
                    <Input label="To" name="endDate" type="date" value={filters.endDate} onChange={handleFilterChange} />
                    <div>
                        <label htmlFor="user" className="block text-sm font-medium text-slate-700 mb-1">Agent</label>
                        <select id="user" name="user" value={filters.user} onChange={handleFilterChange} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus:ring-2 focus:ring-brand-accent sm:text-sm">
                            <option value="">All Agents</option>
                            {users.map(u => <option key={u.username} value={u.username}>{u.username}</option>)}
                        </select>
                    </div>
                     <div>
                        <label htmlFor="serviceType" className="block text-sm font-medium text-slate-700 mb-1">Service Type</label>
                        <select id="serviceType" name="serviceType" value={filters.serviceType} onChange={handleFilterChange} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus:ring-2 focus:ring-brand-accent sm:text-sm">
                            <option value="">All Services</option>
                            {serviceTemplates.map(t => <option key={t.id} value={t.name}>{t.name}</option>)}
                        </select>
                    </div>
                </div>
            </Card>

            {view === 'dashboard' && (
                <>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                        <StatCard title="Revenue" value={`₹${kpiData.totalRevenue.toLocaleString('en-IN')}`} icon={<IconReceipt className="w-6 h-6 text-green-600"/>} iconBg="bg-green-100" />
                        <StatCard title="Operating Cost" value={`₹${kpiData.totalCost.toLocaleString('en-IN')}`} icon={<IconClock className="w-6 h-6 text-red-600"/>} iconBg="bg-red-100" />
                        <StatCard title="Net Profit" value={`₹${kpiData.netProfit.toLocaleString('en-IN')}`} icon={<IconChartBar className="w-6 h-6 text-blue-600"/>} iconBg="bg-blue-100" subtext={`Margin: ${kpiData.profitMargin.toFixed(1)}%`} />
                        <StatCard title="Jobs Closed" value={kpiData.count.toString()} icon={<IconCheck className="w-6 h-6 text-purple-600"/>} iconBg="bg-purple-100" />
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        <Card title="Revenue & Volume Trend">
                            <ChartComponent 
                                type="line" 
                                data={{
                                    labels: chartData.timeline.labels,
                                    datasets: [
                                        {
                                            label: 'Revenue (₹)',
                                            data: chartData.timeline.revenue,
                                            borderColor: '#0D2A4F',
                                            backgroundColor: 'rgba(13, 42, 79, 0.1)',
                                            fill: true,
                                            tension: 0.4,
                                            yAxisID: 'y'
                                        },
                                        {
                                            label: 'Jobs',
