import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { Service, ServiceStatus, ProfitLoss, PredefinedCost } from '../../types';
import Card from '../ui/Card';
import Input from '../ui/Input';
import Button from '../ui/Button';
import { IconDeviceFloppy, IconCheck, IconChevronDown, IconSettings, IconPlus, IconTrash } from '../ui/Icon';

interface ProfitLossPageProps {
  submissions: Service[];
  profitLossData: ProfitLoss[];
  onSave: (pl: ProfitLoss) => void;
  predefinedCosts: PredefinedCost[];
  onUpdatePredefinedCosts: (costs: PredefinedCost[]) => void;
}

// Internal Settings Modal for Defining Presets
const CostPresetsModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    costs: PredefinedCost[];
    onUpdate: (costs: PredefinedCost[]) => void;
}> = ({ isOpen, onClose, costs, onUpdate }) => {
    const [localCosts, setLocalCosts] = useState<PredefinedCost[]>(costs);

    useEffect(() => {
        if (isOpen) setLocalCosts(costs);
    }, [isOpen, costs]);

    if (!isOpen) return null;

    const handleAdd = () => {
        setLocalCosts(prev => [...prev, { id: `pc_${Date.now()}`, name: '', value: 0 }]);
    };

    const handleUpdate = (id: string, field: keyof PredefinedCost, val: string | number) => {
        setLocalCosts(prev => prev.map(c => c.id === id ? { ...c, [field]: val } : c));
    };

    const handleDelete = (id: string) => {
        setLocalCosts(prev => prev.filter(c => c.id !== id));
    };

    const handleSave = () => {
        onUpdate(localCosts.filter(c => c.name.trim() !== ''));
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-[70] p-4 modal-backdrop" onClick={onClose}>
            <div onClick={(e) => e.stopPropagation()} className="w-full max-w-lg modal-content">
                <Card title="Manage Quick-Add Costs">
                    <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-2">
                        <p className="text-sm text-slate-600">Create presets for common operating costs like overhead, rent shares, or base labor.</p>
                        {localCosts.map((cost) => (
                            <div key={cost.id} className="flex gap-2 items-end p-2 bg-slate-50 rounded border border-slate-200">
                                <div className="flex-grow">
                                    <Input 
                                        label="Cost Label" 
                                        id={`pc-name-${cost.id}`}
                                        value={cost.name} 
                                        onChange={e => handleUpdate(cost.id, 'name', e.target.value)} 
                                        placeholder="e.g., Overhead"
                                    />
                                </div>
                                <div className="w-24">
                                    <Input 
                                        label="Value (₹)" 
                                        id={`pc-val-${cost.id}`}
                                        type="number" 
                                        value={cost.value} 
                                        onChange={e => handleUpdate(cost.id, 'value', parseFloat(e.target.value) || 0)} 
                                    />
                                </div>
                                <Button variant="danger" size="sm" className="mb-0.5 p-2 h-10 w-10" onClick={() => handleDelete(cost.id)}>
                                    <IconTrash className="w-5 h-5" />
                                </Button>
                            </div>
                        ))}
                        <Button variant="ghost" onClick={handleAdd} className="w-full py-3 border-dashed border-2">
                            <IconPlus className="w-4 h-4 mr-2" /> Add New Cost Preset
                        </Button>
                    </div>
                    <div className="mt-6 flex justify-end gap-2 pt-4 border-t border-slate-200">
                        <Button variant="ghost" onClick={onClose}>Cancel</Button>
                        <Button onClick={handleSave}>Save Settings</Button>
                    </div>
                </Card>
            </div>
        </div>
    );
};

const ProfitLossCalculator: React.FC<{ 
    service: Service, 
    profitLoss: ProfitLoss | undefined, 
    onSave: (pl: ProfitLoss) => void,
    predefinedCosts: PredefinedCost[]
}> = ({ service, profitLoss, onSave, predefinedCosts }) => {

    // Determine defaults: either existing record, or inherent service data
    const initialPL = profitLoss || {
        serviceId: service.submissionId,
        materialCost: service.tyreMaterialCost || 0,
        laborCost: service.tyreLaborCost || 0,
        otherExpenses: 0,
        calculatedProfit: 0,
        notes: ''
    };

    const calculateProfit = useCallback((material: number, labor: number, other: number) => {
        return service.grandTotal - material - labor - other;
    }, [service.grandTotal]);

    // Ensure profit is correctly set initially if derived from Service data
    if (!profitLoss) {
        initialPL.calculatedProfit = calculateProfit(initialPL.materialCost, initialPL.laborCost, initialPL.otherExpenses);
    }

    const [pl, setPl] = useState<ProfitLoss>(initialPL);
    const [isSaved, setIsSaved] = useState(!!profitLoss);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        const numValue = name !== 'notes' ? parseFloat(value) || 0 : 0;

        setPl(prev => {
            const updated = { ...prev, [name]: name === 'notes' ? value : numValue };
            if (name !== 'notes') {
                updated.calculatedProfit = calculateProfit(
                    name === 'materialCost' ? numValue : updated.materialCost,
                    name === 'laborCost' ? numValue : updated.laborCost,
                    name === 'otherExpenses' ? numValue : updated.otherExpenses
                );
            }
            return updated;
        });
        setIsSaved(false);
    };

    const applyPreset = (cost: number, name: string) => {
        setPl(prev => {
            const updatedOther = prev.otherExpenses + cost;
            const updatedNotes = prev.notes ? `${prev.notes}, ${name}` : name;
            return {
                ...prev,
                otherExpenses: updatedOther,
                notes: updatedNotes,
                calculatedProfit: calculateProfit(prev.materialCost, prev.laborCost, updatedOther)
            };
        });
        setIsSaved(false);
    };

    const handleSave = () => {
        onSave(pl);
        setIsSaved(true);
    };

    const isNegative = pl.calculatedProfit < 0;

    return (
        <div className="p-4 bg-slate-50 rounded-lg border-l-4 border-slate-300 space-y-4 shadow-sm">
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 items-end">
                <Input label="Material Cost (₹)" name="materialCost" type="number" value={pl.materialCost} onChange={handleChange} className="bg-white" />
                <Input label="Labor Cost (₹)" name="laborCost" type="number" value={pl.laborCost} onChange={handleChange} className="bg-white" />
                <Input label="Other Expenses (₹)" name="otherExpenses" type="number" value={pl.otherExpenses} onChange={handleChange} className="bg-white" />
                <div className="flex flex-col h-full justify-end pb-1 px-3 bg-white rounded border border-slate-200">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Estimated Profit</p>
                    <p className={`text-2xl font-bold ${isNegative ? 'text-red-600' : 'text-green-600'}`}>
                        ₹{pl.calculatedProfit.toFixed(2)}
                    </p>
                </div>
            </div>

            {predefinedCosts.length > 0 && (
                <div className="flex flex-wrap gap-2 items-center">
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Quick Add:</span>
                    {predefinedCosts.map(cost => (
                        <button 
                            key={cost.id} 
                            onClick={() => applyPreset(cost.value, cost.name)}
                            className="px-2 py-1 text-xs bg-white border border-slate-200 rounded-full hover:border-brand-accent hover:text-brand-blue transition-all shadow-sm flex items-center gap-1 active:scale-95"
                        >
                            <span className="font-semibold">{cost.name}</span>
                            <span className="text-slate-400">₹{cost.value}</span>
                        </button>
                    ))}
                </div>
            )}

            <div className="flex items-center gap-4">
                <div className="flex-grow">
                     <textarea
                        name="notes"
                        value={pl.notes || ''}
                        onChange={handleChange}
                        rows={1}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-brand-accent sm:text-sm bg-white"
                        placeholder="Cost details or specific parts used..."
                    />
                </div>
                <Button 
                    onClick={handleSave} 
                    size="sm" 
                    variant={isSaved ? "ghost" : "primary"}
                    className="flex-shrink-0 min-w-[100px]"
                >
                    {isSaved ? <><IconCheck className="w-4 h-4 mr-2 text-green-600" /> Saved</> : <><IconDeviceFloppy className="w-4 h-4 mr-2" /> Save</>}
                </Button>
            </div>
        </div>
    );
};

const ProfitLossPage: React.FC<ProfitLossPageProps> = ({ submissions, profitLossData, onSave, predefinedCosts, onUpdatePredefinedCosts }) => {
    const [openMonths, setOpenMonths] = useState<Record<string, boolean>>({});
    const [isSettingsOpen, setIsSettingsOpen] = useState(false);

    const completedServicesByDate = useMemo(() => {
        const grouped: Record<string, Record<string, Service[]>> = {};

        submissions
            .filter(s => s.status === ServiceStatus.Completed)
            .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
            .forEach(service => {
                const date = new Date(service.timestamp);
                const monthYear = `${date.toLocaleString('default', { month: 'long' })} ${date.getFullYear()}`;
                const day = date.toISOString().split('T')[0];

                if (!grouped[monthYear]) {
                    grouped[monthYear] = {};
                }
                if (!grouped[monthYear][day]) {
                    grouped[monthYear][day] = [];
                }
                grouped[monthYear][day].push(service);
            });

        // Set most recent month to be open by default
        const firstMonth = Object.keys(grouped)[0];
        if (firstMonth && Object.keys(openMonths).length === 0) {
            setOpenMonths({ [firstMonth]: true });
        }

        return grouped;
    }, [submissions]);

    const totalNetProfit = useMemo(() => {
        return submissions
            .filter(s => s.status === ServiceStatus.Completed)
            .reduce((sum, s) => {
                const pl = profitLossData.find(p => p.serviceId === s.submissionId);
                if (pl) return sum + pl.calculatedProfit;
                return sum + s.grandTotal - ((s.tyreLaborCost || 0) + (s.tyreMaterialCost || 0));
            }, 0);
    }, [submissions, profitLossData]);

    const toggleMonth = (monthYear: string) => {
        setOpenMonths(prev => ({ ...prev, [monthYear]: !prev[monthYear] }));
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h2 className="text-xl font-bold text-slate-800">Job-Level Profit & Loss</h2>
