                </div>
                <div className="flex items-center gap-3">
                    <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm flex items-center gap-3">
                        <div className="p-2 bg-blue-100 rounded-full text-brand-blue">
                            <IconCheck className="w-5 h-5" />
                        </div>
                        <div>
                            <p className="text-[10px] font-bold text-slate-400 uppercase">Filtered Net Profit</p>
                            <p className={`text-xl font-bold ${totalNetProfit >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                                ₹{totalNetProfit.toLocaleString('en-IN')}
                            </p>
                        </div>
                    </div>
                    <Button variant="secondary" onClick={() => setIsSettingsOpen(true)}>
                        <IconSettings className="w-5 h-5 mr-2" />
                        Quick Add Settings
                    </Button>
                </div>
            </div>

            <div className="space-y-4">
                {Object.entries(completedServicesByDate).map(([monthYear, days]) => (
                    <Card key={monthYear} className="overflow-visible !p-4">
                        <button onClick={() => toggleMonth(monthYear)} className="w-full flex justify-between items-center text-left group">
                            <h2 className="text-xl font-bold text-slate-700 group-hover:text-brand-blue transition-colors">{monthYear}</h2>
                            <IconChevronDown className={`w-5 h-5 text-slate-500 transition-transform duration-300 ${openMonths[monthYear] ? 'rotate-180' : ''}`} />
                        </button>

                        {openMonths[monthYear] && (
                            <div className="mt-6 space-y-8">
                                {Object.entries(days).map(([day, services]) => (
                                    <div key={day} className="space-y-4">
                                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest pb-1 border-b border-slate-100">
                                            {new Date(day).toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'short' })}
                                        </h3>
                                        <div className="space-y-6">
                                            {services.map(service => (
                                                <div key={service.submissionId}>
