interface DataTableReportProps {
  submissions: Service[];
  profitLossData?: ProfitLoss[];
}

const DataTableReport: React.FC<DataTableReportProps> = ({ submissions, profitLossData = [] }) => {
  if (submissions.length === 0) {
    return (
      <Card>
        <p className="text-center text-slate-500 py-8">No data available for the selected filters.</p>
      </Card>
    );
  }

  const flattenedData = submissions.map(s => {
    const addonsSummary = [
      ...(s.dynamicAddons || []).map(a => `${a.name} (x${a.quantity})`),
      ...(s.categorizedAddons || []).map(a => `${a.productName} (x${a.quantity})`),
    ].join('; ');

    const serviceList = s.serviceSelection.map(sel => {
        if (sel === 'Car Washing') return `Car Washing (${s.carWashDetails?.washType || 'N/A'})`;
        if (sel === 'Car Care') return `Car Care (${s.carCareDetails?.careType || 'N/A'})`;
        return sel;
    }).join(', ');

    // Profit Calculation Logic
    const pl = (profitLossData || []).find(p => p.serviceId === s.submissionId);

    // Fallback to service defaults if no PL record exists
    const materialCost = pl ? pl.materialCost : (s.tyreMaterialCost || 0);
    const laborCost = pl ? pl.laborCost : (s.tyreLaborCost || 0);
    const otherCost = pl ? pl.otherExpenses : 0;

    const totalCost = materialCost + laborCost + otherCost;
    const netProfit = s.grandTotal - totalCost;

    return {
      'Order ID': s.appointmentId?.split('-').pop() || '',
      'Date': new Date(s.timestamp).toLocaleString('en-IN'),
      'Customer Name': `${s.customerFirstName} ${s.customerLastName}`,
      'Mobile': s.mobileNumber,
      'Car Brand & Model': s.carBrandModel,
      'Car Number': s.carNumber,
      'Services': serviceList,
      'Assigned Agent': s.assignedTo || 'N/A',
      'Status': s.status,
      'Revenue': `₹${s.grandTotal.toFixed(2)}`,
      'Material Cost': `₹${materialCost.toFixed(2)}`,
      'Labor Cost': `₹${laborCost.toFixed(2)}`,
      'Other Cost': `₹${otherCost.toFixed(2)}`,
      'Total Operating Cost': `₹${totalCost.toFixed(2)}`,
      'Net Profit': `₹${netProfit.toFixed(2)}`,
      'Profit %': s.grandTotal > 0 ? `${((netProfit / s.grandTotal) * 100).toFixed(1)}%` : '0%',
      'Addons': addonsSummary || '-',
    };
  });

  const headers = Object.keys(flattenedData[0]);

  return (
    <Card className="!p-0 border border-slate-200">
      <div className="overflow-x-auto relative rounded-lg" style={{ maxHeight: '70vh' }}>
        <table className="min-w-full text-xs text-left text-slate-500">
          <thead className="text-[10px] text-slate-700 uppercase bg-slate-100 sticky top-0 z-10 border-b border-slate-200">
            <tr>
              {headers.map(header => (
                <th key={header} scope="col" className="px-4 py-3 whitespace-nowrap font-bold">
                  {header}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-slate-100">
            {flattenedData.map((row, rowIndex) => (
              <tr key={rowIndex} className="hover:bg-slate-50 transition-colors">
                {headers.map(header => {
                  const val = row[header as keyof typeof row];
                  let className = "px-4 py-3 whitespace-nowrap";
                  if (header === 'Net Profit') {
                      const num = parseFloat(String(val).replace('₹', ''));
                      className += num >= 0 ? " text-green-600 font-bold" : " text-red-600 font-bold";
                  }
                  if (header === 'Revenue') {
                      className += " font-bold text-slate-800";
                  }
                  return (
                    <td key={header} className={className}>
                        {val}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Card>
  );
};

