const mergeWithDefaultPrefs = (prefs?: Partial<NotificationPreferences>): NotificationPreferences => {
    return {
        ...defaultNotificationPrefs,
        ...(prefs || {}),
        enabled: { ...defaultNotificationPrefs.enabled, ...(prefs?.enabled || {}) }
    };
};

const mergeSubmissions = (cloudSubs: Service[], localSubs: Service[]): Service[] => {
    const submissionMap = new Map<string, Service>();
    for (const sub of cloudSubs) submissionMap.set(sub.submissionId, sub);
    for (const sub of localSubs) {
        const existing = submissionMap.get(sub.submissionId);
        if (!existing || new Date(sub.timestamp) > new Date(existing.timestamp)) submissionMap.set(sub.submissionId, sub);
    }
    return Array.from(submissionMap.values());
};

const cleanSubmissionsArray = (submissions: Service[]): Service[] => {
    return submissions.map(sub => {
        const cleanedSub = {...sub};
        let finalStatus = cleanedSub.status;
        const validStatuses = Object.values(ServiceStatus);
        if ((finalStatus as any) === 'Submitted') finalStatus = ServiceStatus.Completed;
        else if ((finalStatus as any) === 'Order Created') finalStatus = ServiceStatus.Queued;
        if (!finalStatus || !validStatuses.includes(finalStatus as ServiceStatus)) finalStatus = ServiceStatus.Queued;
        if (cleanedSub.carwashTotalAmount && !cleanedSub.carWashDetails) {
            cleanedSub.vehicleCategoryTag = getCategoryForVehicle(cleanedSub.carBrandModel);
            cleanedSub.carWashDetails = { washType: 'Basic Wash', price: robustParseFloat(cleanedSub.carwashTotalAmount), mrp: robustParseFloat(cleanedSub.carwashTotalAmount) * 1.5 };
        }
        if (cleanedSub.carCareTotalAmount && !cleanedSub.carCareDetails) {
            cleanedSub.vehicleCategoryTag = getCategoryForVehicle(cleanedSub.carBrandModel);
            cleanedSub.carCareDetails = { careType: 'Legacy Package', price: robustParseFloat(cleanedSub.carCareTotalAmount), mrp: robustParseFloat(cleanedSub.carCareTotalAmount) * 1.5 };
        }
        return {
            ...cleanedSub,
            status: finalStatus,
            dynamicAddons: Array.isArray(cleanedSub.dynamicAddons) ? cleanedSub.dynamicAddons : [],
            categorizedAddons: Array.isArray(cleanedSub.categorizedAddons) ? cleanedSub.categorizedAddons : [],
            customFieldData: cleanedSub.customFieldData || [],
            dependsOn: cleanedSub.dependsOn || [],
            grandTotal: robustParseFloat(cleanedSub.grandTotal),
            tyreReplacementTotalAmount: robustParseFloat(cleanedSub.tyreReplacementTotalAmount),
            tyreReplacementPrice: robustParseFloat(cleanedSub.tyreReplacementPrice),
            tyreReplacementQuantity: robustParseInt(cleanedSub.tyreReplacementQuantity),
            batteryReplacementTotalAmount: robustParseFloat(cleanedSub.batteryReplacementTotalAmount),
            batteryReplacementQuantity: robustParseInt(cleanedSub.batteryReplacementQuantity),
            addonsTotal: robustParseFloat(cleanedSub.addonsTotal),
            categorizedAddonsTotal: robustParseFloat(cleanedSub.categorizedAddonsTotal),
            customServicesTotal: robustParseFloat(cleanedSub.customServicesTotal),
            batteryDetails: (cleanedSub.batteryDetails || []).map(bd => ({ ...bd, exchangeValue: robustParseFloat(bd.exchangeValue), newBatteryAmount: robustParseFloat(bd.newBatteryAmount) })),
            customServices: (cleanedSub.customServices || []).map(cs => ({ ...cs, amount: robustParseFloat(cs.amount) })),
            internalNotes: cleanedSub.internalNotes || '',
            isFollowUp: cleanedSub.isFollowUp || false,
            appointmentId: cleanedSub.appointmentId || cleanedSub.submissionId
        };
    });
};

export const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try {
        const storedUserJson = localStorage.getItem('service_app_current_user');
        if (!storedUserJson) return null;
        const user = JSON.parse(storedUserJson);
        user.notificationPreferences = mergeWithDefaultPrefs(user.notificationPreferences);
        return user;
    } catch (error) { return null; }
  });
  const [loginError, setLoginError] = useState('');
  const [appIsLoading, setAppIsLoading] = useState(true);
  const [view, setView] = useState<AppView>('DASHBOARD');
  const [submissions, setSubmissions] = useState<Service[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [settings, setSettings] = useState<Settings>({ googleSheetsUrl: PERMANENT_SHEET_URL, googleDriveUploadUrl: PERMANENT_DRIVE_URL, customLogoUrl: '', retentionKpiTargets: defaultKpiTargets });
  const [subscriptionPlans, setSubscriptionPlans] = useState<SubscriptionPlan[]>([]);
  const [userSubscriptions, setUserSubscriptions] = useState<UserSubscription[]>([]);
  const [serviceTemplates, setServiceTemplates] = useState<ServiceTemplate[]>([]);
  const [serviceRequests, setServiceRequests] = useState<ServiceRequest[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [locationHistory, setLocationHistory] = useState<LocationHistory[]>([]);
  const [profitLossData, setProfitLossData] = useState<ProfitLoss[]>([]);
  const [predefinedCosts, setPredefinedCosts] = useState<PredefinedCost[]>([]);
  const [vehicleData, setVehicleData] = useState<Record<string, string[]>>(CAR_BRANDS);
  const [tyreData, setTyreData] = useState<TyreData>({ brands: TIRE_BRANDS, models: [], sizes: [] });

  const [editingService, setEditingService] = useState<Service | null>(null);
  const [editingTemplate, setEditingTemplate] = useState<ServiceTemplate | null>(null);
  const [printingService, setPrintingService] = useState<Service | null>(null);
  const [summarizingService, setSummarizingService] = useState<Service | null>(null);
  const [deletingService, setDeletingService] = useState<Service | null>(null);
  const [sharingService, setSharingService] = useState<Service | null>(null);
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('OFFLINE');
  const [syncError, setSyncError] = useState<string | null>(null);
  const [logoHasError, setLogoHasError] = useState(false);
  const [isManualRefreshing, setIsManualRefreshing] = useState(false);
  const isInitialLoad = useRef(true);
  const [isSidebarMinimized, setIsSidebarMinimized] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isNotificationHistoryOpen, setIsNotificationHistoryOpen] = useState(false);
  const locationWatcherIdRef = useRef<number | null>(null);
  const [isChatbotOpen, setIsChatbotOpen] = useState(false);
  const [publicService, setPublicService] = useState<{ data: any } | null>(null);

  const loadAndMergeData = useCallback(async (isInitial: boolean = false) => {
    if (isInitial) setAppIsLoading(true);
    setSyncError(null);
    setSyncStatus('SYNCING');
    const persistedSettings = { googleSheetsUrl: PERMANENT_SHEET_URL, googleDriveUploadUrl: PERMANENT_DRIVE_URL, customLogoUrl: localStorage.getItem('customLogoUrl') || '', retentionKpiTargets: JSON.parse(localStorage.getItem('retentionKpiTargets') || 'null') || defaultKpiTargets };
    try {
        const cloudData = await cloudDataService.loadAppData(persistedSettings);
        let usersToSet = cloudData.users;
        if (usersToSet.length === 0 && cloudData.submissions.length === 0) {
            const defaultAdmin: User = { username: 'admin', password: 'admin@123', role: 'admin', notificationPreferences: defaultNotificationPrefs, permissions: authService.getDefaultPermissionsForRole('admin'), attendanceStatus: 'CHECKED_OUT', attendanceHistory: [] };
            usersToSet = [defaultAdmin];
            cloudDataService.saveRecord('Users', defaultAdmin, PERMANENT_SHEET_URL);
        }
        usersToSet = usersToSet.map(user => {
            const finalUser = { ...user };
            let needsSave = false;
            if (!finalUser.notificationPreferences) { finalUser.notificationPreferences = mergeWithDefaultPrefs(); needsSave = true; }
            if (!finalUser.attendanceStatus) { finalUser.attendanceStatus = 'CHECKED_OUT'; needsSave = true; }
            if (!finalUser.permissions || finalUser.permissions.length === 0) { finalUser.permissions = authService.getDefaultPermissionsForRole(finalUser.role); needsSave = true; }

            // CRITICAL: Ensure Admin/Manager roles have the Pricing permission in the database
            if ((finalUser.role === 'admin' || finalUser.role === 'manager') && !finalUser.permissions.includes(Permission.CAN_MANAGE_PRICING)) {
                finalUser.permissions = [...new Set([...finalUser.permissions, Permission.CAN_MANAGE_PRICING, Permission.CAN_MANAGE_PLANS, Permission.CAN_MANAGE_SUBSCRIPTIONS])];
                needsSave = true;
            }

            if (needsSave) cloudDataService.saveRecord('Users', finalUser, PERMANENT_SHEET_URL);
            return finalUser;
        });
        const localSubmissionsJson = localStorage.getItem('service_app_submissions');
        const rawLocalSubmissions: Service[] = localSubmissionsJson ? JSON.parse(localSubmissionsJson) : [];
        const cleanedLocalSubmissions = cleanSubmissionsArray(rawLocalSubmissions);
        const mergedSubmissions = mergeSubmissions(cleanSubmissionsArray(cloudData.submissions), cleanedLocalSubmissions);
        setSubmissions(mergedSubmissions);
        setUsers(usersToSet);
        setSettings({ ...cloudData.settings, googleSheetsUrl: PERMANENT_SHEET_URL, googleDriveUploadUrl: PERMANENT_DRIVE_URL });
        setSubscriptionPlans(cloudData.subscriptionPlans || []);
        setUserSubscriptions(cloudData.userSubscriptions || []);
        setServiceTemplates(cloudData.serviceTemplates.length > 0 ? cloudData.serviceTemplates : DEFAULT_SERVICE_TEMPLATES);
        setServiceRequests(cloudData.serviceRequests || []);
        setNotifications(cloudData.notifications || []);
        setLocationHistory(cloudData.locationHistory || []);
        setProfitLossData(cloudData.profitLoss || []);
        setPredefinedCosts(cloudData.predefinedCosts || []);
        setVehicleData(cloudData.vehicleData || CAR_BRANDS);
        setTyreData(cloudData.tyreData || { brands: TIRE_BRANDS, models: [], sizes: [] });
        setSyncStatus('SYNCED');
    } catch (e) {
        setSyncStatus('ERROR');
        setSyncError(e instanceof Error ? e.message : "Load failed");
    } finally {
        if (isInitial) setAppIsLoading(false);
        isInitialLoad.current = false;
    }
  }, []);

  const handleManualRefresh = async () => {
    if (isManualRefreshing) return;
    setIsManualRefreshing(true);
    await loadAndMergeData(false);
    setIsManualRefreshing(false);
  };

  useEffect(() => {
