            {view === 'ANALYTICS' && <AnalyticsPage submissions={submissions} users={users} serviceTemplates={serviceTemplates} profitLossData={profitLossData} onSaveProfitLoss={handleUpdateProfitLoss} predefinedCosts={predefinedCosts} onUpdatePredefinedCosts={handleUpdatePredefinedCosts} />}
