import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { Service, ServiceStatus, ProfitLoss, PredefinedCost, DynamicCostItem, PLTab } from '../../types';
import Card from '../ui/Card';
import Input from '../ui/Input';
import Button from '../ui/Button';
import { 
    IconDeviceFloppy, IconCheck, IconChevronDown, IconSettings, 
    IconPlus, IconTrash, IconChartBar, IconReceipt, IconEngine, 
    IconWorld, IconClock, IconSparkles, IconFilter
} from '../ui/Icon';

interface ProfitLossPageProps {
  submissions: Service[];
  profitLossData: ProfitLoss[];
  onSave: (pl: ProfitLoss) => void;
  predefinedCosts: PredefinedCost[];
  onUpdatePredefinedCosts: (costs: PredefinedCost[]) => void;
}

const ProfitLossCalculator: React.FC<{ 
    service: Service, 
    profitLoss: ProfitLoss | undefined, 
    onSave: (pl: ProfitLoss) => void,
    predefinedCosts: PredefinedCost[],
    specificServiceRevenue?: number,
    isSelected?: boolean,
    onToggleSelect?: () => void
}> = ({ service, profitLoss, onSave, predefinedCosts, specificServiceRevenue, isSelected, onToggleSelect }) => {

    const initialPL = profitLoss || {
        serviceId: service.submissionId,
        materialCost: service.tyreMaterialCost || 0,
        laborCost: service.tyreLaborCost || 0,
        otherExpenses: 0,
        dynamicCosts: [],
        calculatedProfit: 0,
        notes: ''
    };

    const revenue = specificServiceRevenue !== undefined ? specificServiceRevenue : service.grandTotal;

    const calculateProfit = useCallback((material: number, labor: number, other: number, dynamic: DynamicCostItem[]) => {
        const dynamicSum = (dynamic || []).reduce((s, item) => s + item.value, 0);
        return revenue - material - labor - other - dynamicSum;
    }, [revenue]);

    const [pl, setPl] = useState<ProfitLoss>(initialPL);
    const [isSaved, setIsSaved] = useState(!!profitLoss);

    // Sync if external props change (important for bulk updates)
    useEffect(() => {
        if (profitLoss) {
            setPl(profitLoss);
            setIsSaved(true);
        }
    }, [profitLoss]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        const numValue = name !== 'notes' ? parseFloat(value) || 0 : 0;

        setPl(prev => {
            const updated = { ...prev, [name]: name === 'notes' ? value : numValue };
            if (name !== 'notes') {
                updated.calculatedProfit = calculateProfit(
                    name === 'materialCost' ? numValue : updated.materialCost,
                    name === 'laborCost' ? numValue : updated.laborCost,
                    name === 'otherExpenses' ? numValue : updated.otherExpenses,
                    updated.dynamicCosts || []
                );
            }
            return updated;
        });
        setIsSaved(false);
    };

    const updateDynamicCost = (id: string, field: 'label' | 'value', value: string | number) => {
        setPl(prev => {
            const updatedCosts = (prev.dynamicCosts || []).map(c => c.id === id ? { ...c, [field]: value } : c);
            return {
                ...prev,
                dynamicCosts: updatedCosts,
                calculatedProfit: calculateProfit(prev.materialCost, prev.laborCost, prev.otherExpenses, updatedCosts)
            };
        });
        setIsSaved(false);
    };

    const removeDynamicCost = (id: string) => {
        setPl(prev => {
            const updatedCosts = (prev.dynamicCosts || []).filter(c => c.id !== id);
            return {
                ...prev,
                dynamicCosts: updatedCosts,
                calculatedProfit: calculateProfit(prev.materialCost, prev.laborCost, prev.otherExpenses, updatedCosts)
            };
        });
        setIsSaved(false);
    };

    const applyPreset = (cost: number, name: string) => {
        setPl(prev => {
            const newDynamic = [...(prev.dynamicCosts || []), { id: `dc_${Date.now()}_${Math.random()}`, label: name, value: cost }];
            return {
                ...prev,
                dynamicCosts: newDynamic,
                calculatedProfit: calculateProfit(prev.materialCost, prev.laborCost, prev.otherExpenses, newDynamic)
            };
        });
        setIsSaved(false);
    };

    return (
        <div className={`p-4 rounded-lg border-l-4 transition-all ${isSelected ? 'bg-brand-accent/5 border-brand-accent ring-1 ring-brand-accent/20' : 'bg-slate-50 border-slate-300'} space-y-4 shadow-sm`}>
            <div className="flex justify-between items-center border-b pb-2 mb-2">
                <div className="flex items-center gap-3">
                    <input 
                        type="checkbox" 
                        checked={isSelected} 
                        onChange={onToggleSelect} 
                        className="h-5 w-5 rounded border-slate-300 text-brand-accent focus:ring-brand-accent"
                    />
                    <span className="text-xs font-bold text-slate-500 uppercase">Individual Breakdown</span>
                </div>
                {isSaved ? <span className="text-[10px] font-bold text-green-600 bg-green-100 px-2 py-0.5 rounded">SYNCED</span> : <span className="text-[10px] font-bold text-amber-600 bg-amber-100 px-2 py-0.5 rounded">UNSAVED</span>}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 items-end">
                <Input label="Material Cost (₹)" name="materialCost" type="number" value={pl.materialCost} onChange={handleChange} className="bg-white" />
                <Input label="Labor Cost (₹)" name="laborCost" type="number" value={pl.laborCost} onChange={handleChange} className="bg-white" />
                <div className="flex flex-col h-full justify-end pb-1 px-3 bg-blue-50 rounded border border-blue-200">
                    <p className="text-[10px] font-bold text-blue-400 uppercase tracking-wider">Revenue Share</p>
                    <p className="text-2xl font-bold text-brand-blue">₹{revenue.toLocaleString()}</p>
                </div>
                <div className="flex flex-col h-full justify-end pb-1 px-3 bg-white rounded border border-slate-200">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Net Profit</p>
                    <p className={`text-2xl font-bold ${pl.calculatedProfit < 0 ? 'text-red-600' : 'text-green-600'}`}>
                        ₹{pl.calculatedProfit.toFixed(2)}
                    </p>
                </div>
            </div>

            <div className="space-y-2">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Dynamic Line Items</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                    {(pl.dynamicCosts || []).map(cost => (
                        <div key={cost.id} className="flex items-center gap-2 bg-white p-1.5 rounded border border-slate-200">
                            <input 
                                placeholder="Cost Label"
                                value={cost.label} 
                                onChange={e => updateDynamicCost(cost.id, 'label', e.target.value)}
                                className="flex-grow text-xs border-none focus:ring-0"
                            />
                            <div className="w-20 flex items-center gap-1 border-l pl-2">
                                <span className="text-[10px] text-slate-400">₹</span>
                                <input 
                                    type="number" 
                                    value={cost.value} 
                                    onChange={e => updateDynamicCost(cost.id, 'value', parseFloat(e.target.value) || 0)}
                                    className="w-full text-xs border-none focus:ring-0 font-bold text-right"
                                />
                            </div>
                            <button onClick={() => removeDynamicCost(cost.id)} className="text-slate-300 hover:text-red-500"><IconTrash className="w-3.5 h-3.5" /></button>
                        </div>
                    ))}
                </div>
            </div>

            <div className="flex flex-wrap gap-2 items-center">
                {predefinedCosts.filter(c => !c.category || c.category === 'ALL' || c.category === service.serviceSelection[0]).map(cost => (
                    <button 
                        key={cost.id} 
                        onClick={() => applyPreset(cost.value, cost.name)}
                        className="px-2 py-1 text-[10px] bg-white border border-slate-200 rounded-full hover:border-brand-accent"
                    >
                        + {cost.name} (₹{cost.value})
                    </button>
                ))}
            </div>

            <div className="flex items-center gap-4 border-t pt-3 mt-4">
                <textarea
                    name="notes"
                    value={pl.notes || ''}
                    onChange={handleChange}
                    rows={1}
                    className="flex-grow px-3 py-1.5 border border-slate-300 rounded-md text-xs bg-white focus:ring-1 focus:ring-brand-accent"
                    placeholder="Expense notes..."
                />
                <Button onClick={() => onSave(pl)} size="sm" variant={isSaved ? "ghost" : "primary"}>
                    {isSaved ? <IconCheck className="w-4 h-4 text-green-600" /> : <IconDeviceFloppy className="w-4 h-4" />}
                </Button>
            </div>
        </div>
    );
};

export const ProfitLossPage: React.FC<ProfitLossPageProps> = ({ submissions, profitLossData, onSave, predefinedCosts, onUpdatePredefinedCosts }) => {
    const [activeTab, setActiveTab] = useState<PLTab>('ALL');
    const [selectedJobIds, setSelectedJobIds] = useState<string[]>([]);
    const [isBulkManagerOpen, setIsBulkManagerOpen] = useState(false);

    // Quick Add Form for Presets
    const [newPresetName, setNewPresetName] = useState('');
    const [newPresetValue, setNewPresetValue] = useState<number | ''>('');

    const serviceTabs: { id: PLTab, label: string, icon: any }[] = [
        { id: 'ALL', label: 'All Jobs', icon: <IconChartBar /> },
        { id: 'WASH', label: 'Car Washing', icon: <IconCheck /> },
        { id: 'CARE', label: 'Car Care', icon: <IconSparkles /> },
        { id: 'TYRE', label: 'Tyre Replace', icon: <IconEngine /> },
        { id: 'BATTERY', label: 'Battery Replace', icon: <IconWorld /> },
        { id: 'CUSTOM', label: 'Custom Service', icon: <IconPlus /> }
    ];

    const filteredJobs = useMemo(() => {
        const completed = submissions.filter(s => s.status === ServiceStatus.Completed && !s.isDeleted);
        switch (activeTab) {
            case 'WASH': return completed.filter(s => s.serviceSelection.includes('Car Washing'));
            case 'CARE': return completed.filter(s => s.serviceSelection.includes('Car Care'));
            case 'TYRE': return completed.filter(s => s.serviceSelection.includes('Tyre Replacement'));
            case 'BATTERY': return completed.filter(s => s.serviceSelection.includes('Battery Replacement'));
            case 'CUSTOM': return completed.filter(s => s.customServices?.length > 0);
            default: return completed;
        }
    }, [submissions, activeTab]);

    const handleSelectAll = () => {
        if (selectedJobIds.length === filteredJobs.length) setSelectedJobIds([]);
        else setSelectedJobIds(filteredJobs.map(j => j.submissionId));
    };

    const toggleJobSelection = (id: string) => {
        setSelectedJobIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
    };

    const handleAddPreset = () => {
        if (!newPresetName || newPresetValue === '') return;
        const newPreset: PredefinedCost = {
            id: `pc_${Date.now()}`,
            name: newPresetName,
            value: Number(newPresetValue),
            category: activeTab
        };
        onUpdatePredefinedCosts([...predefinedCosts, newPreset]);
        setNewPresetName('');
        setNewPresetValue('');
    };

    const handleDeletePreset = (id: string) => {
        onUpdatePredefinedCosts(predefinedCosts.filter(p => p.id !== id));
    };

    const applyBulkCost = (preset: PredefinedCost) => {
        if (selectedJobIds.length === 0) {
            alert("Please select at least one job first.");
            return;
        }

        selectedJobIds.forEach(jobId => {
            const service = filteredJobs.find(j => j.submissionId === jobId);
            if (!service) return;

            const existingPL = profitLossData.find(pl => pl.serviceId === jobId) || {
                serviceId: jobId,
                materialCost: service.tyreMaterialCost || 0,
                laborCost: service.tyreLaborCost || 0,
                otherExpenses: 0,
                dynamicCosts: [],
                calculatedProfit: 0,
                notes: ''
            };

            const newDynamicItem: DynamicCostItem = {
                id: `dc_${Date.now()}_${Math.random()}`,
                label: preset.name,
                value: preset.value
            };

            const updatedPL = {
                ...existingPL,
                dynamicCosts: [...(existingPL.dynamicCosts || []), newDynamicItem]
            };

            // Recalculate profit
            const revenue = activeTab === 'ALL' ? service.grandTotal : 
                            (activeTab === 'WASH' ? (service.carWashDetails?.price || 0) : 
                            (activeTab === 'TYRE' ? service.tyreReplacementTotalAmount : service.grandTotal));

            const dynamicSum = updatedPL.dynamicCosts.reduce((s, i) => s + i.value, 0);
            updatedPL.calculatedProfit = revenue - updatedPL.materialCost - updatedPL.laborCost - updatedPL.otherExpenses - dynamicSum;

            onSave(updatedPL);
        });

        setSelectedJobIds([]);
        setIsBulkManagerOpen(false);
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h2 className="text-3xl font-black text-slate-800 tracking-tight">Financial Ledger</h2>
                    <p className="text-slate-500">Configure cost types and perform bulk updates across service lines.</p>
                </div>
                <div className="flex items-center gap-2">
                     <Button variant="secondary" onClick={() => setIsBulkManagerOpen(!isBulkManagerOpen)}>
                        <IconSettings className="w-5 h-5 mr-2" />
                        Quick Settings
                    </Button>
                </div>
            </div>

            {/* Bulk Manager / Preset Settings Section */}
            {isBulkManagerOpen && (
                <Card className="border-2 border-brand-accent/30 bg-slate-50">
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                        <div>
                            <h4 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
                                <IconPlus className="w-4 h-4 text-brand-accent"/>
                                Define New Cost Type for {activeTab}
                            </h4>
                            <div className="flex items-end gap-3">
                                <div className="flex-grow"><Input label="Cost Label" value={newPresetName} onChange={e => setNewPresetName(e.target.value)} placeholder="e.g. Delivery, Electricity share" /></div>
                                <div className="w-28"><Input label="Value (₹)" type="number" value={newPresetValue} onChange={e => setNewPresetValue(e.target.value === '' ? '' : Number(e.target.value))} /></div>
                                <Button onClick={handleAddPreset} className="mb-0.5 h-[38px]"><IconPlus className="w-5 h-5" /></Button>
                            </div>
                            <p className="text-[10px] text-slate-400 mt-2">These labels will be saved for all future {activeTab} calculations.</p>
                        </div>
                        <div>
                            <h4 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
                                <IconCheck className="w-4 h-4 text-green-600"/>
                                Active Presets
                            </h4>
                            <div className="flex flex-wrap gap-2">
                                {predefinedCosts.filter(p => p.category === activeTab).map(p => (
                                    <div key={p.id} className="flex items-center gap-2 bg-white border border-slate-200 px-3 py-1.5 rounded-lg shadow-sm group">
                                        <span className="text-xs font-bold text-slate-700">{p.name} (₹{p.value})</span>
                                        <button onClick={() => handleDeletePreset(p.id)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <IconTrash className="w-3.5 h-3.5" />
                                        </button>
                                        <button onClick={() => applyBulkCost(p)} className="text-[10px] font-black text-brand-blue hover:text-brand-accent ml-2 uppercase tracking-tighter">
                                            Apply Bulk
                                        </button>
                                    </div>
                                ))}
                                {predefinedCosts.filter(p => p.category === activeTab).length === 0 && <p className="text-xs text-slate-400 italic">No presets for this tab yet.</p>}
                            </div>
                        </div>
                    </div>
                </Card>
            )}

            {/* Tabbed Navigation */}
            <div className="flex flex-wrap gap-1.5 bg-slate-200 p-1 rounded-xl w-fit">
                {serviceTabs.map(tab => (
                    <button
                        key={tab.id}
                        onClick={() => { setActiveTab(tab.id); setSelectedJobIds([]); }}
                        className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                            activeTab === tab.id 
                            ? 'bg-brand-blue text-white shadow-lg scale-105' 
                            : 'text-slate-500 hover:bg-slate-300'
                        }`}
                    >
                        {React.cloneElement(tab.icon as React.ReactElement<React.SVGProps<SVGSVGElement>>, { className: "w-3.5 h-3.5" })}
                        {tab.label}
                    </button>
                ))}
            </div>

            {/* List Header with Select All */}
            <div className="flex items-center justify-between bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
                <div className="flex items-center gap-4">
                    <label className="flex items-center gap-2 cursor-pointer">
                        <input 
                            type="checkbox" 
                            checked={selectedJobIds.length === filteredJobs.length && filteredJobs.length > 0} 
                            onChange={handleSelectAll}
                            className="h-5 w-5 rounded border-slate-300 text-brand-accent"
                        />
                        <span className="text-sm font-bold text-slate-700">Select All Visible ({filteredJobs.length})</span>
                    </label>
                    {selectedJobIds.length > 0 && (
                        <span className="text-xs font-black text-brand-accent animate-pulse uppercase">
                            {selectedJobIds.length} Selected for Bulk Action
                        </span>
                    )}
                </div>
                <div className="text-right">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Aggregated Result</p>
                    <p className="text-lg font-black text-slate-800">₹{filteredJobs.reduce((sum, j) => sum + j.grandTotal, 0).toLocaleString()}</p>
                </div>
            </div>

            <div className="space-y-6">
                {filteredJobs.length > 0 ? filteredJobs.map(service => (
                    <div key={service.submissionId} className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 hover:border-brand-accent/50 transition-colors">
                        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
                            <div className="flex items-center gap-4">
                                <div className="p-3 bg-brand-blue/10 rounded-xl text-brand-blue">
                                    {service.serviceSelection.includes('Car Washing') ? <IconCheck /> : <IconEngine />}
                                </div>
                                <div>
                                    <h3 className="font-black text-xl text-slate-800">
                                        {service.customerFirstName} {service.customerLastName}
                                        <span className="ml-2 text-sm font-mono text-slate-400">#{service.appointmentId?.split('-').pop()}</span>
                                    </h3>
                                    <div className="flex items-center gap-2 text-xs font-bold text-slate-500 uppercase tracking-widest mt-1">
                                        <span>{service.carBrandModel}</span>
                                        <span>•</span>
                                        <span>{new Date(service.timestamp).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}</span>
                                    </div>
                                </div>
                            </div>
                            <div className="text-left sm:text-right">
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Order Total</p>
                                <p className="text-2xl font-black text-brand-blue">₹{service.grandTotal.toLocaleString()}</p>
                            </div>
                        </div>

                        <ProfitLossCalculator
                            service={service}
                            profitLoss={profitLossData.find(pl => pl.serviceId === service.submissionId)}
                            onSave={onSave}
                            predefinedCosts={predefinedCosts}
                            isSelected={selectedJobIds.includes(service.submissionId)}
                            onToggleSelect={() => toggleJobSelection(service.submissionId)}
                            specificServiceRevenue={activeTab === 'ALL' ? undefined : (activeTab === 'WASH' ? service.carWashDetails?.price : (activeTab === 'TYRE' ? service.tyreReplacementTotalAmount : undefined))}
                        />
                    </div>
                )) : (
                    <div className="bg-slate-100 border-2 border-dashed border-slate-300 rounded-2xl p-12 text-center">
                        <IconClock className="w-10 h-10 text-slate-300 mx-auto mb-2" />
                        <p className="text-slate-500 font-medium">No completed jobs found for this category.</p>
                    </div>
                )}
            </div>
        </div>
    );
};

