const parseServiceSelection = (raw: any): string[] => {
    if (Array.isArray(raw)) return raw.flatMap(item => parseServiceSelection(item));
    if (typeof raw === 'string') {
        const trimmed = raw.trim();
        if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
            try {
                const parsed = JSON.parse(trimmed);
                if (Array.isArray(parsed)) return parseServiceSelection(parsed);
            } catch (e) { }
        }
        return trimmed.split(',').map(s => s.replace(/[\[\]"']/g, '').trim()).filter(Boolean);
    }
    return [];
};

export const loadAppData = async (currentSettings: Settings): Promise<AppData> => {
    const sheetsUrl = currentSettings.googleSheetsUrl;
    if (!sheetsUrl) return getDefaultAppData(currentSettings);
    try {
        const url = new URL(sheetsUrl);
        url.searchParams.set('action', 'loadAllData');
        const response = await fetch(url.toString(), { method: 'GET', mode: 'cors' });
        const result = await response.json();
        if (result.status !== 'success') throw new Error(result.message || 'Cloud script returned an error.');

        const flatData = result.data;
        const tyreDetails = (flatData.TyreDetails || []);
        const batteryDetails = (flatData.BatteryDetails || []).map(d => ({ ...d, exchangeValue: robustParseFloat(d.exchangeValue), newBatteryAmount: robustParseFloat(d.newBatteryAmount) }));
        const customServices = (flatData.CustomServices || []).map(d => ({ ...d, amount: robustParseFloat(d.amount) }));
        const categorizedAddonsArr = (flatData.CategorizedAddons || []).map(d => ({ ...d, quantity: robustParseInt(d.quantity), amount: robustParseFloat(d.amount) }));
        const locationHistory = (flatData.LocationHistory || []).map(d => ({ ...d, latitude: robustParseFloat(d.latitude), longitude: robustParseFloat(d.longitude) }));
        const miscSpends = (flatData.MiscSpends || []).map(s => ({ ...s, amount: robustParseFloat(s.amount) }));
        const bookkeeping = (flatData.Bookkeeping || []).map(b => ({ ...b, amount: robustParseFloat(b.amount) }));
        const profitLoss = (flatData.ProfitLoss || []).map(pl => ({ ...pl, materialCost: robustParseFloat(pl.materialCost), laborCost: robustParseFloat(pl.laborCost), otherExpenses: robustParseFloat(pl.otherExpenses), calculatedProfit: robustParseFloat(pl.calculatedProfit) }));
        const businessOverheads = (flatData.BusinessOverheads || []).map(bo => ({ ...bo, amount: robustParseFloat(bo.amount) }));
        const spendCategories = (flatData.SpendCategories || []).map(c => ({ ...c }));
        const predefinedCosts = (flatData.PredefinedCosts || []).map(c => ({ ...c, value: robustParseFloat(c.value) }));
        const vehicleData = (flatData.VehicleData && flatData.VehicleData[0]?.data) ? JSON.parse(flatData.VehicleData[0].data) : CAR_BRANDS;
        const tyreData = (flatData.TyreData && flatData.TyreData[0]?.data) ? JSON.parse(flatData.TyreData[0].data) : { brands: TIRE_BRANDS, models: [], sizes: [] };
        const pricingConfig = (flatData.PricingConfig && flatData.PricingConfig[0]?.data) ? JSON.parse(flatData.PricingConfig[0].data) : DEFAULT_PRICING_CONFIG;
        const subscriptionPlans = (flatData.SubscriptionPlans || []).map(p => ({ ...p, price: robustParseFloat(p.price), totalWashes: robustParseInt(p.totalWashes), features: p.features ? String(p.features).split(',').map(f => f.trim()) : [] }));
        const userSubscriptions = (flatData.UserSubscriptions || []).map(s => ({ ...s, washesRemaining: robustParseInt(s.washesRemaining) }));
        const serviceRequests = (flatData.ServiceRequests || []);
        const notifications = (flatData.Notifications || []).map(n => ({ ...n, isRead: String(n.isRead).toUpperCase() === 'TRUE' }));
        const serviceTemplates = (flatData.ServiceTemplates || []).map(t => ({ ...t, isEnabled: String(t.isEnabled).toUpperCase() === 'TRUE', customFields: (flatData.ServiceTemplateFields || []).filter(f => f.relatedTemplateId === t.id).map(({ relatedTemplateId, ...rest }) => rest) }));

        const submissions = (flatData.Submissions || []).map((sub: any): Service => {
            let status = sub.status;
            if (status === "Submitted") status = ServiceStatus.Completed;
            else if (status === "Order Created") status = ServiceStatus.Queued;
            if (!status || !Object.values(ServiceStatus).includes(status as ServiceStatus)) status = ServiceStatus.Queued;

            let dynamicAddons = [];
            try { if (sub.dynamicAddons) dynamicAddons = typeof sub.dynamicAddons === 'string' ? JSON.parse(sub.dynamicAddons) : sub.dynamicAddons; } catch(e) { }
            let carWashDetails = undefined;
            try { if (sub.carWashDetails) carWashDetails = typeof sub.carWashDetails === 'string' ? JSON.parse(sub.carWashDetails) : sub.carWashDetails; } catch(e) { }
            let carCareDetails = undefined;
            try { if (sub.carCareDetails) carCareDetails = typeof sub.carCareDetails === 'string' ? JSON.parse(sub.carCareDetails) : sub.carCareDetails; } catch(e) { }

            return {
                ...sub, status, 
                dynamicAddons: Array.isArray(dynamicAddons) ? dynamicAddons : [], 
                carWashDetails, carCareDetails,
                isSubscription: String(sub.isSubscription).toUpperCase() === 'TRUE',
                isFollowUp: String(sub.isFollowUp).toUpperCase() === 'TRUE',
                isAutoScheduled: String(sub.isAutoScheduled).toUpperCase() === 'TRUE',
                acknowledgement: String(sub.acknowledgement).toUpperCase() === 'TRUE',
                grandTotal: robustParseFloat(sub.grandTotal),
                appointmentId: sub.appointmentId || sub.submissionId,
                tyreDetails: tyreDetails.filter(d => d.relatedServiceId === sub.submissionId),
                batteryDetails: batteryDetails.filter(d => d.relatedServiceId === sub.submissionId),
                customServices: customServices.filter(d => d.relatedServiceId === sub.submissionId),
                categorizedAddons: categorizedAddonsArr.filter(d => d.relatedServiceId === sub.submissionId),
                customFieldData: (flatData.CustomFieldData || []).filter(d => d.relatedServiceId === sub.submissionId).map(({ relatedServiceId, ...rest }) => rest),
                serviceSelection: parseServiceSelection(sub.serviceSelection),
                dependsOn: sub.dependsOn ? String(sub.dependsOn).split(',').map(s => s.trim()) : [],
            };
        });

        const cloudSettingsPartial = (flatData.Settings && flatData.Settings[0]) ? flatData.Settings[0] : {};
        const settings: Settings = {
            googleSheetsUrl: cloudSettingsPartial.googleSheetsUrl || currentSettings.googleSheetsUrl,
            googleDriveUploadUrl: cloudSettingsPartial.googleDriveUploadUrl || currentSettings.googleDriveUploadUrl,
            customLogoUrl: cloudSettingsPartial.customLogoUrl || currentSettings.customLogoUrl,
            retentionKpiTargets: cloudSettingsPartial.retentionKpiTargets ? (typeof cloudSettingsPartial.retentionKpiTargets === 'string' ? JSON.parse(cloudSettingsPartial.retentionKpiTargets) : cloudSettingsPartial.retentionKpiTargets) : currentSettings.retentionKpiTargets
        };

        const users = (flatData.Users && flatData.Users.length > 0) 
            ? (flatData.Users).map(u => ({ ...u, notificationPreferences: u.notificationPreferences ? JSON.parse(u.notificationPreferences) : {}, attendanceHistory: u.attendanceHistory ? JSON.parse(u.attendanceHistory) : [], permissions: u.permissions ? JSON.parse(u.permissions) : [], latitude: u.latitude ? robustParseFloat(u.latitude) : undefined, longitude: u.longitude ? robustParseFloat(u.longitude) : undefined }))
            : getDefaultAppData(settings).users;

        return { submissions, users, settings, subscriptionPlans, userSubscriptions, serviceTemplates, serviceRequests, notifications, locationHistory, miscSpends, bookkeeping, profitLoss, businessOverheads, vehicleData, tyreData, pricingConfig, spendCategories, predefinedCosts, predefinedAddons: [] };
    } catch (error) { throw new Error(error instanceof Error ? error.message : "Load failed"); }
};

