export const SubmissionList: React.FC<SubmissionListProps> = ({ submissions, users, onEdit, onPrint, onSummarize, currentUser, serviceTemplates }) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [filters, setFilters] = useState({ textSearch: '', startDate: '', endDate: '', status: '', assignedUser: '' });
  const [sortField, setSortField] = useState<SortField>('scheduledDate');
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');
  const [currentPage, setCurrentPage] = useState(1);
  const [isFilterPanelOpen, setIsFilterPanelOpen] = useState(false);

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
    setCurrentPage(1);
  };

  const handleToggleDetails = (id: string) => {
    setExpandedId(currentId => (currentId === id ? null : id));
  };

  const filteredAndSortedSubmissions = useMemo(() => {
    const filtered = submissions.filter(service => {
        const searchTerm = filters.textSearch.toLowerCase().trim();
        const name = `${service.customerFirstName || ''} ${service.customerLastName || ''}`.toLowerCase();
        const mobile = String(service.mobileNumber || '').toLowerCase();
        const carNum = String(service.carNumber || '').toLowerCase();
        const appIdSuffix = (service.appointmentId ? String(service.appointmentId).split('-').pop() || '' : '').toLowerCase();

        const matchesSearch = searchTerm === '' ||
            name.includes(searchTerm) ||
            mobile.includes(searchTerm) ||
            carNum.includes(searchTerm) ||
            appIdSuffix.includes(searchTerm);

        const serviceDate = new Date(service.timestamp);
        const startDate = filters.startDate ? new Date(filters.startDate) : null;
        const endDate = filters.endDate ? new Date(filters.endDate) : null;

        if (startDate) startDate.setHours(0, 0, 0, 0);
        if (endDate) endDate.setHours(23, 59, 59, 999);

        const matchesDate = (!startDate || serviceDate >= startDate) && (!endDate || serviceDate <= endDate);
        const matchesStatus = !filters.status || service.status === filters.status;
        const matchesUser = !filters.assignedUser || service.assignedTo === filters.assignedUser;

        return matchesSearch && matchesDate && matchesStatus && matchesUser;
    });

    filtered.sort((a, b) => {
        if (sortField === 'scheduledDate') {
            const dateA = parseDateTime(a);
            const dateB = parseDateTime(b);
            if (!dateA && !dateB) return 0;
            if (!dateA) return 1;
            if (!dateB) return -1;
            return sortOrder === 'asc' ? dateA.getTime() - dateB.getTime() : dateB.getTime() - dateA.getTime();
        }
        const timeA = new Date(a.timestamp).getTime();
        const timeB = new Date(b.timestamp).getTime();
        return sortOrder === 'asc' ? timeA - timeB : timeB - timeA;
    });

    return filtered;
  }, [submissions, filters, sortField, sortOrder]);

  const totalPages = Math.ceil(filteredAndSortedSubmissions.length / ITEMS_PER_PAGE);
  const paginatedSubmissions = useMemo(() => {
      const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
      return filteredAndSortedSubmissions.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [filteredAndSortedSubmissions, currentPage]);

  const statusConfig = {
    [ServiceStatus.Completed]: 'bg-green-100 text-green-800',
    [ServiceStatus.InProgress]: 'bg-purple-100 text-purple-800',
    [ServiceStatus.Assigned]: 'bg-blue-100 text-blue-800',
    [ServiceStatus.Queued]: 'bg-slate-100 text-slate-800',
    [ServiceStatus.Draft]: 'bg-yellow-100 text-yellow-800',
  };

  return (
    <div className="space-y-6">
       <MetricsReport submissions={filteredAndSortedSubmissions} users={users} currentUser={currentUser} />

       <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Service History</h2>

       <Card>
            <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4">
                <div className="flex-grow">
                    <Input
                        label="Search by Name, Number, or ID"
                        id="textSearch"
                        name="textSearch"
                        value={filters.textSearch}
                        onChange={handleFilterChange}
                        placeholder="e.g., John Doe, 987..."
                        className="sm:max-w-sm"
                    />
                </div>
                <Button variant="secondary" onClick={() => setIsFilterPanelOpen(prev => !prev)} className="w-full sm:w-auto">
                    <IconFilter className="w-5 h-5 mr-2" />
                    <span>Filter & Sort</span>
                     <IconChevronDown className={`w-4 h-4 ml-2 transition-transform duration-300 ${isFilterPanelOpen ? 'rotate-180' : ''}`} />
                </Button>
            </div>
             {isFilterPanelOpen && (
                <div className="mt-4 pt-4 border-t border-slate-200">
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
                        <div className="space-y-4">
                            <div>
                                <label htmlFor="status" className="block text-sm font-medium text-slate-700 mb-1">Filter by Status</label>
                                <select
                                    id="status"
                                    name="status"
                                    value={filters.status}
                                    onChange={handleFilterChange}
                                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                                >
                                    <option value="">All Statuses</option>
                                    {Object.values(ServiceStatus).map(status => (
                                        <option key={status} value={status}>{status}</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label htmlFor="assignedUser" className="block text-sm font-medium text-slate-700 mb-1">Filter by Assigned User</label>
                                <select
                                    id="assignedUser"
                                    name="assignedUser"
                                    value={filters.assignedUser}
                                    onChange={handleFilterChange}
                                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                                >
                                    <option value="">All Users</option>
                                    {users.map(user => (
                                        <option key={user.username} value={user.username}>{user.username}</option>
                                    ))}
                                </select>
                            </div>
                        </div>
                        <div className="space-y-4">
                             <div>
                                <p className="block text-sm font-medium text-slate-700 mb-1">Filter by Submission Date Range</p>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                                    <Input
                                        label="From"
                                        id="startDate"
                                        name="startDate"
                                        type="date"
                                        value={filters.startDate}
                                        onChange={handleFilterChange}
                                    />
                                    <Input
                                        label="To"
                                        id="endDate"
                                        name="endDate"
                                        type="date"
                                        value={filters.endDate}
                                        onChange={handleFilterChange}
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Sort Results</label>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                                    <select
                                        id="sortField"
                                        name="sortField"
                                        value={sortField}
                                        onChange={(e) => setSortField(e.target.value as SortField)}
                                        className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus:ring-2 focus:ring-brand-accent focus:border-brand-accent sm:text-sm"
                                    >
                                        <option value="scheduledDate">Scheduled Date</option>
                                        <option value="timestamp">Submission Date</option>
                                    </select>
                                    <div className="flex rounded-md shadow-sm">
                                        <button
                                            type="button"
                                            onClick={() => setSortOrder('asc')}
                                            className={`relative inline-flex items-center justify-center px-3 py-2 rounded-l-md border border-slate-300 text-sm font-medium transition-colors ${sortOrder === 'asc' ? 'bg-brand-accent text-brand-blue z-10' : 'bg-white text-slate-500 hover:bg-slate-50'}`}
                                            title="Ascending"
                                        >
                                            <IconChevronUp className="w-5 h-5" />
                                        </button>
                                        <button
                                            type="button"
                                            onClick={() => setSortOrder('desc')}
                                            className={`-ml-px relative inline-flex items-center justify-center px-3 py-2 rounded-r-md border border-slate-300 text-sm font-medium transition-colors ${sortOrder === 'desc' ? 'bg-brand-accent text-brand-blue z-10' : 'bg-white text-slate-500 hover:bg-slate-50'}`}
                                            title="Descending"
                                        >
                                            <IconChevronDown className="w-5 h-5" />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
             )}
        </Card>

       {submissions.length === 0 ? (
          <Card className="text-center">
            <p className="text-slate-500 mt-2">No service history found.</p>
          </Card>
        ) : filteredAndSortedSubmissions.length === 0 ? (
          <Card className="text-center">
            <p className="text-slate-500 mt-2">No services found matching your filters.</p>
          </Card>
        ) : (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {paginatedSubmissions.map(service => {
