import React, { useMemo } from 'react';
// FIX: Imports are now valid as types.ts has been updated.
import { Service, ServiceStatus, User, Permission } from '../types';
import Card from './ui/Card';
import Button from './ui/Button';
import { IconDownload } from './ui/Icon';

// Let TypeScript know that the XLSX object will be available globally from the CDN script
declare var XLSX: any;

interface MetricsReportProps {
  submissions: Service[];
  users: Omit<User, 'password'>[];
  currentUser: User;
}

const MetricDisplay: React.FC<{ label: string; value: string | number; className?: string }> = ({ label, value, className }) => (
    <div className={`p-4 bg-slate-100 rounded-lg text-center ${className}`}>
        <p className="text-sm font-semibold text-slate-600 uppercase tracking-wider">{label}</p>
        <p className="text-3xl font-bold text-brand-blue">{value}</p>
    </div>
);

export const MetricsReport: React.FC<MetricsReportProps> = ({ submissions, users, currentUser }) => {

    const metrics = useMemo(() => {
        // Base all calculations on completed services from the provided submissions list.
        const completedServices = submissions.filter(s => s.status === ServiceStatus.Completed);

        const totalRevenue = completedServices.reduce((acc, s) => acc + Number(s.grandTotal || 0), 0);
        const completedCount = completedServices.length;
        const averageRevenue = completedCount > 0 ? totalRevenue / completedCount : 0;

        const serviceCounts = completedServices.flatMap(s => s.serviceSelection).reduce((acc, service) => {
            acc[service] = (acc[service] || 0) + 1;
            return acc;
        }, {} as Record<string, number>);

        return {
            completedCount,
            totalRevenue: totalRevenue.toFixed(2),
            averageRevenue: averageRevenue.toFixed(2),
            serviceCounts
        };
    }, [submissions]);

    const handleExportXlsx = () => {
        // Only export completed services that are being reported on.
        const completedServices = submissions.filter(s => s.status === ServiceStatus.Completed);

        if (completedServices.length === 0) {
            alert("No completed services in the current view to export.");
            return;
        }

        if (typeof XLSX === 'undefined') {
            alert("Error: The reporting library (SheetJS) could not be loaded. Please check your internet connection and refresh the page.");
            return;
        }

        const wb = XLSX.utils.book_new();
        const reportDate = new Date();
        const fileName = `completed_services_report_${reportDate.toISOString().split('T')[0]}.xlsx`;

        const submissionsFlat = completedServices.map(s => {
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            const { tyreDetails, batteryDetails, customServices, categorizedAddons, dynamicAddons, customFieldData, dependsOn, ...rest } = s;
            return {
                ...rest,
                serviceSelection: s.serviceSelection.join(', '), // convert array to string for excel
                dynamicAddons: (s.dynamicAddons || []).map(a => `${a.name} (Qty: ${a.quantity})`).join(', '),
                categorizedAddons: (s.categorizedAddons || []).map(a => `${a.productName} (Qty: ${a.quantity})`).join(', '),
                customServices: (s.customServices || []).map(cs => cs.serviceDescription).join(', '),
            };
        });

        const ws_submissions = XLSX.utils.json_to_sheet(submissionsFlat);
        XLSX.utils.book_append_sheet(wb, ws_submissions, 'CompletedServices');

        XLSX.writeFile(wb, fileName);
    };

    return (
        <Card className="mb-8">
            <div className="flex flex-wrap gap-4 justify-between items-center mb-6">
                 <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Metrics for Completed Services</h2>
                 {currentUser.permissions.includes(Permission.CAN_MANAGE_ADMINS) && (
                    <Button onClick={handleExportXlsx} disabled={metrics.completedCount === 0}>
                        <IconDownload className="w-5 h-5 mr-2" />
                        Export Completed (Excel)
                    </Button>
                 )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <MetricDisplay label="Completed Services" value={metrics.completedCount} />
                <MetricDisplay label="Total Revenue" value={`₹${metrics.totalRevenue}`} />
                <MetricDisplay label="Average Revenue" value={`₹${metrics.averageRevenue}`} />
            </div>

            {Object.keys(metrics.serviceCounts).length > 0 && (
                <div className="mt-6 pt-6 border-t border-slate-200">
                    <h3 className="text-lg font-semibold text-slate-700 mb-4">Completed Service Breakdown</h3>
                    <div className="flex flex-wrap gap-4">
                        {/* FIX: Cast entries to explicitly typed [string, number][] to fix rendering errors. */}
                        {(Object.entries(metrics.serviceCounts) as [string, number][]).map(([service, count]) => (
                             <div key={service} className="px-4 py-2 bg-blue-100 text-blue-800 rounded-lg">
                                <span className="font-semibold">{service}:</span> {count}
                             </div>
                        ))}
                    </div>
                </div>
            )}
        </Card>
    );
};

// FIX: Updated to follow the latest @google/genai SDK guidelines.
const { GoogleGenAI } = require("@google/genai");

// Helper to format service data into a readable string for the prompt
const formatServiceForPrompt = (service) => {
    let promptText = `Customer: ${service.customerFirstName} ${service.customerLastName}\n`;
    promptText += `Car: ${service.carBrandModel} (${service.carNumber})\n`;
    promptText += `Date: ${new Date(service.timestamp).toLocaleDateString()}\n`;
    promptText += `Services Performed: ${service.serviceSelection.join(', ')}\n\n`;
    promptText += "Itemized Details:\n";

    // Add details for each service
    if (service.carWashDetails) promptText += `- Car Wash (${service.carWashDetails.washType}): ₹${service.carWashDetails.price.toFixed(2)}\n`;
    if (service.tyreReplacementTotalAmount > 0) promptText += `- Tyre Replacement: ₹${service.tyreReplacementTotalAmount.toFixed(2)}\n`;
    if (service.batteryReplacementTotalAmount > 0) promptText += `- Battery Service: ₹${service.batteryReplacementTotalAmount.toFixed(2)}\n`;
    if (service.addonsTotal > 0) promptText += `- Add-ons Total: ₹${service.addonsTotal.toFixed(2)}\n`;
    if (service.customServicesTotal > 0) promptText += `- Custom Services: ₹${service.customServicesTotal.toFixed(2)}\n`;

    promptText += `\nGrand Total: ₹${service.grandTotal.toFixed(2)}\n`;
    return promptText;
};

exports.handler = async function(event, context) {
  if (event.httpMethod !== 'POST') {
    return {
      statusCode: 405,
      body: JSON.stringify({ error: 'Method Not Allowed' }),
    };
  }

  if (!process.env.API_KEY) {
      return {
          statusCode: 500,
          body: JSON.stringify({ error: 'API_KEY environment variable not set on Netlify.' }),
      };
  }

  try {
    const service = JSON.parse(event.body);

    // Guideline: Always use a named parameter for the API key.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const formattedService = formatServiceForPrompt(service);
    const prompt = `Please provide a brief, friendly summary of the following auto service record for the customer. Mention the key services performed and the grand total. Keep it under 80 words and use a positive tone. Here is the service data:\n\n${formattedService}`;

    // Guideline: Use ai.models.generateContent with model and contents.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    // Guideline: Access generated text via the .text property.
    const summary = response.text;

    return {
      statusCode: 200,
      headers: {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*",
      },
      body: JSON.stringify({ summary }),
    };

  } catch (error) {
    console.error("Error in summarize-service function:", error);
    const errorMessage = error instanceof Error ? error.message : "An unknown error occurred";
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Failed to generate summary.', details: errorMessage }),
    };
  }
};

// FIX: Updated to follow the latest @google/genai SDK guidelines.
const { GoogleGenAI } = require("@google/genai");

exports.handler = async function(event) {
  if (event.httpMethod !== 'POST') {
    return { statusCode: 405, body: JSON.stringify({ error: 'Method Not Allowed' }) };
  }

  if (!process.env.API_KEY) {
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'API_KEY environment variable not set on Netlify.' }),
    };
  }

  try {
    const { messages, serviceTemplates } = JSON.parse(event.body);

    // Guideline: Always use a named parameter for the API key.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const serviceNames = serviceTemplates.map(t => t.name).join(', ');

    const systemInstruction = `You are 'A Big Engine AI Assistant', a friendly and efficient chatbot that helps users book a vehicle service.
Your goal is to fill out a service form by asking the user a series of questions in a specific, conversational order.
You must ask for:
1. Customer's first name, last name, and 10-digit mobile number.
2. Car's registration number and brand/model.
3. The customer's street address.
4. Which services they need. The main available services are: ${serviceNames}.
5. If they select 'Car Washing', ask for the quantity.

Once you believe you have all the necessary information, present a clear, bulleted summary of the details you've collected.
Then, ask the user to confirm if the details are correct. For example: "Is this information correct?"

If the user confirms, and ONLY if they confirm, you MUST respond with just the final JSON object containing all the collected data, enclosed in a \`\`\`json code block. Do not include any other text, greetings, or explanation outside the code block.
The JSON schema you must adhere to is:
{
  "customerFirstName": "string",
  "customerLastName": "string",
  "mobileNumber": "string (10 digits only, no country code)",
  "carNumber": "string",
  "carBrandModel": "string",
  "streetAddress": "string",
  "serviceSelection": ["array", "of", "strings"],
  "carwashQuantity": "number (if Car Washing is selected, otherwise 0)"
}

Start the conversation by greeting the user and asking for their first name. Be friendly and conversational. Ask one simple question at a time. Do not ask for multiple pieces of information in a single message.`;

    const contents = messages.map(msg => ({
      role: msg.role === 'user' ? 'user' : 'model',
      parts: [{ text: msg.text }]
    }));

    // Guideline: Use ai.models.generateContent with model, contents, and config.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: contents,
      config: { systemInstruction: { parts: [{ text: systemInstruction }] } }
    });

    // Guideline: Access generated text via the .text property.
    const text = response.text;

    return {
      statusCode: 200,
      headers: {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*",
      },
      body: JSON.stringify({ reply: text }),
    };

  } catch (error) {
    console.error("Error in chat-with-bot function:", error);
    const errorMessage = error instanceof Error ? error.message : "An unknown error occurred";
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Failed to get response from AI.', details: errorMessage }),
    };
  }
};

import React from 'react';
import { Service, CarCareDetails, PricingConfig } from '../types';
import { CAR_CARE_TYPES } from '../constants';

// FIX: Updated Props interface to resolve spread errors in ServiceForm.
interface Props {
  state: Service;
  updateField: <K extends keyof Service>(field: K, value: Service[K]) => void;
  dispatch: React.Dispatch<any>;
  pricingConfig?: PricingConfig;
  googleDriveUploadUrl?: string;
  userSubscriptions?: any[];
  serviceTemplates?: any[];
  errors?: any;
  allSubmissions?: Service[];
  vehicleData?: any;
  tyreData?: any;
  onUpdateVehicleData?: (brand: string, model: string) => void;
  onUpdateTyreData?: (type: string, value: string) => void;
}

const CarCareStep: React.FC<Props> = ({ state, updateField }) => {

  const handleCareTypeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const careType = e.target.value;
    if (careType) {
        const newDetails: CarCareDetails = { careType, price: 0, mrp: 0 };
        updateField('carCareDetails', newDetails);
    } else {
        updateField('carCareDetails', undefined);
    }
  };

  return (
    <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-start">
            <div>
                <label htmlFor="careType" className="block text-sm font-medium text-slate-700 mb-1">
                    Select Car Care Package
                </label>
                <select 
                    id="careType" 
                    value={state.carCareDetails?.careType || ''} 
                    onChange={handleCareTypeChange}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm bg-white focus:outline-none focus-visible:ring-2 focus-visible:ring-brand-accent sm:text-sm"
                >
                    <option value="">-- No Car Care --</option>
                    {CAR_CARE_TYPES.map(type => (
                        <option key={type} value={type}>{type}</option>
                    ))}
                </select>
            </div>
             <div className="text-left md:text-right pt-7">
                <p className="text-xs text-slate-500">MRP: ₹{(state.carCareDetails?.mrp || 0).toFixed(2)}</p>
                <p className="text-2xl font-bold text-slate-800">Total: ₹{(state.carCareDetails?.price || 0).toFixed(2)}</p>
            </div>
        </div>
    </div>
  );
};

export default CarCareStep;
